export const GUIDE = JSON.parse("[{\"slug\":\"01-introduction\",\"title\":\"Introduction\",\"summary\":\"dunx is a dependency injection framework for Bun.\",\"sections\":[\"What it is built on\",\"Design decisions\",\"The measured position\",\"When not to use dunx\",\"Where to go next\"],\"body\":\"# Introduction\\n\\ndunx is a dependency injection framework for [Bun](https://bun.com). It gives you\\nmodules, constructor injection, class-based controllers, lifecycle hooks and\\nguards. HTTP is served through `Bun.serve`, not through a server dunx wrote.\\n\\nThere is a running app at [demo.dunx.win](https://demo.dunx.win) if you would\\nrather click than read: it is `examples/full`, which uses every package in this\\nguide, and its API explorer, ops dashboard and queue board are all open.\\n\\nThe architecture follows the pattern Spring and Angular established. A container\\nowns object lifetimes. Metadata replaces wiring code. Modules draw domain\\nboundaries. If you have worked with either framework, the shape is familiar:\\n\\n```ts\\nimport { Module } from '@dunx/core';\\nimport { Controller, Get, HttpFactory } from '@dunx/http';\\n\\nexport class GreetingsService {\\n  greet(name: string): string {\\n    return `hello, ${name}`;\\n  }\\n}\\n\\n@Controller('greetings')\\nexport class GreetingsController {\\n  constructor(private readonly greetings: GreetingsService) {}\\n\\n  @Get('/')\\n  index(): { greeting: string } {\\n    return { greeting: this.greetings.greet('world') };\\n  }\\n}\\n\\n@Module({\\n  controllers: [GreetingsController],\\n  providers: [GreetingsService],\\n})\\nexport class AppModule {}\\n\\nconst app = await HttpFactory.create(AppModule);\\nawait app.listen(3000);\\n```\\n\\nNote what is absent: no `@Injectable()` on the service, no `@Inject()` in the\\nconstructor, no `reflect-metadata` import, no `experimentalDecorators` in the\\ntsconfig.\\n\\nListing a class in a module's `providers` makes it injectable, and\\n`@dunx/transform` reads the constructor parameter's type at load time.\\n[Providers](dunx://guide/03-providers) explains how, and what happens when the type\\ncannot be recovered.\\n\\n## What it is built on\\n\\n**Bun does the I/O.** `Bun.serve({ routes })` matches paths, dispatches per method\\nand answers a method miss, in native Zig. dunx builds the routes object at boot\\nand hands it over. The same goes for SQLite, Postgres, Redis, S3, image resizing,\\npassword hashing and `.env` loading: Bun already does each of those.\\n`ConfigModule` has no loader because Bun reads `.env` itself.\\n\\nYou can see where the line falls in the dependency tree: `@dunx/core` has **zero\\ndependencies**, and nothing in dunx pulls in express, `ws`, ioredis, pg, sharp or\\ndotenv.\\n\\nThe one exception is the parser. Bun cannot tell you a TypeScript constructor's\\nparameter types, so `@dunx/transform` reads them with\\n[oxc-parser](https://github.com/oxc-project/oxc), a Rust parser over N-API. It is\\nbuild-time only and ships as its own package. A production deploy carries no\\nparser.\\n\\n**Libraries do the hard parts.** Where Bun has no primitive, dunx integrates\\nsomething mature rather than growing its own:\\n\\n| Concern            | Library                             | What dunx adds                                        |\\n| ------------------ | ----------------------------------- | ----------------------------------------------------- |\\n| Validation         | zod, Valibot, ArkType, TypeBox, ajv | Nothing. Routes target the Standard Schema interface  |\\n| ORM and migrations | drizzle-orm                         | A module over `drizzle-orm/bun-sqlite` and `/bun-sql` |\\n| Authentication     | better-auth                         | The mount and a guard, none of the flow               |\\n| Queues             | bullmq                              | A module over bullmq's own `createBunRedisClient`     |\\n\\nThese are `peerDependencies`. You install them and you own the version, and where a\\nlibrary has a Bun-native driver that driver is the one dunx uses.\\n\\nValidation shows the shape of it best: `@dunx/http` restates the Standard Schema\\ntypes in one file and depends on no validator at all. Anything with a `~standard`\\nproperty works, a hand-written object included. TypeBox and ajv do not ship one, and\\neach took about ten lines to bridge in the benchmark harness without touching\\n`@dunx/http`.\\n\\n## Design decisions\\n\\n**TC39 decorators only.** The standard has no parameter decorators, so there is no\\n`@Inject()`. `inject()` in a field initializer covers what a constructor parameter\\ncannot express. No `@Injectable()` either: listing a class in `providers` is enough.\\n\\n**Module scoping replaces globals and path matching.** Each module is a scope,\\n`exports` is its public surface, and `global: true` publishes one app-wide. These\\nare fields on the one options object. A module's `middleware` covers the routes\\nits own controllers declare. See [Modules](dunx://guide/04-modules).\\n\\n**Circular imports work.** Dependencies are recorded as a thunk and read at\\nresolution, so a class declared later in the file, or across a circular import,\\nresolves without `forwardRef`.\\n\\n**Singleton providers only.** Every provider lives for the container's lifetime.\\nPer-request state is an argument. Per-request correlation is `AsyncLocalStorage`\\nthrough `RequestContext`, which never touches the container.\\n\\n**Eager resolution.** `AppFactory.create()` builds every provider and awaits every\\nasync factory before the server binds. A wiring mistake fails at boot, not on the\\nfirst request that hits it. This costs boot time, measured below.\\n\\n**ESM only, Bun only.** No CommonJS build, no Node compatibility layer.\\n\\n## The measured position\\n\\n`@dunx/http` sits on `Bun.serve`. The most useful number the benchmark harness\\nproduces is the gap between the two: that gap is dunx's own overhead.\\n\\nRun on an AMD Ryzen 9 5950X with 32 logical cores, Bun 1.4.2, Node 24.21.0, oha\\n1.15.0, 64 connections, 3 s warmup, 5 measured rounds of 5 s, dated 2026-09-09:\\n\\n| Scenario    | raw `Bun.serve` | `@dunx/http` | % of raw |          Elysia |\\n| ----------- | --------------: | -----------: | -------: | --------------: |\\n| `plaintext` |   134,478 req/s |      133,993 |    99.6% | 133,151 (99.0%) |\\n| `json`      |   129,641 req/s |      123,999 |    95.6% | 122,220 (94.3%) |\\n| `params`    |   128,172 req/s |      120,942 |    94.4% | 127,701 (99.6%) |\\n| `validate`  |    90,015 req/s |       82,903 |    92.1% |  80,372 (89.3%) |\\n| `io`        |    27,721 req/s |       27,646 |    99.7% | 27,741 (100.1%) |\\n\\n**dunx costs under 1% to 8%** against the API it dispatches through, and is level\\nwith Elysia. Read a ratio as plus or minus one point. Anything under three points\\nis a tie: two full runs of the same code disagreed by a median of 0.6 points.\\n\\n`io` is the one that leaves the process: a Redis `GET` and then a Postgres\\n`SELECT`. The framework is 0.3% of it. Every difference above it is smaller than\\none query, which is the honest framing for the other four rows.\\n\\nA figure at or above 100% would be noise: dunx dispatches through `Bun.serve` and\\ncannot serve a request faster than the API it calls.\\n\\nStartup is the clearest loss, and it is a real one:\\n\\n| Subject          | cold start to first served request (median of 7) |\\n| ---------------- | -----------------------------------------------: |\\n| raw `Bun.serve`  |                                          24.0 ms |\\n| **`@dunx/http`** |                                      **46.2 ms** |\\n| Elysia           |                                          51.9 ms |\\n| raw `node:http`  |                                          80.7 ms |\\n| Express          |                                         110.1 ms |\\n| Fastify          |                                         135.4 ms |\\n| NestJS (Express) |                                         243.7 ms |\\n\\ndunx boots in **1.93x** raw `Bun.serve`'s time, for the `oxc-parser` preload plus\\neager DI resolution and route discovery. Read the ratio rather than the\\nmilliseconds: both absolute figures move with the Bun release, and have moved in\\nboth directions.\\n\\nEvery figure here is **spawn to a request served**, not to `listen()` returning.\\nThe second milestone is roughly 20 ms earlier on both, so a number measured that\\nway is not comparable with this table.\\n\\nThat cost is paid once at boot, never per request. It is a real cost on a\\nshort-lived process.\\n\\nTwo more numbers worth having before you commit to anything:\\n\\n**Request logging is on by default and costs throughput.** `@dunx/http` installs\\n`RequestLoggingMiddleware` outermost, writing one structured entry per request.\\nWith it on, `plaintext` runs at 78,060 req/s against 137,539 with it off: 57.0%\\nof raw `Bun.serve` against 100.4%.\\n\\nThe cost decomposes to about 1.3 µs reading `req.headers`, 0.9 µs for the\\n`AsyncLocalStorage` scope, 2.1 µs building and serialising the entry, and 0.7 µs\\nreading `req.url`. Turn it off with\\n`HttpFactory.create(root, { requestLogging: false })` and sample at the edge.\\n\\n**Parsing a body costs about three times what validating it costs.** Measured\\nagainst raw `Bun.serve`: putting a body on the wire and never reading it adds\\n0.27 µs, `await req.json()` adds 3.10 µs, and zod on top adds 0.94 µs.\\n\\nEvery Standard Schema validator measured, including Valibot, ArkType, TypeBox and\\najv, came in under the parse, so no throughput argument separates them. Pick on\\nAPI, error quality and ecosystem.\\n\\nThe harness does not measure absolute capacity, concurrency beyond one process,\\nbehaviour under sustained load, TLS, HTTP/2, websockets or streaming. Its only\\nI/O is the `io` row's one Redis `GET` and one Postgres `SELECT`; no filesystem, no\\nupstream HTTP, and nothing about a pool under contention.\\n\\nIt does measure resident set and CPU per request, which this page does not\\nreproduce. dunx boots at 51.3 MiB against raw `Bun.serve`'s 34.6, and peaks at\\n71.9 against 60.5 while serving the `io` row.\\n\\nOn that one row the framework is **0.3%** of the request. That is a result about\\nthis workload, not a law: a heavier query moves it further toward nothing, and an\\nendpoint that touches no service at all is the `plaintext` row instead. It is\\nenough to say the four rows above are the wrong thing to choose a framework on.\\n\\n## When not to use dunx\\n\\n**You do not want dependency injection.** Elysia and Hono own Bun's web-framework\\nspace, they are mature, and they are faster to learn. Neither offers DI, modules\\nor class-based controllers, and that gap is the whole reason dunx exists. If you\\nwould not use the DI, you are paying its boot cost and its concepts for nothing.\\n\\n**Boot time is the number that matters.** A short-lived process, a serverless\\nfunction billed per invocation, or a CLI will feel the ~46 ms. dunx is built for a\\nservice that starts once and stays up. Note also that the startup numbers were\\ntaken on an idle 32-core desktop, which is not what a constrained serverless CPU\\nlooks like.\\n\\n**You need request-scoped or transient providers.** Not supported, rejected with\\nmeasurements, and not coming back.\\n\\n**You are not on Bun, or you might not be.** There is no CommonJS build, no Node\\ncompatibility layer, and `Bun.serve`, `bun:sqlite`, `Bun.RedisClient`,\\n`Bun.password` and `Bun.S3Client` are load-bearing throughout. Portability was\\nnever a goal.\\n\\n**You want MySQL or MariaDB with nothing to assemble.** The database module\\nships two backends: `bun:sqlite`, and `Bun.SQL` for Postgres. `drizzle-orm/bun-sql`\\nbuilds a Postgres dialect unconditionally, so a MySQL URL is rejected at\\nconstruction with a message saying so. MySQL and MariaDB do run, through\\n`drizzle-orm/mysql-proxy` over `Bun.SQL`, but the backend is a `DbOptions` subclass\\nyou write. [`examples/databases`](https://github.com/petarzarkov/dunx/tree/main/examples/databases)\\nships a working one.\\n\\n**You want a mature ecosystem of third-party modules.** There is not one. dunx is\\nten published workspaces in one repository. The established frameworks have a decade or more\\nof community modules behind them and dunx has none.\\n\\n## Where to go next\\n\\n[First steps](dunx://guide/02-first-steps) scaffolds an application and walks every\\ngenerated file. [Providers](dunx://guide/03-providers) is the DI deep dive.\\n[Modules](dunx://guide/04-modules) covers composition, `exports` and module scoping.\\n[Controllers](dunx://guide/05-controllers) covers routing, validation and errors.\\n\\n[ARCHITECTURE.md](https://github.com/petarzarkov/dunx/blob/main/docs/ARCHITECTURE.md) records what was measured, what was\\nrejected, and why. If a decision here looks arbitrary, its reasoning is in that\\ndocument.\\n\"},{\"slug\":\"02-first-steps\",\"title\":\"First steps\",\"summary\":\"This page scaffolds an application, explains every file in it, and then adds a route, a service and a test.\",\"sections\":[\"Scaffold\",\"Choosing features\",\"What you got\",\"Run it\",\"Add a route\",\"Add a service\",\"Next\"],\"body\":\"# First steps\\n\\nThis page scaffolds an application, explains every file in it, and then adds a\\nroute, a service and a test. It assumes Bun 1.4 or newer and nothing else.\\n\\n## Scaffold\\n\\n```bash\\nbunx @dunx/create-app my-api\\n```\\n\\nIt asks what the app should do. Enter on an empty selection gives the minimal\\ntemplate:\\n\\n```\\n✓ Features  none, the minimal template\\n\\nCreated my-api in my-api/\\n  12 files from the minimal template\\n\\nNext:\\n  cd my-api\\n  bun install\\n  bun run dev  # or `start`, which does not watch\\n```\\n\\nThe target directory is the only positional argument. Four flags remain, and none\\nof them chooses anything about the app:\\n\\n| Flag            | Effect                                                     |\\n| --------------- | ---------------------------------------------------------- |\\n| `--name <name>` | Package name for the app. Defaults to the directory's base |\\n| `--force`       | Write into a directory that already has files in it        |\\n| `--yes`, `-y`   | Skip the questions and take the minimal template           |\\n| `--help`        | Print usage                                                |\\n\\n**Piped, or in CI, it asks nothing** and writes the minimal template, so a script\\nnever blocks on a question nothing can answer. To choose features without a\\nterminal, call `scaffold({ target, features })` from `@dunx/create-app`.\\n\\nName the directory `.` to write into the one you are already in.\\n\\nThe package name is validated against npm's rules before anything is written, so a\\ndirectory called `My-API` produces a second question asking for a name npm takes,\\nrather than a directory whose `bun install` fails later. A directory that already\\nhas files in it produces the other question, and answering no writes nothing.\\n\\nEvery `@dunx/*` version in the generated manifest is resolved at run time from the\\nversion of `@dunx/create-app` doing the scaffolding. The packages version in\\nlockstep, so the right version to install is whatever generated the app, and the\\ntemplate never goes stale between releases.\\n\\n## Choosing features\\n\\nThe minimal template is five files and one route: small enough to read, thin\\nenough to start from. Anything more is composed from the list:\\n\\n```\\n? Features  3 chosen, 1 pulled in\\n  ○ notes       CRUD routes with zod validation. The smallest real feature.\\n  ◉ openapi     OpenAPI 3.1 from the routes own schemas, plus the Swagger UI page.\\n  ◉ http        CORS, a middleware of your own on the response, and error mapping.\\n  ◈ database    drizzle over bun:sqlite, with a schema, seeds and migrations.\\n❯ ◉ users       A repository, a service and validated routes over the database.\\n  database comes along as a requirement.\\n  Space toggles. ↑↓ moves. a all, n none. Enter continues.\\n```\\n\\n```\\nCreated my-api in my-api/\\n  33 files, 4 features: openapi, http, database, users\\n  database came along as a requirement\\n```\\n\\n`◉` is chosen, `◈` is pulled in by something else you chose, `○` is neither.\\n`↑` `↓` move, `k` and `j` do the same, `a` takes everything and `n` clears it.\\nCtrl+C stops without writing.\\n\\nThe set:\\n\\n| Feature      | What arrives                                                     | Pulls in                     |\\n| ------------ | ---------------------------------------------------------------- | ---------------------------- |\\n| `notes`      | CRUD routes with zod validation. The smallest real feature       |                              |\\n| `openapi`    | OpenAPI 3.1 from the routes' own schemas, plus the explorer page |                              |\\n| `http`       | CORS, a request-logging middleware and error mapping             |                              |\\n| `guards`     | `@Roles` and `@Public`, and a protected controller               |                              |\\n| `database`   | drizzle over `bun:sqlite`, with a schema, seeds and migrations   |                              |\\n| `users`      | A repository, a service and validated routes over the database   | `database`                   |\\n| `auth`       | better-auth mounted, with `SessionGuard` and an audit trail      | `database`                   |\\n| `cache`      | `Bun.RedisClient` behind a session store                         |                              |\\n| `websockets` | A `@Gateway` with `@OnMessage`, `PubSub` and a Redis relay       | `cache`                      |\\n| `images`     | `Bun.Image` resizing and format conversion behind a route        |                              |\\n| `files`      | Uploads and downloads on `Bun.file`                              |                              |\\n| `jobs`       | bullmq queues and a job processor, over `Bun.RedisClient`        | `images`                     |\\n| `health`     | Liveness and readiness probes, and which parts are degraded      | `cache`, `database`, `files` |\\n\\nRequirements come along automatically. The list marks them `◈` while you choose.\\nImport order is construction order, so a database is built before the feature that\\nreads it and torn down after it. `cache`, `websockets` and `jobs` want a Redis or\\nValkey. Each reports itself degraded rather than failing the boot, so the app still\\nstarts without one.\\n\\n### Where the code comes from\\n\\nEvery feature directory is copied out of dunx's own\\n[`examples/full`](https://github.com/petarzarkov/dunx/tree/main/examples/full).\\nCI builds, typechecks, tests and tours that service on every push. A byte-for-byte\\nparity test fails the moment a copy drifts from the example.\\n\\nThe wiring cannot be copied. `app.module.ts`, `config.ts` and `main.ts` name every\\nfeature at once in the full example, so those three are **generated** for the\\nselection. The config carries only the variables your features read, and the\\nmanifest only the dependencies they need.\\n\\nCI scaffolds every feature alone, the whole set, and the combinations with\\nsomething to get wrong, then typechecks each one.\\n\\nThe `*.demo.ts` files are the full example's scripted walkthroughs, and they come\\nalong because their module registers them. They are executable documentation of the\\nfeature; delete one and its `providers` entry when you do not want it.\\n\\n## What you got\\n\\n```\\nmy-api/\\n  bunfig.toml\\n  package.json\\n  tsconfig.json\\n  README.md\\n  AGENTS.md\\n  CLAUDE.md\\n  .gitignore\\n  src/\\n    main.ts\\n    app.module.ts\\n    greetings.service.ts\\n    greetings.controller.ts\\n    app.test.ts\\n```\\n\\n### `bunfig.toml`\\n\\n```toml\\n# The one line that makes constructor injection work. The compiler plugin records\\n# each class's constructor parameter types so the container can resolve them.\\n# Without it, providers are built with no arguments and boot fails saying so.\\npreload = [\\\"@dunx/transform/preload\\\"]\\n\\n[test]\\npreload = [\\\"@dunx/transform/preload\\\"]\\n```\\n\\nThe only setup dunx asks for. Read it rather than copying it.\\n\\n`@dunx/transform/preload` registers a Bun plugin. On load, the plugin parses each\\n`.ts` and `.tsx` file with `oxc-parser`, reads every class declaration's\\nconstructor parameter types, and appends one statement after the class:\\n\\n```ts\\nexport class GreetingsService {\\n  constructor(private readonly logger: Logger) {}\\n}\\nObject.defineProperty(GreetingsService, Symbol.for('dunx.deps'), {\\n  value: () => [Logger],\\n});\\n```\\n\\nThe container reads that record and resolves the arguments before calling `new`.\\nFiles under `node_modules` are skipped: a published package was already\\ntransformed by its own build, and re-parsing dependencies on every load is pure\\ncost.\\n\\nThere are two `preload` entries because Bun's test runner reads its own. The\\ntop-level one covers `bun run start` and `bun src/main.ts`; the `[test]` one\\ncovers `bun test`. Miss the second and your app runs but your suite does not.\\n\\n**What breaks without it.** The container compares the recorded dependency count\\nagainst `Function.prototype.length`, which still reports the declared parameter\\ncount after TypeScript's parameter properties are compiled away. Zero recorded\\ndependencies plus a non-zero arity can only mean the plugin never saw the file.\\nBoot fails with a clear message carrying the fix:\\n\\n```\\nGreetingsService declares 1 constructor parameter(s) but no dependencies were\\nrecorded for it, so @dunx/transform did not transform GreetingsService. Register\\nthe plugin, then retry:\\n\\n  # bunfig.toml\\n  preload = [\\\"@dunx/transform/preload\\\"]\\n\\n  [test]\\n  preload = [\\\"@dunx/transform/preload\\\"]\\n```\\n\\nThere are no false positives. A constructor whose parameters all have defaults\\nhas `length === 0` and is genuinely callable with no arguments. A class bound\\nwith `useValue` is never constructed. The transform only writes a record whose\\nlength equals the parameter count, so a present record is never empty.\\n\\n`@dunx/core` does not register the plugin on import, for two reasons, both fatal.\\n\\nIt would make DI import-order dependent. Bun's `onLoad` only affects modules\\nloaded after registration, and static imports evaluate depth-first in source\\norder, so `import { AppFactory } from '@dunx/core'` before your module would work\\nwhile the reverse order silently skipped the transform. That is the\\n\\\"`reflect-metadata` must be the first import\\\" fragility dunx exists to avoid.\\n\\nIt would also cost `@dunx/core` its empty dependency list. Every production\\ndeploy would carry a Rust parser to run code already transformed at build time.\\n\\nTwo other places accept the same plugin object if `bunfig.toml` does not suit you:\\n\\n```ts\\nimport { depsPlugin } from '@dunx/transform';\\n\\n// A production build.\\nawait Bun.build({ entrypoints: ['./src/main.ts'], plugins: [depsPlugin] });\\n```\\n\\nand `bun --preload @dunx/transform/preload src/main.ts`, which needs no config\\nfile at all.\\n\\n### `package.json`\\n\\n```json\\n{\\n  \\\"name\\\": \\\"my-api\\\",\\n  \\\"version\\\": \\\"0.1.0\\\",\\n  \\\"private\\\": true,\\n  \\\"type\\\": \\\"module\\\",\\n  \\\"scripts\\\": {\\n    \\\"dev\\\": \\\"bun --watch src/main.ts\\\",\\n    \\\"start\\\": \\\"bun src/main.ts\\\",\\n    \\\"test\\\": \\\"bun test\\\",\\n    \\\"typecheck\\\": \\\"tsc --noEmit\\\"\\n  },\\n  \\\"dependencies\\\": {\\n    \\\"@dunx/core\\\": \\\"^0.1.0\\\",\\n    \\\"@dunx/http\\\": \\\"^0.1.0\\\",\\n    \\\"@dunx/transform\\\": \\\"^0.1.0\\\"\\n  },\\n  \\\"devDependencies\\\": {\\n    \\\"@dunx/testing\\\": \\\"^0.1.0\\\",\\n    \\\"@types/bun\\\": \\\">=1.4.0\\\",\\n    \\\"typescript\\\": \\\"^5.7.0\\\"\\n  },\\n  \\\"engines\\\": {\\n    \\\"bun\\\": \\\">=1.4.0\\\"\\n  }\\n}\\n```\\n\\n`\\\"type\\\": \\\"module\\\"` is required. Every dunx package is ESM only, and\\nwithout it `verbatimModuleSyntax` raises `TS1287` against ESM syntax.\\n\\n`@dunx/transform` is a runtime dependency rather than a dev dependency because the\\npreload runs when you run the app. If you compile ahead of time with\\n`Bun.build({ plugins: [depsPlugin] })`, it becomes build-time only and can move.\\n\\n`@dunx/testing` is a dev dependency. It is what `src/app.test.ts` uses.\\n\\n`dev` is `--watch`, which restarts the process on a change. `--hot` swaps modules\\nin place, but a container is built once at boot. The old providers would still\\nhold the socket the new ones are trying to bind.\\n\\n### Keep every `@dunx/*` on the same version\\n\\nThe scaffold already does this, and it matters when you add a package by hand\\nlater.\\n\\ndunx releases in lockstep: every package shares one version and ships together,\\neven the ones a release did not touch. The packages peer-depend on each other by\\ncaret range, so mixing minors resolves to a graph that warns on install:\\n\\n```\\nwarn: incorrect peer dependency \\\"@dunx/http@0.2.0\\\"\\n```\\n\\nThat happens when a lockfile already has an entry satisfying your range. Adding\\n`@dunx/auth` to an app pinned at `^0.2.0` can resolve auth to 0.2.5 and leave the\\nrest at 0.2.0, and `@dunx/auth@0.2.5` peers on `@dunx/http@^0.2.5`.\\n\\nThe warning is the good case. The bad one is **two copies of `@dunx/core` in one\\ntree**, which breaks dependency injection. A token _is_ a class object, so two\\ncopies are two different classes. A provider bound against one is invisible to a\\nresolution against the other. The error says nothing is bound, from somewhere\\nunrelated to the version mismatch.\\n\\nSo when you add a package, match the version to the ones already installed:\\n\\n```bash\\nbun add @dunx/auth@$(bun pm pkg get dependencies.@dunx/core --workspaces=false | tr -d '\\\"^')\\n```\\n\\nOr edit the manifest so every `@dunx/*` range reads the same, and reinstall.\\n\\n### `tsconfig.json`\\n\\n```json\\n{\\n  \\\"compilerOptions\\\": {\\n    \\\"target\\\": \\\"ESNext\\\",\\n    \\\"lib\\\": [\\\"ESNext\\\"],\\n    \\\"module\\\": \\\"nodenext\\\",\\n    \\\"moduleResolution\\\": \\\"nodenext\\\",\\n    \\\"types\\\": [\\\"bun\\\"],\\n    \\\"strict\\\": true,\\n    \\\"noUncheckedIndexedAccess\\\": true,\\n    \\\"exactOptionalPropertyTypes\\\": true,\\n    \\\"noImplicitOverride\\\": true,\\n    \\\"noPropertyAccessFromIndexSignature\\\": true,\\n    \\\"verbatimModuleSyntax\\\": true,\\n    \\\"skipLibCheck\\\": true,\\n    \\\"noEmit\\\": true\\n  },\\n  \\\"include\\\": [\\\"src\\\"],\\n  \\\"exclude\\\": [\\\"node_modules\\\"]\\n}\\n```\\n\\n**Do not enable `experimentalDecorators` or `emitDecoratorMetadata`.** dunx uses\\nTC39 standard decorators, and those flags change decorator semantics under you.\\n\\n`moduleResolution: nodenext` is why relative imports carry a `.js` extension:\\n`import { AppModule } from './app.module.js'`. The file on disk is `.ts`. The\\nspecifier is what the emitted declaration would carry, and an extensionless one\\nfails to resolve for consumers on `node16` or `nodenext`. Under this setting it\\nis a compile error.\\n\\n`verbatimModuleSyntax` is why type-only imports must say so: `import type { Input }`.\\nIt is also, indirectly, a DI hazard, and [Providers](dunx://guide/03-providers) covers\\nit: a constructor parameter whose type came in through a type-only import has no\\nruntime value to record, so the container cannot resolve it.\\n\\n### `src/main.ts`\\n\\n```ts\\nimport { HttpFactory } from '@dunx/http';\\nimport { AppModule } from './app.module.js';\\n\\nconst app = await HttpFactory.create(AppModule);\\napp.enableShutdownHooks();\\n\\nconst url = await app.listen(3000);\\nconsole.log(`listening on ${url}greetings`);\\n\\nawait app.closed;\\n```\\n\\nFour lines of real work.\\n\\n`HttpFactory.create(AppModule)` builds the container from the root module's import\\ngraph, resolves every provider, awaits every async factory, runs every `onInit`,\\nthen discovers each controller's routes and rejects any collision. It does not\\nbind a port. There is no separate `init()` step: resolution is eager, so an app\\nthat exists is an app that booted.\\n\\n`app.enableShutdownHooks()` registers `SIGTERM` and `SIGINT` handlers. Pass your\\nown list to change that. On a signal, the server stops first, then every provider\\nwith an `onShutdown` method runs in reverse construction order.\\n\\n`app.listen(3000)` builds the `Bun.serve` route table and binds. This is the\\npoint of no return: `setGlobalPrefix`, `use`, `set` and `enableCors` all throw\\nafterwards, since the route table and the middleware chain are folded into one\\nclosure per route when the server binds.\\n\\nIt returns the URL with a trailing slash, so the log line concatenates\\n`greetings` directly.\\n\\n`await app.closed` holds the process. The promise resolves once shutdown has\\nfinished, whoever triggered it.\\n\\n### `src/app.module.ts`\\n\\n```ts\\nimport { Module } from '@dunx/core';\\nimport { GreetingsController } from './greetings.controller.js';\\nimport { GreetingsService } from './greetings.service.js';\\n\\n@Module({\\n  controllers: [GreetingsController],\\n  providers: [GreetingsService],\\n})\\nexport class AppModule {}\\n```\\n\\n`@Module` is a marker. It writes its options onto the class under\\n`Symbol.for('dunx.module')` and the class is never instantiated. `controllers` and\\n`providers` are registered identically; the split exists so the HTTP adapter knows\\nwhich constructed instances to scan for routes.\\n\\nNote that a bare class in either list is shorthand for binding it to itself. There\\nis no `provide(GreetingsService, { useClass: GreetingsService })` to write for the\\nordinary case. [Modules](dunx://guide/04-modules) covers `imports`, why there is no\\n`exports`, and how ordering works.\\n\\n### `src/greetings.service.ts`\\n\\n```ts\\nimport { Logger, type OnInit } from '@dunx/core';\\n\\nexport class GreetingsService implements OnInit {\\n  #greeted = 0;\\n\\n  constructor(private readonly logger: Logger) {}\\n\\n  onInit(): void {\\n    this.logger.info('greetings ready');\\n  }\\n\\n  greet(name: string): { greeting: string; served: number } {\\n    this.#greeted++;\\n    return { greeting: `hello, ${name}`, served: this.#greeted };\\n  }\\n}\\n```\\n\\nA plain class. No decorator, no registration boilerplate. Listing it in a module's\\n`providers` is what makes it injectable.\\n\\n`Logger` in the constructor is the entire dependency injection story. Nothing in\\nthis app bound `Logger` and it still resolves. `AppFactory.create` offers a\\ndefault binding for `Logger` and `RequestContext` after every module's. A module\\nthat binds either one wins, and an app that binds neither still gets one.\\n\\nThe default is `ConsoleLogger`, which writes one JSON line per entry and reaches\\nfor no dependency. It performs no sanitizing, masking or rotation, so swapping in\\n`@dunx/infra/logger` earns its place later.\\n\\n`Logger` is an `abstract class` rather than an interface. The transform records\\nconstructor parameter _types_, and an interface has no runtime value to record,\\nso an interface in that position would be a boot error at the injection site.\\n\\n`implements OnInit` is structural. The container checks for an `onInit` method by\\nshape, so the `implements` clause is only there to make TypeScript check the\\nsignature for you. `onInit` runs after the whole graph is constructed, in\\ndependency order.\\n\\n### `src/greetings.controller.ts`\\n\\n```ts\\nimport { Controller, Get, type Input, type RouteSchemas } from '@dunx/http';\\nimport { GreetingsService } from './greetings.service.js';\\n\\n@Controller('greetings')\\nexport class GreetingsController {\\n  constructor(private readonly greetings: GreetingsService) {}\\n\\n  @Get('/')\\n  index(): { routes: readonly string[] } {\\n    return { routes: ['GET /greetings', 'GET /greetings/:name'] };\\n  }\\n\\n  @Get('/:name')\\n  one({ req }: Input<RouteSchemas>): { greeting: string; served: number } {\\n    return this.greetings.greet(req.params['name'] ?? 'world');\\n  }\\n}\\n```\\n\\nA controller is a provider with routes on it, and `GreetingsService` in the\\nconstructor is resolved exactly the way the service's own `Logger` was.\\n\\nReturning a plain object is enough. `@dunx/http` wraps it in `Response.json()`.\\nThere is no `res` to forget to send, and returning a `Response` yourself passes\\nthrough untouched when you need the escape hatch.\\n\\n`@Get('/:name')` declares no schemas, so the path parameter stays on\\n`req.params` as a string. `noUncheckedIndexedAccess` is why the `?? 'world'`\\nis there. Declaring a `params` schema is what makes it typed and coerced, and\\n[Controllers](dunx://guide/05-controllers) shows that.\\n\\n`Input<RouteSchemas>` is the annotation for a route with no options at all. You\\ncould also take no parameter. What you cannot do is leave the parameter\\nunannotated: a standard method decorator can check a handler's input type but\\ncannot contextually type an unannotated one, so an unannotated parameter is\\n`TS7006`. The reasoning, and the measurement behind it, are in\\n[Controllers](dunx://guide/05-controllers).\\n\\n### `src/app.test.ts`\\n\\n```ts\\nimport { describe, expect, test } from 'bun:test';\\nimport { createTestServer } from '@dunx/testing';\\nimport { AppModule } from './app.module.js';\\n\\ndescribe('minimal', () => {\\n  test('serves the greeting', async () => {\\n    const server = await createTestServer({ modules: [AppModule] });\\n\\n    const { status, body } = await server.json<{ greeting: string }>(\\n      'greetings/ada',\\n    );\\n\\n    expect(status).toBe(200);\\n    expect(body.greeting).toBe('hello, ada');\\n    await server.close();\\n  });\\n});\\n```\\n\\n`createTestServer` boots the real application behind a real `Bun.serve` on port 0.\\nNothing is faked. `Bun.serve` binds in about a millisecond, and a fake would only\\nbe able to prove the parts of the request path dunx wrote rather than the parts\\nBun owns: routing, params, method dispatch, upgrades.\\n\\n`modules` takes one module or several; they become the `imports` of one synthetic\\nroot, so you do not have to write a fixture module. Request logging is off unless\\nyou ask for it, because a suite printing one JSON line per assertion helps nobody.\\n\\n`server.json(path)` returns `{ status, headers, body }` in one await. `server.request()`\\ngives you the raw `Response` for bytes, HTML or a header assertion. `server.close()`\\nis `app.shutdown()`: it stops the server, then tears the container down.\\n\\n### `AGENTS.md` and `CLAUDE.md`\\n\\n`AGENTS.md` states this app's layout, its commands, and the rules dunx fails at boot\\nover: no `@Injectable()` to add, `.js` on relative imports, a `import type` at an\\ninjection site being an error rather than an `undefined`. A composed app also lists\\nthe features it carries and the services they want running.\\n\\n`CLAUDE.md` is four lines pointing at it, so both filenames find the same\\ninstructions and there is one file to edit.\\n\\nNeither restates the framework. They link\\n[setup.md](https://dunx.win/setup.md) and\\n[llms.txt](https://dunx.win/llms.txt), which are served from the\\ndocumentation site and move with each release.\\n\\n## Run it\\n\\n```bash\\ncd my-api\\nbun install\\nbun run dev     # or `bun run start`, which does not watch\\n```\\n\\n```\\n{\\\"level\\\":\\\"info\\\",\\\"message\\\":\\\"greetings ready\\\", ...}\\nlistening on http://localhost:3000/greetings\\n```\\n\\n```bash\\ncurl localhost:3000/greetings/ada\\n```\\n\\n```json\\n{ \\\"greeting\\\": \\\"hello, ada\\\", \\\"served\\\": 1 }\\n```\\n\\n```bash\\nbun test\\n```\\n\\n## Add a route\\n\\nGive the existing route a validated parameter. Add zod:\\n\\n```bash\\nbun add zod\\n```\\n\\nThen declare the schema and annotate the handler with it:\\n\\n```ts\\nimport { Controller, Get, type Input, type RouteSchemas } from '@dunx/http';\\nimport { z } from 'zod';\\nimport { GreetingsService } from './greetings.service.js';\\n\\nconst oneGreeting = {\\n  params: z.object({ name: z.string().min(1).max(40) }),\\n} as const satisfies RouteSchemas;\\n\\n@Controller('greetings')\\nexport class GreetingsController {\\n  constructor(private readonly greetings: GreetingsService) {}\\n\\n  @Get('/:name', oneGreeting)\\n  one({ params }: Input<typeof oneGreeting>): {\\n    greeting: string;\\n    served: number;\\n  } {\\n    return this.greetings.greet(params.name);\\n  }\\n}\\n```\\n\\n`params.name` is now a `string` the schema has already checked, and the\\n`?? 'world'` is gone because the field cannot be missing. A request that fails the\\nschema never reaches the handler; it gets a 400 whose body carries every issue.\\n\\n`as const satisfies RouteSchemas` is the convention for a hoisted options object.\\n`satisfies` checks the shape without replacing the type, so a misspelled field is\\ncaught at the declaration. What you must not write is\\n`const oneGreeting: RouteSchemas = { ... }`: that annotation makes `params`\\noptional, `Input<typeof oneGreeting>` degrades to bare `{ req }`, and every\\nhandler loses its typed input.\\n\\n## Add a service\\n\\nA second provider, injected into the first. No annotation anywhere:\\n\\n```ts\\n// src/audit.service.ts\\nimport { Logger } from '@dunx/core';\\n\\nexport class AuditService {\\n  readonly seen: string[] = [];\\n\\n  constructor(private readonly logger: Logger) {}\\n\\n  record(name: string): void {\\n    this.seen.push(name);\\n    this.logger.info('greeted', { name, total: this.seen.length });\\n  }\\n}\\n```\\n\\n```ts\\n// src/greetings.service.ts\\nimport { AuditService } from './audit.service.js';\\n\\nexport class GreetingsService {\\n  constructor(private readonly audit: AuditService) {}\\n\\n  greet(name: string): { greeting: string } {\\n    this.audit.record(name);\\n    return { greeting: `hello, ${name}` };\\n  }\\n}\\n```\\n\\n```ts\\n// src/app.module.ts\\n@Module({\\n  controllers: [GreetingsController],\\n  providers: [GreetingsService, AuditService],\\n})\\nexport class AppModule {}\\n```\\n\\nOrder inside `providers` does not matter. The container resolves dependencies\\nrecursively, so `AuditService` is built before `GreetingsService` regardless of\\nwhere it appears in the list. What order does control is teardown, and\\n[Modules](dunx://guide/04-modules) covers that.\\n\\nForget to list `AuditService` and it still works: every class is injectable by\\ndefault and an unbound constructor self-binds.\\n\\nThat convenience has two sharp edges. A typo in a module's `providers` list goes\\nuncaught, and an abstract class that is injected but never bound gets constructed\\ninto a useless object rather than erroring.\\n[Providers](dunx://guide/03-providers) covers both.\\n\\n## Next\\n\\n[Providers](dunx://guide/03-providers) for how injection actually works and every shape of\\n`provide()`. [Modules](dunx://guide/04-modules) for composition, ordering and dynamic\\nmodules. [Controllers](dunx://guide/05-controllers) for routing, validation and errors.\\n\\nThe four example applications in the repository are a ladder:\\n[`examples/minimal`](https://github.com/petarzarkov/dunx/blob/main/examples/minimal) is this app,\\n[`examples/databases`](https://github.com/petarzarkov/dunx/blob/main/examples/databases) sets up SQLite, Postgres and\\nMySQL, [`examples/testing`](https://github.com/petarzarkov/dunx/blob/main/examples/testing) covers overrides and guards,\\nand [`examples/full`](https://github.com/petarzarkov/dunx/blob/main/examples/full) is every package in one long-running\\nservice.\\n\"},{\"slug\":\"03-providers\",\"title\":\"Providers\",\"summary\":\"A provider is anything the container can hand you: a service, a repository, a configuration object, a database connection.\",\"sections\":[\"How constructor injection works\",\"When the type cannot be recovered\",\"`inject()`, the escape hatch\",\"`provide()` in all its shapes\",\"Tokens\",\"Scope: singletons, and only singletons\",\"Eager resolution\",\"Lifecycle\",\"Ordering\",\"Cycles\",\"Duplicate bindings\",\"Overrides, for tests\",\"Next\"],\"body\":\"# Providers\\n\\nA provider is anything the container can hand you: a service, a repository, a\\nconfiguration object, a database connection. Most of them are plain classes listed\\nin a module's `providers`, and injecting one is a constructor parameter with no\\nannotation of any kind.\\n\\n```ts\\nexport class UsersService {\\n  constructor(private readonly repo: UsersRepository) {}\\n}\\n```\\n\\nNo `@Injectable()`. No `@Inject()`. No `reflect-metadata`.\\n\\n## How constructor injection works\\n\\nAdd one line to `bunfig.toml`:\\n\\n```toml\\npreload = [\\\"@dunx/transform/preload\\\"]\\n```\\n\\n`@dunx/transform` reads each class's constructor parameter types as the file\\nloads and records them on the class. The container resolves them before calling\\n`new`. Nothing annotates the class, and nothing annotates the parameter.\\n\\nThree consequences you can rely on:\\n\\n- **Declaration order does not matter.** The record is evaluated at resolution\\n  time, so a dependency declared later in the same file, or reached across a\\n  circular import, resolves normally. There is no `forwardRef` in dunx.\\n- **A genuine cycle is still an error.** `A` needing `B` while `B` needs `A`\\n  fails at boot with the full path. See [Cycles](#cycles).\\n- **An unrecoverable type is a boot error**, not a silent `undefined`. See\\n  [When the type cannot be recovered](#when-the-type-cannot-be-recovered).\\n\\nA class with constructor parameters and no record means the preload never ran,\\nand the container says so at boot with the snippet above.\\n\\nIt checks the entrypoint before choosing that snippet. The plugin's filter is\\n`/\\\\.tsx?$/`, so it never sees an emitted `.js` no matter how it is preloaded. When\\n`Bun.main` ends in `.js`, `.cjs` or `.mjs` the message says the tree is prebuilt and\\nprints the build-time fix instead:\\n\\n```\\nimport { depsPlugin } from '@dunx/transform';\\nawait Bun.build({ /* ... */ plugins: [depsPlugin] });\\n```\\n\\nHow the transform rewrites the source, and why the record is a thunk:\\n[Dependency injection](https://github.com/petarzarkov/dunx/blob/main/docs/architecture/dependency-injection.md).\\n\\n### Inheritance\\n\\n`readDeps` does a plain prototype-chain lookup rather than `Object.hasOwn`. A\\nsubclass that declares no constructor of its own inherits its base's constructor,\\nso it must inherit the base's dependencies with it:\\n\\n```ts\\nexport abstract class Repository {\\n  constructor(protected readonly db: Database) {}\\n}\\n\\n// No constructor. Inherits Repository's, and its dependency record with it.\\nexport class UsersRepository extends Repository {\\n  findAll() {\\n    return this.db.select().from(users);\\n  }\\n}\\n```\\n\\nA subclass that _does_ declare a constructor gets its own record from the\\ntransform, which shadows the base's.\\n\\n`@Module` uses the opposite rule. Module options are read with `Object.hasOwn`,\\nso subclassing a module does not silently inherit its bindings. Constructors are\\ninherited by the language and dependencies follow them. Module options are not.\\n\\n## When the type cannot be recovered\\n\\nThe transform reads names out of source text. A parameter whose type names nothing\\nthat exists at runtime is recorded as `unresolved`, along with the parameter's\\noriginal text, and becomes a boot error naming it:\\n\\n```\\nUsersService cannot be constructed: parameter 2 (private readonly cfg: AppConfig)\\nnames nothing that exists at runtime, so there is no token to resolve. Replace the\\ntype with an abstract class, or bind it with token() and declare the parameter as\\nthat token.\\n```\\n\\nSix cases are detected this way:\\n\\n| Parameter type             | Why it is erased                                   |\\n| -------------------------- | -------------------------------------------------- |\\n| a local `interface`        | Interfaces have no runtime value                   |\\n| a local `type` alias       | Same                                               |\\n| a type-only import         | `import type { X }` emits nothing                  |\\n| an inline `type` specifier | `import { type X }` emits nothing for `X`          |\\n| a class type parameter     | `class Box<T> { constructor(x: T) {} }` erases `T` |\\n| a primitive or a union     | `number`, `string`, `A \\\\| B` are not tokens        |\\n\\nFor comparison, `emitDecoratorMetadata` given\\n`constructor(db: Db, cache: Cache, n: number)` yields `[\\\"Db\\\", \\\"Object\\\", \\\"Number\\\"]`.\\nAn interface degrades to `Object` and a primitive to `Number`, indistinguishably.\\nA metadata-driven container then needs `@Inject(TOKEN)` for everything that is\\nnot a class. The dunx transform reads the difference from source and names the\\nparameter.\\n\\nThe fix is one of two things. If the erased type is a contract implemented\\nelsewhere, make it an `abstract class`, which is a runtime value and therefore a\\nusable token:\\n\\n```ts\\n// Not `interface Clock`.\\nexport abstract class Clock {\\n  abstract now(): Date;\\n}\\n\\nexport class SystemClock extends Clock {\\n  now(): Date {\\n    return new Date();\\n  }\\n}\\n\\n// In a module:\\nprovide(Clock, { useClass: SystemClock });\\n\\n// At the injection site, unchanged:\\nexport class Invoices {\\n  constructor(private readonly clock: Clock) {}\\n}\\n```\\n\\n`Logger` and `RequestContext` in `@dunx/core` are both abstract classes for this\\nreason, and [`examples/full`](https://github.com/petarzarkov/dunx/blob/main/examples/full) uses zero `token()` calls for\\nservices.\\n\\nIf there is genuinely no class worth writing, use `token()` and reach it with\\n`inject()`. Both are below.\\n\\n## `inject()`, the escape hatch\\n\\n`inject(token)` resolves a value from inside a field initializer:\\n\\n```ts\\nimport { inject, Logger, type OnInit } from '@dunx/core';\\nimport { BUILD_STAMP, FEATURE_FLAGS } from './tokens.js';\\n\\nexport class BuildInfo implements OnInit {\\n  readonly #stamp = inject(BUILD_STAMP);\\n  readonly #flags = inject(FEATURE_FLAGS);\\n\\n  constructor(private readonly logger: Logger) {}\\n\\n  onInit(): void {\\n    this.logger.info(\\n      `build ${this.#stamp.revision}, flags [${[...this.#flags].join(', ')}]`,\\n    );\\n  }\\n}\\n```\\n\\nBoth mechanisms may appear in one class. Use `inject()` when there is no\\nconstructor parameter for the value to hang off. In practice that means a\\n`Token<T>`: a token is a value rather than a type, so it cannot be a parameter\\ntype and the transform has nothing to record.\\n\\nThe window is narrow. Constructor arguments resolve _before_ the injector is\\nmade ambient, since argument resolution recurses back through `get()` and must\\nnot see the class being built as its own scope. A module-level current injector\\nis then set around the `new Klass()` call, so an `inject()` in a field\\ninitializer resolves against it.\\n\\nField initializers run synchronously inside the constructor, so this costs no\\nasync gap and no `AsyncLocalStorage`.\\n\\nCalling it anywhere else throws:\\n\\n```\\ninject(Clock) was called outside of construction. inject() only works in a field\\ninitializer or constructor of a class the container builds, because that is what\\ndecides which module scope the token resolves from.\\n```\\n\\n**A factory cannot use `inject()`.** After a factory's first `await`, the\\nmodule-level current injector is no longer its own. Declare factory dependencies\\nwith `inject: [...]` on the provider instead. Despite the shared name, that\\noption and the `inject()` function are separate mechanisms.\\n\\nBoth paths go through the same `get()`, so cycle detection, duplicate-binding\\nrejection and the async-factory retry apply identically whether a dependency\\narrived as a constructor parameter or as an `inject()` call.\\n\\n## `provide()` in all its shapes\\n\\nA bare class in `providers` is shorthand for binding it to itself, and that covers\\nmost of an application. `provide()` is for the rest: a token, a constant, a\\ncomputed value, or an implementation chosen at wiring time.\\n\\n```ts\\nimport { Module, provide } from '@dunx/core';\\n\\n@Module({\\n  providers: [\\n    // useValue: a constant, resolved before anything asks for it.\\n    provide(FEATURE_FLAGS, {\\n      useValue: new Set(['transactions', 'websockets']),\\n    }),\\n\\n    // useFactory: computed once, at boot, from other bindings.\\n    provide(BUILD_STAMP, {\\n      useFactory: (config: AppConfigService): BuildStamp => ({\\n        startedAt: new Date().toISOString(),\\n        revision: `${config.get('appName')}-dev`,\\n      }),\\n      inject: [AppConfigService] as const,\\n    }),\\n\\n    // useClass: the long form of listing the bare class.\\n    provide(BuildInfo, { useClass: BuildInfo }),\\n\\n    // The shorthand for the line above.\\n    WiringDemo,\\n  ],\\n})\\nexport class WiringModule {}\\n```\\n\\nThree kinds, and the list is complete.\\n\\n`useValue` is checked against the token's type. `provide()` stays a _call_ rather\\nthan a `{ provide, useValue }` object literal because per-element type inference\\nacross a heterogeneous array requires one. The object-literal form is untyped for\\nwant of it.\\n\\n`useFactory` takes its dependencies from `inject`, positionally, with no generics\\nwritten by hand. The factory's parameters are typed from the tuple. A factory may\\nbe `async`, and the container awaits it before any constructor that needs it runs.\\n\\n`useClass` binds one token to a different constructor, which is how an abstract\\ncontract gets an implementation and how a test override swaps one without touching\\nthe module.\\n\\n**There is no `useExisting`.** Alias one token to another with\\n`provide(Alias, { useFactory: (real) => real, inject: [Real] })`. `ConfigModule`\\nuses that to bind both `ConfigService` and your subclass to one instance.\\n\\n## Tokens\\n\\nThree ways to name a binding, in order of preference.\\n\\n**A concrete class.** Nothing to declare. An unbound class self-binds, so\\n`constructor(private readonly repo: UsersRepository)` works whether or not\\n`UsersRepository` appears in any `providers` list.\\n\\n**An abstract class**, for a contract whose implementation is chosen elsewhere. It\\nis a runtime value, so it works as a token; it cannot be constructed, so the\\ncontainer will not self-bind it by accident. `Logger` and `RequestContext` in\\n`@dunx/core` are both this.\\n\\n**`token<T>(description)`**, only for what has no runtime value to name:\\n\\n```ts\\nimport { token, type Token } from '@dunx/core';\\n\\nexport interface BuildStamp {\\n  readonly startedAt: string;\\n  readonly revision: string;\\n}\\n\\nexport const BUILD_STAMP: Token<BuildStamp> = token<BuildStamp>('BuildStamp');\\nexport const FEATURE_FLAGS: Token<ReadonlySet<string>> =\\n  token<ReadonlySet<string>>('FeatureFlags');\\n```\\n\\n`token<T>()` returns a unique object. The description is only a label for error\\nmessages, so two `token<Config>('config')` calls are two distinct tokens and\\nnominal collision is impossible. No prefixing convention is needed.\\n\\nThe reason it is last on the list: a `Token<T>` cannot be written as a constructor\\nparameter type, so the transform cannot see it and `inject()` becomes the only way\\nto reach it. That asymmetry is why a class is better whenever a class exists.\\n\\n### The self-binding hole\\n\\nEvery class is injectable by default, which is convenient and has one sharp edge\\nworth publishing.\\n\\n`abstract` does not exist at runtime. An abstract class that is injected but never\\nbound therefore gets self-bound and constructed into a useless object rather than\\nerroring. TypeScript blocks it in the `providers` array, because a bare entry must\\nbe constructible, but not at the `inject()` call site.\\n\\nThe same shape appears with options classes: a class whose constructor arguments\\nare all optional resolves successfully when nothing bound it, so\\n`app.get(QueueOptions)` on a container with no `QueueModule` returns defaults\\nrather than throwing. Any presence check for a class-shaped token has that hole.\\n\\nA self-bind lands in **the scope that asked for it** rather than in a global\\npool. Two modules that each inject an unlisted collaborator get one each, so an\\naccidental instance stays local instead of leaking across features.\\n\\nAn unbound token that is _not_ a class fails cleanly, and the message is answered\\nfrom the whole graph:\\n\\n```\\nCannot resolve BuildStamp for ReleaseService in module \\\"ReleaseModule\\\". Nothing in\\nthe module graph declares it. Bind it with provide() in a module's providers, and\\nexport it if the consumer is in a different module.\\n```\\n\\n## Scope: singletons, and only singletons\\n\\nEvery provider is a singleton **in the module that declares it**, for the\\nlifetime of the container. An importer resolving it through `exports` gets that\\nsame instance, so `DbConnection` exported by `DbModule` is one connection however\\nmany modules import it. Two modules that each _declare_ the same class get two\\ninstances: that is rebinding.\\n\\nThere is no `Scope.REQUEST`, no `Scope.TRANSIENT`, and no plan to add either.\\nRequest-scoped DI was measured and turned down as a container's largest source of\\ncomplexity and per-request cost.\\n\\nPer-request state travels as an explicit argument. Correlation data travels\\nthrough `RequestContext`, an `AsyncLocalStorage` that never touches the\\ncontainer.\\n\\nFull lifetime, boot order, hooks and error propagation: [Lifecycle](dunx://guide/07-lifecycle).\\n\\n## Eager resolution\\n\\n`AppFactory.create()` instantiates every declared binding and awaits every async\\nfactory before it returns, so wiring errors surface at boot rather than at first\\nrequest. There is no separate `init()`.\\n\\nTwo kinds of provider sit outside that. A class that self-binds because no module\\ndeclared it, and the `Logger` / `RequestContext` defaults the container promotes into\\nevery scope, are built on first `get`. A provider nothing ever asks for is therefore\\nnever constructed, and never gets an `onInit` or an `onShutdown`.\\n\\nThat is also what keeps `inject()` synchronous: by the time any constructor runs,\\nevery async provider has resolved.\\n\\nThe mechanism leaks into one rule you have to follow, so it is worth a paragraph.\\nThere is no static graph to topologically sort: `inject()` calls are discovered\\nonly by running field initializers.\\n\\nConstruction is therefore recursive and synchronous. An async factory reached\\nfrom inside a constructor parks its promise, throws a private signal to unwind,\\nand the async caller awaits that token and _retries_ the construction. Each retry\\nresolves at least one more async binding, so it terminates in at most one pass\\nper async dependency. Parking the promise before throwing keeps any factory from\\nrunning twice.\\n\\n**The rule that follows: field initializers must stay pure wiring.** A constructor\\naborted by that retry runs its already-evaluated field initializers again. An\\n`inject()` call is fine. Incrementing a counter, pushing to a shared array or\\nopening a socket in a field initializer is not.\\n\\n## Lifecycle\\n\\nThree hooks, all structural. Implement the method and the container finds it; the\\n`implements` clause only makes TypeScript check the signature. `OnInit` and\\n`OnShutdown` are below; `OnBeforeShutdown` runs while the server is still accepting\\nand is covered in [Lifecycle](dunx://guide/07-lifecycle).\\n\\n```ts\\nimport type { OnInit, OnShutdown } from '@dunx/core';\\n\\nexport class Connection implements OnInit, OnShutdown {\\n  #handle: Handle | undefined;\\n\\n  async onInit(): Promise<void> {\\n    this.#handle = await open();\\n  }\\n\\n  async onShutdown(): Promise<void> {\\n    await this.#handle?.close();\\n  }\\n}\\n```\\n\\nBoth may return a promise, and both are awaited.\\n\\nNote the split of responsibilities. Anything that must exist before a constructor\\nruns belongs in a `useFactory`, because factories are awaited during resolution.\\n`onInit` runs after the _entire_ graph is constructed, which makes it the right\\nplace for work that depends on peers being ready: running migrations, seeding,\\nsubscribing, or logging what the app resolved to.\\n\\n## Ordering\\n\\nConstruction order is dependency order, and it is recorded as construction\\n_completion_ order: a value is appended to the container's list once it exists, so\\na dependency always appears before its dependent.\\n\\nTwo things follow.\\n\\n`onInit` runs in that order. A provider's dependencies have already had their\\n`onInit` called by the time its own runs.\\n\\n`onShutdown` runs in exactly reverse order. A database connection constructed\\nearly is torn down last, after every repository that uses it. Reversing\\nconstruction-completion order is already a dependency-aware teardown, so\\n`app.shutdown()` needs no separate pass.\\n\\nFor an HTTP application there are three steps in front of that.\\n`HttpApp.shutdown()` runs the container's `drain()`, then stops the `Bun.serve`\\nserver, then closes `PubSub`, then delegates to the container's teardown. Draining\\nbefore the port closes is what lets a readiness probe fail while the server is still\\nanswering; requests in flight then finish against providers that are still alive.\\n\\nBeyond dependency order, the order tokens are _registered_ decides the rest, and\\nthat is a module-graph question. [Modules](dunx://guide/04-modules) covers it: imports\\nregister before importers, so a module listed first in `imports` is constructed\\nfirst and torn down last.\\n\\n## Cycles\\n\\nA real dependency cycle is a boot error carrying the full path:\\n\\n```\\nCircular dependency: Alpha -> Beta -> Alpha\\n```\\n\\nthrown as `CircularDependencyError`, which carries the path as a\\n`readonly string[]` on `error.cycle`. Without the in-flight tracking that produces\\nit, a field-initializer\\ncycle would be unbounded recursion with an unreadable stack.\\n\\nTo be precise about what is and is not a cycle: a circular _import_ between two\\nfiles is fine, because the dependency record is a thunk. A circular _dependency_,\\nwhere two providers each need the other constructed first, is not, and no\\nmechanism can make it one. Break it by extracting the shared piece into a third\\nprovider, or by having one side depend on an event rather than an object.\\n\\n## Duplicate bindings\\n\\nA token has one binding **per module**, so the only thing left to reject is the same\\ntoken declared twice in one module:\\n\\n```\\nDuplicate binding for Options in module \\\"StoreModule\\\": it is declared twice in the\\nsame module. A DynamicModule unions its options with the ones its class's @Module\\ndecorator declares, so a forRoot() in each place is two bindings.\\n```\\n\\nTwo _different_ modules binding one token is legal per-module rebinding, and\\ngives two instances silently.\\n\\nTwo other shapes are legal but **warned** at boot, being more often a mistake\\nthan an intent: declaring what an import already exports, and importing one token\\nfrom two modules that disagree. [Modules](dunx://guide/04-modules) has all four cases in\\none table.\\n\\n## Overrides, for tests\\n\\n`AppFactory.create(root, { overrides })` replaces a binding **in place**, keyed by\\ntoken, in every scope that holds it:\\n\\n```ts\\nimport { createTestApp } from '@dunx/testing';\\nimport { provide } from '@dunx/core';\\n\\nconst app = await createTestApp({\\n  modules: [UsersModule],\\n  overrides: [provide(Clock, { useValue: new FixedClock('2026-01-01') })],\\n});\\n```\\n\\nEvery scope, so a test stubbing `Logger` does not have to know how many modules bind\\nit. There is no `in:` option to name one: where two scopes bind a token differently\\nand only one is meant, resolve through the module that matters instead.\\n\\nReplacement rather than addition, and the distinction matters twice over. The\\ndiscarded provider is never instantiated, so its `useFactory` never runs and its\\n`onInit` never fires. That is what makes overriding a database safe.\\n\\nAn override naming a **non-class** token nobody binds is an error rather than a\\nsilent no-op:\\n\\n```\\nNothing to override for DSN: no module in the graph binds it, and it is not a class,\\nso nothing self-binds it either. An override replaces a binding - it cannot add one,\\nbecause a token nobody bound is a token nothing under test resolves.\\n```\\n\\nA **class** token nobody bound is accepted, and registered lazily. A class self-binds\\non demand anyway, so the override is replacing the binding that would otherwise have\\nappeared rather than adding one. An abstract class counts as a class here: the check\\nis `typeof token === 'function'`.\\n\\n`Logger` and `RequestContext` are substituted too, so overriding `Logger` works in\\nan app that binds none. `@dunx/testing` ships a `RecordingLogger` for exactly\\nthat.\\n\\n## Next\\n\\n[Modules](dunx://guide/04-modules) for how providers are grouped, ordered and configured.\\n[Controllers](dunx://guide/05-controllers) for the providers that have routes on them.\\n\"},{\"slug\":\"04-modules\",\"title\":\"Modules\",\"summary\":\"A module is a scope: a named set of registrations that are private to it, plus a list of tokens it makes visible to whoever imports it.\",\"sections\":[\"`@Module` is a marker\",\"The five lists\",\"How a token resolves\",\"`exports` is the public surface\",\"Module middleware\",\"Two modules binding one token\",\"Traversal, ordering and deduplication\",\"Dynamic modules\",\"`forRoot` versus `forRootAsync`\",\"`ConfigModule`, end to end\",\"The root module, and what wraps it\",\"Next\"],\"body\":\"# Modules\\n\\nA module is a **scope**: a named set of registrations that are private to it, plus a\\nlist of tokens it makes visible to whoever imports it.\\n\\n```ts\\nimport { Module } from '@dunx/core';\\n\\n@Module({\\n  imports: [DatabaseModule],\\n  controllers: [UsersController],\\n  providers: [UsersService, UsersRepository],\\n  exports: [UsersService],\\n})\\nexport class UsersModule {}\\n```\\n\\n`UsersRepository` is not on the `exports` line, so nothing outside `UsersModule`\\ncan resolve it.\\n\\n## `@Module` is a marker\\n\\nThe decorator writes its options onto the class as a\\n`Symbol.for('dunx.module')` property and returns the class. The class is never\\ninstantiated. It has no constructor to inject into, no lifecycle hooks, and no\\nruntime behaviour. It exists to give a module a name for error messages.\\n\\nA class handed to `AppFactory.create` or to `imports` without the decorator is a\\nboot error:\\n\\n```\\nUsersModule is not a dunx module. Decorate it with @Module({ providers: [...] }),\\nor import a configured one from a static factory such as UsersModule.forRoot().\\n```\\n\\nOptions are read with `Object.hasOwn`, so **subclassing a module does not inherit\\nits bindings**. `class TestUsersModule extends UsersModule {}` throws the message\\nabove rather than quietly registering `UsersModule`'s providers. Constructor\\ndependencies follow the opposite rule, where a subclass does inherit;\\n[Providers](dunx://guide/03-providers) covers both.\\n\\n## The five lists\\n\\n| Key           | Contains                                                         |\\n| ------------- | ---------------------------------------------------------------- |\\n| `imports`     | Modules whose `exports` this one may resolve                     |\\n| `controllers` | Classes whose constructed instances are scanned for routes       |\\n| `providers`   | Everything else, private to this module unless exported          |\\n| `exports`     | The tokens - or whole modules - an importer may resolve          |\\n| `middleware`  | Middleware for **this module's** routes, resolved from its scope |\\n\\nplus one flag, `global: true`, which publishes this module's `exports` app-wide.\\n\\n`controllers` and `providers` are registered **identically**. Core constructs both\\nthe same way; the split exists so an HTTP adapter can ask which instances to scan.\\nThe only behavioural consequence: a class in `controllers` that declares no\\nroutes is a boot error telling you to move it to `providers`.\\n\\nA `controllers` entry is a bare class. A `providers` entry is a bare class, which\\nbinds it to itself, or a `Registration` from `provide()` - `providers` is the only\\nlist whose type admits one. See [Providers](dunx://guide/03-providers) for the shapes.\\n\\n## How a token resolves\\n\\nFor a provider declared by module `M`, asking for a token:\\n\\n1. `M`'s own `providers` and `controllers`.\\n2. The `exports` of the modules `M` imports, transitively through re-exports.\\n3. The global scope - the `exports` of every module marked `global: true`.\\n4. If the token is a **class** and **no module in the graph declares it**, it\\n   self-binds into `M`'s scope.\\n5. Otherwise it is a boot error, and the message names the fix.\\n\\nStep 4 tests the whole graph, not what `M` can see. A class some other module\\ndeclares but does not export to `M` is a boot error naming that module. Self-binding\\nit instead would hand `M` a second instance of a provider somebody already\\nconfigured, which is the bug the check exists to catch.\\n\\n**Local shadows imported.** If `M` declares a token an import also exports, `M`'s\\nbinding wins. This per-module rebinding is why the scope boundary exists: a\\n`Clock` bound one way in billing and another way in reporting costs two lines and\\none token.\\n\\nVisibility is flattened **once, at boot**, into one map per module. An import chain is\\nnever walked per lookup, so resolution stays the single `Map.get` it was before scopes\\nexisted, and the whole graph for `examples/full`, which is every feature the\\nframework has, builds in a median 1.7 ms.\\n\\n## `exports` is the public surface\\n\\n**Absent means nothing is exported.** A module with providers and no `exports` is\\nfully private.\\n\\n`exports` accepts a token or a **module reference**. A module reference\\nre-exports whatever that module exports, which is how a facade works:\\n\\n```ts\\n@Module({\\n  imports: [DbModule, RedisModule],\\n  exports: [DbModule, RedisModule],\\n})\\nexport class InfraModule {}\\n```\\n\\nAn importer of `InfraModule` sees the database and the cache without naming either.\\nRe-export cycles - `A` exports `B` and `B` exports `A` - are legal and terminate: an\\nexport set is a union, union only grows, so the sets are computed to a fixed point\\nrather than by recursion. There is no `forwardRef` for this or for anything else.\\n\\nExporting a token no module in reach provides is a boot error, raised where the\\nmistake is rather than in the module that later fails to resolve it:\\n\\n```\\nModule \\\"ReportsModule\\\" exports UsersRepository, but does not declare it and no\\nmodule it imports exports it. Add it to this module's providers, or import the\\nmodule that provides it.\\n```\\n\\n### `global: true`\\n\\nA global module's `exports` land in one global scope visible from every other scope,\\nwith no import needed. Its private providers stay private.\\n\\n```ts\\n@Module({ providers: [Clock], exports: [Clock], global: true })\\nexport class ClockModule {}\\n```\\n\\nA **field**, with no `@Global()` decorator beside it. A `DynamicModule` would\\nneed the field anyway, so a decorator would be a second spelling for one idea.\\n`ConfigModule.forRoot` sets it, configuration being the one thing every module\\nreads.\\n\\nGlobal is the weakest source: an import beats it, and a local declaration beats both.\\n\\n### The error is the feature\\n\\n`exports` reintroduces the most complained-about error in the Nest ecosystem, so dunx\\nanswers it from the whole graph, which it has at boot:\\n\\n```\\nCannot resolve UsersRepository in module \\\"ReportsModule\\\". \\\"UsersModule\\\" declares it\\nand \\\"ReportsModule\\\" imports that module, but it does not export UsersRepository. Add\\nUsersRepository to that module's exports, or move the provider into \\\"ReportsModule\\\".\\n```\\n\\nA dependency declared through `token()` gets one clause more, naming the class that\\nasked: `Cannot resolve Dsn for DataService in module \\\"DataModule\\\"`. A class token\\ndoes not, because the container re-raises the original error for those rather than\\nrewriting it.\\n\\nA token declared by a module you do **not** import says so instead, and names the\\n`imports` line to add. A token nothing declares says that, rather than blaming the\\nnearest module.\\n\\n## Module middleware\\n\\nA module can put middleware in front of the routes its own controllers declare:\\n\\n```ts\\n@Module({\\n  controllers: [ReportsController],\\n  providers: [ReportsService, TenantPolicy, TenantGuard],\\n  middleware: [TenantGuard],\\n  exports: [ReportsService],\\n})\\nexport class ReportsModule {}\\n```\\n\\n`TenantGuard` is resolved from `ReportsModule`'s scope, so it injects `TenantPolicy`,\\nwhich no other module can see. There is no `forRoutes()` and no path matching: a\\nmodule already owns its controllers, so the routes it applies to are the routes those\\ncontrollers declare.\\n\\n**There is no inheritance.** A module's middleware applies to its own controllers and\\nto nothing it imports, so importing a module never changes the request path of the\\nimporter's routes. Middleware that really is app-wide stays app-wide, in\\n`HttpFactory.create(root, { middleware })`.\\n\\nOne field rather than `middleware` plus `guards`, because a guard here is middleware\\nthat throws. [Middleware and guards](dunx://guide/08-middleware-and-guards) has the full chain.\\n\\n## Two modules binding one token\\n\\nUnder scopes this is legal - it is the rebinding the boundary exists to allow - so the\\nold blanket duplicate check split into one error and two warnings:\\n\\n| Case                                                   | What happens                        |\\n| ------------------------------------------------------ | ----------------------------------- |\\n| The same token twice **in one module**                 | boot error                          |\\n| Two **different** modules each declaring it            | legal and silent: two instances     |\\n| A module declaring what an import also exports to it   | legal, and **warned once** at boot  |\\n| A module importing it from **two** modules that differ | legal, last import wins, and warned |\\n\\nThe warnings are on `app.warnings` and logged at boot. They exist because \\\"my\\noverride is not being used\\\" is otherwise unexplainable; Nest is silent here and it\\ncosts people hours. A diamond - two imports that re-export the _same_ binding - stays\\nsilent, because there is only one answer.\\n\\n```\\nModule \\\"ReportsModule\\\" declares Clock, which module \\\"ClockModule\\\" also exports to\\nit. The local one wins, so these are two separate instances. Remove one, or ignore\\nthis if the rebinding is deliberate.\\n```\\n\\n## Traversal, ordering and deduplication\\n\\n`AppFactory.create(RootModule)` flattens the import graph depth-first, visiting\\n**imports before importers**, so a module's dependencies register before it does.\\nEach reference is visited once.\\n\\n```ts\\n@Module({\\n  imports: [\\n    ConfigModule.forRoot({ validate, as: AppConfigService }),\\n    LoggerModule.forRootAsync({ useFactory, inject: [AppConfigService] }),\\n    DatabaseModule,\\n    UsersModule,\\n    HealthModule,\\n  ],\\n})\\nexport class AppModule {}\\n```\\n\\nRead that list top to bottom as construction order and bottom to top as shutdown\\norder. Config and the logger are built first and torn down last; the database\\noutlives every feature that queries it. That is the practical reason to care about\\n`imports` order at all, and the reason a long-running service should put its\\ninfrastructure at the top.\\n\\nTo be precise: within the container, a dependency is always constructed before its\\ndependent regardless of where either was registered, because resolution recurses.\\nRegistration order decides the rest, which is everything not pinned by a\\ndependency edge. Teardown reverses construction completion order exactly.\\n\\nVisiting each reference once is what makes two other shapes work. A diamond, where\\ntwo modules both import `SharedModule`, gives one scope that both see. A cycle in\\nthe import graph terminates instead of recursing, and is legal - a module cycle is\\nnot a provider cycle, and only the second is an error.\\n\\n**Deduplication is per reference rather than per module identity.** A bare class\\nis one reference however many modules import it, and the same `DynamicModule` _object_\\nimported twice is likewise one reference. Two _different_ configurations of the\\nsame module are two objects, and each gets **its own scope**:\\n\\n```ts\\n@Module({\\n  imports: [\\n    StoreModule.forRoot({ bucket: 'uploads' }),\\n    StoreModule.forRoot({ bucket: 'reports' }),\\n  ],\\n})\\nclass Root {}\\n```\\n\\nTwo scopes, two `Options` bindings, two `Store` instances. Under the flat\\ncontainer this was a duplicate-binding error. The importer above sees `Store`\\nexported from both, so it is warned that the last one wins:\\n\\n```\\nModule \\\"Root\\\" imports Store from both \\\"StoreModule\\\" and \\\"StoreModule\\\". The last\\nimport wins, so these are two separate instances. Import one, or declare it here.\\n```\\n\\nImport each configuration from the consumer that needs it. One module importing\\nboth can only see one of them.\\n\\n**A `DynamicModule` unions its options with its own class's decorator.** If\\n`Root.forRoot()` returns `{ module: Root, providers: [...] }` and `Root` is also\\ndecorated with `@Module({ providers: [...] })`, both sets are collected. The\\ndynamic options do not replace the declared ones:\\n\\n```ts\\n@Module({ providers: [provide(A, { useValue: 'from the decorator' })] })\\nclass Root {\\n  static dyn(): DynamicModule {\\n    return {\\n      module: Root,\\n      providers: [provide(B, { useValue: 'from the static' })],\\n    };\\n  }\\n}\\n\\n// Both A and B resolve.\\nawait AppFactory.create(Root.dyn());\\n```\\n\\nThat matches the convention, and it is the reason the warning above fires most often:\\na `ConfigModule.forRoot()` in the decorator's `imports` and another in the static's\\nis two configurations of one module. Put it in one place or the other.\\n\\n## Dynamic modules\\n\\nA `DynamicModule` is a plain object: a module class for identity, plus the same\\noption lists.\\n\\n```ts\\nexport interface DynamicModule extends ModuleOptions {\\n  readonly module: ModuleClass;\\n}\\n```\\n\\n`ModuleOptions` is the same five lists plus `global`, so a configured module exports,\\ngoes global and declares middleware exactly as a decorated one does.\\n\\nThe convention is a static factory named `forRoot`:\\n\\n```ts\\nimport { provide, type DynamicModule } from '@dunx/core';\\n\\nexport class MailerOptions {\\n  constructor(\\n    readonly apiKey: string,\\n    readonly from: string,\\n  ) {}\\n}\\n\\nexport class Mailer {\\n  constructor(private readonly options: MailerOptions) {}\\n\\n  send(to: string, body: string): Promise<void> {\\n    return post(this.options.apiKey, this.options.from, to, body);\\n  }\\n}\\n\\nexport class MailerModule {\\n  static forRoot(options: MailerOptions): DynamicModule {\\n    return {\\n      module: MailerModule,\\n      providers: [provide(MailerOptions, { useValue: options }), Mailer],\\n      exports: [Mailer],\\n    };\\n  }\\n}\\n```\\n\\n```ts\\n@Module({\\n  imports: [\\n    MailerModule.forRoot(new MailerOptions(key, 'noreply@example.com')),\\n  ],\\n})\\nexport class AppModule {}\\n```\\n\\n`exports: [Mailer]` is required for an importer to resolve it. `MailerOptions`\\nstays private; an importer has no business resolving another module's options.\\n\\nThe `module` field is the identity. It is what error messages name and what lets\\ntraversal tell two configurations of one module apart. Registrations from a\\nconfigured module are **merged** with whatever the class's own `@Module` decorator\\ndeclares, so a module can have a static core plus configured extras. A class used\\nonly through its factory, like `MailerModule` above, needs no decorator at all.\\n\\n## `forRoot` versus `forRootAsync`\\n\\nThe `forRootAsync` pattern exists to build a module's options from other injected\\nproviders, asynchronously. It needs a distinct mechanism because a container resolves\\nlazily and has to defer.\\n\\n**dunx has no such mechanism, and does not need one.** Resolution is eager and\\nevery async factory is settled before any constructor runs, so \\\"options computed\\nfrom another provider\\\" is already just a provider:\\n\\n```ts\\nimport {\\n  provide,\\n  type AsyncModuleConfig,\\n  type Deps,\\n  type DynamicModule,\\n} from '@dunx/core';\\n\\nexport class MailerModule {\\n  static forRoot(options: MailerOptions): DynamicModule {\\n    return {\\n      module: MailerModule,\\n      providers: [provide(MailerOptions, { useValue: options }), Mailer],\\n      exports: [Mailer],\\n    };\\n  }\\n\\n  static forRootAsync<const D extends Deps>(\\n    config: AsyncModuleConfig<MailerOptions, D>,\\n  ): DynamicModule {\\n    return {\\n      module: MailerModule,\\n      ...(config.imports === undefined ? {} : { imports: config.imports }),\\n      providers: [provide(MailerOptions, config), Mailer],\\n      exports: [Mailer],\\n    };\\n  }\\n}\\n```\\n\\nTwo lines differ. There is no deferred-options token, no `ASYNC_OPTIONS_TYPE`, no\\nsecond code path in the module, and the container does not know the difference.\\n\\n`AsyncModuleConfig` is `FactoryProvider` plus an `imports` field, and that field is\\nthere because of scoping: the factory is **written** at the call site but **runs** in\\nthe configured module's scope, so whatever it injects has to be visible from there.\\n`ConfigModule` is `global: true`, so the common case needs nothing; a factory reading\\nsome other module's export passes `imports: [ThatModule]`.\\n\\nSo why does the name exist at all? Because reading options off `ConfigService` is\\nthe one thing a zero-argument options object cannot do, and `forRootAsync` is the\\nconventional name for that.\\n\\nEvery configured module in the framework has one:\\n\\n- `@dunx/infra`: `LoggerModule`, `DbModule`, `RedisModule`, `QueueModule`,\\n  `ScheduleModule`, `FilesModule`, `ImagesModule`\\n- `@dunx/http`: `HealthModule`, `HttpClientModule`, `StaticModule`\\n- `AuthModule`, `OpenApiModule`, `DashboardModule`\\n\\n```ts\\n@Module({\\n  imports: [\\n    ConfigModule.forRoot({ validate, as: AppConfigService }),\\n    RedisModule.forRootAsync({\\n      useFactory: (config: AppConfigService) => {\\n        const { url } = config.get('redis');\\n        return {\\n          ...(url === undefined ? {} : { url }),\\n          connectionTimeout: 500,\\n          maxRetries: 0,\\n        };\\n      },\\n      inject: [AppConfigService] as const,\\n    }),\\n  ],\\n})\\nexport class InfraModule {}\\n```\\n\\nThe `useFactory` may be `async`. By the time any repository's constructor runs,\\nthe connection is open and its options applied. That guarantee is what removes the\\nsecond mechanism.\\n\\nOne shipped variant takes an extra first argument. Check it before writing your\\nown:\\n\\n```ts\\nDbModule.forRootAsync(SyncDatabase, {\\n  useFactory: (config: AppConfigService) =>\\n    new SyncSqliteOptions({\\n      schema,\\n      filename: config.get('database').file,\\n      pragmas: ['foreign_keys = ON'],\\n    }),\\n  inject: [AppConfigService],\\n});\\n```\\n\\nThe token comes first because _which_ drizzle class the database binds to only\\nbecomes knowable once the options factory has run, which is too late to register a\\nprovider under it. If your own module's token depends on its own options, you have\\nthe same problem and the same fix.\\n\\n## `ConfigModule`, end to end\\n\\n`ConfigModule` is the dynamic module most applications import first, and it shows\\nevery idea on this page at once.\\n\\n```ts\\n// src/config.ts\\nimport { ConfigService, type ConfigSource } from '@dunx/core';\\nimport { z } from 'zod';\\n\\nconst envSchema = z.object({\\n  PORT: z.coerce.number().int().min(0).max(65535).default(3000),\\n  DATABASE_FILE: z.string().default(':memory:'),\\n  CORS_ORIGIN: z.string().default('https://example.com'),\\n});\\n\\nexport interface AppConfig {\\n  readonly port: number;\\n  readonly corsOrigin: string;\\n  readonly database: { readonly file: string };\\n}\\n\\nexport class AppConfigService extends ConfigService<AppConfig> {}\\n\\nexport const validate = (env: ConfigSource): AppConfig => {\\n  const parsed = envSchema.safeParse(env);\\n  if (!parsed.success) {\\n    const issues = parsed.error.issues\\n      .map((issue) => `${issue.path.join('.') || '(root)'}: ${issue.message}`)\\n      .join('\\\\n - ');\\n    throw new Error(`Configuration is invalid:\\\\n - ${issues}`);\\n  }\\n  const value = parsed.data;\\n  return {\\n    port: value.PORT,\\n    corsOrigin: value.CORS_ORIGIN,\\n    database: { file: value.DATABASE_FILE },\\n  };\\n};\\n```\\n\\n```ts\\n@Module({\\n  imports: [ConfigModule.forRoot({ validate, as: AppConfigService })],\\n})\\nexport class AppModule {}\\n```\\n\\nFour things to take from it.\\n\\n**One validation function in place of a schema DSL.** `validate` receives the raw source\\nand returns the shaped, typed object. Whatever it throws is what boot fails with,\\nso throw something whose message names the wrong keys. zod is\\n`validate: (env) => schema.parse(env)`. A hand-written function works identically\\nand costs no dependency. dunx does not pick the library.\\n\\n**Flat variables in, a shaped object out.** `config.get('database')` hands back a\\ngroup rather than a lone string, because the validation step is where flattening\\nstops. Nothing downstream reads `process.env`.\\n\\n**There is no loader and no `dotenv`.** The source defaults to `Bun.env`, which\\nalready carries `.env` and `.env.local` because Bun loads them itself. In a test,\\npass `source` rather than mutating the process environment:\\n\\n```ts\\nConfigModule.forRoot({ validate, source: { PORT: '0' } });\\n```\\n\\n**`as` is not optional in practice.** Declare a subclass and hand it over:\\n\\n```ts\\nexport class AppConfigService extends ConfigService<AppConfig> {}\\n```\\n\\nWithout it, `inject: [ConfigService]` resolves to\\n`ConfigService<Record<string, unknown>>` and a factory annotating\\n`ConfigService<AppConfig>` is rejected: parameters are contravariant and the\\ntoken carries no type argument to recover.\\n\\nA subclass is a distinct runtime value, so it serves as both a precise token and\\na usable constructor annotation. `ConfigService` stays bound to the same instance\\nthrough an alias provider, so library code that knows only the base contract\\nstill injects.\\n\\nThere is no `isGlobal` to pass, because `ConfigModule.forRoot` already sets\\n`global: true` and exports both `ConfigService` and whatever `as` names.\\nConfiguration is the one thing every module reads, so making each of them import it\\nwould be ceremony with no boundary behind it. And there is no\\n`ConfigModule.forRootAsync`, because eager resolution settles an async `validate`\\nbefore any constructor runs.\\n\\n## The root module, and what wraps it\\n\\n`AppFactory.create(root)` takes a module class or a `DynamicModule`. So does\\n`HttpFactory.create(root)`, which wraps your root in an internal module of its own\\nin order to bind `PubSub`, `ClientAddress` and, unless you turned it off,\\n`RequestLoggingMiddleware`. That wrapper is why those are injectable in an\\napplication that imported nothing.\\n\\n`ClientAddress` is bound rather than left to self-bind because an unbound class\\nself-binds into whichever scope asks first: `listen()` would attach the live server\\nto one instance while a second module's middleware injected another, and\\n`app.clientIp(req)` would throw on an instance that never got a server.\\n\\nThe wrapper is invisible to the boundary. Global middleware, `@UseGuards` classes\\nand an error filter all resolve as **your** root sees them, so listing a guard in\\n`HttpFactory.create` never obliges your root to re-export it. Anything named\\nthere is found in the one module that declares it, and two modules declaring it\\nis an error. `app.get()` resolves the same way.\\n\\nThe same technique is available to you. `OpenApiModule.forRoot({ root: AppModule, ... })`\\nwraps the root it documents, so `create()` is still handed one module reference and\\nthe generated document's own routes are discovered with the rest:\\n\\n```ts\\nconst app = await HttpFactory.create(\\n  OpenApiModule.forRoot({\\n    title: 'my-api',\\n    version: '0.1.0',\\n    root: AppModule,\\n  }),\\n);\\n```\\n\\n`@dunx/testing` does the same thing for a different reason: `createTestApp({ modules })`\\nmakes the modules under test the `imports` of one synthetic root, so no fixture\\nmodule has to be written by hand.\\n\\n## Next\\n\\n[Controllers](dunx://guide/05-controllers) for what a class in `controllers` does with its\\nroutes.\\n\"},{\"slug\":\"05-controllers\",\"title\":\"Controllers\",\"summary\":\"A controller is a provider with routes on it.\",\"sections\":[\"Bun does the routing\",\"How routes are found\",\"The verbs\",\"Path parameters\",\"Declared input\",\"Returning values\",\"Errors\",\"Application-level configuration\",\"Middleware, guards and metadata\",\"The fast path\",\"Request logging\",\"Next\"],\"body\":\"# Controllers\\n\\nA controller is a provider with routes on it. It is constructed by the container\\nlike anything else, injects like anything else, and the only thing that\\ndistinguishes it is being listed in a module's `controllers` rather than its\\n`providers`.\\n\\n```ts\\nimport { Controller, Get, Post, type Input } from '@dunx/http';\\nimport { z } from 'zod';\\nimport { UsersService } from './users.service.js';\\n\\nconst createUser = { body: z.object({ name: z.string().min(1) }) } as const;\\nconst oneUser = { params: z.object({ id: z.coerce.number().int() }) } as const;\\n\\n@Controller('users')\\nexport class UsersController {\\n  constructor(private readonly users: UsersService) {}\\n\\n  @Get('/')\\n  list(): Promise<readonly User[]> {\\n    return this.users.findAll();\\n  }\\n\\n  @Get('/:id', oneUser)\\n  one({ params }: Input<typeof oneUser>): Promise<User | null> {\\n    return this.users.find(params.id);\\n  }\\n\\n  @Post('/', createUser)\\n  create({ body }: Input<typeof createUser>): Promise<User> {\\n    return this.users.create(body.name);\\n  }\\n}\\n```\\n\\nThree routes, mounted at `GET /users`, `GET /users/:id` and `POST /users`. The\\nlast one answers 201.\\n\\n## Bun does the routing\\n\\n`Bun.serve({ routes })` handles path parameters, per-method dispatch, static\\n`Response` values and 404-on-method-miss in native Zig. dunx ships no router.\\n`@dunx/http` builds the `routes` object at boot and hands it to Bun.\\n\\nFour consequences worth knowing about.\\n\\n**An unmatched method returns 404 where most frameworks return 405.** Bun answers a\\nmethod miss natively only when nothing else can claim the request. dunx always\\ninstalls the `fetch` fallback described below, so a method miss reaches it, runs the\\nwhole global middleware chain and comes back as the framework's 404 - the same shape\\nas an unmatched path. Measured:\\n\\n```\\nGET     /thing   200   the route\\nOPTIONS /thing   ->    the fallback\\nPOST    /thing   ->    the fallback\\nGET     /nope    ->    the fallback\\n```\\n\\nThe status is 404 either way; what differs is that your middleware sees it, so\\nrequest logging, throttling and CORS all get a look at a method miss.\\n\\n**Paths are matched exactly, so a trailing slash is a different path.** `GET /t`\\nis a 200 and `GET /t/` is a 404. The same goes for `/t/sub/` and `POST /t/`.\\nNest, Express and Elysia accept both spellings; Fastify and Hono do not. A\\nclient ported from one of the first three hits a 404 that reads like a missing\\nroute.\\n\\nThe declared side is already normalised: `@Get('/')` inside `@Controller('t')` is\\n`/t`, never `/t/`, so both spellings are never live at once. Route discovery\\nstrips it too, so `@Get('sub/')` is `/t/sub`.\\n\\n`strict: false` serves both:\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule, { strict: false });\\n```\\n\\nIt registers a second key ending in `/`, pointing at the handlers the first one\\nalready has, so the request log, the metrics series and the OpenAPI document all\\nstill say `/t/:id`. Every route gets one except `/` and a wildcard mount, which\\nalready matches its own trailing slash.\\n\\n`strict` defaults to `true`, which is what `Bun.serve` matches on its own and\\nwhat Hono defaults to. A reverse-proxy rewrite in front of dunx does the same\\njob for a caller you do not control.\\n\\n**CORS preflight is mounted, not inferred.** An `OPTIONS` request does reach the\\nfallback. Answering preflight there would mean reconstructing which verbs the path\\ndeclares, after Bun has already failed to match it.\\n\\n`enableCors()` mounts an explicit `OPTIONS` handler on every path instead, built at\\nboot from the verbs that path declares. It cannot collide with one of yours: there is\\nno `OPTIONS` verb decorator.\\n\\n**A route collision is a boot error.** Bun silently lets one route win, so dunx\\nrejects a duplicate method-and-path pair before it can, naming both handlers:\\n\\n```\\nRoute collision: GET /users/:id is declared by UsersController.one and by\\nLegacyController.show. Bun would keep only one of them.\\n```\\n\\nThe check runs twice: at `create()` on the discovered paths, and again at\\n`listen()` on the final prefixed ones.\\n\\nA dunx application has exactly one `fetch` handler, and it does no routing. Bun\\nanswers an unmatched path itself, so without the fallback nothing in the\\nmiddleware chain would see a 404, leaving it invisible to request logging,\\nmetrics and tracing.\\n\\n`listen()` installs a fallback that runs the global middleware and returns\\n`{\\\"error\\\":\\\"NOT_FOUND\\\",\\\"status\\\":404}`. It runs only after Bun has decided nothing\\nmatched, so Bun still does every bit of the matching.\\n\\n## How routes are found\\n\\nThere is no registry and nothing accumulates at class-definition time. A method\\ndecorator sets a symbol property on the function it receives and returns it. At\\nboot, after the container has constructed the controller, the adapter walks the\\ninstance's prototype chain and collects every marked method.\\n\\nFive things fall out of doing it that way, and each one is a paper cut you will\\nnever hit:\\n\\n**No class decorator is required.** `@Controller` supplies a prefix and may be\\nomitted entirely. There is no `@Routes()` to remember, because nothing needs\\nclosing.\\n\\n**No import-order dependence and no cross-file leak.** An accumulator records\\nroutes as files evaluate; inspection reads what is there when it is asked.\\n\\n**Overriding a decorated base method works without re-decorating.** Discovery\\nfinds the base's marker, and dispatch lands on the override, because the handler\\nis bound off the constructed instance rather than off the prototype.\\n\\n**Most-derived wins on a repeated name.** An undecorated override does not shadow\\nits decorated base out of existence.\\n\\n**The prefix is inherited.** `prefixOf` reads through the prototype chain, so two\\nsubclasses of one decorated base collide loudly at boot instead of silently\\nmounting at the root.\\n\\nA class in `controllers` with no routes at all is a boot error:\\n\\n```\\nHealthService is registered as a controller but declares no routes. Add a\\n@Get/@Post/... method, or move it to providers.\\n```\\n\\n## The verbs\\n\\n`@Get`, `@Post`, `@Put`, `@Patch`, `@Delete`. Each takes a path, defaulting to\\n`/`, and an optional options object:\\n\\n```ts\\n@Get()                          // GET  <prefix>/\\n@Get('/active')                 // GET  <prefix>/active\\n@Get('/:id', oneUser)           // GET  <prefix>/:id, with a params schema\\n@Post('/', createUser)          // POST <prefix>/\\n```\\n\\nThe controller prefix and the method path are joined and normalised: duplicate\\nslashes collapse and a trailing slash is stripped, so `@Controller('users/')` plus\\n`@Get('/')` is `/users`.\\n\\nThe path may also be a **thunk** (`RoutePath` is `string | (() => string)`), read\\nat route discovery rather than at decoration.\\n\\nIt covers one situation: a path coming out of validated configuration is unknown\\nwhen a decorator's arguments are evaluated, and discovery runs after every\\nprovider has settled. `OpenApiModule.forRootAsync` is the caller, mounting its\\npage where `ConfigService` says. A thunk must answer the same path every call.\\n\\nThere is no `@Options` and no `@Head`. `HttpMethod` is\\n`'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE'`, and `OPTIONS` is reserved for the\\nCORS preflight handler.\\n\\n## Path parameters\\n\\nBun's own syntax, because Bun does the matching. Without a `params` schema they\\narrive as strings on `req.params`:\\n\\n```ts\\n@Get('/:name')\\none({ req }: Input<RouteSchemas>): { greeting: string } {\\n  return { greeting: `hello, ${req.params['name'] ?? 'world'}` };\\n}\\n```\\n\\nDeclare a `params` schema and they arrive typed, validated and coerced on\\n`params`:\\n\\n```ts\\nconst oneUser = { params: z.object({ id: z.coerce.number().int().min(1) }) } as const;\\n\\n@Get('/:id', oneUser)\\nasync one({ params }: Input<typeof oneUser>): Promise<User> {\\n  // Already a number. The schema coerced it before this ran.\\n  const user = await this.users.find(params.id);\\n  if (user === null) {\\n    throw new HttpError(HttpStatusCode.NOT_FOUND, `No user ${params.id}`);\\n  }\\n  return user;\\n}\\n```\\n\\n`z.coerce` is where `:id` stops being a string. Path parameters are always strings\\non the wire, so a schema that expects a number without coercion will reject every\\nrequest.\\n\\n## Declared input\\n\\nThe second argument to a verb declares what the route accepts. Declaring a schema\\nis what makes the matching `input` field exist, get parsed and get validated;\\nomitting one means the framework never touches it.\\n\\n```ts\\nexport interface RouteSchemas {\\n  readonly body?: StandardSchemaV1;\\n  readonly query?: StandardSchemaV1;\\n  readonly params?: StandardSchemaV1;\\n  /** Overrides the default success status: 201 for POST, 200 otherwise. */\\n  readonly status?: number;\\n}\\n```\\n\\n| Field    | Source                                   | Present when      |\\n| -------- | ---------------------------------------- | ----------------- |\\n| `req`    | the `BunRequest`                         | always            |\\n| `body`   | parsed by `content-type`, then validated | `body` declared   |\\n| `query`  | the query string, then validated         | `query` declared  |\\n| `params` | `req.params`, then validated             | `params` declared |\\n\\nThe parameter takes either shape. Destructuring is the usual one, and a handler\\nthat passes the request on names the whole object instead:\\n\\n```ts\\n@Post('/', createNote)\\ncreate({ body }: Input<typeof createNote>): Note {\\n  return this.notes.add(body.text);\\n}\\n\\n@Post('/', createNote)\\nrecord(input: Input<typeof createNote>): Note {\\n  return this.audit.write(input);\\n}\\n```\\n\\nValidation targets the **Standard Schema** spec (`~standard.validate`), restated\\nin `@dunx/http`'s own types rather than depended on: the spec is an interface and\\n`@standard-schema/spec` ships nothing but declarations.\\n\\nzod 4, Valibot and ArkType therefore drop straight in while `@dunx/http` keeps\\nzero dependencies. Anything with a `~standard` property qualifies, including a\\nhand-written object and a bridged compiled checker.\\n\\nA `~standard.validate` may return a promise and the reader handles that, though\\nnone of zod, Valibot or ArkType ever does. Measured, and it lets a `query`-only\\nor `params`-only route validate without allocating a promise.\\n\\n### Why `Input<typeof opts>` has to be written out\\n\\nA TypeScript limit rather than a design choice, and the one piece of ceremony\\ndunx could not remove.\\n\\nA standard method decorator is\\n`(value: V, ctx: ClassMethodDecoratorContext) => V | void`. It can _reject_ a\\nmismatched `V`, but it has no way to contextually type an unannotated parameter.\\nDecorators observe; they do not type. Measured with `tsc`, because this is a\\ntype-level claim `bun` cannot answer:\\n\\n| Handler                       | Result                                                        |\\n| ----------------------------- | ------------------------------------------------------------- |\\n| annotated correctly           | compiles                                                      |\\n| unannotated parameter         | `TS7006: Parameter 'input' implicitly has an 'any' type`      |\\n| unannotated destructured      | `TS7031: Binding element 'body' implicitly has an 'any' type` |\\n| annotated with the wrong type | `TS1241` + `TS1270`, naming the mismatched property           |\\n\\nSo the annotation is required. What makes it cheap is that `Input<O>` is a\\ntype-level function over the options object, so every field type still comes from\\nthe schema and nothing is declared twice:\\n\\n```ts\\nconst createNote = { body: CreateNote, status: HttpStatusCode.CREATED } as const;\\n\\n@Post('/', createNote)\\ncreate({ body }: Input<typeof createNote>): Note {\\n  return this.notes.add(body.text); // body.text is string\\n}\\n```\\n\\n`Input<O>` reads the options object's **declared** type, so the one thing you must\\nnot do is annotate that constant as `RouteSchemas`:\\n\\n```ts\\n// Wrong. RouteSchemas.body is optional, so Input<typeof createNote> degrades to\\n// bare { req } and body is a compile error at every handler.\\nconst createNote: RouteSchemas = { body: CreateNote };\\n\\n// Right. `satisfies` checks the shape without replacing the type.\\nconst createNote = { body: CreateNote } as const satisfies RouteSchemas;\\n```\\n\\n`as const satisfies RouteSchemas` is the convention throughout the codebase.\\n`satisfies` catches a misspelled field at the declaration rather than as a missing\\nfield in the handler, and `as const` keeps `status` a literal. Options\\npassed inline need neither, because the decorator's own `const O` type parameter\\nstops them widening on the way in.\\n\\nFor a route with no options, annotate `Input<RouteSchemas>` or take no parameter\\nat all.\\n\\n### Body parsing\\n\\nOnly when `body` is declared, and by media type:\\n\\n| `content-type`                      | `body` before validation                |\\n| ----------------------------------- | --------------------------------------- |\\n| `application/json`, `*+json`, none  | `req.json()`                            |\\n| `application/x-www-form-urlencoded` | fields; a repeated key becomes an array |\\n| `multipart/form-data`               | fields and `File`s, same repeat rule    |\\n| `text/*`                            | `req.text()`, a string                  |\\n| anything else                       | **415**, nothing read                   |\\n\\nA repeated key becoming an array is the same rule for query strings, so `?tag=a&tag=b`\\nreaches the schema whole instead of silently losing `a`.\\n\\nA body the caller mangled is a **400** (`Malformed application/json body`), never\\na 500. A missing `content-type` reads as JSON, because `fetch` omits the header\\nfor a bodyless request and a 415 there would only hide the schema error that is\\nabout to be more useful.\\n\\n### Validation failures\\n\\nA rejected schema is a `ValidationError`, always a 400, and the issues survive\\ninto the response body, because a caller cannot fix what it cannot see. Paths are\\nflattened to dots, and both zod's bare keys and Valibot's `{ key }` objects render\\nthe same way:\\n\\n```json\\n{\\n  \\\"error\\\": \\\"Invalid body\\\",\\n  \\\"status\\\": 400,\\n  \\\"issues\\\": [{ \\\"message\\\": \\\"name must be a non-empty string\\\", \\\"path\\\": \\\"name\\\" }]\\n}\\n```\\n\\n`ValidationError` carries `source`, which is `'body'`, `'query'` or `'params'`,\\nand `issues`, if you want to remap it in your own error mapper.\\n\\n## Returning values\\n\\n| Handler returns       | Response                                   |\\n| --------------------- | ------------------------------------------ |\\n| a `Response`          | passed through untouched, the escape hatch |\\n| `undefined` or `null` | **204**, no body                           |\\n| anything else         | `Response.json(value)` at the status below |\\n\\nThere is no `res` and nothing to forget to send. Return a `Response` directly to\\nstream, to redirect, or to set an unusual content type; it is never\\nsecond-guessed.\\n\\n`undefined` and `null` become 204 rather than `Response.json(null)`.\\n\\nA handler may be synchronous or return a promise. Both work, and the synchronous\\ncase is genuinely faster; see [The fast path](#the-fast-path).\\n\\n### Status codes\\n\\nPrecedence: `options.status`, else **201 for POST**, else **200**. That is the usual\\nrule, kept because it is the one people already know.\\n\\n```ts\\n// 201, by virtue of being a POST.\\nconst createUser = { body: CreateUser } as const;\\n\\n// 201, said out loud. Identical behaviour, clearer at the call site.\\nconst createNote = {\\n  body: CreateNote,\\n  status: HttpStatusCode.CREATED,\\n} as const satisfies RouteSchemas;\\n\\n// 202, because a POST that queues work is not a POST that created something.\\nconst enqueue = { body: Job, status: HttpStatusCode.ACCEPTED } as const;\\n```\\n\\n`HttpStatusCode` is a frozen object plus an indexed-access union rather than an\\nenum, so `HttpStatusCode.CREATED` is both a value and a narrow type, and erases.\\n`HttpStatusName` gives you the names.\\n\\nA thrown `HttpError` still goes through the error mapper, so `status` only sets\\nthe _success_ status.\\n\\n## Errors\\n\\nThrow `HttpError` for anything the caller should see:\\n\\n```ts\\nimport { HttpError, HttpStatusCode } from '@dunx/http';\\n\\nthrow new HttpError(HttpStatusCode.NOT_FOUND, 'No such user');\\n```\\n\\n`HttpError.status` is a plain `number`, so a status `HttpStatusCode` does not list\\nis still expressible. It extends `AppError`, and it accepts an `ErrorOptions` third\\nargument, so `{ cause }` works.\\n\\nThe default mapper produces three shapes:\\n\\n```jsonc\\n// ValidationError\\n{ \\\"error\\\": \\\"Invalid body\\\", \\\"status\\\": 400, \\\"issues\\\": [ ... ] }\\n\\n// any other HttpError\\n{ \\\"error\\\": \\\"No such user\\\", \\\"status\\\": 404 }\\n\\n// anything else: logged through the bound Logger, and the message is not leaked\\n{ \\\"error\\\": \\\"Internal Server Error\\\", \\\"status\\\": 500 }\\n```\\n\\nThe last line is the one that matters for security. An unrecognised throw is a\\n500 with a fixed body. Your message, your stack and your database error text do\\nnot reach the client.\\n\\nThe stack does reach **the log**, through the same `Logger` everything else uses:\\n`@arkv/logger` in a service that imported `@dunx/infra/logger`, core's\\n`ConsoleLogger` otherwise. One entry, one line, sanitized like the rest.\\n\\nAn `HttpError` is not logged by the mapper at all. Its status is the whole\\nrecord, and request logging has already written the 4xx line.\\n\\nReplace the whole mapper with `HttpOptions.onError`:\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule, {\\n  onError: (error, req) => {\\n    if (error instanceof DomainConflict) {\\n      return Response.json(\\n        { error: error.message, status: 409 },\\n        { status: 409 },\\n      );\\n    }\\n    return defaultErrorMapper(error, req);\\n  },\\n});\\n```\\n\\nAn `ErrorMapper` is `(error: unknown, req: Request) => Response`. There is one per\\napplication and there is no imperative equivalent, so it must be passed to\\n`create()`. This is the \\\"filters\\\" slot: dunx has one error mapper rather than an\\nexception filter hierarchy.\\n\\n`defaultErrorMapper` writes through core's `ConsoleLogger`, because a bare export\\nhas no container to ask. `errorMapper(logger)` is the same mapper over any `Logger`\\nyou hand it, and is what `create()` builds from the bound one when `onError` is\\nabsent. Reach for it when the wrapper above should keep the app's logger rather\\nthan the default:\\n\\n```ts\\nimport { errorMapper } from '@dunx/http';\\n\\nconst mapper = errorMapper(logger); // whatever LoggerModule was configured with\\n\\nconst app = await HttpFactory.create(AppModule, {\\n  onError: (error, req) =>\\n    error instanceof DomainConflict ? conflict(error) : mapper(error, req),\\n});\\n```\\n\\nCORS headers are applied _outside_ the mapper, so a mapped 500 still carries the\\nheaders the browser needs in order to display it.\\n\\n## Application-level configuration\\n\\n`create()` boots the container and discovers routes. `listen()` is what builds the\\n`Bun.serve` route table. Everything between the two still gets to shape it:\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule);\\napp.setGlobalPrefix('api');\\napp.use(AuditMiddleware);\\napp.set('trust proxy', true);\\napp.enableCors({ origin: 'https://example.com', credentials: true });\\nawait app.listen(3000);\\n```\\n\\n| Hook                   | Effect                                                              |\\n| ---------------------- | ------------------------------------------------------------------- |\\n| `setGlobalPrefix(p)`   | Prefixes every discovered route. Slashes normalised, last call wins |\\n| `use(...middleware)`   | Appends container-resolved `Ctor<Middleware>`, so it can inject     |\\n| `set(key, value)`      | Typed settings; a key must exist on `AppSettings`                   |\\n| `setting(key)`         | Reads one back                                                      |\\n| `enableCors(options?)` | Response headers plus an `OPTIONS` preflight per path               |\\n| `clientIp(req)`        | The `ClientAddress` singleton, honouring `'trust proxy'`            |\\n| `listen(port?)`        | Builds the table and binds. A second call throws                    |\\n\\nCalling any of them **after** `listen()` throws:\\n\\n```\\nsetGlobalPrefix() must be called before listen(). The route table and the\\nmiddleware chain are folded into one closure per route when the server binds, so\\nthis call could not take effect.\\n```\\n\\nA trade against the alternative, which is a silent no-op.\\n\\n`setGlobalPrefix` moves controller routes only. A WebSocket gateway path is the\\nexact path it declared. The collision check re-runs on the prefixed paths, though\\na uniform prefix cannot introduce a collision the unprefixed paths lacked, so the\\nearly check at `create()` is already complete.\\n\\n`set` is typed against the `AppSettings` interface rather than being a string bag,\\nso a typo is a compile error rather than a setting that silently never applies.\\nThere is one key today: `'trust proxy'`, typed `boolean | number`.\\n\\n- The value is how many proxies sit in front of the server, `true` meaning one.\\n- The address is taken that many entries from the **right-hand** end of\\n  `X-Forwarded-For`. A direct client can put anything in the header it sends, so only\\n  the entries a proxy appended carry weight.\\n- A count higher than the number of proxies you run hands the caller its own choice\\n  of address.\\n\\n## Middleware, guards and metadata\\n\\nOne extension point in place of five. Comparable frameworks have middleware,\\nguards, interceptors, pipes and filters; dunx has a `Middleware` interface, and\\nthe other four fall out of it:\\n\\n```ts\\nexport interface Middleware {\\n  handle(req: BunRequest, ctx: RouteContext, next: Next): Promise<Response>;\\n}\\n```\\n\\nA guard is middleware that throws. An interceptor wraps `next()`. A pipe is a\\nschema in the route options. A filter is the error mapper.\\n\\nMiddleware classes come out of the container, so they inject. Chains are folded\\ninto a single closure per route **at boot**, so there is no per-request array\\niteration. Order is global outermost, then class-level `@UseGuards`, then\\nmethod-level, then the handler.\\n\\n`ctx` names the route and carries whatever its decorators declared, resolved once\\nat discovery with the handler's metadata merged over the class's. `ctx.get(key)`\\nis therefore a `Map` lookup, and a method-level `@Public()` overrides a\\nclass-level `@Roles()`:\\n\\n```ts\\nimport {\\n  HttpError,\\n  HttpStatusCode,\\n  PUBLIC,\\n  ROLES,\\n  type Middleware,\\n} from '@dunx/http';\\n\\nexport class AuthGuard implements Middleware {\\n  constructor(private readonly logger: Logger) {}\\n\\n  handle(req: BunRequest, ctx: RouteContext, next: Next): Promise<Response> {\\n    if (ctx.get(PUBLIC)) return next();\\n    const role = req.headers.get('authorization')?.replace(/^Bearer\\\\s+/i, '');\\n    if (role === undefined) {\\n      throw new HttpError(HttpStatusCode.UNAUTHORIZED, 'No credentials');\\n    }\\n    return next();\\n  }\\n}\\n```\\n\\n```ts\\n@Roles('admin')\\n@UseGuards(AuthGuard)\\n@Controller('reports')\\nexport class ReportsController {\\n  @Public()\\n  @Get('/health')\\n  health(): { ok: true } {\\n    return { ok: true };\\n  }\\n\\n  @UseGuards(RolesGuard)\\n  @Post('/', createReport)\\n  create({ body }: Input<typeof createReport>): readonly string[] {\\n    return this.reports.add(body.title);\\n  }\\n}\\n```\\n\\n`ROLES` and `PUBLIC` are exported so your own guard can read what `@Roles` and\\n`@Public` set. They are thin wrappers over the generic channel, and your own key\\nneeds nothing more:\\n\\n```ts\\nimport { meta, metaKey, type MetaKey } from '@dunx/http';\\n\\nexport const RATE_LIMIT: MetaKey<number> = metaKey('rateLimit');\\nexport const RateLimit = (perMinute: number) => meta(RATE_LIMIT, perMinute);\\n```\\n\\n`metaKey` mints a fresh unique symbol per call, so two libraries that both name a\\nkey `roles` never read each other's value.\\n\\nMiddleware has three homes, and which one to use is decided by scope rather than by\\nkind. App-wide goes to `HttpFactory.create` or `app.use()`. A feature's own goes to\\n`@Module({ middleware })`, where it covers the routes that module's controllers\\ndeclare and nothing else. One controller's or one route's goes to `@UseGuards`.\\n\\n## The fast path\\n\\nA route with **no middleware and no CORS** is dispatched by a handler in which\\nnothing is `async`. It returns a `Response` rather than a `Promise<Response>`\\nwherever it has nothing to wait for, and Bun accepts either.\\n\\nThis is most of what closed the gap to Elysia. The general path is\\n`async (req) => toResponse(await handler(await read(req)))` inside an `async`\\ntry/catch: four awaits across two async frames, on values that are usually not\\nthenable.\\n\\nEmitting the synchronous shape was worth about 6 points of raw `Bun.serve`\\nthroughput on the `params` scenario, and a further 5 on `validate` once it\\ncovered routes that read input.\\n\\nA route with no declared schemas awaits nothing. Nor does one with only `query`\\nor `params`, every Standard Schema validator worth using being synchronous. Even\\na `body` route, which must wait for `req.json()`, pays one promise link in place\\nof six async frames. A handler or validator returning a promise still works and\\nis adopted rather than awaited.\\n\\n**Adding middleware opts a route back into the async path**, middleware being\\n`async` by contract. That includes request logging, which is on by default. A\\nbare `next()`-only middleware measures 0.05 µs, and the 6 points the direct path\\nwins on `params` do not reappear as a cost, since the request is already paying\\nfor everything else.\\n\\nWhat remains of dunx's own per-request cost is dispatch. A dunx route whose\\nhandler does its own parsing costs about 1.17 µs over the identical raw\\n`Bun.serve` handler, and the declared-input reader adds nothing measurable on top\\nof doing the same work by hand.\\n\\nRemoving that last microsecond means generating per-route source and `eval`-ing\\nit, which is Elysia's approach. At 1.3 µs on a request whose parse alone is\\n2.9 µs, it is not the next thing worth doing.\\n\\n## Request logging\\n\\n`@dunx/http` installs `RequestLoggingMiddleware` by default, outermost in the\\nchain, writing **one structured entry per request** carrying the request and the\\nresponse together. Frameworks without that property need a middleware plus an interceptor, because\\nthey are different classes; dunx does not, because middleware wraps `next()`.\\n\\nA 4xx logs at `warn` and a 5xx at `error`. Unmatched paths are logged too, through\\nthe `fetch` fallback described above.\\n\\nTurn it off with `HttpFactory.create(root, { requestLogging: false })`, or pass an\\noptions object to tune what it records. It costs real throughput, and\\n[Introduction](dunx://guide/01-introduction) has the measured numbers and the\\ndecomposition.\\n\\n## Next\\n\\n[Providers](dunx://guide/03-providers) for how a controller's constructor gets filled in.\\n[Modules](dunx://guide/04-modules) for how controllers are grouped. The\\n[`@dunx/http` reference](https://github.com/petarzarkov/dunx/blob/main/packages/http) covers WebSocket gateways, CORS\\noptions and the client-address resolver, none of which are on this page.\\n\"},{\"slug\":\"06-validation\",\"title\":\"Validation\",\"summary\":\"A route declares the shape of what it accepts on the decorator itself.\",\"sections\":[\"Standard Schema is the contract\",\"`RouteSchemas`\",\"Coercion\",\"`Input<typeof schema>` and why it must be written out\",\"What a validation failure produces\",\"Vendor-specific features sit behind a vendor check\",\"What validation costs\",\"Sharp edges\"],\"body\":\"# Validation\\n\\nA route declares the shape of what it accepts on the decorator itself. The\\nframework parses, validates and types the request before the handler runs.\\n\\n```ts\\nimport {\\n  Controller,\\n  Get,\\n  Post,\\n  type Input,\\n  type RouteSchemas,\\n} from '@dunx/http';\\nimport { z } from 'zod';\\n\\nconst CreateUser = z.object({ name: z.string().min(1).max(40) });\\nconst createUser = { body: CreateUser } as const satisfies RouteSchemas;\\n\\n@Controller('users')\\nexport class UsersController {\\n  constructor(private readonly users: UsersService) {}\\n\\n  @Post('/', createUser)\\n  create({ body }: Input<typeof createUser>): Promise<User> {\\n    return this.users.create(body.name);\\n  }\\n}\\n```\\n\\nThe body arrives parsed and validated: `body.name` is already a `string`,\\nand a POST answers 201, all without writing `await req.json()`, `Response.json()`\\nor a status code by hand. A request that fails the schema never reaches the\\nhandler.\\n\\n## Standard Schema is the contract\\n\\nWhat a route's `body`, `query` and `params` accept is anything implementing\\n[Standard Schema v1](https://standardschema.dev): an object carrying a\\n`~standard` property. `@dunx/http` needs no validator dependency to enforce\\nthat. Its `peerDependencies` are `@dunx/core` and (optionally) `@types/bun`,\\nand the list ends there.\\n\\n```ts\\nexport interface StandardSchemaV1<In = unknown, Out = In> {\\n  readonly '~standard': {\\n    readonly version: 1;\\n    readonly vendor: string;\\n    readonly validate: (\\n      value: unknown,\\n    ) => StandardSchemaResult<Out> | Promise<StandardSchemaResult<Out>>;\\n    readonly types?: { readonly input: In; readonly output: Out } | undefined;\\n  };\\n}\\n```\\n\\nThat interface is restated in `@dunx/http` rather than imported. The spec is\\nonly an interface: `@standard-schema/spec` ships type declarations with no\\nruntime code, so restating it costs one file and adds no dependency to the\\npackage. zod 4, Valibot and ArkType already satisfy the shape, so all three\\ndrop straight into a route's options with no adapter needed:\\n\\n```ts\\nimport { z } from 'zod';\\nimport * as v from 'valibot';\\nimport { type } from 'arktype';\\n\\nconst withZod = { query: z.object({ limit: z.coerce.number() }) } as const;\\nconst withValibot = { query: v.object({ limit: v.number() }) } as const;\\nconst withArkType = { query: type({ limit: 'number' }) } as const;\\n```\\n\\nThe one thing the framework reads is `schema['~standard'].validate(value)`. It\\ndoes not know or care which library produced the object.\\n\\n### Sync and async validators\\n\\n`~standard.validate` is permitted to return a promise, though zod, Valibot and\\nArkType never do. The input reader is built around that difference: it checks\\n`result instanceof Promise` and only allocates a promise link when it gets one.\\nA validator that really is asynchronous still works and is awaited correctly; it\\njust costs an async frame that the synchronous ones do not.\\n\\n## `RouteSchemas`\\n\\nThe second argument to `@Get` / `@Post` / `@Put` / `@Patch` / `@Delete`:\\n\\n```ts\\nexport interface RouteSchemas {\\n  readonly body?: StandardSchemaV1;\\n  readonly query?: StandardSchemaV1;\\n  readonly params?: StandardSchemaV1;\\n  /** Overrides the default success status: 201 for POST, 200 otherwise. */\\n  readonly status?: number;\\n  /** What the route answers with, keyed by status. Documented, never validated. */\\n  readonly response?: Readonly<Record<number, StandardSchemaV1>>;\\n}\\n```\\n\\n**Declaring a schema is what makes the matching field appear.** Omit `query` and\\nthe framework never parses a query string; omit `body` and it never reads the\\nrequest stream. There is no \\\"validate everything by default\\\" mode and no global\\npipe to turn off. An undeclared source is untouched code rather than skipped\\ncode.\\n\\n`response` is the exception that proves the rule, and the one key here the request\\npath never reads:\\n\\n```ts\\nexport const oneUser = {\\n  params: UserIndex,\\n  response: { 200: SanitizedUser, 404: NotFound },\\n} as const satisfies RouteSchemas;\\n```\\n\\nThe same Standard Schema contract as the request side, so\\n[`@dunx/openapi`](dunx://guide/10-openapi) hoists a named response schema into\\n`components/schemas` exactly as it hoists a body.\\n\\nIt is **checked at compile time, not at runtime.** Validating every response body\\nwould be a per-request cost paid for a documentation feature. The verb decorator\\nholds the handler's return type to the entry for the route's success status\\ninstead, so this does not compile:\\n\\n```ts\\n@Get('/:id', oneUser)\\none({ params }: Input<typeof oneUser>): { id: number } {\\n  //                                ^ TS1241: property 'name' is missing\\n}\\n```\\n\\nFour things that follow. Only the success status is checked, since a 404 body\\nleaves through a thrown `HttpError` that no return type describes. A `Response` is\\nalways allowed. A `readonly User[]` satisfies a schema inferring `User[]`, because\\nmutability does not survive serialisation. And returning nothing is a 204, so it\\nfails against a declared 200 body.\\n\\n`response` does not appear in `Input<O>`: nothing about it reaches the handler.\\n\\nWrite the options object next to the schemas and hand the same value to both the\\ndecorator and the annotation:\\n\\n```ts\\nimport type { RouteSchemas } from '@dunx/http';\\nimport { z } from 'zod';\\n\\nexport const UserIndex = z.object({ id: z.coerce.number().int().min(1) });\\nexport const ListUsers = z.object({\\n  q: z.string().min(1).optional(),\\n  limit: z.coerce.number().int().min(1).max(50).default(10),\\n});\\n\\nexport const oneUser = { params: UserIndex } as const satisfies RouteSchemas;\\nexport const listUsers = { query: ListUsers } as const satisfies RouteSchemas;\\n```\\n\\n`as const` is load bearing. Without it `{ body: CreateNote, status: 201 }` widens\\nto `RouteSchemas` and `Input<typeof opts>` degrades to a bare `{ req }`, taking\\nthe type check with it. `satisfies RouteSchemas` checks the object without\\nwidening it, so the pair is written that way rather than with a type\\nannotation.\\n\\n### Path params\\n\\nBun's router matches `/users/:id` and puts the segment on `req.params`. Declaring\\na `params` schema validates that object and replaces it with the schema's output:\\n\\n```ts\\n@Get('/:id', oneUser)\\nasync one({ params }: Input<typeof oneUser>): Promise<User> {\\n  const user = await this.users.find(params.id);\\n  ...\\n}\\n```\\n\\nWithout a `params` schema the raw values are still reachable at `req.params`. The\\nframework does not hide them; it just does not type or check them.\\n\\n### Query strings\\n\\nQuery values are read with `URLSearchParams` and grouped before validation, so a\\nrepeated key becomes an array:\\n\\n```\\n?tag=a&tag=b   ->   { tag: ['a', 'b'] }\\n?tag=a         ->   { tag: 'a' }\\n```\\n\\nThat is deliberate: dropping `a` silently is the behaviour a schema can never\\nrecover from. If a field is single-valued, say so in the schema and a repeated key\\nbecomes a 400 rather than a surprise.\\n\\nThe query string is sliced out of `req.url` by hand rather than through\\n`new URL(req.url)`. Constructing a `URL` resolves scheme, host, port, path and\\nfragment to hand back one `searchParams` object, measuring about 1,040 ns of the\\nroughly 1,520 ns a three-pair query route cost. That is more than the entire body\\nreader.\\n\\nThe fragment is still stripped, though a client is not supposed to send one, so a\\nhostile request target cannot change what a schema sees.\\n\\n### Bodies\\n\\nThe content type decides the parser:\\n\\n| `content-type`                       | parsed with                         |\\n| ------------------------------------ | ----------------------------------- |\\n| `application/json`, anything `+json` | `req.json()`                        |\\n| `application/x-www-form-urlencoded`  | `URLSearchParams`, grouped          |\\n| `multipart/form-data`                | `req.formData()`, grouped           |\\n| `text/*`                             | `req.text()`                        |\\n| anything else                        | 415, before the schema is consulted |\\n\\nNo `content-type` header at all reads as JSON. `fetch` omits the header for a\\nbodyless request, and answering 415 there would be useless because the schema is\\nabout to reject `undefined` with a better message anyway.\\n\\n## Coercion\\n\\nPath params and query values arrive as **strings**, always. HTTP has no other\\nrepresentation for them. Coercion belongs to the schema, and with zod it is one\\ncall:\\n\\n```ts\\nexport const UserIndex = z.object({ id: z.coerce.number().int().min(1) });\\n```\\n\\n`z.coerce.number()` turns `\\\"42\\\"` into `42` before `.int().min(1)` runs, so by the\\ntime the handler executes `params.id` is a `number` at runtime **and** in\\nthe type, because `Input<>` reads the schema's _output_ type rather than its\\ninput:\\n\\n```ts\\n@Get('/:id', oneUser)\\nasync one({ params }: Input<typeof oneUser>): Promise<User> {\\n  // Already a number. The params schema coerced it before this ran.\\n  const user = await this.users.find(params.id);\\n  if (user === null) {\\n    throw new HttpError(HttpStatusCode.NOT_FOUND, `No user ${params.id}`);\\n  }\\n  return user;\\n}\\n```\\n\\nThe same applies to query defaults. `limit: z.coerce.number().int().min(1).max(50).default(10)`\\nmeans the handler sees a `number` whether or not the caller sent `?limit=`, and\\n`\\\"999\\\"` is a 400 rather than a page size nobody intended.\\n\\nThis is one of the two reasons the framework does not try to be clever about\\ntypes on its own. The other is that `.default()` changes the _type_ as well as the\\nvalue, and only the validator knows that.\\n\\n## `Input<typeof schema>` and why it must be written out\\n\\nThe annotation on the handler parameter carries the type the schema infers. It is\\nnot optional, and not a wart the framework could remove if it tried.\\n\\nA TC39 standard method decorator is\\n`(value: V, context: ClassMethodDecoratorContext) => V | void`. It receives the\\nmethod and can _reject_ one whose type does not match, but there is no mechanism\\nin the proposal for a decorator to contextually type an unannotated parameter.\\nThis was measured with `tsc` rather than assumed:\\n\\n```\\nannotated correctly            -> compiles\\nunannotated parameter          -> TS7006: Parameter 'input' implicitly has an 'any' type\\nannotated with the wrong type  -> TS1241 + TS1270, naming the mismatched property\\n```\\n\\nThe guarantee is therefore a _check_ rather than an inference. Get the annotation\\nwrong and the compiler names the property that does not line up; leave it off and\\n`strict` mode rejects the implicit `any`. It is never silently wrong.\\n\\nThe saving grace is that **no type is written twice**. `Input<O>` is a type-level\\nfunction over the options object:\\n\\n```ts\\nexport type Input<O extends RouteSchemas> = {\\n  readonly req: BunRequest;\\n} & (O extends { body: infer B }\\n  ? { readonly body: InferOutput<B> }\\n  : unknown) &\\n  (O extends { query: infer Q }\\n    ? { readonly query: InferOutput<Q> }\\n    : unknown) &\\n  (O extends { params: infer P }\\n    ? { readonly params: InferOutput<P> }\\n    : unknown);\\n```\\n\\nEvery field type still comes from the schema. `Input<typeof createUser>` is\\n`{ req: BunRequest; body: { name: string } }` because `CreateUser` says so, and\\nchanging the schema changes the handler's type with no second edit.\\n\\nA route with no schemas at all still gets the request:\\n\\n```ts\\n@Get('/whoami')\\nwhoami({ req }: Input<RouteSchemas>): { ip: string | undefined } {\\n  return { ip: this.address.of(req) };\\n}\\n```\\n\\n`InferOutput<S>` is exported separately for the times a service signature needs\\nthe same type: `InferOutput<typeof CreateUser>` is `{ name: string }`.\\n\\nRelated reading: [Controllers](dunx://guide/05-controllers) covers the decorators\\nthemselves and how a return value becomes a `Response`.\\n\\n## What a validation failure produces\\n\\nA rejected schema throws `ValidationError`, which is an `HttpError` with status\\n400 carrying every issue the validator reported. The default error mapper turns it\\ninto:\\n\\n```json\\n{\\n  \\\"error\\\": \\\"Invalid body\\\",\\n  \\\"status\\\": 400,\\n  \\\"issues\\\": [{ \\\"message\\\": \\\"<the validator's own message>\\\", \\\"path\\\": \\\"name\\\" }]\\n}\\n```\\n\\nThe message is whatever the validator produced, passed through unaltered: dunx\\ndoes not rewrite, translate or truncate it, because the library that rejected the\\nvalue is the one that knows why.\\n\\nThree properties of that shape:\\n\\n- **`error` names the source.** `Invalid body`, `Invalid query` or\\n  `Invalid params`, so a caller can tell a bad payload from a bad page size.\\n- **The issues survive into the response.** A caller cannot fix what it cannot\\n  see. This is the one place the framework echoes request detail back to the\\n  caller, a 400 being by definition the caller's own input.\\n- **`path` is flattened to dots**, and absent when the root itself failed.\\n  Standard Schema lets a vendor report a path as bare keys (zod) or as\\n  `{ key }` objects (Valibot); both are normalised here to a single string.\\n\\nTwo other failures are not validation failures and do not carry issues:\\n\\n- A body the caller mangled is `400 Malformed application/json body`. The parse\\n  rejected, so there was never a value to validate.\\n- An undeclared content type is\\n  `415 Unsupported content type \\\"application/xml\\\". Declared bodies accept\\napplication/json, application/x-www-form-urlencoded, multipart/form-data or text/*.`\\n\\nReplace all of it by passing `onError` to `HttpFactory.create`; see\\n[Middleware and guards](dunx://guide/08-middleware-and-guards#the-error-mapper).\\n\\n## Vendor-specific features sit behind a vendor check\\n\\nStandard Schema validates. It says nothing about describing, serialising or\\nconverting a schema, so there is no vendor-neutral way to turn one into JSON\\nSchema. `@dunx/openapi` needs exactly that, and resolves it with the one\\npiece of vendor information the interface does carry:\\n\\n```ts\\nexport const vendorOf = (schema: StandardSchemaV1): string =>\\n  schema['~standard'].vendor;\\n```\\n\\nIf the vendor is `zod`, the package dynamically imports zod and calls\\n`z.toJSONSchema(schema, { io: 'input', unrepresentable: 'any' })`. If it is\\nanything else, the schema is documented as permissive and a warning is recorded:\\n\\n```\\nUsersController_createBody: no JSON Schema conversion for Standard Schema vendor\\n\\\"valibot\\\". Standard Schema validates; it does not describe. The schema is\\ndocumented as permissive.\\n```\\n\\nWarnings are readable off `app.get(OpenApiExplorer).warnings` straight after\\n`HttpFactory.create()`, so a degraded document shows up at boot rather than when\\nsomebody notices an empty request body in the explorer.\\n\\nzod is an **optional** `peerDependency` of `@dunx/openapi`. A consumer on Valibot\\nnever loads it, and a consumer without it installed gets warnings rather than a\\nmodule-resolution crash. Details in [OpenAPI](dunx://guide/10-openapi).\\n\\nThe rule generalises: validation stays library-agnostic because a standard exists;\\nanything the standard does not cover is gated on `~standard.vendor` and degrades\\nloudly.\\n\\n## What validation costs\\n\\nThis repo measures its own losses rather than guessing at them. Here, the loss\\nsits somewhere most people would not expect.\\n\\nFour raw `Bun.serve` routes, each doing exactly one thing more than the one above\\nit, all answering the same bytes, all against a 69 byte three-field payload:\\n\\n| Step                                 |   req/s | µs/req | this step adds |\\n| ------------------------------------ | ------: | -----: | -------------: |\\n| `GET /json`, no request body at all  | 113,881 |   8.78 |              - |\\n| `POST`, body on the wire, never read | 110,537 |   9.05 |       +0.27 µs |\\n| `POST` + `await req.json()`          |  82,341 |  12.14 |       +3.10 µs |\\n| `POST` + `req.json()` + zod          |  76,412 |  13.09 |       +0.94 µs |\\n\\n**Reading the body costs about three times what validating it costs.** Putting the\\npayload on the wire is near free; `req.json()` is 3.10 µs and zod is 0.94 µs. Of\\nthe roughly 30% throughput drop between a JSON route and a validating one, 77% is\\n`req.json()` and 23% is the validator. No framework can remove the parse, and no\\nchoice of validator affects it.\\n\\nThere is no throughput argument for steering anyone off zod:\\n\\n| Validator                   |    costs | `~standard` |\\n| --------------------------- | -------: | ----------- |\\n| TypeBox, `TypeCompiler` AOT | -0.01 µs | bridged     |\\n| ajv, compiled JSON Schema   |  0.34 µs | bridged     |\\n| ArkType                     |  0.42 µs | native      |\\n| Valibot                     |  0.89 µs | native      |\\n| zod                         |  0.94 µs | native      |\\n\\nzod, Valibot and ArkType are within noise of each other; the noise floor for that\\nharness is about ±0.3 µs. Both compiled options land at or under it, which means\\nTypeBox's compiled checker is indistinguishable from not validating at all on a\\npayload this size. Saving 0.9 µs on a 13 µs request is 7%, against giving up zod's\\necosystem, error messages and `z.toJSONSchema`. Pick on API and error quality.\\n\\nThe framework's own overhead was the number worth chasing. A route with a\\ndeclared `body` used to cross six `async` frames, exactly one of which\\n(`req.json()`) ever had anything to wait for, and the reader's plumbing cost\\n2.05 µs, nearly twice what zod itself cost.\\n\\nRebuilding it to adopt promises rather than await them took the plumbing from\\n597 ns to 146 ns with a no-op schema. A `params`-only route with a synchronous\\nvalidator now reads and validates in 56 ns, allocating no promise.\\n\\nIn the benchmark suite that moved the `validate` scenario from 84.0% of raw\\n`Bun.serve` to over 92%, and put dunx ahead of Elysia on the one scenario where\\nit used to be level.\\n\\n## Sharp edges\\n\\n- **`as const` is not optional.** Drop it and the handler's `input` silently\\n  becomes `{ req }`. `satisfies RouteSchemas` is what catches a typo in a key\\n  name without re-widening the object.\\n- **A `params` schema replaces `req.params` on the input object only.**\\n  `req.params` is still the raw string record.\\n- **The framework validates input and never output.** A handler's return value is\\n  serialised as it is, `response` schemas included: they document the answer for\\n  `@dunx/openapi` and nothing checks them at runtime. If a response shape matters,\\n  the annotation on the handler is what enforces it.\\n- **`status` on the options object changes the success status only.** Errors\\n  still come from the thrown `HttpError` or from the mapper.\\n- **A schema that is not an object is fine for `body` and wrong for\\n  `query`/`params`.** A query string is a set of named parameters, so a non-object\\n  schema there documents nothing and `@dunx/openapi` warns about it.\\n- **Request-body logging is off by default** and reading it means\\n  `req.clone().text()`, a second buffered copy of every payload. Turning both body\\n  options on costs roughly two thirds of the throughput on the `validate`\\n  scenario, and the request body is the field most likely to contain a password.\\n  See [Middleware and guards](dunx://guide/08-middleware-and-guards#request-logging).\\n\"},{\"slug\":\"07-lifecycle\",\"title\":\"Lifecycle\",\"summary\":\"One lifetime, three hooks, eager boot.\",\"sections\":[\"Provider lifetime\",\"Boot\",\"`OnInit`\",\"`OnShutdown`\",\"`OnBeforeShutdown`\",\"Circular dependencies\",\"Error propagation\",\"Overrides in tests\",\"Reaching the container\"],\"body\":\"# Lifecycle\\n\\nOne lifetime, three hooks, eager boot. All of it is `@dunx/core` and none of it\\nneeds `@dunx/http`.\\n\\n## Provider lifetime\\n\\nEvery provider is a singleton **within the module scope that declares it**.\\n\\n```ts\\n@Module({ providers: [UsersService] })\\nexport class UsersModule {}\\n```\\n\\n`UsersService` is constructed once. Everything resolving from `UsersModule`'s\\nscope receives that instance.\\n\\n| Nest              | dunx                         |\\n| ----------------- | ---------------------------- |\\n| `Scope.DEFAULT`   | the only lifetime            |\\n| `Scope.REQUEST`   | absent, and will stay absent |\\n| `Scope.TRANSIENT` | absent, and will stay absent |\\n\\nTwo modules that each list the same class in `providers` get two instances, one\\nper scope. [Modules](dunx://guide/04-modules) covers when that is what you want.\\n\\n### Per-request state\\n\\nRequest-scoped DI was measured and turned down. It is a container's largest\\nsource of per-request cost and complexity, and two replacements cover what it\\nwas used for.\\n\\n**Correlation data** goes through `RequestContext`, an `AsyncLocalStorage` that\\nnever touches the container:\\n\\n```ts\\nexport class OrdersService {\\n  constructor(\\n    private readonly context: RequestContext,\\n    private readonly logger: Logger,\\n  ) {}\\n\\n  place(order: Order) {\\n    // traceId was set by RequestLoggingMiddleware, on the way in\\n    const { traceId } = this.context.getContext();\\n    this.logger.info('placing', { traceId });\\n  }\\n}\\n```\\n\\n**Everything else** is a parameter:\\n\\n```ts\\n@Post('/orders', { body: OrderSchema })\\ncreate(req: BunRequest, body: Order) {\\n  return this.orders.place(body, req.headers.get('x-tenant'));\\n}\\n```\\n\\nReasoning and the measurement: [architecture/dependency-injection.md](https://github.com/petarzarkov/dunx/blob/main/docs/architecture/dependency-injection.md).\\n\\n## Boot\\n\\n`AppFactory.create()` builds the scope graph, instantiates **every** provider,\\nawaits **every** async factory, then runs `onInit`. It returns a live app; there\\nis no separate `init()` call.\\n\\n```ts\\nconst app = await AppFactory.create(AppModule);\\n```\\n\\nA wiring error therefore surfaces at boot rather than on the first request that\\nhappens to hit the broken route.\\n\\n| Stage | What runs                                                         |\\n| ----- | ----------------------------------------------------------------- |\\n| 1     | `buildScopes` walks the import graph                              |\\n| 2     | overrides replace matching bindings in every scope that holds one |\\n| 3     | every provider is constructed, dependencies first                 |\\n| 4     | `onInit()` on each instance, in construction order                |\\n| 5     | shadowing and ambiguous-import warnings are logged                |\\n\\n### Async factories\\n\\n`useFactory` may return a promise. `create()` awaits it before any dependent is\\nconstructed.\\n\\n```ts\\nprovide(DbConnection, {\\n  useFactory: async (config: AppConfigService) =>\\n    DbConnection.open(config.get('databaseUrl')),\\n  inject: [AppConfigService],\\n});\\n```\\n\\nA rejected factory rejects `AppFactory.create()`. Nothing partially built is\\nreturned, and `onInit` never runs.\\n\\n`inject` lists `AppConfigService`, the subclass, rather than `ConfigService`. A\\nfactory parameter annotated `ConfigService<AppConfig>` against `inject: [ConfigService]`\\nis rejected: parameters are contravariant and the token carries no type argument.\\n[Configuration](dunx://guide/12-configuration) covers the `as` option that declares the\\nsubclass.\\n\\n## `OnInit`\\n\\nImplement the interface. No registration.\\n\\n```ts\\nimport type { OnInit } from '@dunx/core';\\n\\nexport class SearchIndex implements OnInit {\\n  async onInit() {\\n    await this.warmCache();\\n  }\\n}\\n```\\n\\nRuns after every provider is constructed, so a dependency is fully built by the\\ntime yours starts. A throwing `onInit` rejects `create()`.\\n\\n## `OnShutdown`\\n\\n```ts\\nimport type { OnShutdown } from '@dunx/core';\\n\\nexport class QueueConnection implements OnShutdown {\\n  async onShutdown() {\\n    await this.client.close();\\n  }\\n}\\n```\\n\\n`app.shutdown()` runs every `onShutdown` in **reverse construction order**, so a\\nservice tears down before the connection it was built on. It is idempotent:\\nconcurrent callers await the same drain, and `app.closed` resolves once it\\nfinishes.\\n\\n| Nest                        | dunx               |\\n| --------------------------- | ------------------ |\\n| `OnModuleInit`              | `OnInit`           |\\n| `OnModuleDestroy`           | `OnShutdown`       |\\n| `onApplicationBootstrap`    | `OnInit`           |\\n| `beforeApplicationShutdown` | `OnBeforeShutdown` |\\n\\n## `OnBeforeShutdown`\\n\\nShutdown has two phases, and this is the first one. It runs **while the app is still\\nserving**.\\n\\n```ts\\nimport type { OnBeforeShutdown } from '@dunx/core';\\n\\nexport class Readiness implements OnBeforeShutdown {\\n  async onBeforeShutdown() {\\n    this.accepting = false;\\n    await Bun.sleep(15_000);\\n  }\\n}\\n```\\n\\n`onShutdown` runs too late for anything that has to be observable from outside.\\n`@dunx/http` stops the server before tearing providers down. A readiness probe\\nflipped inside `onShutdown` would answer on an already-closed port, while a load\\nbalancer is still routing traffic to it.\\n\\nSo `app.drain()` runs every `onBeforeShutdown` first, then the port closes, then\\n`onShutdown` tears down. `shutdown()` calls the drain itself, which is what makes a\\nprocess with no server drain at all.\\n\\nEvery `onBeforeShutdown` runs **concurrently**, unlike `onShutdown`. These are\\nindependent waits, so the phase costs as much as the slowest one rather than\\ntheir sum. Teardown, in contrast, follows dependencies and has to run\\nsequentially.\\n\\n`@dunx/http`'s `HealthModule` is built on this, and its `drainDelayMs` is the window\\nabove. A queue consumer that must stop accepting jobs before its database closes\\nwants the same phase.\\n\\nDo not confuse it with `@OnDrain()`, a websocket handler decorator in `@dunx/http`\\nthat fires when socket backpressure clears. Different layer, unrelated.\\n\\n### Signals\\n\\n```ts\\napp.enableShutdownHooks(); // SIGTERM, SIGINT\\napp.enableShutdownHooks(['SIGTERM']);\\napp.enableShutdownHooks(['SIGTERM'], { exitAfterMs: false });\\n```\\n\\n**This ends the process.** After the drain completes, an `unref()`d timer gives\\nthe runtime 1000 ms to exit on its own, then calls `process.exit`. A process\\nwith nothing pending exits in about 1 ms and the timer never fires. It fires\\nonly when a handle outside the container is still holding the loop open, and\\nwhen that happens it logs a warning naming the case before exiting.\\n\\nPass `exitAfterMs: false` when the app does not own its process, and in any test\\nthat fires a signal at its own runner. A programmatic `app.shutdown()` never\\nexits the process at any setting.\\n\\n## Circular dependencies\\n\\n`@dunx/transform` records constructor dependencies as a **thunk** evaluated at\\nresolution time, so a class declared later in the file, or reached across a\\ncircular import, resolves normally. There is no `forwardRef` to reach for.\\n\\nA genuine cycle throws `CircularDependencyError` at boot, carrying the full path:\\n\\n```text\\nCircularDependencyError: Circular dependency: UsersService -> AuditService -> UsersService\\n```\\n\\n`error.cycle` is the same path as a `string[]`.\\n\\n## Error propagation\\n\\n| Failure                                     | Surfaces as                                                      |\\n| ------------------------------------------- | ---------------------------------------------------------------- |\\n| Erased constructor parameter type           | boot error naming the parameter                                  |\\n| Constructor parameters, no transform record | boot error quoting the `bunfig.toml` preload                     |\\n| Token no module exports                     | boot error naming the module that declares it and the one asking |\\n| Cycle                                       | `CircularDependencyError` with the path                          |\\n| Rejected `useFactory`                       | rejects `AppFactory.create()`                                    |\\n| Throwing `onInit`                           | rejects `AppFactory.create()`                                    |\\n| Throwing `onShutdown` via signal            | logged, exit code 1, **remaining teardown skipped**              |\\n\\nEvery one of these is a rejected `create()` except the last. An app that boots\\nhas resolved everything it declares.\\n\\nThe last row is the one to design around. The teardown loop is unguarded, so the\\nfirst `onShutdown` that throws aborts it.\\n\\n- Every provider after it in the reverse order keeps its resources.\\n- `app.closed` never resolves.\\n- `ShutdownHooks` catches the rejection, logs `[dunx] shutdown failed` and arms exit\\n  code 1. Its exit timer is what still ends the process.\\n\\nPut a `try` inside any `onShutdown` whose failure should not strand the ones behind\\nit.\\n\\n## Overrides in tests\\n\\nA test wants the same container with one binding swapped, not a second boot\\npath built to route around it. `createTestApp` replaces a binding **in place**,\\nin every scope that holds one:\\n\\n```ts\\nconst app = await createTestApp({\\n  modules: [OrdersModule],\\n  overrides: [provide(Clock, { useValue: new FixedClock('2026-01-01') })],\\n});\\n```\\n\\nThe discarded provider is never constructed, so an async `useFactory` that would\\nhave opened the real database does not run.\\n\\nOverriding a token that nothing binds throws, unless the token is a class. A\\nsilent no-op there would produce a test asserting against a provider it\\nbelieved it had swapped. A class token nobody bound is accepted instead and\\nbound lazily, because a class self-binds on demand anyway.\\n\\nFull harness, including `createTestServer` and `RecordingLogger`:\\n[Testing](dunx://guide/11-testing).\\n\\n## Reaching the container\\n\\nThe container itself is reachable too, for wiring and debugging code that sits\\noutside constructor injection:\\n\\n```ts\\napp.get(UsersService); // root scope view, then any single declarer\\napp.get(UsersService, OrdersModule); // prefers OrdersModule's view\\n```\\n\\n`app.get` is more permissive than constructor injection. With a module argument\\nit prefers that module's view. Failing that, it falls back to the root scope's\\nview, then to the single module that declares the token, and finally self-binds\\na class into the module named. Two scopes binding the token differently is an\\nerror rather than a guess, and a module that is not in the graph at all throws.\\n\\n`AppRef` is the injectable form, and is dunx's `ModuleRef`.\\n\"},{\"slug\":\"08-middleware-and-guards\",\"title\":\"Middleware and guards\",\"summary\":\"Frameworks in this lineage tend to ship five concepts - middleware, guards, interceptors, pipes and filters - five base classes, five places to look when a request does something unexpected.\",\"sections\":[\"Writing one\",\"`next()` is a function you call\",\"The request lifecycle\",\"`RouteContext`\",\"Guards\",\"Module middleware\",\"The error mapper\",\"Request logging\",\"CORS\",\"Sharp edges\"],\"body\":\"# Middleware and guards\\n\\nFrameworks in this lineage tend to ship five concepts - middleware, guards, interceptors, pipes and filters -\\nfive base classes, five places to look when a request does something unexpected.\\ndunx has one.\\n\\n```ts\\nexport interface Middleware {\\n  handle(req: BunRequest, ctx: RouteContext, next: Next): Promise<Response>;\\n}\\n\\nexport type Next = () => Promise<Response>;\\n```\\n\\nThat is the entire extension point. A guard is middleware that throws. An\\ninterceptor is middleware that wraps `next()`. A pipe is a schema on the route\\ndecorator, covered in [Validation](dunx://guide/06-validation). A filter is the error\\nmapper, one class for the whole app.\\n\\nWhere a layer comes from - the app, a module, a controller, a method - varies. What\\na layer _is_ does not.\\n\\n## Writing one\\n\\nA middleware is a class, resolved from the container like anything else, so it has\\nconstructor injection with no annotation:\\n\\n```ts\\nimport type { BunRequest } from 'bun';\\nimport type { Middleware, Next, RouteContext } from '@dunx/http';\\n\\nexport class RequestTrail {\\n  readonly entries: string[] = [];\\n}\\n\\nexport class RequestTrailMiddleware implements Middleware {\\n  constructor(private readonly trail: RequestTrail) {}\\n\\n  async handle(\\n    req: BunRequest,\\n    ctx: RouteContext,\\n    next: Next,\\n  ): Promise<Response> {\\n    const response = await next();\\n    this.trail.entries.push(\\n      `${req.method} ${new URL(req.url).pathname} -> ${response.status} ` +\\n        `(${ctx.controller}.${ctx.handler})`,\\n    );\\n    response.headers.set('x-handled-by', 'request-trail');\\n    return response;\\n  }\\n}\\n```\\n\\nInstall it globally, either at boot or before `listen()`:\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule, {\\n  middleware: [RequestTrailMiddleware],\\n});\\n// or, equivalently, appended after the ones above:\\napp.use(RequestTrailMiddleware);\\n```\\n\\nBoth take **classes** rather than instances, so the container resolves each one\\nand supplies its dependencies.\\n\\n`app.use()` after `listen()` throws, as does every other configuration call. The\\nchain is folded into one closure per route when the server binds, so a later call\\ncould not take effect.\\n\\n`HttpFactory.create` and `app.use()` are the **app-wide** list. A middleware that\\nbelongs to one feature goes on that feature's module instead - see\\n[Module middleware](#module-middleware) below.\\n\\nBoth resolve the way your root module sees them: for a middleware class, that\\nmeans the single module that declares it. Listing a guard here does not oblige\\nyour root to import or re-export the feature module that provides it.\\n\\n## `next()` is a function you call\\n\\nThis is the design decision the rest of the page follows from.\\n\\nBecause `handle` receives `next` and returns whatever it wants, **one class sees\\nboth halves of a request**. It can time the call, catch the error, rewrite the\\nresponse, or refuse to call `next()` at all.\\n\\nFrameworks that split this across two base classes run middleware before and wrap\\nan interceptor around the observable. They are separate objects with no shared\\nframe, so correlating the two halves means threading a trace through and\\nreassembling the pair in a log aggregator.\\n\\nThe built-in request logger is the proof. It is one class, and it emits **one\\nstructured entry per request** carrying the request and the response together:\\n\\n```ts\\nreturn this.context.runWithContext(\\n  { traceId, spanId, method: ctx.method, event: path, flow: 'http', context: `${ctx.controller}.${ctx.handler}` },\\n  () => { ... this.#dispatch(req, ctx, path, started, request, next) },\\n);\\n```\\n\\nEverything the handler logs in between carries `traceId`, `method`, `event` and\\n`context` without being passed anything, because the whole call runs inside\\n`runWithContext` on an `AsyncLocalStorage`. There is no pair to correlate, because\\nthere is no pair.\\n\\n## The request lifecycle\\n\\nOutermost first, and every numbered layer except the last two is the same\\n`Middleware` interface:\\n\\n1. the **error filter**, the only layer that turns a throw into a response\\n2. `RequestLoggingMiddleware`, unless `requestLogging: false`\\n3. `HttpOptions.middleware`, in the order given\\n4. anything `app.use()` appended, in call order\\n5. the **declaring module's** `middleware`, in the order given\\n6. class-level `@UseGuards(...)`, in the order written\\n7. method-level `@UseGuards(...)`, in the order written\\n8. **validation** of `params`, `query` and `body` against the route's schemas\\n9. the handler\\n\\nThen back out through 7, 6, 5, 4, 3, 2 - because a middleware that does work after\\n`await next()` is what an interceptor would have been.\\n\\n`@dunx/http`'s own test suite asserts exactly that list, in one\\nrequest, in both directions:\\n\\n```\\nglobal:in  use:in  module:in  controller-guard:in  method-guard:in\\n  validate  handler\\nmethod-guard:out  controller-guard:out  module:out  use:out  global:out  log\\n```\\n\\nand asserts the refusal case: a guard that throws at layer 7 never reaches\\nvalidation or the handler, every enclosing layer still unwinds, and the filter runs\\noutside all of them.\\n\\n### If you are coming from Nest\\n\\nNest documents nine numbered stages over five base classes. The mapping is not\\nsubtle, because the stages collapse rather than move:\\n\\n| Nest                                               | dunx                                            |\\n| -------------------------------------------------- | ----------------------------------------------- |\\n| Global middleware                                  | `HttpOptions.middleware` / `app.use()`          |\\n| Module-bound middleware (`configure(consumer)`)    | `@Module({ middleware })`                       |\\n| Global / controller / route **guards**             | the same list, and `@UseGuards`                 |\\n| **Interceptors**, pre-controller                   | anything before `await next()`                  |\\n| **Pipes**, including parameter pipes               | the route decorator's schemas                   |\\n| Controller handler, then services                  | unchanged                                       |\\n| **Interceptors**, post-request                     | anything after `await next()`                   |\\n| **Exception filters**, route → controller → global | `onError`, one filter; or `try` around `next()` |\\n\\nFour things go away with it:\\n\\n- No `forRoutes()` path-matching language. A module already owns its controllers.\\n- No separate `guards`, `interceptors` and `pipes` arrays. They were one\\n  mechanism wearing three names.\\n- No ancestor layer. Importing a module never adds middleware to the importer's\\n  routes.\\n- No per-controller or per-route filter. A middleware wrapping `next()` in a\\n  `try` **is** a scoped filter, in the same class that decided to be there.\\n\\n### Ordering is folded at boot\\n\\nThe chain is composed once per route when the server binds:\\n\\n```ts\\nexport const compose = (\\n  middleware: readonly Middleware[],\\n  ctx: RouteContext,\\n  handler: RouteHandler,\\n): RouteHandler =>\\n  middleware.reduceRight<RouteHandler>(\\n    (next, current) => (req) => current.handle(req, ctx, () => next(req)),\\n    handler,\\n  );\\n```\\n\\nOne `reduceRight` per route at `listen()`, after which a request is a call into a\\nclosure. A guard costs a `Map` lookup where Nest's `Reflector` costs a\\nper-request reflection call, because there is no array iteration, no metadata\\nlookup and no container access left on the request path.\\n\\nA route with **no middleware and no CORS** skips even that, taking a direct\\ndispatch path that allocates no async frame unless something genuinely has to be\\nawaited. On the `plaintext` scenario that took dunx from 89.5% to 97.2% of raw\\n`Bun.serve`.\\n\\nGiving it up costs a known 0.05 µs per request for a bare `next()`-only\\nmiddleware. Install the middleware you need.\\n\\n## `RouteContext`\\n\\nEvery middleware in that chain runs against one fixed route. The second\\nargument tells it which route that is, and what that route's decorators\\ndeclared:\\n\\n```ts\\nexport interface RouteContext {\\n  readonly controller: string;\\n  readonly handler: string;\\n  readonly method: HttpMethod;\\n  readonly path: string;\\n  get<T>(key: MetaKey<T>): T | undefined;\\n}\\n```\\n\\nOne frozen object per route, built when the table is built and closed over by the\\nchain, so every request to that route sees the identical object. `get` is a `Map`\\nlookup over a record already merged at discovery.\\n\\n### Route metadata\\n\\n`metaKey` mints a unique symbol; `meta` writes a value onto a class or a method.\\nBoth are exported, and together they are the whole mechanism:\\n\\n```ts\\nimport { meta, metaKey, type MetaKey } from '@dunx/http';\\n\\nexport const TENANT: MetaKey<string> = metaKey<string>('tenant');\\nexport const Tenant = (name: string) => meta(TENANT, name);\\n```\\n\\n`@Roles(...)` and `@Public()` are wrappers over exactly this, and `ROLES` and\\n`PUBLIC` are exported so your own guard can read what they set. `@ApiDoc` in\\n`@dunx/openapi` is a third wrapper over the same channel, so documentation needs\\nno parallel registry.\\n\\nA fresh `Symbol()` per `metaKey` call means two libraries that both name a key\\n`roles` can never read each other's value. The symbol carries the identity.\\n\\nResolution is **handler first, then class**, the same direction as the familiar\\n`getAllAndOverride`. A method-level `@Public()` beats a class-level `@Roles()`.\\n\\n## Guards\\n\\nA guard is middleware that throws. There is no `CanActivate`, no boolean return,\\nno `ExecutionContext`.\\n\\n```ts\\nimport { HttpError, HttpStatusCode, PUBLIC, ROLES } from '@dunx/http';\\nimport type { Middleware, Next, RouteContext } from '@dunx/http';\\n\\nexport class RolesGuard implements Middleware {\\n  constructor(private readonly logger: Logger) {}\\n\\n  handle(req: BunRequest, ctx: RouteContext, next: Next): Promise<Response> {\\n    const required = ctx.get(ROLES);\\n    if (!required) return next();\\n\\n    const role = roleOf(req);\\n    if (role === undefined || !required.includes(role)) {\\n      throw new HttpError(\\n        HttpStatusCode.FORBIDDEN,\\n        `Requires one of: ${required.join(', ')}`,\\n      );\\n    }\\n    return next();\\n  }\\n}\\n```\\n\\nRefusing a request is `throw`. Allowing it is `return next()`. Compared to a\\nboolean-returning guard, this buys two things: the guard says _why_ in the same\\nstatement that rejects, and the rejection travels the ordinary error path, so the\\nmapper, the logger and CORS all treat it like any other failure. A `403` from a\\nguard is `{\\\"error\\\":\\\"Requires one of: admin\\\",\\\"status\\\":403}`.\\n\\n**Nothing downstream runs.** `next()` was never called, so no further middleware\\nexecutes, the input reader never reads the body, and the handler is never\\ninvoked.\\n\\nThe controller _instance_ already exists. dunx resolves the container eagerly at\\n`HttpFactory.create()`, so every controller is constructed once at boot and the\\nhandler is a bound method closed over it. A guard prevents the call; there is no\\nper-request instantiation to prevent.\\n\\n### Scoping a guard\\n\\n```ts\\n@Roles('admin')\\n@Controller('reports')\\nclass ReportsController {\\n  @Public()\\n  @Get('/health')\\n  health() {\\n    return { ok: true };\\n  }\\n\\n  @UseGuards(RolesGuard)\\n  @Post('/')\\n  create() {\\n    return { created: true };\\n  }\\n\\n  @Roles('editor')\\n  @UseGuards(RolesGuard)\\n  @Get('/draft')\\n  draft() {\\n    return { draft: true };\\n  }\\n}\\n```\\n\\n`@UseGuards` hangs off a class or a method. Guards compose rather than override,\\nso a class-level guard and a method-level guard both run, in that order. That\\ncomposition is why they are not a `MetaKey`.\\n\\nA `@UseGuards` class is resolved from **the scope of the module that declares the\\ncontroller**, so it can inject that module's private providers. One instance is\\nshared by every route that declares it.\\n\\n### Metadata alone decides nothing\\n\\n`GET /reports` above carries `@Roles('admin')` inherited from the class, and it is\\nreadable through `ctx.get(ROLES)`, but no `RolesGuard` is installed on that route,\\nso nothing enforces it. That is not a bug: metadata is a declaration, and which\\nguard reads it is a separate decision. The common shape is one global guard plus\\n`@Public()` on the routes that opt out:\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule, { middleware: [AuthGuard] });\\n```\\n\\n```ts\\n/** `Authorization: Bearer <role>` - enough to demonstrate, short of a real token. */\\nconst roleOf = (req: BunRequest): string | undefined =>\\n  req.headers.get('authorization')?.replace(/^Bearer\\\\s+/i, '');\\n\\nexport class AuthGuard implements Middleware {\\n  handle(req: BunRequest, ctx: RouteContext, next: Next): Promise<Response> {\\n    if (ctx.get(PUBLIC)) return next();\\n    const role = roleOf(req);\\n    if (role === undefined) {\\n      throw new HttpError(HttpStatusCode.UNAUTHORIZED, 'No credentials');\\n    }\\n    return next();\\n  }\\n}\\n```\\n\\nNote that the global guard still _runs_ on a public route. It chose to skip. That\\nis what makes `@Public()` do something rather than decorate, and it is why\\n`@dunx/auth`'s `SessionGuard` can be installed globally at all: better-auth's own\\nsign-in endpoints are `@Public()`, and a sign-in route that needed a session could\\nnever be reached.\\n\\n## Module middleware\\n\\nA guard that only ever made sense for one feature belongs to that feature's module:\\n\\n```ts\\n@Module({\\n  controllers: [ReportsController, ExportsController],\\n  providers: [ReportsService, TenantPolicy, TenantGuard],\\n  middleware: [TenantGuard],\\n  exports: [ReportsService],\\n})\\nexport class ReportsModule {}\\n```\\n\\n`TenantGuard` runs in front of every route `ReportsController` and\\n`ExportsController` declare, and in front of nothing else. It is resolved from\\n`ReportsModule`'s scope, so it injects `TenantPolicy`, which is on neither the\\n`exports` line nor visible anywhere outside this module. That combination - a guard\\nfor these routes, built from providers only these routes can see - is the reason\\nmodule scoping exists.\\n\\nModule middleware differs from Nest's `configure(consumer)` in three ways:\\n\\n**No `forRoutes()`.** Nest needs a path-matching mini-language because\\n`configure(consumer)` registers middleware against paths. A dunx module already owns\\nits controllers, so the routes are already named. If a guard should cover half a\\nmodule's routes, `@UseGuards` on the controller is the half.\\n\\n**No inheritance.** Importing `ReportsModule` does not put `TenantGuard` in front of\\nthe importer's routes. \\\"Importing a module silently changed my request path\\\" is a\\nsurprise worth not having, and the cost is one line in the module that actually\\nwants the guard.\\n\\n**No separate `guards` array.** A guard is middleware that throws, so a second array\\nwould be Nest's split reintroduced at the exact moment the rest of the design is\\nremoving it.\\n\\nA guard that genuinely applies everywhere stays global. `@dunx/auth`'s\\n`SessionGuard` is that case, and belongs in\\n`HttpFactory.create(root, { middleware: [SessionGuard] })`.\\n\\n## The error mapper\\n\\nA guard's `throw` needs somewhere to land as a response. The error mapper is\\nthat place: one function, for the whole app:\\n\\n```ts\\nexport type ErrorMapper = (error: unknown, req: Request) => Response;\\n```\\n\\nThe default:\\n\\n```ts\\nexport const errorMapper =\\n  (logger: Logger): ErrorMapper =>\\n  (error) => {\\n    if (error instanceof ValidationError) {\\n      return Response.json(\\n        { error: error.message, status: error.status, issues: error.issues },\\n        { status: error.status },\\n      );\\n    }\\n    if (error instanceof HttpError) {\\n      return Response.json(\\n        { error: error.message, status: error.status },\\n        { status: error.status },\\n      );\\n    }\\n    // Any `AppError` that named a status, whoever raised it.\\n    if (error instanceof AppError && isStatus(error.status)) {\\n      if (error.status >= 500) logger.error('Unhandled error', error);\\n      return Response.json(\\n        { error: error.message, status: error.status },\\n        { status: error.status },\\n      );\\n    }\\n    logger.error('Unhandled error', error);\\n    return Response.json(\\n      {\\n        error: 'Internal Server Error',\\n        status: HttpStatusCode.INTERNAL_SERVER_ERROR,\\n      },\\n      { status: HttpStatusCode.INTERNAL_SERVER_ERROR },\\n    );\\n  };\\n```\\n\\n`create()` builds it from the **bound** `Logger` when `onError` is absent, so the\\nstack lands in the same stream, and in the same shape, as everything else the\\nservice writes. `defaultErrorMapper` is the same mapper over core's\\n`ConsoleLogger`, for the case with no container to ask.\\n\\nAn `HttpError` is trusted: its status and its message reach the caller, because a\\n`404 No user 7` is information the caller is entitled to. Anything else is\\n**not** trusted: it is logged in full and answered with a bare 500, because an\\nunexpected error's message is as likely to contain a connection string as a\\ndiagnosis.\\n\\nReplace it wholesale:\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule, {\\n  onError: (error, req) => {\\n    if (error instanceof TenantMissing) {\\n      return Response.json(\\n        { error: 'Unknown tenant', status: 404 },\\n        { status: 404 },\\n      );\\n    }\\n    return defaultErrorMapper(error, req);\\n  },\\n});\\n```\\n\\nFalling through to `defaultErrorMapper` is the normal way to handle the rest.\\n\\n### An error is mapped by whoever raised it\\n\\n`AppError` carries an optional `status`, and that is how a package with no business\\nimporting the web layer still says what its failure means:\\n\\n```ts\\nexport class CursorError extends AppError {\\n  override readonly name = 'CursorError';\\n  override readonly status = 400;\\n}\\n```\\n\\nAn integer is not a dependency. `@dunx/infra` must not import `@dunx/http`, so it\\ncannot raise an `HttpError` or ship a filter that constructs one; it can set a\\nnumber, and the default mapper reads it. `CursorError` and `PageOptionsError` in\\n`@dunx/infra/pagination` already do, so a bad cursor is a 400 in an app that wrote\\nno `catch` at all.\\n\\nTwo details that follow from where the number is set:\\n\\n- **A 4xx is not logged as an incident.** It is the caller's mistake, and logging\\n  one at error level is how a log fills with entries nobody can act on. A status of\\n  500 or above still logs.\\n- **The value is range-checked.** It is set by hand in a package that never sees a\\n  `Response`, so a typo would otherwise reach `Response.json` as `status: 4000` and\\n  throw a `RangeError` from the error path itself. Anything outside 200 to 599 falls\\n  back to a 500.\\n\\nAn `AppError` with no status is a 500 with its message withheld, which is the right\\nanswer for something like `CircularDependencyError`: a boot failure is not a\\nresponse.\\n\\n### `ErrorFilter`, when the mapper needs dependencies\\n\\nA mapper is a function, so it cannot inject. The interesting ones need the app's\\nconfig to decide how much of an error to reveal, or its `Logger` to record the\\nones that became a 500. dunx's own default proves it: `errorMapper(logger)` is\\ncurried, because currying was the only way to hand a function a dependency.\\n\\n`onError` also takes a **class**, resolved from the container like any middleware:\\n\\n```ts\\nimport { ErrorFilter } from '@dunx/http';\\n\\nexport class AppErrorFilter extends ErrorFilter {\\n  constructor(\\n    private readonly logger: Logger,\\n    private readonly config: AppConfigService,\\n  ) {}\\n\\n  catch(error: unknown, req: Request): Response {\\n    if (error instanceof TenantMissing) {\\n      this.logger.warn('unknown tenant', { path: new URL(req.url).pathname });\\n      return Response.json(\\n        { error: 'Unknown tenant', status: 404 },\\n        { status: 404 },\\n      );\\n    }\\n    return defaultErrorMapper(error, req);\\n  }\\n}\\n\\n@Module({ providers: [AppErrorFilter] })\\nexport class AppModule {}\\n\\nconst app = await HttpFactory.create(AppModule, { onError: AppErrorFilter });\\n```\\n\\n`abstract class` rather than an interface, so it is a runtime value and therefore an\\ninjection token an app can rebind. Extending it is optional - the check is\\nstructural, so any class with a matching `catch` is accepted. The method is named\\n`catch` to match the thing it replaces.\\n\\n### Scoping one, without a second concept\\n\\nMiddleware already is a scoped filter, so there is no separate `@Catch`, no\\nper-controller filter and no per-route filter:\\n\\n```ts\\nexport class ReportErrors implements Middleware {\\n  async handle(\\n    req: BunRequest,\\n    ctx: RouteContext,\\n    next: Next,\\n  ): Promise<Response> {\\n    try {\\n      return await next();\\n    } catch (error) {\\n      if (error instanceof ReportUnavailable) {\\n        return Response.json(\\n          { error: 'Try again shortly', status: 503 },\\n          { status: 503 },\\n        );\\n      }\\n      throw error;\\n    }\\n  }\\n}\\n```\\n\\nPut it in `@Module({ middleware: [ReportErrors] })` and it is a module-scoped filter;\\nput it in `@UseGuards(ReportErrors)` and it is a controller- or route-scoped one.\\nRethrowing hands the error on to the next layer out, and eventually to `onError` -\\nwhich is Nest's route → controller → global cascade, expressed as the nesting it\\nalready was.\\n\\n### Where the app-wide filter sits\\n\\nInside CORS and outside everything else, request logging included. A mapped 500\\nstill carries the CORS headers a browser needs in order to _show_ it, which is\\nexactly the case where a missing header turns a readable error into a silent network\\nfailure in the console.\\n\\nRequest logging is inside it, so a request that ends in a throw is still logged\\nonce. It records the error's own status - an `HttpError`'s `status`, or 500 for\\nanything else - and rethrows, because the filter owns the response. A custom filter\\nthat maps an unexpected error to something other than a 500 is the one case where\\nthe logged status and the sent status differ; throw an `HttpError` and they agree.\\n\\n## Request logging\\n\\n`@dunx/http` installs `RequestLoggingMiddleware` outermost **by default**. It\\ninjects `Logger` and `RequestContext`, both `@dunx/core` contracts with a default\\nbinding, so it works in an app that imported no logging module at all, and picks\\nup `@arkv/logger` automatically once `@dunx/infra/logger` is imported.\\n\\n```ts\\nHttpFactory.create(AppModule, { requestLogging: false }); // remove it\\nHttpFactory.create(AppModule, { requestLogging: { ignore: ['/health'] } }); // tune it\\n```\\n\\n| Option          | Default | Notes                                                        |\\n| --------------- | ------- | ------------------------------------------------------------ |\\n| `maxBodyLength` | `2048`  | Longer bodies log as `[N bytes]`. `0` omits them entirely.   |\\n| `requestBody`   | `false` | Costs a `req.clone().text()` per request.                    |\\n| `responseBody`  | `false` | Same clone-and-buffer cost on the way out.                   |\\n| `ignore`        | `[]`    | Exact paths to skip, for a health check polled every second. |\\n\\nA 4xx logs at `warn`, a 5xx at `error`, everything else at `info`. Do not add a\\nsecond \\\"received request\\\" line; the single paired entry is the point.\\n\\nBoth body options are off for a measured reason. Turning them on costs roughly\\ntwo thirds of the throughput on the `validate` benchmark scenario, and the request\\nbody is the field most likely to contain a password. Turn them on in development,\\nwhere seeing the payload is the point.\\n\\nAn inbound `traceparent` is continued so one trace spans both services, but only\\nif it parses: it is caller-supplied and ends up in every line the request writes,\\nso a malformed one is discarded rather than repaired and the request starts a\\ntrace of its own.\\n\\nEither way the answering span comes back as `traceresponse`, unless the path is in\\n`ignore` and `correlateIgnored` is off; see\\n[Logging](dunx://guide/13-logging#what-ignore-costs-and-how-to-buy-part-of-it-back).\\n\\n### The 404 is logged too\\n\\n`Bun.serve({ routes })` answers an unmatched path itself, which would make every\\n404 invisible to request logging, metrics and tracing. So `listen()` installs one\\n`fetch` fallback that puts the global middleware in front of a\\n`{\\\"error\\\":\\\"NOT_FOUND\\\",\\\"status\\\":404}`.\\n\\nThis is **no** JavaScript router. Bun still does all the matching, and the\\nfallback runs only once Bun has decided nothing matched.\\n\\nThe context it gets says `(unmatched)` for the controller and `(none)` for the\\nhandler, which reads better in a log line than an empty string. The response says\\nonly `NOT_FOUND` and never echoes the path: on an unmatched path, repeating the\\nrequest tells a prober something about the surface it just failed to find.\\n\\n## CORS\\n\\n```ts\\napp.enableCors({\\n  origin: config.get('corsOrigin'),\\n  credentials: true,\\n  exposedHeaders: ['x-handled-by'],\\n  maxAge: 600,\\n});\\n```\\n\\n| Option           | Default                                 | Notes                                          |\\n| ---------------- | --------------------------------------- | ---------------------------------------------- |\\n| `origin`         | `'*'`                                   | A string, a list, or an `(origin) => boolean`. |\\n| `methods`        | the verbs the path declares             | Only for overriding the derived list.          |\\n| `allowedHeaders` | echoes `Access-Control-Request-Headers` |                                                |\\n| `exposedHeaders` | none                                    | What the browser lets script read.             |\\n| `credentials`    | `false`                                 |                                                |\\n| `maxAge`         | unset                                   | Seconds the browser may cache the preflight.   |\\n\\nFour behaviours to expect:\\n\\n- **A disallowed origin gets no CORS headers at all**, rather than an explicit\\n  denial. The absent headers are what make the browser block it.\\n- **`*` with `credentials` reflects the caller instead.** A browser rejects the\\n  pair outright, so the wildcard is quietly turned into the requesting origin.\\n- **A non-wildcard origin appends `vary: Origin`**, because the response now\\n  varies by request origin and a shared cache must not serve one origin's copy to\\n  another.\\n- **CORS headers are applied outside the error mapper**, so a mapped 500 still\\n  carries them.\\n\\n### Why preflight is mounted per path\\n\\nWith `routes` and no `fetch` handler, an `OPTIONS` against a GET-only route\\nreturns **404** where the specification suggests 405. Bun's native method miss\\ncannot be intercepted, so a preflight cannot be inferred:\\n\\n```\\nOPTIONS, no fetch handler   -> 404\\nOPTIONS, with fetch handler -> 418 fell through\\n```\\n\\nSo `enableCors()` mounts an explicit `OPTIONS` handler on every path, built at\\nboot from the verbs that path actually declares. It can never collide with one of\\nyour routes, because `HttpMethod` has no `OPTIONS` verb: only CORS mounts one.\\n\\n## Sharp edges\\n\\n- **Everything below `listen()` is configuration and throws afterwards.**\\n  `setGlobalPrefix`, `use`, `set`, `enableCors`. The message says why.\\n- **`app.use()` takes classes.** Passing an instance means the container never\\n  sees it and its dependencies are never injected.\\n- **A guard that returns `next()` without awaiting is fine** and is the cheaper\\n  form. Only `await` it when you need the response.\\n- **A middleware that throws synchronously out of `handle`** is still caught: the\\n  request logger wraps the `next()` call in a try/catch precisely for that case.\\n- **`ctx.get` returns `undefined` for a key nothing declared.** There is no\\n  default and no throw; a guard that requires a key should say so itself.\\n- **The same guard class declared at both class and method scope runs twice.**\\n  One instance, two positions in the chain. `@UseGuards` guarantees ordering, not\\n  deduplication. The same holds for a class listed in `@Module({ middleware })`\\n  and in `@UseGuards` on one of that module's controllers.\\n- **Module middleware resolves from its module's scope first**, so it can inject\\n  private providers. Declare it in the same module's `providers`. A class the\\n  module cannot see still resolves through the permissive `app.get` lookup, but\\n  it is then a shared instance built somewhere else.\\n- **`'trust proxy'` is off by default, and it is a hop count.**\\n  `app.set('trust proxy', n)` says how many proxies are in front of you, `true`\\n  meaning one, and the address is read that many entries from the **right** of\\n  `X-Forwarded-For`. Over-counting lets a caller choose its own address.\\n\\nNext: [WebSockets](dunx://guide/09-websockets), which are served by the same `Bun.serve`\\ncall and the same container.\\n\"},{\"slug\":\"09-websockets\",\"title\":\"WebSockets\",\"summary\":\"A gateway is a class in `providers` with `@Gateway('/path')` on it.\",\"sections\":[\"The upgrade is a real route\",\"The lifecycle decorators\",\"`Socket`\",\"The envelope\",\"Pub/sub: topics live in the runtime\",\"Multi-node fan-out\",\"Shutdown\",\"Sharp edges\"],\"body\":\"# WebSockets\\n\\nA gateway is a class in `providers` with `@Gateway('/path')` on it. It is served\\nby the **same `Bun.serve` call** as the HTTP routes, from the same container, with\\nthe same constructor injection.\\n\\n```ts\\nimport { Logger } from '@dunx/core';\\nimport {\\n  Gateway,\\n  HttpStatusCode,\\n  OnClose,\\n  OnDrain,\\n  OnMessage,\\n  OnOpen,\\n  OnPing,\\n  OnPong,\\n  OnUpgrade,\\n  type Socket,\\n} from '@dunx/http';\\nimport type { BunRequest } from 'bun';\\n\\n@Gateway('/chat')\\nexport class ChatGateway {\\n  constructor(\\n    private readonly lobby: Lobby,\\n    private readonly logger: Logger,\\n  ) {}\\n\\n  @OnUpgrade()\\n  upgrade(req: BunRequest): Response | { nickname: string } {\\n    const nickname = new URL(req.url).searchParams.get('as') ?? 'anonymous';\\n    if (nickname === 'banned') {\\n      return new Response('nope', { status: HttpStatusCode.FORBIDDEN });\\n    }\\n    return { nickname };\\n  }\\n\\n  @OnOpen()\\n  opened(socket: Socket): void {\\n    socket.subscribe(Lobby.TOPIC);\\n    socket.send('welcome');\\n  }\\n\\n  @OnMessage('say')\\n  say(text: string): { delivered: number } {\\n    return { delivered: this.lobby.broadcast(text) };\\n  }\\n\\n  @OnClose()\\n  closed(socket: Socket, code: number): void {\\n    this.logger.info(`${socket.data.path} closed with ${code}`);\\n  }\\n}\\n```\\n\\n```ts\\n@Module({ providers: [ChatGateway, Lobby] })\\nexport class ChatModule {}\\n```\\n\\nNothing else registers it. `HttpFactory.create()` walks the module graph, finds\\nevery class marked `@Gateway`, and `listen()` mounts the upgrade.\\n\\n## The upgrade is a real route\\n\\n`server.upgrade(req)` works from inside a `routes` handler, and Bun's own types\\nsay so. So a gateway is mounted as a native `GET` route in the same table as\\neverything else, rather than needing a hand-written `fetch` fallback.\\n\\nThree consequences:\\n\\n- **Bun's router runs on the upgrade path.** A gateway path may be a pattern, and\\n  `req.params` is readable inside `@OnUpgrade`.\\n- **A plain `GET` on a gateway path is a 426**, because the upgrade was refused\\n  by Bun rather than by a missing route.\\n- **A path claimed by both a controller and a gateway is a boot error** naming\\n  both, since the two tables merge and one of them would be silently dropped.\\n\\n`app.gatewayPaths` lists every path this app upgrades on, exactly as mounted.\\n`setGlobalPrefix()` moves **routes only**. The prefix applies to discovered\\ncontroller routes, and a gateway path stays what the decorator said.\\n\\n## The lifecycle decorators\\n\\n| Decorator            | Handler signature                                | Notes                                                                                                      |\\n| -------------------- | ------------------------------------------------ | ---------------------------------------------------------------------------------------------------------- |\\n| `@OnUpgrade()`       | `(req: BunRequest) => Response \\\\| unknown`       | Before the socket exists. Return a `Response` to refuse.                                                   |\\n| `@OnOpen()`          | `(socket: Socket) => void`                       | The socket is live.                                                                                        |\\n| `@OnMessage(event?)` | `(data, socket) => unknown`                      | With a name, routed by envelope; without, the raw catch-all.                                               |\\n| `@OnClose()`         | `(socket, code: number, reason: string) => void` |                                                                                                            |\\n| `@OnDrain()`         | `(socket: Socket) => void`                       | Backpressure relieved; safe to resume sending.                                                             |\\n| `@OnPing()`          | `(data, socket: Socket) => void`                 | Observation only; Bun still answers with a pong. `data` is a `Buffer` by default and follows `binaryType`. |\\n| `@OnPong()`          | `(data, socket: Socket) => void`                 | `data` follows `binaryType` the same way.                                                                  |\\n\\nEvery handler may be synchronous or `async`. A returned promise is adopted, and a\\nrejection goes to the same error handler a synchronous throw does.\\n\\n`@OnPing` and `@OnPong` are installed on Bun's handler object **only when a\\ngateway declares them**. Bun answers a ping with a pong on its own, and overriding\\nthe handler with a no-op would take that away.\\n\\n### `@OnUpgrade` is where per-connection state is declared\\n\\nWhatever it returns that is not a `Response` becomes `socket.data.context`:\\n\\n```ts\\n@OnUpgrade()\\nupgrade(req: BunRequest): Response | { nickname: string } {\\n  ...\\n  return { nickname };\\n}\\n\\n@OnOpen()\\nopened(socket: Socket<{ nickname: string }>): void {\\n  socket.send(`welcome, ${socket.data.context.nickname}`);\\n}\\n```\\n\\nReturning a `Response` refuses the upgrade, and it is the only place a connection\\ncan be refused. A gateway has no `@UseGuards`: the request has not become a\\nsocket yet, so the thing to run is a plain function call inside `@OnUpgrade`.\\n\\n## `Socket`\\n\\n```ts\\nexport interface SocketData<T = unknown> {\\n  readonly path: string;\\n  readonly context: T;\\n  /** Minted per connection at the upgrade, with `crypto.randomUUID()`. */\\n  readonly id: string;\\n}\\n\\nexport type Socket<T = unknown> = ServerWebSocket<SocketData<T>>;\\n```\\n\\nThat is a type alias over **Bun's native socket, unwrapped**. `send`, `subscribe`,\\n`unsubscribe`, `isSubscribed`, `publish`, `cork` and `close` are Bun's own methods\\nand nothing here reimplements them. Whatever the Bun documentation says a\\n`ServerWebSocket` does is what this does.\\n\\n`socket.data.path` is the gateway the socket upgraded on, and `socket.data.context`\\nis whatever `@OnUpgrade` returned.\\n\\nServer-wide options are on `HttpOptions.websocket`, `Pick`ed from Bun's own\\n`WebSocketHandler` type rather than restated, so the names cannot drift from the\\nruntime:\\n\\n```ts\\nawait HttpFactory.create(AppModule, {\\n  websocket: { idleTimeout: 30, maxPayloadLength: 64 * 1024 },\\n});\\n```\\n\\n`backpressureLimit`, `closeOnBackpressureLimit`, `idleTimeout`,\\n`maxPayloadLength`, `perMessageDeflate`, `publishToSelf` and `sendPings`, plus two\\nadditions. `onError` is where a throwing or rejecting handler goes; it defaults to\\n`console.error` with the gateway path in the line.\\n\\n`binaryType` is the other, and it says what a binary frame arrives as:\\n\\n```ts\\nawait HttpFactory.create(AppModule, {\\n  websocket: { binaryType: 'blob' },\\n});\\n```\\n\\n`'nodebuffer'` (the default, a `Buffer`), `'arraybuffer'`, `'uint8array'` or\\n`'blob'`. Bun takes it per socket rather than as a handler option, so dunx assigns\\nit as each connection opens, before that gateway's `@OnOpen` runs. It selects what a\\n**binary** frame is and never what a text frame is, so a gateway exchanging JSON is\\nunaffected.\\n\\nBun types `message` as the default's, because the runtime type is chosen at run\\ntime. A gateway that set this narrows the value itself:\\n\\n```ts\\n@OnMessage()\\nasync record(message: string | Buffer): Promise<number> {\\n  if (typeof message === 'string') return 0;\\n  const blob = message as unknown as Blob;\\n  return blob.size;\\n}\\n```\\n\\nThey are server-wide rather than per gateway because Bun's `websocket` object is\\nserver-wide. Gateways themselves are declared in `@Module({ providers })`.\\n\\n## The envelope\\n\\nThe wire protocol is one JSON object:\\n\\n```ts\\nexport interface Envelope {\\n  readonly event: string;\\n  readonly data?: unknown;\\n}\\n```\\n\\nA client sends `{\\\"event\\\":\\\"say\\\",\\\"data\\\":\\\"hello\\\"}`; the frame is routed to\\n`@OnMessage('say')` and the handler receives the `data` alone. If the\\nhandler returns a value other than `undefined`, that value is sent back to the\\nsender under the **same event name**:\\n\\n```ts\\n@OnMessage('say')\\nsay(text: string): { delivered: number } {\\n  return { delivered: this.lobby.broadcast(text) };\\n}\\n```\\n\\nThat replies to the caller. Broadcasting is `PubSub`, below.\\n\\nDecoding is skipped entirely for a gateway that declares no named handlers. A\\ngateway with only a raw `@OnMessage()` never parses anything:\\n\\n```ts\\n@OnMessage()\\nraw(message: string | Buffer, socket: Socket): void { ... }\\n```\\n\\nAnything that is not a valid envelope falls through to the raw handler rather than\\nbeing rejected: binary frames, invalid JSON, a non-object, or an object with no\\n`event` string. If there is no raw handler either, the frame is dropped. A raw\\nhandler's return value is sent as-is when it is a string or binary, and\\n`JSON.stringify`d otherwise.\\n\\nTwo handlers claiming the same slot is a boot error naming both:\\n\\n```\\nHandler collision in ChatGateway: message \\\"say\\\" is claimed by say() and by speak().\\nOne handler per event.\\n```\\n\\nSo is a `@Gateway` with no handlers at all, and two gateways on one path.\\n\\n## Pub/sub: topics live in the runtime\\n\\n`socket.subscribe(topic)` is Bun's own method. There is **no JavaScript map of\\ntopic to socket set** anywhere in dunx, because the runtime already keeps one and\\na userland copy would be slower, would need cleaning up on close, and would be a\\nsecond source of truth.\\n\\nThe consequence is that a node cannot enumerate which topics its sockets joined.\\nNothing hooks `socket.subscribe`, so nothing sees it. That constraint shapes the\\nrelay design below.\\n\\n### `PubSub`\\n\\nPublishing from a service that holds no socket is the common case, so `PubSub` is\\ninjectable. `HttpFactory` binds it around your root module, so nothing has to be\\nimported or registered:\\n\\n```ts\\nimport { PubSub } from '@dunx/http';\\n\\nexport class Lobby {\\n  static readonly TOPIC = 'lobby';\\n\\n  constructor(private readonly pubsub: PubSub) {}\\n\\n  broadcast(text: string): number {\\n    return this.pubsub.publishEvent(Lobby.TOPIC, 'said', text);\\n  }\\n}\\n```\\n\\nListing `PubSub` in your own `providers` raises the container's duplicate-binding\\nerror.\\n\\n| Member                              | Does                                                                           |\\n| ----------------------------------- | ------------------------------------------------------------------------------ |\\n| `publish(topic, data, compress?)`   | `server.publish`. Bytes sent locally, `0` if dropped, `-1` under backpressure. |\\n| `publishEvent(topic, event, data?)` | The same envelope `@OnMessage(event)` reads.                                   |\\n| `subscriberCount(topic)`            | Subscribers on **this** node only.                                             |\\n| `origin`                            | This process's id on the relay channel.                                        |\\n| `attached` / `relaying`             | Whether `listen()` has run, and whether a relay is configured.                 |\\n| `relayThrough(relay, options?)`     | Opt into multi-node fan-out.                                                   |\\n| `close()`                           | Releases a relay this `PubSub` owns.                                           |\\n\\n`PubSub.publish` is `server.publish`, which **reaches the sender**.\\n`socket.publish` does not, absent `publishToSelf`. The two are not\\ninterchangeable, and mixing them up is the usual reason a client does not see its\\nown message. Publishing before `listen()` throws with a message saying so, rather\\nthan dropping the frame.\\n\\n## Multi-node fan-out\\n\\n`server.publish` is per process. Two nodes behind a load balancer each fan out to\\ntheir own sockets and to nobody else's. The fix is a relay: publish locally\\n**and** hand the message to the other nodes, which then publish locally too.\\n\\nThe contract is two methods:\\n\\n```ts\\nexport interface PubSubRelay {\\n  publish(channel: string, message: string): unknown;\\n  subscribe(channel: string, listener: (message: string) => void): unknown;\\n  close?(): unknown;\\n}\\n```\\n\\nThe return types are `unknown` because the implementations disagree: Bun's\\n`publish` resolves the subscriber count, `@dunx/infra`'s resolves nothing, and an\\nin-memory bus resolves nothing at all. A returned promise is awaited by `subscribe` and watched for rejection by\\n`publish`; anything else is taken as having succeeded.\\n\\n`close?` is optional. Omitting it is how a relay says it does not own the\\nconnections and should not close them: a relay built on the application's own\\nshared `RedisConnection` must leave that to the container.\\n\\n### The batteries-included one\\n\\n```ts\\nimport { HttpFactory, RedisRelay } from '@dunx/http';\\n\\nconst app = await HttpFactory.create(AppModule, {\\n  relay: new RedisRelay({ connectionTimeout: 500 }),\\n  relayChannel: 'my-app:ws',\\n});\\n```\\n\\n### The same relay from the container\\n\\n`WsRelayModule` binds the relay as a provider, so its url comes off\\n`ConfigService` like everything else and the container closes it at shutdown:\\n\\n```ts\\n@Module({\\n  imports: [\\n    WsRelayModule.forRootAsync({\\n      useFactory: (config: AppConfigService) => ({\\n        url: config.get('redis').url,\\n        connectionTimeout: 500,\\n      }),\\n      inject: [AppConfigService],\\n    }),\\n  ],\\n  providers: [provide(HttpOptionsProvider, { useClass: AppHttpOptions })],\\n})\\nexport class HttpConfigModule {}\\n```\\n\\n```ts\\nimport { HttpOptionsProvider, WsRelay, type PubSubRelay } from '@dunx/http';\\n\\nexport class AppHttpOptions extends HttpOptionsProvider {\\n  constructor(private readonly bus: WsRelay) {\\n    super();\\n  }\\n\\n  override get relay(): PubSubRelay {\\n    return this.bus;\\n  }\\n}\\n```\\n\\nA relay of your own needs no module: extend `WsRelay`, bind it, and return it from\\nthat same getter. See [Configuration](dunx://guide/12-configuration) for the options\\nprovider.\\n\\n### Postgres instead of Redis\\n\\n`WsRelayModule.forPostgres` and `forPostgresAsync` bind `PostgresRelay`, which\\ncarries the same frames over `LISTEN`/`NOTIFY` on `Bun.SQL`. An app already running\\nPostgres needs no broker for fan-out:\\n\\n```ts\\nWsRelayModule.forPostgresAsync({\\n  useFactory: (config: AppConfigService) => ({\\n    url: config.get('database').url,\\n  }),\\n  inject: [AppConfigService],\\n});\\n```\\n\\nThe factory changes with the method: `PostgresRelayOptions` is `url` and `max`, so\\nRedis-only settings like `connectionTimeout` do not carry across. The injection site\\ndoes not change, because both relays are bound under `WsRelay`. Which method you\\ncall has to be decided up front, though: a binding is fixed once the module graph\\nis built, so it cannot be read from config the container resolves later.\\n\\nSwitching from Redis changes two things. **A frame over about 7.9 KB does not\\ncross**, because Postgres caps a `NOTIFY` payload at 7999 bytes and the envelope\\nadds a topic and an origin id to it; `PubSub` logs one warning and fan-out stays\\nlocal for that message. And `LISTEN`/`NOTIFY` is Postgres only, so `Bun.SQL`'s\\nSQLite and MySQL adapters reject it.\\n\\n`RedisRelay` is built on `Bun.RedisClient`, a Bun global, so the relay itself costs\\n`@dunx/http` **no new dependency**. The package's one runtime dependency is\\n`@arkv/shared`, which the outbound HTTP client behind `./client` uses; nothing in the\\ngateway or the relay path reaches for it. With no `url` it resolves the same chain Bun's client does,\\n`$VALKEY_URL`, then `$REDIS_URL`, then `redis://localhost:6379`.\\n\\nA URL with an unrecognised scheme is rejected at construction. Bun accepts any\\nstring and fails later with an opaque `Connection closed`, which an\\nabsence-tolerant relay would swallow into silent single-node fan-out.\\n\\nIt opens **two** connections. A `Bun.RedisClient` in subscriber mode rejects every\\ndata command and throws synchronously doing it, so the subscription cannot share\\nthe socket that publishes. This is the same split the socket.io Redis adapter\\nmakes.\\n\\n`maxRetries` defaults to **`0`**, and that default is not a preference. A\\n`Bun.RedisClient` that never connects keeps an internal retry timer alive past\\n`close()`, and the process then never exits. A relay is the connection most\\nlikely to be absent, so the default lets the app boot, degrade, and still exit.\\nRaise it when Redis is a hard requirement.\\n\\n### Reusing a connection you already have\\n\\n`PubSubRelay` is two methods, so `@dunx/infra`'s `RedisConnection` satisfies it\\n**structurally**, with no adapter and with `@dunx/http` depending on\\n`@dunx/infra` not at all. Because it has to come out of the container, it goes\\nthrough `relayThrough` rather than the option:\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule);\\nawait app.get(PubSub).relayThrough(app.get(RedisConnection), {\\n  channel: 'my-app:ws',\\n});\\nawait app.listen();\\n```\\n\\n`relayThrough` throws on a second call rather than replacing the relay: two\\nsubscriptions on one channel is another way to get every message twice.\\n\\n### One channel for every topic\\n\\nEvery topic's frames travel on a single broker channel, `dunx:ws` by default.\\n\\nTwo things force it. A node cannot know which topics its sockets joined, because\\n`socket.subscribe` goes straight into Bun. And pattern subscription is not an option:\\n`Bun.RedisClient.psubscribe(pattern)` is accepted, but unlike\\n`subscribe(channel, listener)` it takes no listener - passing one throws - and the\\nclient exposes no hook for pattern messages. Re-checked on Bun 1.3.14.\\n\\nThe cost is stated plainly: **every node reads every relayed frame** and drops the\\nones for topics it has no local subscriber on, which is a `server.publish`\\nreturning `0`. Two applications sharing one Redis need two channels; pass\\n`relayChannel`.\\n\\n### `origin`, and why a node does not fan out its own echo\\n\\nRedis delivers a published message to **every** subscriber of the channel, the\\npublishing application included: a relay's own subscribe connection receives what\\nits publish connection just sent. Fanning that out locally a second time would\\ndeliver twice to every client on the publishing node, which is worse than not\\nhaving the feature at all.\\n\\nSo every frame carries the publishing process's id:\\n\\n```ts\\nreadonly #origin = Bun.randomUUIDv7();\\n```\\n\\nand the inbound path drops a frame whose origin is its own:\\n\\n```ts\\n#inbound(message: string): void {\\n  const frame = decodeRelay(message);\\n  if (!frame || frame.origin === this.#origin) return;\\n  this.#server?.publish(frame.topic, frame.data);\\n}\\n```\\n\\n`Bun.randomUUIDv7` rather than a counter, because two nodes booted in the same\\nmillisecond must not collide.\\n\\nThe other half of the rule is that the inbound path calls `server.publish` and\\n**nothing else**. Re-relaying there would put the frame back on the channel that\\ndelivered it, forever.\\n\\nThe wire format is `{ o, t, d }`, with a `b: 1` flag when `d` is base64: a binary\\nframe has to survive a text channel, because Bun's buffer-mode subscription is not\\nimplemented. Anything that does not decode to that shape is ignored, so another\\napplication's traffic on a shared channel is inert rather than fatal.\\n\\nThis is asserted rather than assumed. `@dunx/http`'s relay suite checks\\n**exactly one** delivery per subscriber with relaying on, once over an in-memory\\nbus and once over real Redis with two `Bun.serve` instances and a client on each.\\nBoth fail with two frames if the origin check is removed, which was verified by\\nremoving it.\\n\\n### `resubscribe`: retrying the boot subscribe\\n\\nPublishing recovers on its own, because every publish retries the broker. A failed\\n**subscribe** used to be retried by nothing, so a node whose broker was briefly\\ndown at boot stayed permanently deaf to the other nodes while still looking\\nhealthy. `RelayOptions.resubscribe` fixes that:\\n\\n```ts\\nawait app.get(PubSub).relayThrough(relay, {\\n  channel: 'my-app:ws',\\n  resubscribe: { attempts: 5, delayMs: 500 },\\n  onError: (error, phase) => logger.warn(`relay could not ${phase}`, { error }),\\n});\\n```\\n\\n| Field      | Default | Meaning                                           |\\n| ---------- | ------- | ------------------------------------------------- |\\n| `attempts` | `5`     | Retries after the first failure. `0` disables.    |\\n| `delayMs`  | `500`   | First delay. Doubles each attempt, capped at 30s. |\\n\\nBounded rather than infinite, and the timer is `unref`'d, so a broker that never\\ncomes back can neither hold the process open nor spin forever. A successful\\nsubscribe cancels the remaining attempts; `close()` cancels a pending one before\\nanything can await, so a retry can never fire against a relay being closed.\\n\\n### Degrading\\n\\nA broker that cannot be reached is reported through `onError` and otherwise left\\nalone. Local fan-out is unaffected and the app boots either way. `onError` is\\ncalled **once** when the relay starts failing and not again until it works, so an\\nunreachable broker cannot flood the log. When `HttpOptions.relay` is used, the\\ndefault `onError` routes through the app's `Logger` at `warn`:\\n\\n```\\nthe websocket relay could not subscribe. Fan-out is local to this process until it recovers.\\n```\\n\\n### What the relay does not cover\\n\\n`socket.publish(topic, data)` is Bun's own method on the socket and does not go\\nthrough `PubSub`, so it stays local. Anything that must cross nodes goes through\\n`PubSub`. `subscriberCount` is local too: Bun counts its own sockets and cannot\\ncount another node's.\\n\\n## Shutdown\\n\\nA graceful `server.stop()` **never resolves while a WebSocket is open**, because\\nit waits for open connections and a WebSocket does not close on its own. So an app\\nwith gateways force-stops:\\n\\n```ts\\nawait this.#server?.stop(this.#websocket !== undefined);\\n```\\n\\nThose clients observe close code **1006**. There is no way around it without\\nhanging, and an app that hangs on `SIGTERM` gets `SIGKILL` anyway.\\n\\n`PubSub.close()` runs **before** the container tears down. A relay this app owns\\nholds two Redis sockets and, with `maxRetries: 0`, nothing else would ever close\\nthem.\\n\\nIt also drops the server reference, which makes an app-owned relay safe to leave\\nsubscribed. `PubSubRelay` has no unsubscribe, so a frame may still arrive on a\\nshared connection after this node stopped, and with no server there is nothing to\\nfan it out to.\\n\\n`enableShutdownHooks()` wires `SIGTERM` and `SIGINT` to all of it.\\n\\n## Sharp edges\\n\\n- **`PubSub.publish` before `listen()` throws.** `listen()` is what attaches the\\n  server. Publish from `onInit` and you get an `AppError` saying exactly that.\\n- **`server.publish` reaches the sender, `socket.publish` does not.** Absent\\n  `publishToSelf`, these are different operations.\\n- **`setGlobalPrefix` does not move gateways.** Only controller routes are\\n  prefixed.\\n- **`idleTimeout` is in seconds** and Bun rejects anything above 960 at\\n  `Bun.serve` time.\\n- **A handler that throws does not close the socket.** It goes to\\n  `websocket.onError` and the connection stays up.\\n- **Two gateways on one path, two handlers in one slot, and a gateway with no\\n  handlers are all boot errors.**\\n- **The event-name reply goes to the sender only.** Returning a value from\\n  `@OnMessage('x')` replies; it does not broadcast.\\n\\nNext: [OpenAPI](dunx://guide/10-openapi).\\n\"},{\"slug\":\"10-openapi\",\"title\":\"OpenAPI\",\"summary\":\"`@dunx/openapi` builds an OpenAPI 3.1 document out of the schemas the routes already validate against, and serves a self-contained explorer page for it.\",\"sections\":[\"What the generator reads\",\"`@ApiDoc`\",\"Security comes from the guards' own metadata\",\"Naming a schema with `.meta({ id })`\",\"The vendor check\",\"The page\",\"Sharp edges\"],\"body\":\"# OpenAPI\\n\\n`@dunx/openapi` builds an OpenAPI 3.1 document out of the schemas the routes\\nalready validate against, and serves a self-contained explorer page for it.\\n\\nThe point is that there is **one** description of a request in the codebase. The\\nzod schema on `@Post('/', createUser)` is the object the request path calls\\n`~standard.validate` on, and it is the same object the generator reads. Nothing is\\nreconstructed from reflection, and there is no annotation that can disagree with\\nwhat the server enforces.\\n\\n```ts\\nimport { HttpFactory } from '@dunx/http';\\nimport { OpenApiModule } from '@dunx/openapi';\\n\\nconst app = await HttpFactory.create(\\n  OpenApiModule.forRoot({\\n    title: 'dunx full example',\\n    version: '0.1.0',\\n    description:\\n      'Generated from the same zod schemas the routes validate against.',\\n    root: AppModule,\\n  }),\\n);\\n```\\n\\nThe page it produces is at\\n[demo.dunx.win/api/docs](https://demo.dunx.win/api/docs), generated from that\\nexample's own schemas.\\n\\n`forRoot` **wraps** the root it documents and returns it, so `HttpFactory.create`\\nis still handed one module ref and the root is named once. That is also why the\\ndocument describes the documentation routes: they are routes, and pretending\\notherwise would be the first lie in the file.\\n\\n| Option        | Default         | Meaning                                    |\\n| ------------- | --------------- | ------------------------------------------ |\\n| `title`       | required        | `info.title`                               |\\n| `version`     | required        | `info.version`                             |\\n| `description` | none            | `info.description`                         |\\n| `servers`     | none            | `servers[]`                                |\\n| `root`        | required        | The module graph to document and to import |\\n| `path`        | `/docs`         | Where the HTML page is mounted             |\\n| `jsonPath`    | `/openapi.json` | Where the document is mounted              |\\n\\n`forRootAsync({ root, useFactory, inject })` is the same module with everything but\\n`root` produced by a factory, which is how any of the above comes off validated\\nconfig:\\n\\n```ts\\nOpenApiModule.forRootAsync({\\n  root: AppModule,\\n  useFactory: (config: AppConfigService) => ({\\n    title: config.get('app').name,\\n    version: config.get('app').version,\\n    path: config.get('app').docsPath,\\n  }),\\n  inject: [AppConfigService],\\n});\\n```\\n\\n`root` stays outside the factory because it is a module reference: the graph must\\nexist before the container that would run the factory does.\\n\\nThe mount paths escape that. The controller declares its two routes with **path\\nthunks**, and route discovery runs after every provider has settled, so the\\nfactory that produced a path has returned before anything reads it. `RoutePath`\\nin `@dunx/http` is the type.\\n\\nzod is an **optional** `peerDependency`. Install it and schemas convert; do not,\\nand the document still generates with warnings where the schemas would have been.\\n\\n## What the generator reads\\n\\n`describeRoutes(root)` walks the module graph and returns exactly what\\n`discoverRoutes` produced for the server, so the document describes the table that\\nis actually served. From each route it reads:\\n\\n- `options.body`, `options.query`, `options.params` - the Standard Schema objects.\\n- `options.status` - the success status, following the same rule `buildRoutes`\\n  applies: an explicit status, else 201 for POST, else 200.\\n- `options.response` - the Standard Schema per status code the route answers with.\\n- `meta` and `classMeta` - whatever `@Public`, `@Roles` and `@ApiDoc` wrote.\\n- the path and the method, from the verb decorator.\\n\\nA document can be written to a file from a script with no container and no\\nserver, because `describeRoutes` never constructs a controller.\\n\\n`discoverRoutes` walks an instance's prototype chain looking for marked\\nmethods, and `Object.create(Controller.prototype)` is that chain with nothing\\nbehind it: `instance.constructor` still resolves to the class, every method is\\nstill reachable, and no constructor, or dependency of one, has to exist:\\n\\n```ts\\nimport { describeRoutes, generateDocument } from '@dunx/openapi';\\n\\nconst { document, warnings } = await generateDocument(\\n  describeRoutes(AppModule),\\n  {\\n    title: 'API',\\n    version: '1.0.0',\\n  },\\n);\\nawait Bun.write('openapi.json', JSON.stringify(document, null, 2));\\n```\\n\\n### Paths, operations and tags\\n\\n- `/users/:id` becomes `/users/{id}`. Bun matches the first form, OpenAPI templates\\n  the second.\\n- `operationId` is `Controller_handler`, for example `UsersController_one`.\\n- The tag is the controller's name with a trailing `Controller` stripped, so\\n  `UsersController` documents itself as `Users`. `@ApiDoc({ tags })` overrides it.\\n- The document's top-level `tags` list is read back off the **operations**, so it\\n  declares exactly the tags they carry. Deriving it separately from the class names\\n  let a document declare tags nothing used and use tags it never declared, which\\n  puts a viewer's sidebar at odds with its own operation list.\\n- Path parameters are driven by the **path** rather than the schema. OpenAPI requires\\n  every path parameter to appear in the template, so a schema property that is not\\n  a path token is not a path parameter. A token with no matching schema property\\n  is documented as a required `string`.\\n- Query parameters are expanded one per property, with `required` taken from the\\n  schema's own `required` list. A `$ref` cannot be split into `parameters`\\n  entries, so a query schema's root object is read rather than referenced.\\n- Ordering is deterministic. Paths sort by code unit rather than `localeCompare`,\\n  because a generated document has to come out byte-identical on every machine and\\n  collation is locale dependent: ICU sorts `/reports/{id}` before\\n  `/reports/health`, and a machine without ICU sorts it after.\\n\\n### The 400 every validating route can produce\\n\\nAny route that declares a `body`, `query` or `params` schema gets a documented\\n`400` referencing a `ValidationError` component:\\n\\n```json\\n{\\n  \\\"error\\\": \\\"Invalid body\\\",\\n  \\\"status\\\": 400,\\n  \\\"issues\\\": [{ \\\"message\\\": \\\"...\\\", \\\"path\\\": \\\"name\\\" }]\\n}\\n```\\n\\nThat is the framework's real error shape, from `defaultErrorMapper` and the issue\\nflattening in the input reader. Documenting it beats leaving a caller to discover\\nit from a failing request.\\n\\n### Response bodies\\n\\n`options.response` is keyed by status code and takes the same Standard Schema\\nvalues the request side takes:\\n\\n```ts\\nexport const oneUser = {\\n  params: UserIndex,\\n  response: { 200: SanitizedUser, 404: NotFound },\\n} as const satisfies RouteSchemas;\\n```\\n\\nOne contract covers both directions: a named response schema hoists into\\n`components/schemas` and the operation `$ref`s it exactly as a request body does.\\nThat gives `.meta({ id })` on a response-only schema its meaning, and gives the\\ndocument what it needs for client codegen.\\n\\nTwo consequences of it being the same contract rather than a second channel:\\n\\n- The response side is converted with **`io: 'output'`**, because it describes what\\n  comes back: a field with a default is always present there, and\\n  `additionalProperties: false` is an output-side claim. The request side keeps\\n  `io: 'input'`. A schema used both ways therefore converts twice, and if the two\\n  views differ, one `.meta({ id })` cannot name both.\\n- **It is never validated.** See\\n  [Validation](dunx://guide/06-validation#routeschemas): documenting a response is not\\n  enforcing it, and paying a validation pass per response for a documentation\\n  feature would be the wrong trade.\\n\\nA status the route does not otherwise mention is documented from this key alone, so\\na `404` a handler throws is in the document without a second annotation. The\\ndeclared success status keeps its own description and gains the `content`.\\n\\n### Names in the explorer\\n\\nA hoisted schema gets a `title` equal to its `components/schemas` key, unless it\\ndeclared one of its own.\\n\\nAn explorer labels a **nested** schema by that title. Swagger UI renders a model as\\n`title || displayName || name`: a `$ref` at the root of a response supplies those\\nfallbacks from the ref, but the same `$ref` inside `items` supplies neither, so\\n`array<User>` read as `array<object>` before the title was there.\\n\\nPut prose in `description`. A sentence in `title` is what a reader sees instead of\\nthe type name, and the Schemas list becomes unbrowsable.\\n\\n### A plain JSON Schema\\n\\n`response` also takes a JSON Schema object, which needs no conversion:\\n\\n```ts\\nconst Pong = Object.freeze({\\n  $id: 'Pong',\\n  type: 'object',\\n  properties: { pong: { type: 'boolean' } },\\n  required: ['pong'],\\n});\\n\\n@Get('/ping', { response: { 200: Pong } })\\n```\\n\\n`$id` hoists it into `components/schemas` and leaves a `$ref`, the way\\n`.meta({ id })` does for a zod schema, and is stripped from the definition. Without\\none it is inlined.\\n\\nThis is the response side only. `body`, `query` and `params` are parsed, so they\\nneed a validator.\\n\\n`@dunx/http` documents `/health/live` and `/health/ready` this way: it has no\\nvalidator dependency, and `HEALTH_REPORT_SCHEMA` is exported, so an app mounting the\\nprobes on its own paths can reference the same definition.\\n\\n## `@ApiDoc`\\n\\nSchemas describe shape. They cannot describe intent, grouping or deprecation, so\\n`@ApiDoc` carries the prose:\\n\\n```ts\\n@ApiDoc({\\n  tags: ['notes'],\\n  description: 'A list in memory, for showing the prefix, middleware and CORS.',\\n})\\n@Controller('notes')\\nexport class NotesController {\\n  @ApiDoc({\\n    summary: 'Echo the caller’s address',\\n    description: 'Reads the socket address, honouring `x-forwarded-for`.',\\n    deprecated: true,\\n  })\\n  @Get('/whoami')\\n  whoami({ req }: Input<RouteSchemas>): { ip: string | undefined } {\\n    return { ip: this.address.of(req) };\\n  }\\n}\\n```\\n\\n| Field         | Type       | Notes                                          |\\n| ------------- | ---------- | ---------------------------------------------- |\\n| `summary`     | `string`   | One line.                                      |\\n| `description` | `string`   | Markdown, rendered server side.                |\\n| `tags`        | `string[]` | Overrides the tag derived from the class name. |\\n| `deprecated`  | `boolean`  | Only `true` is emitted.                        |\\n\\nIt works at class scope and at method scope, and the two **compose per field**.\\nThe operation above is tagged and described from the class, then summarised and\\ndeprecated from the method; the method wins only on a field they both set.\\n\\nClass tags plus per-method summaries therefore need no repetition, and dropping\\nthe class `tags` from a method does not silently fall back to the class-name\\ndefault.\\n\\n`@ApiDoc` is otherwise a thin wrapper over `@dunx/http`'s generic route-metadata\\nchannel: `metaKey` mints a unique symbol and `meta` writes it. No parallel\\nregistry, no second discovery pass. See\\n[Middleware and guards](dunx://guide/08-middleware-and-guards#route-metadata).\\n\\nDocumentation differs from that mechanism in one place. `RouteContext.get`\\nresolves a key handler-first-then-class, **replacing** the class's value, which\\nsuits `@Roles` and breaks a value made of independent fields. Composing the two\\nneeds the class's own record, so a `DiscoveredRoute` carries `classMeta` next to\\nthe merged `meta`.\\n\\n## Security comes from the guards' own metadata\\n\\nThe document reads the same `@Public()` and `@Roles()` that the guards read at\\nruntime, so the two cannot drift. There is no separate `@ApiBearerAuth`\\ndecorator to keep in sync:\\n\\n| Route declares     | Operation gets                                                  |\\n| ------------------ | --------------------------------------------------------------- |\\n| `@Public()`        | `security: []`, an explicit empty requirement                   |\\n| `@Roles('editor')` | `security: [{ bearer: [] }]` and `x-required-roles: ['editor']` |\\n| neither            | nothing, so it inherits any document-level default              |\\n\\nThe description gains a line too: `Requires one of these roles: \\\\`editor\\\\`.`\\n\\n`components.securitySchemes.bearer` is added only when some route declares roles,\\nand it is honest about what it means:\\n\\n> Whatever the guards in front of these routes accept. dunx does not ship an\\n> authentication scheme - this documents that a guard is there.\\n\\nNote the consequence of reading metadata rather than guards: a class-level\\n`@Roles('admin')` is merged into every route on that class and therefore\\ndocumented on all of them, **even where no guard reads it**. The document\\ndescribes what the metadata declares; which guard enforces it is a separate\\ndecision, and one no generator can see. If that gap matters, install the guard.\\n\\n## Naming a schema with `.meta({ id })`\\n\\nzod emits nested definitions under `$defs`. OpenAPI calls that slot\\n`components/schemas`. Hoisting and rewriting `#/$defs/Tag` to\\n`#/components/schemas/Tag` is the whole difference between the two, and\\n`.meta({ id })` is the only annotation this package asks for:\\n\\n```ts\\nexport const Tag = z\\n  .object({ label: z.string().min(1) })\\n  .meta({ id: 'Tag', title: 'A label attached to a user' });\\n\\nexport const CreateUser = z\\n  .object({\\n    name: z.string().min(1).max(40),\\n    tags: z.array(Tag).default([]),\\n  })\\n  .meta({ id: 'CreateUser', title: 'Create a user' });\\n```\\n\\n- `id` names a `components/schemas` entry, and the request body becomes\\n  `{ \\\"$ref\\\": \\\"#/components/schemas/CreateUser\\\" }`. The `Tag` definition it\\n  referenced comes along with it.\\n- `title` lands inline on the schema, as a human label.\\n- A schema with no `id` is **inlined** where it is used, which suits a one-off\\n  body.\\n- A **self-referential** schema is hoisted whether or not it has an `id`. zod emits\\n  a cyclic ref as `#`, meaning \\\"this schema\\\", which is true where zod emitted it\\n  and false once it is one entry among many; hoisting is what gives the ref a place\\n  to point at.\\n\\nQuery and params schemas are expanded into `parameters` rather than referenced, so\\nan `id` on one of those normally creates no component. A cyclic one still does.\\n\\n`danglingRefs(document)` is exported and worth running on any generated document:\\na `$ref` that resolves to nothing renders as an empty box in every viewer and\\nreports no error at all. The generator runs it on its own output as a canary and\\nadds a warning if it ever fires.\\n\\n## The vendor check\\n\\nStandard Schema **validates**. It says nothing about describing, and there is no\\nvendor-neutral way to turn a schema into JSON Schema. So conversion is per vendor,\\ngated on the one piece of vendor information the interface carries:\\n\\n```ts\\nconst vendor = schema['~standard'].vendor;\\nif (vendor !== 'zod') { ... }\\n```\\n\\nzod is the vendor implemented, through\\n`z.toJSONSchema(schema, { io: 'input', unrepresentable: 'any' })`:\\n\\n- `io: 'input'` is what a **request** looks like. A field with a default is\\n  optional going in and present coming out, and `additionalProperties: false` is\\n  an output-side claim.\\n- `unrepresentable: 'any'` because a `Date` or a `bigint` in one schema must not\\n  take the whole document down.\\n\\nzod is imported **dynamically**, and only once a zod schema has actually turned\\nup, so a consumer on Valibot never loads it and a consumer without it installed\\ngets warnings rather than a module-resolution crash at import time.\\n\\nAnything else degrades to a permissive schema plus a warning. Claiming to have\\ndocumented a body that was never read would be worse than saying so:\\n\\n```\\nUsersController_createBody: no JSON Schema conversion for Standard Schema vendor\\n\\\"valibot\\\". Standard Schema validates; it does not describe. The schema is\\ndocumented as permissive.\\n```\\n\\nThe operation also carries `x-schema-vendor` so the gap is visible in the document\\nitself. Every warning is readable straight after boot:\\n\\n```ts\\nconst app = await HttpFactory.create(OpenApiModule.forRoot({ ... }));\\nconsole.log(app.get(OpenApiExplorer).warnings);\\n```\\n\\n`OpenApiExplorer` is bound by an **async** `useFactory`, so the whole document,\\nevery schema conversion included, is settled before the first constructor runs.\\nA degraded document is visible at boot rather than at the moment somebody notices\\nan empty request body in the explorer.\\n\\n## The page\\n\\n`GET /docs` is one self-contained HTML document: a boot `<style>`, the model in a\\n`<script type=\\\"application/json\\\">`, and the explorer bundle in a second\\n`<script>`. **Nothing is fetched.** No CDN, no `src=`, no `<link>`, no webfont, no\\nexternal image.\\n\\nThat guarantee ruled out `swagger-ui-dist` (11.7 MB unpacked, and a CDN in\\npractice) and `@scalar/api-reference` (11 MB). It is asserted by the package's own\\ntests, which boot the real bundle and check that it issues zero fetches.\\n\\nThe explorer is a React and Mantine frontend, bundled at build time and inlined\\ninto the page as a string. Importing `@dunx/openapi` does not load it; see\\n[What the page costs](#what-the-page-costs).\\n\\nWhat the page does that a static rendering cannot:\\n\\n- **Sends requests.** Every operation is executable, the usual reason people\\n  reach for swagger-ui.\\n- **Credentials once.** An **Authorize** dialog reads\\n  `components.securitySchemes` and offers a field per scheme, applied to every\\n  operation that declares it and kept in the tab's `sessionStorage`.\\n- **Path parameters are substituted.** Every `{name}` in the template gets an\\n  input whether or not the document declares it, so a request can never go out\\n  with a literal `{id}` in it.\\n- **The body arrives pre-filled** from the schema, with refs resolved and\\n  `minimum` and `format` honoured.\\n\\nTwo Bun APIs do work a dependency usually would: `Bun.escapeHTML` escapes the\\nshell, and `Bun.markdown.html` renders every description **on the server**, with\\n`noHtmlBlocks`, `noHtmlSpans` and `tagFilter` on, so raw HTML in a schema\\ndescription is escaped rather than trusted and no markdown parser lands in the\\nbundle. Request samples are pre-computed server side too.\\n\\n`OpenApiExplorer` caches by mount prefix, because `setGlobalPrefix()` is applied\\nafter the container is built. The request path only serialises a string that\\nalready exists.\\n\\nThe page needs JavaScript, which the hand-written page it replaced did not. A\\n`<noscript>` block links the raw document.\\n\\n### What the page costs\\n\\nThe explorer is a React bundle: **437 KiB raw, 123 KiB gzipped**, of which React\\nis 188 KiB. The served page is about 458 KiB, or ~125 KiB gzipped.\\n\\n**Importing `@dunx/openapi` does not load it.** `renderPage` lives behind the\\n`@dunx/openapi/ui` subpath and `OpenApiExplorer.page()` reaches it with\\n`await import()` on the first request for the page, caching the rendered string\\nper mount prefix. A service that never serves `/docs` pays 19.8 KB and ~5.7 ms of\\nimport, against 479.6 KB and ~10.9 ms when the bundle was inlined.\\n\\nTo avoid it entirely, do not mount the page. `OpenApiModule` still serves\\n`/openapi.json`, and pointing your own swagger-ui or Scalar at it is one route.\\n`buildModel` and `renderShell` are exported so a page of your own can reuse the\\npre-rendered prose, the samples and the fields.\\n\\n## Sharp edges\\n\\n- **The `root` you pass to `forRoot` is also what gets imported.** Do not import\\n  it separately as well; the container's duplicate-binding check will say so.\\n- **A non-object schema for `query` or `params` documents nothing** and produces\\n  a warning: a query string is a set of named parameters, and there is nothing to\\n  expand.\\n- **A response schema is checked by the compiler, never at runtime.** The verb\\n  decorator constrains the handler's return type to `response[<success status>]`,\\n  so a handler answering with another shape is a `TS1241` naming the mismatched\\n  property. Nothing validates a response body per request. Declaring a plain\\n  JSON Schema instead of a Standard Schema turns the check off for that route:\\n  there is no type to infer from it.\\n- **A schema used in both directions converts twice**, with `io: 'input'` for the\\n  request and `io: 'output'` for the response. If the two views differ - anything\\n  with a `.default()` - one `.meta({ id })` cannot name both, and the store keeps\\n  the first and warns.\\n- **`x-required-roles` is an extension** rather than standard OpenAPI, so a\\n  reader can see the roles without parsing the description sentence.\\n- **A class-level `@Roles` documents every route on that class**, whether or not\\n  a guard reads it there.\\n- **The document describes the mounted paths**, `setGlobalPrefix` included, but\\n  gateway paths are not in it: OpenAPI has no representation for a WebSocket\\n  upgrade. See [WebSockets](dunx://guide/09-websockets).\\n\\nNext: [Testing](dunx://guide/11-testing).\\n\"},{\"slug\":\"11-testing\",\"title\":\"Testing\",\"summary\":\"`@dunx/testing` is two functions and a logger.\",\"sections\":[\"`createTestApp`: the container, and nothing else\",\"`RecordingLogger`\",\"`createTestServer`: a real server on port 0\",\"Testing a guard through the real request path\",\"Configuration the harness does not cover\",\"`{ modules, overrides }`, and nothing more\",\"Sharp edges\"],\"body\":\"# Testing\\n\\n`@dunx/testing` is two functions and a logger. It builds the container your\\napplication would have, with the bindings you name replaced, and it can put a\\nreal `Bun.serve` in front of that container too.\\n\\n```ts\\nimport {\\n  createTestApp,\\n  createTestServer,\\n  RecordingLogger,\\n} from '@dunx/testing';\\n```\\n\\nThe runner is `bun test`. There is no separate test framework to install and\\nnothing to configure.\\n\\n## `createTestApp`: the container, and nothing else\\n\\nUse it when the thing under test is a service, which is most of the time.\\n\\n```ts\\nimport { describe, expect, test } from 'bun:test';\\nimport { provide, token } from '@dunx/core';\\nimport { createTestApp } from '@dunx/testing';\\n\\nclass FixedForecast extends ForecastClient {\\n  constructor(private readonly celsius: number) {\\n    super();\\n  }\\n\\n  override async temperatureAt(): Promise<number> {\\n    return this.celsius;\\n  }\\n}\\n\\ndescribe('createTestApp', () => {\\n  test('an override replaces the real collaborator everywhere', async () => {\\n    const app = await createTestApp({\\n      modules: [WeatherModule],\\n      overrides: [provide(ForecastClient, { useValue: new FixedForecast(31) })],\\n    });\\n\\n    expect(await app.get(WeatherService).read('lisbon')).toEqual({\\n      city: 'lisbon',\\n      celsius: 31,\\n      advice: 'take water',\\n    });\\n\\n    await app.shutdown();\\n  });\\n});\\n```\\n\\n`modules` takes one module ref or several. They become the `imports` of one\\nsynthetic root, so no fixture module has to be written by hand. What comes back is\\na plain `App`: `get`, `shutdown`, `closed`, `enableShutdownHooks`. Providers are\\nresolved eagerly, and `onInit` has already run by the time the promise settles,\\nexactly as in production.\\n\\nThe fake above is a class the test wrote: a subclass with an `override`, nothing\\nmore. It typechecks against the real thing. A hand-built object literal would\\nnot, and there is no mocking framework, interface, or `jest.mock` involved either.\\n\\n### Overrides replace in place\\n\\n`AppFactory.create` builds the scope graph it always would, then substitutes by\\ntoken **in every scope that binds it**, before anything resolves. That reach is\\nwhat makes the harness safe to use: a test that stubs `Logger` never has to know\\nhow many modules bind it.\\n\\nAn override is **not** an extra module appended at the end that wins. A module\\nappended at the end would be its own scope, invisible to everything already\\nwired, so it would win nothing.\\n\\nNaming a scope for the override would push container topology into every suite,\\nso the substitution runs across every scope instead. Where two scopes genuinely\\nbind a token differently and only one is meant, resolve through the module that\\nmatters rather than overriding.\\n\\nThe consequence that matters:\\n\\n```ts\\ntest('the discarded provider is never constructed', async () => {\\n  class Exploding extends ForecastClient {\\n    constructor() {\\n      super();\\n      throw new Error('the real client was constructed');\\n    }\\n  }\\n\\n  @Module({\\n    providers: [\\n      provide(ForecastClient, { useClass: Exploding }),\\n      WeatherService,\\n    ],\\n  })\\n  class ExplodingWeather {}\\n\\n  const app = await createTestApp({\\n    modules: [ExplodingWeather],\\n    overrides: [provide(ForecastClient, { useValue: new FixedForecast(5) })],\\n  });\\n\\n  expect((await app.get(WeatherService).read('oslo')).celsius).toBe(5);\\n  await app.shutdown();\\n});\\n```\\n\\nBecause the replacement happens before anything resolves, the discarded\\nprovider's constructor never runs. Its `useFactory` never runs, and its\\n`onInit` never fires. That is the guarantee a hand-rolled fixture usually\\nmisses: with an \\\"append and win\\\" model, the real database provider is still in\\nthe list, still gets instantiated, and still opens a connection that nothing\\nunder test uses.\\n\\nThe seam lives in `@dunx/core`, as `AppFactory.create(root, { overrides })`,\\nrather than in the testing package. It is not a test-shaped API: it says\\n\\\"compose this graph with these bindings replaced\\\", the same statement a\\ndeployment variant would make. `HttpOptions extends AppOptions`, so\\n`HttpFactory.create` inherits it without a second mechanism.\\n\\n### An unmatched override is an error - unless it is a class\\n\\n```ts\\ntest('an override naming a token nobody binds is an error', async () => {\\n  const Clock = token<Date>('Clock');\\n\\n  const message = await createTestApp({\\n    modules: [WeatherModule],\\n    overrides: [provide(Clock, { useValue: new Date(0) })],\\n  }).then(\\n    () => 'it resolved',\\n    (error: unknown) => (error as Error).message,\\n  );\\n\\n  expect(message).toContain('Nothing to override for Clock');\\n});\\n```\\n\\nThe full message, and the second clause is the important one:\\n\\n> Nothing to override for Clock: no module in the graph binds it, **and it is not a\\n> class, so nothing self-binds it either**. An override replaces a binding - it\\n> cannot add one, because a token nobody bound is a token nothing under test\\n> resolves.\\n\\nA silent no-op here is the worst possible failure. It leaves a suite asserting\\nagainst the real provider it believed it had swapped, and the suite passes. The\\ncheck names **every** unmatched token rather than the first, so a renamed token\\ndoes not turn into three rounds of the same error.\\n\\n**A class is exempt from that check, and that is a real gap in the safety net.**\\nA class self-binds: it needs no declaration to be resolvable. An override for one\\nreplaces the binding that _would_ have happened on demand, so registering it\\neagerly would construct a stub for a collaborator the graph under test never\\nreaches. `Injector.registerLazy` exists to avoid exactly that.\\n\\nThe cost is that a **typo'd class override is accepted in silence**: there is no\\nbinding for it to fail to match, and nothing under test asks for it, so it\\nsimply never fires. Measured:\\n\\n```\\noverride a declared class      -> resolves, replacement used\\noverride a class nobody binds  -> resolves, no error\\noverride a token() nobody binds -> throws \\\"Nothing to override\\\"\\n```\\n\\nSo the check protects `token()` bindings and cannot protect class ones. If a class\\noverride appears not to work, the first thing to suspect is the class itself: two\\ncopies of a package means two class objects, and the one you imported in the suite is\\nnot the one the module bound.\\n\\nThe most common way to hit it is a token whose module you forgot to list in\\n`modules`. The second most common is a second copy of `@dunx/core` in the\\ndependency tree: a second copy is a second `Logger` class and therefore a token\\nthat matches nothing.\\n\\n### Overriding a contract no module bound\\n\\n`Logger` and `RequestContext` are the two tokens `@dunx/core` guarantees are\\nresolvable. They are offered by `registerDefault` **after** every module, so in a\\ntypical app nothing in the module graph binds them at all, and an override of\\n`Logger` would have been \\\"nothing to override\\\".\\n\\nThe defaults are built as a `Registration[]` and run through the same\\nsubstitution, so the logger can be silenced:\\n\\n```ts\\ntest('RecordingLogger keeps entries instead of writing them', async () => {\\n  const logger = new RecordingLogger();\\n  const app = await createTestApp({\\n    modules: [WeatherModule],\\n    overrides: [\\n      provide(ForecastClient, { useValue: new FixedForecast(400) }),\\n      provide(Logger, { useValue: logger }),\\n    ],\\n  });\\n\\n  await app.get(WeatherService).read('venus');\\n\\n  expect(logger.at(LogLevel.ERROR).map((entry) => entry.message)).toEqual([\\n    'implausible reading for venus: 400',\\n  ]);\\n  await app.shutdown();\\n});\\n```\\n\\nOverriding one default does not disturb the other: `RequestContext` is still\\ncore's. The unmatched-override check runs after both stages, module bindings and\\ndefaults, so it never fires spuriously on a token only the defaults provide.\\n\\n## `RecordingLogger`\\n\\nA `Logger` that keeps entries instead of writing them, so a suite can assert on\\nwhat was logged and stays quiet when it does not care.\\n\\n| Member      | Does                                            |\\n| ----------- | ----------------------------------------------- |\\n| `entries`   | `{ level, message, params }[]`, in order.       |\\n| `at(level)` | Filters by `LogLevel`.                          |\\n| `clear()`   | Empties `entries`.                              |\\n| `logLevel`  | `LogLevel.VERBOSE`, so nothing is filtered out. |\\n\\nIt exists because the `Logger` contract is seven levels of three overloads each,\\nand every suite that wanted a silent logger would otherwise hand-write the same\\nthirty lines.\\n\\nIt **interprets nothing**: no level filtering, no error promotion, no merging of\\nextras. Those are the backing logger's behaviour, and asserting against a\\nreimplementation of them would prove nothing about the logger you actually ship.\\nThe one exception is `log()`, which records as `info` per the contract.\\n\\n## `createTestServer`: a real server on port 0\\n\\n```ts\\nimport { describe, expect, test } from 'bun:test';\\nimport { provide } from '@dunx/core';\\nimport { createTestServer } from '@dunx/testing';\\n\\ntest('validates, routes and serialises through the real server', async () => {\\n  const server = await createTestServer({\\n    modules: [WeatherModule],\\n    overrides: [provide(ForecastClient, { useValue: new FixedForecast() })],\\n    prefix: 'api',\\n  });\\n\\n  const { status, body } = await server.json<{ advice: string }>(\\n    'api/weather/oslo',\\n  );\\n\\n  expect(status).toBe(200);\\n  expect(body.advice).toBe('take a coat');\\n  await server.close();\\n});\\n```\\n\\n`TestServerOptions` is `TestAppOptions` plus every `HttpOptions` field except\\n`port` and `overrides`, so `middleware`, `onError`, `websocket` and the rest are\\nall available. `prefix` applies `setGlobalPrefix` before `listen()`, so the\\nclient's URLs carry it.\\n\\n### Pass the same `HttpOptions` production passes\\n\\nEvery one of those fields is **absent unless you pass it**, and two of them\\ndecide what the application _is_: `middleware` holds the global guards, `onError`\\nthe error mapper.\\n\\nA suite that forgets them gets a server with no global guards and the default\\nmapper. It boots fine and answers 200 where production answers 401. That fixture\\nis quietly testing a different application.\\n\\nSo define the options once, export them, and give the same function to `main.ts`\\nand to every suite:\\n\\n```ts\\n// src/http-options.ts\\nexport const httpOptions = (config: AppConfig): HttpOptions => ({\\n  middleware: [ApiKeyGuard, RateLimit],\\n  onError: mapDomainErrors,\\n  requestLogging: { ignore: ['/health'], correlateIgnored: true },\\n  port: config.PORT,\\n});\\n```\\n\\n```ts\\n// main.ts\\nconst app = await HttpFactory.create(AppModule, httpOptions(config));\\n```\\n\\n```ts\\n// any suite\\nconst server = await createTestServer({\\n  modules: [ApiModule],\\n  ...httpOptions(config),\\n});\\n```\\n\\n`createTestServer` overrides `port` and `requestLogging` itself, so spreading the\\nwhole object is safe.\\n\\n**Forgetting is loud.** If the graph declares a `Middleware` implementation that no\\n`@UseGuards` attaches - the shape of a global guard - and no `middleware` was\\npassed, `createTestServer` writes one line to `console.warn` naming the class.\\nPass `middleware: []` to declare the omission intentional and the warning goes\\naway.\\n\\nIt writes to `console.warn` rather than the bound `Logger` so that a suite\\nasserting on a `RecordingLogger` does not find an entry the application never\\nwrote.\\n\\n`TestServer` is a `TestClient` plus two things:\\n\\n| Member                  | Does                                                               |\\n| ----------------------- | ------------------------------------------------------------------ |\\n| `url`                   | The base URL, as `listen()` returned it.                           |\\n| `request(path?, init?)` | The raw `Response`. For bytes, HTML, or a header assertion.        |\\n| `json<T>(path?, init?)` | `{ status, headers, body }` in one await.                          |\\n| `app`                   | The `HttpApp`, for `app.get(...)` on anything in the container.    |\\n| `close()`               | `app.shutdown()`: stops the server, then tears the container down. |\\n\\n`json:` on the init object serialises a body and sets `content-type:\\napplication/json` unless the headers already carry one. It covers every verb, so\\nthere is no `post`/`put`/`patch` triple to remember:\\n\\n```ts\\nconst { status, body } = await server.json('echo', {\\n  method: 'POST',\\n  json: { id: 7 },\\n});\\n```\\n\\n### Why a real server rather than a mocked HTTP layer\\n\\nBecause **the routing under test is Bun's.**\\n\\ndunx writes no JavaScript router. `Bun.serve({ routes })` does the path matching,\\nthe `:param` extraction, the per-method dispatch and the method-miss 404.\\n\\nA fake dispatcher could only exercise the parts of the request path dunx wrote,\\nand would silently agree with itself about the rest. A test that passes against a\\nfake and fails against Bun has taught you nothing except that the fake is\\nwrong.\\n\\nThe specific things only a real server proves:\\n\\n- `/weather/:city` matched, and `req.params.city` populated by Bun.\\n- A method miss is Bun's 404 and not a 405.\\n- The unmatched-path fallback runs, and answers\\n  `{\\\"error\\\":\\\"NOT_FOUND\\\",\\\"status\\\":404}` rather than Bun's default body.\\n- An upgrade actually upgrades, which no fake `Request` can do.\\n- Header casing, `content-type` negotiation and body streaming behave as the\\n  runtime behaves.\\n\\nAnd the objection does not hold up on cost: `Bun.serve` binds in about a\\nmillisecond. **Port 0** means the OS picks a free port, so a suite can run in\\nparallel with a `bun start` already holding 3000 and with other suites.\\n\\n```ts\\ntest('an unmatched path is a JSON 404, not Bun’s default', async () => {\\n  const server = await createTestServer({ modules: [WeatherModule] });\\n\\n  const { status, body } = await server.json<{ error: string }>('nope');\\n\\n  expect(status).toBe(404);\\n  expect(body.error).toBe('NOT_FOUND');\\n  await server.close();\\n});\\n```\\n\\n### Request logging is off here, and only here\\n\\n`createTestServer` defaults `requestLogging` to `false`. The framework default\\nstays on, because one structured entry per request is right in production and pure\\nnoise in a suite that would print a JSON line per assertion.\\n\\nAsking for it is asking for it:\\n\\n```ts\\nconst logger = new RecordingLogger();\\nconst server = await createTestServer({\\n  modules: [ApiModule],\\n  overrides: [provide(Logger, { useValue: logger })],\\n  requestLogging: true,\\n});\\n```\\n\\n## Testing a guard through the real request path\\n\\nA guard is worth testing through the server rather than by calling\\n`guard.handle()` directly. What it reads is route metadata that only exists once\\nroutes have been discovered: `ctx.get(PUBLIC)` has no meaning outside a built\\nroute table, and a hand-constructed `RouteContext` would be testing your\\nconstruction of it rather than the guard.\\n\\n```ts\\nclass KnownKeys extends ApiKeys {\\n  override accepts(presented: string): boolean {\\n    return presented === 'good-key';\\n  }\\n}\\n\\nconst withKnownKeys = () =>\\n  createTestServer({\\n    modules: [ReportsModule],\\n    overrides: [provide(ApiKeys, { useClass: KnownKeys })],\\n  });\\n\\ntest('401 with no key, 403 with a bad one, 200 with a good one', async () => {\\n  const server = await withKnownKeys();\\n\\n  expect((await server.json('reports')).status).toBe(401);\\n  expect(\\n    (await server.json('reports', { headers: { 'x-api-key': 'nope' } })).status,\\n  ).toBe(403);\\n\\n  const ok = await server.json<readonly string[]>('reports', {\\n    headers: { 'x-api-key': 'good-key' },\\n  });\\n  expect(ok.status).toBe(200);\\n  expect(ok.body).toEqual(['q1-revenue', 'q2-revenue']);\\n\\n  await server.close();\\n});\\n\\ntest('@Public() opts a route out of the guard', async () => {\\n  const server = await withKnownKeys();\\n\\n  expect((await server.json('reports/health')).status).toBe(200);\\n\\n  await server.close();\\n});\\n```\\n\\nThe guard has dependencies like anything else, which makes it worth a test: the\\nkey store is injected, so the suite binds a known set of keys instead\\nof reaching for the real one. The guard resolves from the container, so the\\noverride reaches it with no special handling.\\n\\nGuards are covered in [Middleware and guards](dunx://guide/08-middleware-and-guards).\\n\\n## Configuration the harness does not cover\\n\\n`createTestServer` calls `listen()` for you, which means `enableCors`, `use` and\\n`set` have already missed their window. When a test needs one of them, drop to the\\nfactory. `testRoot` is exported for exactly that:\\n\\n```ts\\nimport { testRoot } from '@dunx/testing';\\nimport { HttpFactory } from '@dunx/http';\\n\\nconst app = await HttpFactory.create(testRoot([ApiModule]), {\\n  requestLogging: false,\\n});\\napp.enableCors({ origin: 'https://example.test', credentials: true });\\nconst url = await app.listen(0);\\n```\\n\\n`testClient(url)` is exported too, so the same `request`/`json` pair can be\\npointed at an app booted any other way.\\n\\n## `{ modules, overrides }`, and nothing more\\n\\nA fixture class that needs binding goes in a two-line `@Module`, exactly where\\nit would live if it were real:\\n\\n```ts\\n@Module({\\n  providers: [provide(Clock, { useValue: new FixedClock('2026-01-01') })],\\n})\\nclass FixedTime {}\\n\\nconst app = await createTestApp({ modules: [BillingModule, FixedTime] });\\n```\\n\\nThat two-line module is also why the harness has no `providers` option: the\\ndocumented shape stays `{ modules, overrides }`. A `providers` list would let it\\nassemble graphs that do not exist in the application, and a suite would end up\\nasserting against a container the production app never builds.\\n\\n## Sharp edges\\n\\n- **`json()` throws on a response that is not JSON**, and says so usefully: it\\n  reads the body as text first, so a 204, an HTML error page or a plain-text body\\n  fails with the status and the content type rather than with `JSON.parse`'s\\n  message. Use `request()` for anything that is not JSON.\\n- **Always `close()`.** A `Bun.serve` left listening keeps the test process alive.\\n  `afterAll(() => server.close())` is the usual shape when a suite shares one\\n  server.\\n- **`createTestApp` needs `shutdown()` too** if any provider implements\\n  `onShutdown`, or holds a connection.\\n- **Overrides are keyed by token identity** rather than by name. Two classes\\n  called `Clock` are two tokens.\\n- **The harness is not an assertion DSL** and will not become one. `json()`\\n  returns values that `expect` already reads well, so a failure points at your\\n  assertion rather than at a matcher this package would have had to define.\\n- **`prefix` accepts `string | undefined`** where the other options do not, so a\\n  suite that runs one fixture prefixed and unprefixed can pass a variable without\\n  a conditional spread at the call site.\\n- **An omitted `HttpOptions` field is absent** rather than defaulted to whatever\\n  production uses. `middleware` and `onError` are the two that change what the app\\n  does; share one `httpOptions(config)` between `main.ts` and the suites.\\n\\nThis is the last of the core guides. `examples/testing` is a working version of\\neverything above, and `examples/full/src/service.test.ts` exercises the harness\\nagainst the full application.\\n\"},{\"slug\":\"12-configuration\",\"title\":\"Configuration\",\"summary\":\"Every app needs to turn a pile of environment strings into a typed object, once, at boot, and fail loudly if a value is missing.\",\"sections\":[\"A schema, or a function\",\"One validation function in place of a schema DSL\",\"Configuration files\",\"A worked example\",\"Reading it\",\"Why `as` exists\",\"No loader, and no dotenv\",\"Testing\",\"No `isGlobal`, no `forRootAsync`\",\"Where config is consumed\",\"The HTTP server's own settings\"],\"body\":\"# Configuration\\n\\nEvery app needs to turn a pile of environment strings into a typed object, once,\\nat boot, and fail loudly if a value is missing. `ConfigModule` in `@dunx/core` is\\nthat, and almost nothing else.\\n\\n```ts\\nimport { ConfigModule, Module } from '@dunx/core';\\nimport { validate, AppConfigService } from './config.js';\\n\\n@Module({\\n  imports: [ConfigModule.forRoot({ validate, as: AppConfigService })],\\n})\\nexport class AppModule {}\\n```\\n\\n## A schema, or a function\\n\\n`forRoot` takes exactly one of the two, and the type enforces it.\\n\\n```ts\\nConfigModule.forRoot({ schema: envSchema, as: AppConfigService });\\n```\\n\\n`schema` is any Standard Schema, so zod 4, Valibot and ArkType all work and dunx\\nnames no vendor. A failure fails boot with a `ConfigError` listing every issue and\\nits path, rather than whatever shape the library throws.\\n\\n## One validation function in place of a schema DSL\\n\\n`ConfigModule.forRoot` takes one required option, in either spelling:\\n\\n```ts\\ntype ConfigModuleOptions<T extends object, S extends object = ConfigSource> = {\\n  source?: ConfigSource;\\n  as?: new (values: T) => ConfigService<T>;\\n} & (\\n  | { validate: (env: S) => T | Promise<T>; schema?: undefined }\\n  | { schema: StandardSchemaV1<unknown, T>; validate?: undefined }\\n);\\n```\\n\\n`forRoot` has two signatures, and `files` picks between them: without it `S` is\\n`ConfigSource`, the flat string map `Bun.env` is; with it `S` is `ConfigValues`,\\nwhere a parsed `port: 3000` is already a number. Annotating `ConfigValues` in an\\napp that passes no files is a compile error rather than a run of empty reads.\\n\\n`validate` receives the raw key/value pairs and returns the shaped, typed object.\\nWhatever it throws is what boot fails with, so throw something whose message says\\nwhich keys are wrong. `schema` is the same step handed to a Standard Schema\\ninstead, and its issues become a `ConfigError` naming each path.\\n\\nThat is the whole contract, plus `files`. There is no `envFilePath` and no\\n`expandVariables`.\\n\\n## Configuration files\\n\\n`files` reads YAML, TOML and JSON and merges them under the environment:\\n\\n```ts\\nConfigModule.forRoot({\\n  files: ['application.yml', `application-${Bun.env.NODE_ENV}.yml`],\\n  schema: configSchema,\\n  as: AppConfigService,\\n});\\n```\\n\\n`.yml` and `.yaml` go through `Bun.YAML`, `.toml` through `Bun.TOML`, `.json`\\nthrough `JSON.parse`. All three are native, so this costs no dependency.\\n\\n**A relative path resolves against `process.cwd()`, and a missing file is\\nskipped.** Those two together mean an app started from another directory boots\\non defaults rather than failing, so prefer a path anchored to the module:\\n\\n```ts\\nimport { join } from 'node:path';\\n\\nconst files = [\\n  join(import.meta.dir, '..', 'application.yml'),\\n  join(import.meta.dir, '..', `application-${Bun.env.NODE_ENV}.yml`),\\n];\\n```\\n\\n`examples/full` uses that form.\\n\\nFiles are read in the order given and deep-merged, so an overlay overrides only\\nthe keys it names. **A file that does not exist is skipped**, which is what lets\\none list cover every environment. A file whose top level is not an object fails\\nboot naming the file, and so does one that does not parse.\\n\\nThe shape a file is good at is the one a flat variable is bad at:\\n\\n```yaml\\nseed:\\n  users:\\n    - ada\\n    - grace\\n```\\n\\n`ConfigService.get` reads that back with a dotted path: `config.get('seed.users')`.\\n\\n### The environment still wins\\n\\n`Bun.env` is spread over the merged files, so a variable overrides a file key of\\nthe same name. That match is by exact name. There is no convention mapping\\n`DATABASE__POOLSIZE` onto `database.poolSize`, because that needs a separator, a\\ncase rule and a coercion rule, which is the schema DSL this module does not have.\\n\\nOverride a nested key in `validate`, where it stays visible:\\n\\n```ts\\nvalidate: (src) => schema.parse({\\n  ...src,\\n  database: { ...src.database, url: Bun.env.DATABASE_URL ?? src.database.url },\\n}),\\n```\\n\\nStructure belongs in the file, secrets and per-deploy values in the environment.\\n\\n`validate` receives `ConfigValues` rather than `ConfigSource` once files are in\\nplay: a parsed `port: 3000` is already a number, where `Bun.env` only ever holds\\nstrings.\\n\\nA schema DSL can only express what its author anticipated; a function expresses\\neverything. Grouping flat variables into nested objects, deriving one value from\\ntwo others, reading a secret out of a file, calling a secret manager: each is\\nordinary code inside `validate`, and none needs an option added to dunx.\\n\\nWith zod it is one line, or none at all if the schema is the whole of it:\\n\\n```ts\\nconst validate = (env: ConfigSource): AppConfig => envSchema.parse(env);\\n// or: ConfigModule.forRoot({ schema: envSchema, as: AppConfigService })\\n```\\n\\nA hand-written function works identically and costs no dependency:\\n\\n```ts\\nexport const validate = (env: ConfigSource): AppConfig => {\\n  const port = Number(env['PORT'] ?? 3000);\\n  if (!Number.isInteger(port) || port < 0 || port > 65535) {\\n    throw new Error(`PORT must be a port number, got \\\"${env['PORT']}\\\"`);\\n  }\\n  return { port };\\n};\\n```\\n\\ndunx does not pick the library, and it does not need to know which one you picked.\\n\\n## A worked example\\n\\nThis is `examples/full/src/config.ts`, trimmed. Flat variables in, a shaped object\\nout:\\n\\n```ts\\nimport { ConfigService, type ConfigSource, LogLevel } from '@dunx/core';\\nimport { z } from 'zod';\\n\\nconst envSchema = z.object({\\n  PORT: z.coerce.number().int().min(0).max(65535).default(3000),\\n  LOG_LEVEL: z.enum(LogLevel).default(LogLevel.INFO),\\n  LOG_FILE: z.string().optional(),\\n  DATABASE_FILE: z.string().default(':memory:'),\\n  REDIS_URL: z.string().optional(),\\n});\\n\\nexport interface AppConfig {\\n  readonly appName: string;\\n  readonly port: number;\\n  readonly log: {\\n    readonly level: LogLevel;\\n    readonly file: string | undefined;\\n  };\\n  readonly database: { readonly file: string };\\n  readonly redis: { readonly url: string | undefined };\\n}\\n\\nexport class AppConfigService extends ConfigService<AppConfig> {}\\n\\nexport const validate = (env: ConfigSource): AppConfig => {\\n  const parsed = envSchema.safeParse(env);\\n  if (!parsed.success) {\\n    const issues = parsed.error.issues\\n      .map((issue) => `${issue.path.join('.') || '(root)'}: ${issue.message}`)\\n      .join('\\\\n - ');\\n    throw new Error(`Configuration is invalid:\\\\n - ${issues}`);\\n  }\\n  const value = parsed.data;\\n\\n  return {\\n    appName: 'dunx-full',\\n    port: value.PORT,\\n    log: { level: value.LOG_LEVEL, file: value.LOG_FILE },\\n    database: { file: value.DATABASE_FILE },\\n    redis: { url: value.REDIS_URL },\\n  };\\n};\\n```\\n\\nTwo things worth copying from it. `.default()` is where a value comes from when\\nthe variable is unset, so a clean checkout boots with no `.env` at all. And the\\nreturned shape is nested even though the input is flat, so `config.get('log')`\\nhands back a group rather than a lone string.\\n\\n## Reading it\\n\\n`ConfigService<T>` has three members and no more:\\n\\n```ts\\nclass ConfigService<T extends object = Record<string, unknown>> {\\n  readonly values: T;\\n  get(keyOrPath): // the value there, typed\\n  getOrThrow(keyOrPath): // the same, minus null and undefined\\n}\\n```\\n\\n```ts\\nexport class Notifier {\\n  constructor(private readonly config: AppConfigService) {}\\n\\n  send(): void {\\n    const { level } = this.config.get('log');\\n    const host = this.config.get('db.host');\\n    const { appName } = this.config.values;\\n    const url = this.config.getOrThrow('redis.url');\\n  }\\n}\\n```\\n\\n- `get(key)` returns the value at that key, typed. A key absent from `T` is a\\n  compile error rather than a runtime `undefined`.\\n- `get('a.b')` and `get('a.b.c')` read a path, checked the same way. A step that\\n  is absent or `null` reads as `undefined` rather than throwing, and the return\\n  type says so.\\n- `getOrThrow(...)` guards the **value** being present. A missing key is already\\n  a type error, so this catches a declared-but-optional field that is `undefined`\\n  or `null` at run time. It throws `ConfigError` naming the whole path.\\n- `values` is the whole validated object, for destructuring or passing on.\\n\\nPaths stop at three segments. `config.values.a.b.c.d` is what reaches past them.\\nEach depth is a separate overload rather than one recursive type: a conditional\\ntype over `T` anywhere on this class makes its variance unmeasurable, and\\n`app.get(ConfigService)` then stops compiling. A top-level key that itself\\ncontains a dot is read whole, so it keeps winning over a path that spells it.\\n\\n## Why `as` exists\\n\\nDeclare a subclass and hand it to `as`:\\n\\n```ts\\nexport class AppConfigService extends ConfigService<AppConfig> {}\\n\\nConfigModule.forRoot({ validate, as: AppConfigService });\\n```\\n\\nConstructor injection does not strictly need this. `@dunx/transform` records the\\nbare type name of a constructor parameter and discards the type argument, so\\n`constructor(private readonly config: ConfigService<AppConfig>)` resolves the\\n`ConfigService` token while the annotation keeps the precise type.\\n\\nIt breaks in a **factory's `inject` array**, and `as` exists on the API because\\nof that gap. `inject: [ConfigService]` resolves to\\n`ConfigService<Record<string, unknown>>`: the token is a plain runtime value,\\ncarrying no type argument to recover.\\n\\nA factory annotating its parameter as `ConfigService<AppConfig>` is then\\n**rejected**: parameters are contravariant, so a function demanding the narrower\\ntype is not assignable where one accepting the wider type is expected.\\n\\n```ts\\n// Rejected. The token says Record<string, unknown>; the parameter demands AppConfig.\\nLoggerModule.forRootAsync({\\n  useFactory: (config: ConfigService<AppConfig>) => ({\\n    level: config.get('log').level,\\n  }),\\n  inject: [ConfigService],\\n});\\n\\n// Fine. AppConfigService is a distinct runtime value that is already AppConfig-shaped.\\nLoggerModule.forRootAsync({\\n  useFactory: (config: AppConfigService) => ({\\n    level: config.get('log').level,\\n  }),\\n  inject: [AppConfigService],\\n});\\n```\\n\\nA subclass serves as both a precise token and a usable annotation - exactly what\\nthe factory case needs. Every `forRootAsync` in dunx exists so options can be\\nread off config, so `as` comes up almost immediately.\\n\\n`ConfigService` stays bound to the same instance when `as` is used, so either name\\ninjects. That matters for library code, which only knows the base contract.\\n\\n## No loader, and no dotenv\\n\\nBun loads `.env` and `.env.local` itself, before your code runs. There is\\ntherefore no file loading in `ConfigModule`, no `envFilePath`, and no `dotenv`\\ndependency. `source` defaults to `Bun.env`, which already carries whatever those\\nfiles set.\\n\\nThe precedence and file list are Bun's, documented by Bun, and dunx does not\\nre-implement or override them.\\n\\n## Testing\\n\\nPass `source` instead of mutating the process environment:\\n\\n```ts\\nimport { AppFactory, ConfigModule, Module } from '@dunx/core';\\n\\nconst module = ConfigModule.forRoot({\\n  validate,\\n  source: { PORT: '8080', LOG_LEVEL: 'debug' },\\n});\\n```\\n\\nMutating `Bun.env` in a test leaks into every other test in the same process, and\\n`bun test` runs a file's tests in one process. A literal object is also the only\\nway to assert that `validate` rejects a bad value, since you cannot unset a\\nvariable that a developer happens to have exported in their shell.\\n\\nThe raw source is bound too, under the `ConfigInput` token, but it is **not**\\nexported: `validate` is what reads it, and everything downstream reads the shaped\\nobject instead.\\n\\n## No `isGlobal`, no `forRootAsync`\\n\\n`ConfigModule.forRoot` is already `global: true`, and exports `ConfigService`\\nplus whatever `as` names. Configuration is the one thing every module reads, so\\na flag to turn that on would only ever be turned on. `ConfigInput` stays\\nprivate: it is the raw environment, and nothing outside the module should read\\nit.\\n\\nEvery other module offers `forRootAsync`; `ConfigModule` needs none. `validate`\\nmay already return a promise, and the container settles every factory before the\\nfirst constructor runs, so an async validation has finished by the time anything\\ncan read it.\\n\\n`forRootAsync` exists elsewhere to let a factory **inject**, the one thing a\\nzero-argument function cannot do. `validate` runs before everything and has\\nnothing to inject.\\n\\n## Where config is consumed\\n\\n`forRootAsync({ useFactory, inject })` on `LoggerModule`, `ImagesModule`,\\n`RedisModule`, `FilesModule`, `DbModule`, `QueueModule` and `AuthModule` all exist\\nso their options can come off `ConfigService`:\\n\\n```ts\\nDbModule.forRootAsync(SyncDatabase, {\\n  useFactory: (config: AppConfigService) =>\\n    new SyncSqliteOptions({ schema, filename: config.get('database').file }),\\n  inject: [AppConfigService],\\n});\\n```\\n\\nSee [Logging](dunx://guide/13-logging), [Database](dunx://guide/14-database),\\n[Queues](dunx://guide/15-queues), [Authentication](dunx://guide/17-authentication) and\\n[Files and images](dunx://guide/18-files-and-images) for the rest, and\\n[Providers](dunx://guide/03-providers) for how a factory provider resolves in general.\\n\\n## The HTTP server's own settings\\n\\n`HttpFactory.create(root, options)` builds the container, so its `options` argument\\nis assembled before `ConfigService` exists. `HttpOptionsProvider` is the same\\nsettings as a provider, which can inject:\\n\\n```ts\\nexport class AppHttpOptions extends HttpOptionsProvider {\\n  constructor(private readonly config: AppConfigService) {\\n    super();\\n  }\\n\\n  override get prefix(): string {\\n    return this.config.get('prefix');\\n  }\\n}\\n\\n@Module({\\n  providers: [provide(HttpOptionsProvider, { useClass: AppHttpOptions })],\\n  exports: [HttpOptionsProvider],\\n})\\nexport class HttpConfigModule {}\\n```\\n\\nEvery member has a default, so a subclass overrides only what differs. Anything\\npassed to `create()` wins field by field, and `setGlobalPrefix`, `enableCors` and\\n`set` still work and win over both, since they run after construction.\\n\\nOverride a field with a field and a getter with a getter - TypeScript rejects the\\nother pairing (`TS2611`, `TS2610`). To derive a field from config, declare\\n`override trustProxy: boolean` and assign it in the constructor.\\n\\nSee [Upgrading](dunx://guide/23-upgrading) for what each imperative call maps to.\\n\"},{\"slug\":\"13-logging\",\"title\":\"Logging\",\"summary\":\"dunx logs every HTTP request by default, in an app that imported no logging module at all, and it does that without `@dunx/core` taking a single dependency.\",\"sections\":[\"The contract lives in core\",\"`ConsoleLogger`, the zero-dependency default\",\"`RequestContext` and `AsyncRequestContext`\",\"`LoggerModule`: swapping in `@arkv/logger`\",\"What is logged at boot\",\"Request logging\",\"What it costs\",\"Related\"],\"body\":\"# Logging\\n\\ndunx logs every HTTP request by default, in an app that imported no logging\\nmodule at all, and it does that without `@dunx/core` taking a single\\ndependency.\\n\\n## The contract lives in core\\n\\n`Logger` is an **abstract class** in `@dunx/core`:\\n\\n```ts\\nexport abstract class Logger {\\n  abstract readonly logLevel: LogLevel;\\n\\n  abstract verbose(message: string, ...optionalParams: unknown[]): void;\\n  abstract debug(message: string, ...optionalParams: unknown[]): void;\\n  abstract info(message: string, ...optionalParams: unknown[]): void;\\n  abstract warn(message: string, ...optionalParams: unknown[]): void;\\n  abstract error(message: string, ...optionalParams: unknown[]): void;\\n  abstract fatal(message: string, ...optionalParams: unknown[]): void;\\n}\\n```\\n\\nAn abstract class rather than an `interface`: `@dunx/transform` records\\nconstructor parameter **types**, and an interface has no runtime value to\\nrecord. An interface here would be a boot error at every injection site. That is\\nthe same trick `RequestContext`, `Storage`, `DbOptions` and `Auth` all use.\\n\\nInject it like anything else:\\n\\n```ts\\nexport class Notes {\\n  constructor(private readonly logger: Logger) {}\\n\\n  create(title: string): void {\\n    this.logger.info('note created', { title });\\n  }\\n}\\n```\\n\\n### Levels\\n\\n`LogLevel` is a frozen object plus an indexed-access union rather than a\\nTypeScript `enum`. One exported name serves as both the value and the type:\\n\\n```ts\\nimport { LogLevel } from '@dunx/core';\\n\\nLogLevel.VERBOSE; // 'verbose'\\nLogLevel.DEBUG; // 'debug'\\nLogLevel.INFO; // 'info'\\nLogLevel.WARN; // 'warn'\\nLogLevel.ERROR; // 'error'\\nLogLevel.FATAL; // 'fatal'\\n```\\n\\n`LOG_LEVELS` is the same six in ascending severity, and position in that array is\\nwhat level filtering compares. Entries below the configured `logLevel` are dropped\\nbefore anything is serialised.\\n\\n`log()` also exists and is **deprecated**. It emits `level: 'info'` either way. It\\nis kept only because the backing `@arkv/logger` keeps it to satisfy a third-party\\n`LoggerService` interface, and dropping it here would reject that class.\\n\\n### Three call shapes\\n\\nEvery level accepts the same three:\\n\\n```ts\\nlogger.info('order placed', { orderId, total }); // message plus extras\\nlogger.info({ orderId, total }); // fields merged into the entry\\nlogger.info(err); // the error's message becomes the message\\n```\\n\\nAn `Error` among the extras becomes the entry's `error`. At `warn` and above, a\\nbare string or an `{ err }` / `{ error }` property is promoted to an error too.\\nThat promotion is what `isErrorLevel(level)` reports.\\n\\n## `ConsoleLogger`, the zero-dependency default\\n\\n`AppFactory.create` offers a default binding for two tokens **after** every\\nmodule's own providers, so a module that binds either one wins:\\n\\n| Token            | Default               | Replaced by                                       |\\n| ---------------- | --------------------- | ------------------------------------------------- |\\n| `Logger`         | `ConsoleLogger`       | `LoggerModule`, which binds `@arkv/logger`        |\\n| `RequestContext` | `AsyncRequestContext` | `LoggerModule`, which binds arkv's `ContextStore` |\\n\\nThey exist so `@dunx/http` can log every request without the app having imported\\nanything. Neither default reaches for a dependency: `ConsoleLogger` writes one\\nJSON line per entry, and `AsyncRequestContext` is `AsyncLocalStorage`, a Node\\nbuilt-in Bun implements natively.\\n\\nOne line per entry, stdout below `warn` and stderr from `warn` up so a shipper can\\nseparate them:\\n\\n```json\\n{\\n  \\\"level\\\": \\\"info\\\",\\n  \\\"timestamp\\\": \\\"2026-08-02T09:14:22.881Z\\\",\\n  \\\"pid\\\": 4711,\\n  \\\"message\\\": \\\"GET /notes 200\\\",\\n  \\\"traceId\\\": \\\"4bf92f3577b34da6a3ce929d0e0e4736\\\",\\n  \\\"spanId\\\": \\\"00f067aa0ba902b7\\\",\\n  \\\"traceFlags\\\": \\\"01\\\",\\n  \\\"statusCode\\\": 200,\\n  \\\"elapsedMs\\\": 3\\n}\\n```\\n\\n**What it does not do:** sanitize, mask, rotate, colour, or handle a cyclic\\nobject. It calls `JSON.stringify` directly; a cycle in a log entry would be the\\nlogger's fault, and the replacement that handles cycles is one import away.\\n\\nThat missing list is what `@dunx/infra/logger` buys.\\n\\n### Buffering, and the durability trade\\n\\n`ConsoleLogger` **batches `info` and below into one write per event-loop turn.**\\n\\nA `console.log` per entry is a `write(2)` per entry. Measured, that was the\\nlargest single component of request logging: **1.84 µs**, more than the\\n`JSON.stringify` that produced the line. Concatenating into one string and\\nwriting it once per event-loop turn costs **0.27 µs**.\\n\\nThe trade matters: **a line still sitting in the buffer is lost if the process\\ndies without unwinding** - a `SIGKILL`, an OOM kill, a segfault - and a crash is\\nwhen the log is needed most.\\n\\nThree things bound it:\\n\\n- **`warn`, `error` and `fatal` are never buffered.** They go out immediately and\\n  **flush everything queued ahead of them**, so the entries you go looking for\\n  after a crash are the ones that were never held back.\\n- The window is **one event-loop turn** rather than a timer interval.\\n- `flush()` is public, `onShutdown()` calls it, and so does `process.on('exit')`.\\n\\nOpt out entirely if you would rather have the syscall:\\n\\n```ts\\nnew ConsoleLogger(context, LogLevel.INFO, /* buffered */ false);\\n```\\n\\nThe buffer is module-level, shared by every `ConsoleLogger` instance, because they\\nall write to the same descriptor and separate buffers would interleave two\\nloggers' lines.\\n\\n## `RequestContext` and `AsyncRequestContext`\\n\\nThe second contract in core. It is what carries `traceId` from the middleware\\nthat adopted it down to a service three constructor hops away, without anything\\nbeing passed:\\n\\n```ts\\nexport abstract class RequestContext {\\n  abstract getContext(): RequestFields;\\n  abstract updateContext(fields: Partial<RequestFields>): void;\\n  abstract runWithContext<T>(\\n    context: RequestFields,\\n    callback: () => T,\\n    options?: RunWithContextOptions,\\n  ): T;\\n}\\n```\\n\\n`RequestFields` names the well-known keys a log pipeline can rely on -\\n`traceId`, `spanId`, `parentSpanId`, `traceFlags`, `userId`, `method`, `event`,\\n`context`, `flow` - and permits anything else. The first four are OpenTelemetry's\\nlog data model fields, so a collector joins these lines to spans emitted by\\nanything else that speaks the standard.\\n\\n`AsyncRequestContext` is the default implementation, over `AsyncLocalStorage`,\\nwith one departure from the built-in: **nested scopes merge.**\\n\\n`AsyncLocalStorage.run` replaces the store outright, dropping the `traceId` an\\nouter scope established. `runWithContext` merges into a fresh object instead, so\\nan `updateContext` inside a nested scope does not leak back out. Pass\\n`{ inherit: false }` for the replacing behaviour.\\n\\n```ts\\nexport class Importer {\\n  constructor(private readonly context: RequestContext) {}\\n\\n  async run(batchId: string): Promise<void> {\\n    await this.context.runWithContext(\\n      { flow: 'import', event: batchId },\\n      async () => {\\n        // every log line in here carries flow, event, and the caller's traceId\\n      },\\n    );\\n  }\\n}\\n```\\n\\n`updateContext` is how you add a field to the scope you are already in, which is\\nhow `@dunx/auth` puts `userId` on every line after a session is resolved.\\n\\n## `LoggerModule`: swapping in `@arkv/logger`\\n\\n`@dunx/infra/logger` binds core's contract to\\n[`@arkv/logger`](https://www.npmjs.com/package/@arkv/logger). dunx supplies the\\ncontract and the wiring and **restates none of the configuration**.\\n\\n```ts\\nimport { Module } from '@dunx/core';\\nimport { LoggerModule } from '@dunx/infra/logger';\\n\\n@Module({\\n  imports: [LoggerModule.forRoot({ name: 'my-api', level: 'debug' })],\\n})\\nexport class AppModule {}\\n```\\n\\nNo adapter class sits between them. `@arkv/logger`'s `Logger` already declares\\n`logLevel` and all six levels with the same overloads, so it satisfies the\\ncontract structurally, and the binding is a `provide` with nothing in the middle.\\nThe same holds for context: arkv's `ContextStore` satisfies `RequestContext`\\nstructurally, so `LoggerModule` binds one to the other directly.\\n\\nThat last point is load-bearing rather than tidy. Without it, `@dunx/http`'s\\nrequest logging would write a `traceId` into core's default store while\\n`@arkv/logger` read its own, and no entry would carry one.\\n\\n### What it binds\\n\\n| Token            | Bound to                                                 |\\n| ---------------- | -------------------------------------------------------- |\\n| `LoggerSettings` | The `LoggerConfig` you passed, so a factory can read it  |\\n| `ContextStore`   | arkv's store                                             |\\n| `RequestContext` | The same `ContextStore`                                  |\\n| `BackingLogger`  | The `@arkv/logger` instance, typed as the implementation |\\n| `Logger`         | The same instance, typed as core's contract              |\\n\\n`BackingLogger` reaches the three things the contract omits: `child(bindings)`,\\n`flush()` and `close()`. Core's `Logger` covers the six levels and nothing else,\\nso an app wanting a child logger asks for the implementation by name instead of\\nevery app carrying a wider contract.\\n\\n### Reading the level off config\\n\\n`forRootAsync` exists for the one thing `forRoot` cannot express, since the\\nfunction it takes receives no arguments: **injecting**.\\n\\n```ts\\nLoggerModule.forRootAsync(\\n  {\\n    useFactory: (config: AppConfigService) => {\\n      const log = config.get('log');\\n      return {\\n        name: config.get('appName'),\\n        level: log.level,\\n        ...(log.file === undefined\\n          ? {}\\n          : { transports: fileAndConsole(log.file) }),\\n      };\\n    },\\n    inject: [AppConfigService] as const,\\n  },\\n  { captureGlobalErrors: true },\\n);\\n```\\n\\nSee [Configuration](dunx://guide/12-configuration) for why the parameter is\\n`AppConfigService` and not `ConfigService<AppConfig>`.\\n\\n### Transports\\n\\nSupplying `transports` **replaces** the console sink, so keeping stdout means\\nnaming it:\\n\\n```ts\\nimport {\\n  ConsoleTransport,\\n  FileTransport,\\n  type Transport,\\n} from '@dunx/infra/logger';\\n\\nconst fileAndConsole = (path: string): Transport[] => [\\n  new ConsoleTransport(),\\n  new FileTransport({\\n    path,\\n    interval: 'daily',\\n    maxFiles: 7,\\n    bufferBytes: 16 * 1024,\\n  }),\\n];\\n```\\n\\n`FileTransport` buffers, which is safe here because `LoggerModule` registers a\\nlifecycle provider that drains it from `onShutdown`. That hook runs late:\\n`App.shutdown` walks instances in reverse resolution order and the logger resolves\\nbefore anything that depends on it, so services can still log while they close.\\n\\nIt drains with `closeAsync`, and the await matters for anything reached over a\\nnetwork. A file is written synchronously and either form finishes it; a collector\\ncannot answer synchronously at all, so a plain `close()` discards whatever it was\\nholding and every deploy loses its last batch.\\n\\n### Shipping somewhere other than a file\\n\\n`HttpTransport` covers the collectors that differ only in the shape of the body:\\n\\n```ts\\nimport { HttpTransport, SamplingTransport } from '@dunx/infra/logger';\\n\\nnew HttpTransport({\\n  url: 'https://logs.example.com/ingest',\\n  headers: { authorization: `Bearer ${token}` },\\n  batchSize: 200,\\n  flushIntervalMs: 2000,\\n});\\n```\\n\\n`encode` is the seam: Datadog wants a JSON array, Splunk HEC concatenated objects,\\nLoki streams and values. `SyslogTransport` speaks RFC 5424 over UDP or TCP, and\\nanything else that batches is a subclass of `BatchTransport`, which owns the\\nbounded queue, the retry and the drop accounting.\\n\\n`SamplingTransport` wraps another transport to thin what reaches it. Warnings and\\nworse are never sampled, and every discard is announced in the stream rather than\\nbeing silent.\\n\\n`logger.stats()` on the `BackingLogger` token reports what each transport is\\nholding and what it has dropped - the numbers an alert on \\\"we are losing logs\\\"\\nreads.\\n\\n### Output formats\\n\\n`format` on any transport takes one of four:\\n\\n| Formatter      | Emits                                               |\\n| -------------- | --------------------------------------------------- |\\n| `jsonFormat`   | `{\\\"level\\\":\\\"info\\\",\\\"message\\\":\\\"order placed\\\",…}`       |\\n| `prettyFormat` | the same JSON, ANSI-coloured for a terminal         |\\n| `textFormat`   | `09:00:15.123 INFO  order placed  traceId=4bf92f35` |\\n| `logfmtFormat` | `level=info msg=\\\"order placed\\\" order.id=ord_1`      |\\n\\n`examples/full` reads `LOG_FORMAT` and wires whichever you name. A file always\\ntakes a machine format even when the console does not, since nothing reads a log\\nfile with its eyes first.\\n\\n### `captureGlobalErrors`\\n\\n```ts\\nLoggerModule.forRoot({ name: 'my-api' }, { captureGlobalErrors: true });\\n```\\n\\nInstalls `uncaughtException` and `unhandledRejection` handlers that log through\\nthis logger and flush before the process goes away. `true` takes the defaults:\\nfatal for an uncaught exception, then `process.exit(1)`. Pass an options object to\\ntune it. Worth having in a service meant to stay up.\\n\\n## What is logged at boot\\n\\nTwo things, without being asked, and both because the alternative was silence.\\n\\n**The served table, once, at `listen()`.** One `info` entry naming every route on its\\nfinal path and every gateway with the messages it claims:\\n\\n```json\\n{\\n  \\\"level\\\": \\\"info\\\",\\n  \\\"message\\\": \\\"Serving 32 route(s) and 1 gateway(s)\\\",\\n  \\\"routes\\\": [\\\"GET /api/users\\\", \\\"POST /api/users\\\", \\\"...\\\"],\\n  \\\"gateways\\\": [\\n    { \\\"path\\\": \\\"/ws\\\", \\\"gateway\\\": \\\"EventsGateway\\\", \\\"events\\\": [\\\"chatMessage\\\"] }\\n  ]\\n}\\n```\\n\\nThis is the answer to \\\"is my route registered\\\"; a service that logs nothing at\\nboot cannot answer it from production. Nest emits a line per controller and a\\nline per route to say the same thing. One structured entry carries the same\\ncontent in the shape a collector wants, and it is what `WorkerFactory` already\\ndoes for the consuming side, with `Consuming N job(s) on M queue(s)`.\\n\\nIt is at `listen()` rather than `create()` because `setGlobalPrefix` runs in between,\\nand a table listing unprefixed paths would name routes that do not exist.\\n\\n```ts\\nHttpFactory.create(AppModule, { bootLogging: false }); // off\\n```\\n\\nSeparate from `requestLogging` rather than sharing its switch: one is per request and\\none is per process, so silencing the noisy one is not a reason to lose the quiet one.\\n`@dunx/testing` defaults it off, for the same reason it defaults request logging off:\\na suite that boots a server per file does not want a route table per file.\\n\\n**Scope warnings, at `warn`, from `AppFactory.create`.** A module that declares\\nwhat an import already exports to it, or imports one token from two modules that\\ndisagree, is legal and warned.\\n\\nThey used to sit on `app.warnings` and be logged by nobody, on the reasoning that\\ncore had no logger. It has one now: `Logger` is always bound, and the reference\\napp never read the property, so a shadowed binding would have been silent in the\\napp most likely to hit one. The list is still public for an app that would\\nrather fail boot on it.\\n\\n## Request logging\\n\\n`@dunx/http` installs `RequestLoggingMiddleware` **by default**, outermost in the\\nchain, ahead of anything `middleware` declares. So a request rejected by a guard\\nis still logged with the status it got.\\n\\n```ts\\nHttpFactory.create(AppModule); // on, defaults\\nHttpFactory.create(AppModule, { requestLogging: false }); // off\\nHttpFactory.create(AppModule, {\\n  requestLogging: { ignore: ['/health'], requestBody: true },\\n});\\n```\\n\\n### One entry per request\\n\\nThe entry carries the request and its response together:\\n\\n```json\\n{\\n  \\\"level\\\": \\\"info\\\",\\n  \\\"timestamp\\\": \\\"...\\\",\\n  \\\"pid\\\": 4711,\\n  \\\"message\\\": \\\"POST /notes 201\\\",\\n  \\\"traceId\\\": \\\"4bf92f3577b34da6a3ce929d0e0e4736\\\",\\n  \\\"spanId\\\": \\\"00f067aa0ba902b7\\\",\\n  \\\"traceFlags\\\": \\\"01\\\",\\n  \\\"method\\\": \\\"POST\\\",\\n  \\\"event\\\": \\\"/notes\\\",\\n  \\\"flow\\\": \\\"http\\\",\\n  \\\"context\\\": \\\"NotesController.create\\\",\\n  \\\"request\\\": { \\\"userAgent\\\": \\\"curl/8.5.0\\\" },\\n  \\\"statusCode\\\": 201,\\n  \\\"elapsedMs\\\": 4\\n}\\n```\\n\\ndunx writes both halves from one middleware, because middleware wraps `next()`\\nand both halves are the same closure. A framework whose middleware cannot see\\nthe response needs a middleware for the inbound half and an interceptor for the\\noutbound one instead: different classes, and the interceptor cannot see what\\nthe middleware saw. There is no pair to correlate by `traceId` just to find\\nout how a call ended.\\n\\n- A **4xx** is the same line at `warn`.\\n- A **5xx** is the same line at `error`.\\n- An error is logged and **rethrown**, so the error mapper still owns the status\\n  and the response shape.\\n\\nAn unmatched path is logged too. `Bun.serve({ routes })` answers a miss itself, so\\n`listen()` installs one `fetch` fallback that puts the global middleware in front\\nof a `{\\\"error\\\":\\\"NOT_FOUND\\\",\\\"status\\\":404}`. That is not a JavaScript router: Bun\\nstill does all the matching, and the fallback only runs once it has matched\\nnothing.\\n\\n**Every global middleware runs on a miss, guards included.** A miss matched no\\nroute, so it carries no route metadata, and a guard reading none of it refuses: an\\napp with a global `SessionGuard` answers an anonymous request for a nonexistent\\npath with that guard's status rather than a 404. There is no `@Public()` to put\\non a path that does not exist.\\n\\nThe alternative leaks: if a miss answers 404 while every real path answers 401,\\nthe difference enumerates your surface. For the conventional 404:\\n\\n```ts\\nawait HttpFactory.create(AppModule, { notFound: 'public' });\\n```\\n\\nThe miss then reports itself as `@Public()`, so a guard honouring that flag\\npasses it through. Either way it is logged and adopts a trace, so the fallback\\nruns the middleware for both.\\n\\nA guard can decide for itself under either setting. `UNMATCHED` is set on a miss\\nand no real route ever sets it:\\n\\n```ts\\nimport { PUBLIC, UNMATCHED } from '@dunx/http';\\n\\nif (ctx.get(PUBLIC) === true && ctx.get(UNMATCHED) !== true) return next();\\n```\\n\\nEverything the handler logs in between carries `traceId`, `method`, `event` and\\n`context` without being passed anything, because the whole call runs inside\\n`runWithContext`.\\n\\n### W3C Trace Context\\n\\nEvery request adopts a trace. An inbound `traceparent` is continued with a span of\\nthis server's own; without one, a fresh trace id and span id are minted. Four\\nfields reach the async scope and therefore every line the request writes:\\n`traceId`, `spanId`, `parentSpanId` when a caller sent one, and `traceFlags`.\\n\\nThe response carries `traceresponse`, naming the span that answered. That header\\nis a W3C Distributed Tracing Working Group proposal rather than a ratified\\nstandard: `traceparent` and `tracestate` are the Recommendation, and both are\\nrequest headers. Treat a caller reading it as a bonus.\\n\\n```console\\n$ curl -i -H 'traceparent: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01' localhost:3000/notes\\ntraceresponse: 00-4bf92f3577b34da6a3ce929d0e0e4736-7a9d1a31080e694d-01\\n```\\n\\nA malformed `traceparent` is **discarded rather than repaired**, which is what the\\nstandard requires. The request starts a trace of its own rather than joining one\\nthat may not exist, and nothing tells the caller.\\n\\nAn all-zero trace id, an all-zero span id, the reserved version `ff` and a non-hex\\nfield are each rejected. A version this code does not know keeps its first four\\nfields, so a future format still propagates.\\n\\nAn inbound sampling decision is kept rather than overridden, so a trace an upstream\\nsampler declined is not re-sampled here. `tracestate` is carried through verbatim\\nalongside a valid `traceparent`, and dropped without one.\\n\\n`@dunx/http/client` sends the adopted trace upstream as `traceparent`, so one trace\\nspans both services. It reads `traceFlags` out of the same store, which is why\\nthat field is there.\\n\\nThere is no exporter, no sampler and no dependency: one header parsed and two\\nwritten. `traceId`, `spanId` and `traceFlags` are OpenTelemetry's own log data\\nmodel fields, so a collector correlates these lines with spans emitted by anything\\nspeaking the standard - including an OpenTelemetry SDK running in the same Bun\\nprocess, which Bun 1.4.0 supports.\\n\\n`trace: false` removes all of it, at which point a request carries no correlation\\nid at all.\\n\\n```ts\\nHttpFactory.create(AppModule, { requestLogging: { trace: false } });\\n```\\n\\n### Options\\n\\n```ts\\ninterface RequestLoggingOptions {\\n  maxBodyLength?: number; // default 2048; bodies past this log as a size, 0 omits\\n  requestBody?: boolean; // default false\\n  responseBody?: boolean; // default false\\n  ignore?: readonly string[]; // paths skipped entirely - see below\\n  ignorePrefix?: readonly string[]; // prefixes skipped, for a whole mount\\n  correlateIgnored?: boolean; // default false; keep the trace on an ignored path\\n  correlate?: boolean; // default true; false drops the async scope - see below\\n  trace?: boolean; // default true; W3C Trace Context - see above\\n  traceResponse?: boolean; // default true; false stops `traceresponse` going out\\n}\\n```\\n\\n### `traceResponse`\\n\\nThe response header is the only part of request logging that leaves the process,\\nand it is about 500 ns of the 4.7 µs the path costs, which is 11%. It is the\\nlargest single thing you can turn off without losing a field from a log line.\\n\\n```ts\\nrequestLogging: {\\n  traceResponse: false;\\n}\\n```\\n\\nWhat you keep: the trace is still adopted, still on every line the middleware\\nwrites, still in the `AsyncLocalStorage` scope, and still on the metrics exemplar.\\n\\nWhat you lose is the outward half, a caller quoting the answering span back at\\nyou. That includes failures: the error mapper stamps a fresh `Response` from what\\n`TraceContext.adopt` marked, and `false` stops it marking.\\n\\nTurn it off on a service nothing correlates from the outside. Leave it on at an\\nedge.\\n\\n**Both body options default to `false`**, and the request body is the field most\\nlikely to contain a password. Turn them on in development.\\n\\nWhat `requestBody` costs depends on whether the route declares a `body` schema, and\\nby a factor of fifteen:\\n\\n| Setting                            | µs/req | vs the default |\\n| ---------------------------------- | -----: | -------------: |\\n| the default, both bodies off       |  17.25 |              - |\\n| `requestBody: true`, schema route  |  19.12 |       +1.87 µs |\\n| `responseBody: true`               |  19.80 |       +2.55 µs |\\n| both bodies, schema route          |  20.03 |       +2.78 µs |\\n| `requestBody: true`, **no** schema |  46.06 |      +28.81 µs |\\n\\nA route that declares a body schema has already had the body buffered to validate\\nit, so logging it reads that text and copies nothing. A route that declares none\\nleaves the middleware to `req.clone()`, and cloning a request whose body is an\\nunread network stream is the whole difference.\\n\\n### What `ignore` costs, and how to buy part of it back\\n\\n`ignore` is for a health check polled every second, and **entirely** is literal.\\nThe middleware slices the pathname - it has to, to check the list - and then\\nreturns `next()` without touching anything else, so an ignored path has:\\n\\n- no entry;\\n- no trace, and no `traceresponse` on the response;\\n- no `AsyncLocalStorage` scope, so anything the handler logs is uncorrelated: no\\n  `traceId`, no `event`, no `context`.\\n\\nSkipping all three is what makes it free. \\\"Do not log the health check, but do\\nkeep its trace\\\" is `correlateIgnored`:\\n\\n```ts\\nHttpFactory.create(AppModule, {\\n  requestLogging: { ignore: ['/health'], correlateIgnored: true },\\n});\\n```\\n\\nThe path still writes no entry of its own. It gets a `traceresponse`, continuing\\nan inbound trace or starting one, and everything the handler logs carries it.\\n\\nIt is off by default because it costs something: the path pays for reading the\\nheader, minting the ids, the `runWithContext` scope and one `Headers.set`.\\nThat is **~2.5 µs** of the 4.78 the full default path costs in the table below.\\nIt never pays for building and serialising the entry, the expensive half.\\n\\n### Turning the async scope off with `correlate: false`\\n\\nThe `runWithContext` scope used to be the most expensive thing request logging did\\nthat was not the entry itself, at +0.91 µs on Bun 1.3.14. **Bun 1.4 made it too\\ncheap to measure:** +0.24 µs as a step, and turning it off moves the whole default\\npath from 4.78 µs to 4.48 µs. Both figures are inside the harness's ±0.5 µs\\nresolution, so the honest reading is that this option now buys nothing measurable.\\n\\n```ts\\nHttpFactory.create(AppModule, { requestLogging: { correlate: false } });\\n```\\n\\n**The request entry is unchanged.** The same `traceId`, `method`, `event`, `flow`\\nand `context` fields are written onto it directly instead of being read back out of\\nthe store, so the line a log pipeline sees is identical and the `traceresponse`\\nheader still goes out. What is lost is everything _else_ the request logs: those\\nlines carry no `traceId`, and `updateContext` in a handler has nothing to update.\\n\\nIt is not the default because correlation is most of what a trace is for, and on\\nBun 1.4 there is no throughput argument on the other side either.\\n\\nThe option stays for an app that already threads correlation through explicitly, and\\nfor `ignore` with `correlateIgnored`, where an ignored path gets the response header\\nand no scope. Do not reach for it expecting a speedup; re-measure on your own Bun\\nfirst.\\n\\n## What it costs\\n\\n`GET /json`, AMD Ryzen 9 5950X, Bun 1.4.0, 64 connections:\\n\\n| Subject                        | req/s (median) | p50 ms | vs `Bun.serve` |\\n| ------------------------------ | -------------: | -----: | -------------: |\\n| `Bun.serve` (raw)              |        124,234 |  0.484 |         100.0% |\\n| `@dunx/http`                   |        114,283 |  0.519 |          92.0% |\\n| `@dunx/http` + request logging |         73,675 |  0.807 |          59.3% |\\n\\nStructured logging of every request costs about 40% of peak throughput. That is not\\na dunx tax; it is the cost of the work itself, and the breakdown says where it goes.\\nEach row below is the same app on the same route with one more piece of the\\ndefault path switched on. Read anything under about **±0.5 µs** as unresolvable:\\n\\nThe two trace rows were measured against a `crypto.randomUUID()` pair. Adopting a\\ntrace is 49.2 ns against that path's 260.5 ns, so both rows are upper bounds.\\n\\n| Step                                            | µs/req | this step adds |\\n| ----------------------------------------------- | -----: | -------------: |\\n| `requestLogging: false`                         |   7.98 |              - |\\n| one middleware that only calls `next()`         |   8.58 |       +0.60 µs |\\n| the pathname sliced out of `req.url`            |   9.31 |       +0.73 µs |\\n| `traceparent` and `user-agent` read             |  10.28 |       +0.97 µs |\\n| `TraceContext.adopt`                            |   9.98 |       -0.30 µs |\\n| `runWithContext` around the handler             |  10.22 |       +0.24 µs |\\n| `traceresponse` set on the response             |  10.46 |       +0.24 µs |\\n| the real middleware, `Logger` discards          |  10.85 |       +0.38 µs |\\n| `new Date().toISOString()`                      |  11.05 |       +0.21 µs |\\n| the entry and `JSON.stringify`, string dropped  |  12.83 |       +1.77 µs |\\n| **batched write instead - the shipped default** |  12.76 |       -2.40 µs |\\n\\nThe whole default path is **+4.78 µs**, and two steps account for most of it: the\\n**first touch of `req.headers`** and **building and serialising the entry**. Six of\\nthe eleven steps land inside the ±0.5 µs resolution, and one of them is negative -\\nadopting the trace reads as -0.30 µs, which is the clearest available evidence\\nthat a single step at this scale is at the harness's floor. Read the total, not the\\nrow.\\n\\nThe `AsyncLocalStorage` scope is one of those six now. On Bun 1.3.14 it measured\\n+0.91 µs and was the third-largest item here; on 1.4 it is +0.24 µs, which the\\nharness cannot separate from zero. That changes what `correlate: false` is worth -\\nsee below.\\n\\nThe write, isolated:\\n\\n| Write                                    | µs/req |\\n| ---------------------------------------- | -----: |\\n| batched, `/dev/null`                     |  12.76 |\\n| one `console.log` per entry, `/dev/null` |  15.16 |\\n| batched, into a pipe nobody reads        |  12.98 |\\n| one per entry, into a pipe nobody reads  |  17.17 |\\n\\n**Batching is now the largest single saving on the path**, worth 2.40 µs against a\\n`console.log` per entry and 4.19 µs when the consumer is slow, against a 4.78 µs\\ntotal. A `write(2)` per entry would cost more than everything else combined.\\n\\nBatching also makes a slow consumer far less able to stall the server, which is\\nthe last row's problem.\\n\\nTwo micro-optimisations in `ConsoleLogger` fall out of the same measurements.\\n\\n`new Date().toISOString()` measured about 170 ns, and the millisecond has usually\\nnot moved since the last entry, so one `Date.now()` guards a memoised stamp.\\n\\n`logger.info('GET /json 200', fields)` is the shape every framework call takes,\\nso it is built directly instead of going through the general merge path, which\\nwould cost two array allocations, a third object and an `Object.assign`.\\n\\nNothing in `RequestLoggingMiddleware` is `async`. Reading the request or the\\nresponse body are the only steps that can wait, both are off by default, and both\\nare adopted with `.then` rather than awaited. An `async` scope callback alone cost\\n**0.44 µs/request** against a synchronous one on raw `Bun.serve`.\\n\\n## Related\\n\\n- [Configuration](dunx://guide/12-configuration) for `AppConfigService` and `forRootAsync`\\n- [Authentication](dunx://guide/17-authentication), which writes `userId` into\\n  `RequestContext` so every line after sign-in is correlated\\n- [Providers](dunx://guide/03-providers) for how the default bindings are layered\\n\"},{\"slug\":\"14-database\",\"title\":\"Database\",\"summary\":\"`@dunx/infra/db` is drizzle, wired into the container.\",\"sections\":[\"Setup\",\"What `DbModule` binds\",\"Two backends, and they are not interchangeable\",\"Synchronous mode: `SyncSqliteOptions`\",\"Querying\",\"Transactions\",\"Migrations\",\"Seeding\",\"MySQL\",\"The raw handle and shutdown\",\"Pagination\",\"No entity decorators\",\"Related\"],\"body\":\"# Database\\n\\n`@dunx/infra/db` is **drizzle**, wired into the container. What it adds is what\\na drizzle handle does not have on its own: a lifecycle, module wiring, an\\nasync-safe transaction, and data seeding. It adds no query abstraction, no\\nentity decorators, and no repository base class. drizzle is the interface.\\n\\n```bash\\nbun add drizzle-orm\\n```\\n\\n`drizzle-orm` is an **optional peer dependency**, so an app that only uses\\n`@dunx/infra/files` installs nothing.\\n\\n## Setup\\n\\n```ts\\nimport { Module } from '@dunx/core';\\nimport { DbModule, SqliteOptions } from '@dunx/infra/db';\\nimport * as schema from './schema.js';\\n\\n@Module({\\n  imports: [\\n    DbModule.forRoot(\\n      new SqliteOptions({\\n        schema,\\n        filename: './dev.db',\\n        pragmas: ['foreign_keys = ON'],\\n      }),\\n    ),\\n  ],\\n  providers: [Widgets],\\n})\\nexport class AppModule {}\\n```\\n\\nThen inject drizzle's own database class:\\n\\n```ts\\nimport { BunSQLiteDatabase } from 'drizzle-orm/bun-sqlite';\\nimport { desc } from 'drizzle-orm';\\nimport * as schema from './schema.js';\\nimport { widgets, type Widget } from './schema.js';\\n\\nexport class Widgets {\\n  constructor(private readonly db: BunSQLiteDatabase<typeof schema>) {}\\n\\n  async list(): Promise<readonly Widget[]> {\\n    return this.db.select().from(widgets).orderBy(desc(widgets.id)).all();\\n  }\\n}\\n```\\n\\n`BunSQLiteDatabase` and `BunSQLDatabase` are real runtime classes, so a class is\\nusable as a token directly: `@dunx/transform` records the bare type name while\\nignoring the type argument. One erased class is the token; the schema types\\nstay on the annotation. There is no wrapper in that constructor.\\n\\n`schema` is required for that reason: it is the type argument that reaches\\n`BunSQLiteDatabase<typeof schema>` at every injection site. Pass `{}` if you only\\nrun `sql` templates.\\n\\n## What `DbModule` binds\\n\\n| Token                                                   | What it is                                                 |\\n| ------------------------------------------------------- | ---------------------------------------------------------- |\\n| `DbOptions`                                             | The resolved configuration, so anything can read `dialect` |\\n| `DbConnection`                                          | The lifecycle and the raw driver handle                    |\\n| `BunSQLiteDatabase` / `BunSQLDatabase` / `SyncDatabase` | The drizzle handle a repository injects                    |\\n\\nThe drizzle handle is bound through a factory that depends on `DbConnection`,\\nwhich fixes the shutdown order. dunx tears down in reverse construction order, so\\nthe connection is constructed first and closes last, after every repository has\\ndrained.\\n\\nEvery factory settles before the first constructor runs, so the connection is open\\nand handshaked before any repository is built. There is no lazy connect and no\\n`await db.ready()`.\\n\\n### `forRootAsync` takes the token first\\n\\n```ts\\nDbModule.forRootAsync(SyncDatabase, {\\n  useFactory: (config: AppConfigService) =>\\n    new SyncSqliteOptions({\\n      schema,\\n      filename: config.get('database').file,\\n      pragmas: ['foreign_keys = ON'],\\n    }),\\n  inject: [AppConfigService],\\n});\\n```\\n\\nThe token is a positional argument here, unlike `forRoot`. Which drizzle class the\\nhandle is bound under only becomes known once the factory has produced the\\noptions, which is too late to register a provider under it.\\n\\nSee [Configuration](dunx://guide/12-configuration) for why the parameter is\\n`AppConfigService` rather than `ConfigService<AppConfig>`.\\n\\n## Two backends, and they are not interchangeable\\n\\n| Options class       | Driver                         | Handle              | Dialect  |\\n| ------------------- | ------------------------------ | ------------------- | -------- |\\n| `SqliteOptions`     | `bun:sqlite`                   | `BunSQLiteDatabase` | SQLite   |\\n| `SyncSqliteOptions` | `bun:sqlite`, synchronous mode | `SyncDatabase`      | SQLite   |\\n| `SqlOptions`        | `Bun.SQL`                      | `BunSQLDatabase`    | Postgres |\\n\\nBoth go through drizzle's Bun-native drivers, `drizzle-orm/bun-sqlite` and\\n`drizzle-orm/bun-sql`. No `pg`, no `better-sqlite3`, no `postgres.js`. The library\\nowns the abstraction, Bun owns the I/O.\\n\\nBecause schema modules are dialect-specific (`sqliteTable` versus `pgTable`), the\\ntwo backends are a **build-time choice**. One `DATABASE_URL` naming either is not a\\nsupported shape.\\n\\n### Postgres\\n\\n```ts\\nimport { DbModule, SqlOptions } from '@dunx/infra/db';\\nimport * as schema from './schema.js';\\n\\nDbModule.forRoot(new SqlOptions({ schema, url, max: 4, connectionTimeout: 5 }));\\n```\\n\\n`SqlInit` extends `Bun.SQL`'s own option type rather than restating it, so\\npooling, TLS and auth stay in sync with whatever Bun supports. `url` is required\\nand `adapter` is dropped, because the URL scheme decides it.\\n\\nThe dialect is resolved from the URL **at construction**, so a bad URL throws\\nbefore any I/O. A non-Postgres URL throws with a message saying why:\\n\\n> `drizzle-orm/bun-sql` builds a `PgDialect` **unconditionally**. Read from\\n> drizzle-orm 0.45.2's `bun-sql/driver.js`, there is no branch on\\n> `client.options.adapter` anywhere in the module.\\n\\nPointed at a `sqlite://` client it does not error. It compiles `$1` placeholders\\nand Postgres identifier quoting against SQLite, the trivial cases pass, and that\\nis worse than failing. So `SqlOptions` refuses.\\n\\nThe handshake is awaited inside `open()` rather than deferred to the first query.\\n\\n### `SqliteOptions`\\n\\n| Field          | Default      | Notes                                                         |\\n| -------------- | ------------ | ------------------------------------------------------------- |\\n| `schema`       | required     | The type argument that reaches every injection site           |\\n| `filename`     | `':memory:'` | A path, or a `sqlite:`/`file:` URL, whose scheme is stripped  |\\n| `readOnly`     | `false`      | Opens `SQLITE_OPEN_READONLY`, suppresses `create`             |\\n| `create`       | `true`       | `false` throws on a missing file on Bun 1.4; see below        |\\n| `strict`       | `true`       | **Not the driver's default.** See below                       |\\n| `safeIntegers` | `false`      | Return integers as `bigint` rather than truncating to 53 bits |\\n| `pragmas`      | `[]`         | Run once after opening, each prefixed with `PRAGMA`           |\\n| `casing`       | drizzle's    | `'snake_case'` or `'camelCase'`, forwarded to `drizzle()`     |\\n| `logger`       | drizzle's    | `true`, or anything with `logQuery`, forwarded to `drizzle()` |\\n\\n`pragmas` is the only place `journal_mode = WAL` can be set before the first\\nquery.\\n\\n`create: false` behaves differently across Bun versions. On 1.4 it throws\\n`bad parameter or other API misuse` when the file is missing - the behaviour\\nthe option is for. On 1.3.14 it created the file anyway. `readOnly` refuses a\\nmissing file on both, with `unable to open database file`, so it is the\\nportable way to require an existing database.\\n\\n`strict: true` is this package's default and the driver's is not. Strict mode\\nturns an unsupported binding into a `TypeError` instead of a silent `NULL`. It is also why `SqliteOptions` opens the `bun:sqlite` handle itself instead\\nof letting `drizzle('./dev.db')` do it: drizzle's own path forwards only\\n`readonly`/`create`/`readwrite` and hands back a **non-strict** handle.\\n\\n### drizzle's own options: `casing` and `logger`\\n\\nBoth backends' init types extend `DrizzleInit`, whose two fields are drizzle's and\\nare forwarded to `drizzle()` untouched. They are the reason opening the handle by\\nhand is not the only way to reach them:\\n\\n```ts\\nDbModule.forRoot(\\n  new SqliteOptions({\\n    schema,\\n    filename: './dev.db',\\n    casing: 'snake_case',\\n    logger: { logQuery: (query, params) => logger.debug(query, { params }) },\\n  }),\\n);\\n```\\n\\n`casing: 'snake_case'` lets a column be declared as `text()` with no name and\\nresolve to `first_name`. It has to agree with `drizzle.config.ts`, because\\ndrizzle-kit generates migrations from the config while the handle queries with\\nthis - if they disagree, the migration writes one column name and the query reads\\nanother.\\n\\n`logger` takes `true` for drizzle's own console output, or anything with a\\n`logQuery(query, params)` method. Routing it into the injected `Logger` at `debug`\\nis how a slow endpoint gets diagnosed without a proxy in front of the database. It\\nis per-connection, so a `DB_LOG_QUERIES` env flag is just\\n`logger: config.DB_LOG_QUERIES` inside a `forRootAsync` factory.\\n\\n`SqlOptions` consumes both before building the `Bun.SQL` options, exactly as it\\nconsumes `schema` and `url` - the driver has no idea what `casing` means.\\n\\n## Synchronous mode: `SyncSqliteOptions`\\n\\n`bun:sqlite` is synchronous underneath, and `@dunx/http` has a dispatch path that\\nallocates no promise when a handler returns a plain value, so a request can go\\nparse, query, respond without ever yielding.\\n\\nReads already could, drizzle's bun-sqlite builders having `.all()`, `.get()` and\\n`.run()`. A **write** was stopped by `transaction()`, which returns a promise, so\\nany route that wrote anything went back to `async`.\\n\\n`SyncSqliteOptions` closes that. Every init field is `SqliteOptions`'s. Choosing it\\nchanges exactly two things: the token becomes `SyncDatabase`, and\\n`transactionSync(db, fn)` becomes reachable.\\n\\n```ts\\nDbModule.forRoot(new SyncSqliteOptions({ schema, filename: './dev.db' }));\\n```\\n\\n```ts\\nimport { SyncDatabase, transactionSync } from '@dunx/infra/db';\\nimport { desc, sql } from 'drizzle-orm';\\nimport * as schema from './schema.js';\\nimport { widgets, type Widget } from './schema.js';\\n\\nexport class SyncWidgets implements OnInit {\\n  constructor(private readonly db: SyncDatabase<typeof schema>) {}\\n\\n  /** Returns void, not Promise<void>. There is nothing to wait for. */\\n  onInit(): void {\\n    this.db.run(sql`CREATE TABLE IF NOT EXISTS widgets (\\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\\n      name TEXT NOT NULL,\\n      weight INTEGER NOT NULL\\n    )`);\\n  }\\n\\n  add(name: string, weight: number): Widget {\\n    return this.db.insert(widgets).values({ name, weight }).returning().get();\\n  }\\n\\n  list(): readonly Widget[] {\\n    return this.db.select().from(widgets).orderBy(desc(widgets.id)).all();\\n  }\\n}\\n```\\n\\n### Why it is a sibling class and not a flag\\n\\nThe mode decides the handle type, and the handle type is what `DbModule.forRoot`\\ninfers the injection token from. A flag would leave that inference with a union to\\nguess at.\\n\\n`SyncDatabase` is an empty subclass of `BunSQLiteDatabase` with **one declared\\nproperty**, `synchronous: true`. That property is the whole mechanism. TypeScript\\nis structural, so an empty subclass would be mutually assignable to its base and\\nwould gate nothing. `SyncSqliteConnection` defines the property on the handle\\ndrizzle built, so the type is true rather than claimed.\\n\\nThe relationship is **one-way**. A `SyncDatabase` _is_ a `BunSQLiteDatabase`, so\\n`transaction()`, `runSeeds` and repositories written before the mode existed all\\nstill take one. Synchronous mode is a superset rather than a fork. The reverse\\nfails: a service annotating `SyncDatabase` under `SqliteOptions` does not resolve\\nat boot, nothing having bound that token.\\n\\n### How to choose, and what it is actually worth\\n\\nMeasured through a real `Bun.serve`, interleaved round-robin, `requestLogging: false` so every route stays on the\\ndirect dispatch path. AMD Ryzen 9 5950X, Bun 1.3.14, oha 1.15.0, 64 connections,\\n11 rounds of 5 s, medians:\\n\\n| unit          | req/s  |    σ | p50 ms | p99 ms |\\n| ------------- | ------ | ---: | ------ | ------ |\\n| `read:async`  | 17,625 | 1368 | 3.473  | 7.002  |\\n| `read:sync`   | 18,399 | 1411 | 3.268  | 6.729  |\\n| `write:async` | 7,942  |  370 | 7.435  | 15.580 |\\n| `write:sync`  | 8,283  |  410 | 7.104  | 15.140 |\\n\\n**Synchronous mode is about 4-6% more req/s and 0.2-0.3 ms off p50**, reproduced\\nacross two independent runs (read +5.7% then +4.4%; write +4.2% then +4.3%).\\n\\nThe rest of it, plainly: σ on the read rows is about 8% of the median, so a\\nsingle round proves nothing and the per-round ranges overlap.\\n\\nThe effect is real, being consistent in direction across 18 rounds and both\\nscenarios, but **it sits at the edge of this box's noise floor**. At roughly\\n57 µs of service time per request, the saving is about 3 µs: one async frame, one\\npromise from drizzle's thenable builder, one promise adoption in the dispatch\\npath.\\n\\nAnd the framing that motivated the work, \\\"one API call could be 5-10 ms instead of\\n30-50 ms\\\", is **right about SQLite and wrong about this feature**. That difference\\nis an embedded database versus one over a network, and an app gets it from\\n`SqliteOptions` just as much as from `SyncSqliteOptions`.\\n\\nSo:\\n\\n- **Pick `SqliteOptions`** if the app might move to Postgres later. Every call is\\n  already awaited, so the move costs no signature change.\\n- **Pick `SyncSqliteOptions`** if SQLite is the decision for good and you want a\\n  request path with no promise in it at all. Sync mode is SQLite forever.\\n\\n`Bun.SQL` talks to a server over a socket, and no amount of API design makes a\\nPostgres query return a row instead of a promise. That asymmetry is structural:\\n`SqlOptions` has no sync sibling, and `transactionSync` does not accept a\\n`BunSQLDatabase`. There is **no `SyncSqlOptions`, and there will not be one.**\\n\\n## Querying\\n\\ndrizzle's builder, unchanged. On `bun:sqlite` it is **synchronous**, so a statement\\nends in `.run()`, `.all()` or `.get()`. On Postgres, awaiting the builder executes\\nit.\\n\\n```ts\\ndb.insert(users).values({ email }).run();\\nconst rows = db.select().from(users).orderBy(users.id).limit(10).all();\\nconst one = db.select().from(users).where(eq(users.id, id)).get();\\n```\\n\\n`.get()` returns **`undefined`** when there is no row. Wrappers that returned\\n`null` are a common source of confusion here.\\n\\nRepository methods are still worth declaring `async` on `bun:sqlite` if you are on\\n`SqliteOptions`: callers await them anyway, and moving that table to Postgres later\\nthen costs no signature change.\\n\\nRaw SQL is where the two adapters share nothing at all. bun-sqlite has\\n`run`/`all`/`get`/`values` and no `execute`; bun-sql has `execute` and none of the\\nothers:\\n\\n```ts\\nimport { sql } from 'drizzle-orm';\\n\\ndb.run(sql`PRAGMA foreign_keys = ON`); // bun-sqlite\\nconst counted = db.all<{ n: number }>(sql`SELECT count(*) AS n FROM users`);\\n\\nawait pg.execute(sql`CREATE TABLE IF NOT EXISTS notes (id SERIAL PRIMARY KEY)`);\\n```\\n\\n### Two sharp edges in raw SQL\\n\\n**`prepare()` compiles one statement and silently drops the rest.** A\\nmulti-statement string, say four `CREATE TABLE`s separated by semicolons, creates\\nthe first table only, with no error. That reaches through drizzle, because\\n``db.run(sql`...`)`` goes via `prepare`. A DDL block has to be one statement per\\ncall; `db.exec()` on the raw handle is the one that takes several.\\n\\n**A `Date` is not normalised for you, and on a non-strict handle the failure is\\nsilent.** Measured on Bun 1.3.14 with drizzle-orm 0.45.2:\\n\\n```ts\\ndb.run(sql`INSERT INTO audit (at) VALUES (${new Date()})`);\\n// strict: true  (this package's default) -> DrizzleError, cause: Missing parameter \\\"1\\\"\\n// strict: false                          -> no error at all, and the column holds NULL\\n```\\n\\nTwo ways to write a timestamp, both verified. Pick one per column, because they\\nstore different things:\\n\\n```ts\\n// 1. A TEXT column and a raw template: convert it yourself.\\ndb.run(sql`INSERT INTO logins (at) VALUES (${new Date().toISOString()})`);\\n\\n// 2. A column that declares its mode, and the builder. drizzle maps both ways.\\nexport const audit = sqliteTable('audit', {\\n  at: integer('at', { mode: 'timestamp' }).notNull(), // epoch seconds\\n});\\ndb.insert(audit).values({ at: new Date() }).run();\\n```\\n\\nThe mapping belongs to the **column**, so it applies to the builder and never to a\\n`sql` template. Postgres is the exception: it parses a `timestamptz` from the\\nstring and takes a native `Date` binding as well.\\n\\n## Transactions\\n\\n`transaction(db, fn)` is a standalone function rather than a method, because on\\none of the two backends it **replaces** drizzle's own.\\n\\n```ts\\nimport { transaction } from '@dunx/infra/db';\\n\\nconst id = await transaction(db, async (tx) => {\\n  const row = tx.insert(users).values({ email }).returning().get();\\n  await Bun.sleep(1); // still inside the transaction\\n  tx.insert(audit).values({ userId: row.id }).run();\\n  return row.id;\\n});\\n```\\n\\nCommit on return, roll back on throw, and the throw propagates. Nesting takes a\\nsavepoint, so an inner failure unwinds only the inner work.\\n\\n### Why it is not `db.transaction()` on `bun:sqlite`\\n\\nBecause drizzle's is synchronous there. `drizzle-orm/bun-sqlite`'s session hands\\nthe callback straight to `bun:sqlite`'s own wrapper:\\n\\n```js\\nconst nativeTx = this.client.transaction(() => {\\n  result = transaction(tx);\\n});\\nnativeTx[config.behavior ?? 'deferred']();\\n```\\n\\nThat wrapper commits as soon as the callback **returns its promise**. So\\n`client.inTransaction` is already `false` before the first `await` resumes, every\\nstatement after it runs in autocommit, and a later throw rolls back nothing.\\nMeasured on Bun 1.3.14: insert, `await Bun.sleep(1)`, throw, catch, and the row is\\nstill there.\\n\\ndrizzle inherits the behaviour rather than fixing it, so `transaction()` issues\\n`BEGIN`/`COMMIT`/`ROLLBACK` itself. There is only one connection, so two\\noverlapping top-level transactions would issue a nested `BEGIN`; they queue\\ninstead. A nested call is already inside the holder's turn and takes a savepoint,\\nso it must not queue behind itself.\\n\\nOn **Postgres** the same function delegates to drizzle's `db.transaction()`,\\nwhich is genuinely async: `Bun.SQL`'s `begin()` reserves a connection for the\\nduration.\\n\\nThe callback there receives drizzle's `PgTransaction` (exported as\\n`SqlTransaction<TSchema>`) rather than the database, since the pooled outer\\nhandle would take a different connection and sit outside the transaction. Nesting\\non Postgres is therefore `tx.transaction(...)`, drizzle's own savepoint.\\n\\n### `transactionSync(db, fn)`, where `db.transaction()` **is** right\\n\\nEverything above is downstream of the callback being asynchronous. Take the\\npromise away and `bun:sqlite`'s wrapper is exactly correct, so `transactionSync`\\ndelegates to drizzle's own `db.transaction()` rather than issuing statements\\nitself: one native transaction, no `BEGIN` strings, no queue, no promise.\\n\\n```ts\\nconst total = transactionSync(this.db, (tx) => {\\n  tx.insert(widgets).values({ name: first, weight: 1 }).run();\\n  if (fail) throw new Error('rolling back on purpose');\\n  tx.insert(widgets).values({ name: second, weight: 2 }).run();\\n  return tx.select().from(widgets).all().length;\\n});\\n```\\n\\nIt returns the value rather than a promise, and throws where `transaction()`\\nrejects, so recovery is `try`/`catch`.\\n\\nThe callback is held to being synchronous **at compile time**. Its return type is\\nconstrained to a non-thenable, so an `async` callback, or one returning\\n`Promise.resolve(...)`, is a type error naming the constraint rather than a\\nrollback that silently does nothing. Verified against Bun 1.3.14: with a\\nsynchronous callback the row is gone after a throw; with an async one it is not.\\n\\nOne consequence of that constraint: `NotThenable`'s object branch is a weak type,\\nso TypeScript rejects an object or array sharing no property with\\n`{ then?: undefined }`. Returning a scalar, as above, is what it currently\\naccepts.\\n\\nThe two compose. A `transactionSync` opened while an async `transaction()` is\\nsuspended across an `await` takes a **savepoint** rather than failing, because\\n`bun:sqlite` branches on `Database.inTransaction`, which the outer `BEGIN` already\\nset.\\n\\n## Migrations\\n\\nSchema migrations are **drizzle-kit's**, and dunx does not wrap them.\\n`drizzle-kit generate` writes the SQL, owns its own journal, and owns the snapshot\\nfolder. Apply them with drizzle's own migrator:\\n\\n- `drizzle-orm/bun-sqlite/migrator` for `bun:sqlite`, which is synchronous\\n- `drizzle-orm/bun-sql/migrator` for Postgres, which is async\\n\\nWrapping any of that would produce a worse version of something drizzle already\\nships, and a second journal that could disagree with the first.\\n\\n## Seeding\\n\\ndrizzle-kit has no concept of **data**. `runSeeds` covers that, with its own\\njournal table separate from drizzle's.\\n\\n```ts\\nimport { runSeeds } from '@dunx/infra/db';\\n\\nconst report = await runSeeds(db, { dir: `${import.meta.dir}/seeds` });\\nreport.applied; // journaled by this run, in the order they ran\\nreport.journaled; // already recorded, so not run again\\nreport.skipped; // refused by their own when(env)\\n```\\n\\nA seed file exports `seed`, and optionally `when`:\\n\\n```ts\\n// seeds/0001_users.seeder.ts\\nexport const when = (env: string): boolean => env !== 'production';\\n\\nexport function seed(db: BunSQLiteDatabase<typeof schema>): void {\\n  db.insert(users).values({ email: 'ada@example.com' }).run();\\n}\\n```\\n\\n| Option    | Default                          | Notes                                 |\\n| --------- | -------------------------------- | ------------------------------------- |\\n| `dir`     | required                         | Directory holding the numbered files  |\\n| `env`     | `NODE_ENV`, then `'development'` | What `when` is handed                 |\\n| `table`   | `'dunx_seeds'`                   | The journal table                     |\\n| `pattern` | `'*.seeder.{ts,js}'`             | Bun runs TypeScript; a build emits JS |\\n\\nRules:\\n\\n- **Order is the numeric prefix** rather than the filename, so `0010_x` runs after\\n  `0009_x`. A file without a prefix is an error, and so are two files sharing a\\n  number. The whole value of a journal is that the order is identical everywhere,\\n  and a tie would be settled by whatever order `Bun.Glob` happened to scan in.\\n- **One transaction per seed**, covering the seed **and** its journal row. A seed\\n  that throws leaves neither the data nor the record, so it is retried on the next\\n  boot instead of being half-applied and marked done. On `bun:sqlite` that\\n  transaction is this package's, for the reason above.\\n- **A `when(env)` refusal is not journaled.** It lands in `skipped` and writes no\\n  row, so the same file still runs the first time it reaches an environment it\\n  does belong in.\\n- The journal table is created `IF NOT EXISTS` on every call, so it is safe on\\n  every boot. `applied_at` is `TEXT` on SQLite and `TIMESTAMPTZ` on Postgres,\\n  written as an ISO 8601 **string** either way, because of the `Date` refusal\\n  above.\\n\\nThe handle a seed receives is the transaction's, which on `bun:sqlite` **is** the\\ndatabase (one connection) and on Postgres is a `PgTransaction`.\\n`SeedHandle<TSchema>` is the union; a seed file annotates the one it was written\\nfor, since a body that names tables is dialect-specific anyway.\\n\\n## MySQL\\n\\nThere is no MySQL backend in `@dunx/infra/db`, a documented gap with a worked\\nroute around it.\\n\\ndrizzle 0.45.2 has **no Bun-native MySQL driver.** Its only Bun entrypoints are\\n`bun-sql`, which is Postgres by construction, and `bun-sqlite`. Its MySQL drivers\\nare `mysql2` and `mysql-proxy`, and `mysql2` is a JavaScript reimplementation of a\\nwire protocol Bun already speaks, so it is banned.\\n\\n`drizzle-orm/mysql-proxy` is the way through: drizzle's MySQL dialect with the\\ntransport left as a callback, and `Bun.SQL` supplying the transport. drizzle owns\\nthe SQL generation and the schema, Bun owns every byte of I/O, and nothing pulls in\\n`mysql2`.\\n\\nA working `DbOptions` for it is in **`examples/databases/src/mysql/driver.ts`**:\\nabout forty lines, needing **no change to the package**.\\n\\nVerified end to end against MySQL 8 on Bun 1.3.14: inserts, selects, `where`,\\nordering, updates, deletes, aggregates, `$returningId()` single and multi-row,\\ninner and left joins, `placeholder()` prepared statements, and the `mysql-proxy`\\nmigrator.\\n\\nFour details the adapter has to get right, each measured:\\n\\n- **`.values()` is mandatory for `method === 'all'`.** drizzle's `mapResultRow`\\n  indexes rows **positionally**, and `Bun.SQL`'s default object rows lose columns\\n  on a join: selecting `users.id, users.name, posts.id, posts.name` returns two\\n  keys rather than four, the later names overwriting the earlier ones. A manual\\n  object-to-array conversion would be silently wrong.\\n- **`method === 'execute'` covers SELECTs too**, whenever the query carries no\\n  fields. Return the rows when the result array is non-empty, or\\n  ``db.execute(sql`...`)`` silently yields nothing.\\n- **`insertId` and `affectedRows` go in `rows[0]`** rather than at the top level, despite\\n  `RemoteCallback`'s declared type. `mysql-proxy/session.js` reads\\n  `data[0].insertId`, and Bun's own property is `lastInsertRowid`.\\n- **Name the `adapter`.** In the **options-object** form on Bun 1.3.14,\\n  `POSTGRES_URL`, `PGURL` or `TLS_POSTGRES_DATABASE_URL` in the environment\\n  silently overrides an explicitly passed `url` and forces `adapter: 'postgres'`,\\n  so a MySQL URL is dialled as Postgres and fails with a bare\\n  `Connection closed`. `new Bun.SQL(urlString)` and `new Bun.SQL(new URL(url))`\\n  are unaffected, and so is naming the adapter.\\n\\n`mysql-proxy` also refuses `db.transaction()` outright, because a callback\\ntransport has no way to pin its statements to one connection. `Bun.SQL`'s\\n`begin()` does have a way, so the example opens the transaction on the client and\\nbuilds a second drizzle handle over the reserved socket. That is the one functional\\ngap against drizzle's `mysql2` driver, and it costs an extra handle rather than\\ncosting correctness.\\n\\nOne more, if you write a CLI or a seeder against MySQL: an in-flight `Bun.SQL`\\nquery on the **MySQL** adapter does not hold the event loop open. A script whose\\nonly pending work is such a query exits with code 0, mid-query, with no error.\\n`Bun.serve` keeps a reference so a server never sees it; hold a `setInterval` for\\nthe duration of the work in a one-shot script.\\n\\n## The raw handle and shutdown\\n\\n`DbConnection` holds `backend`, `dialect`, `db` (the drizzle handle), `raw` (the\\n`bun:sqlite` `Database` or the `Bun.SQL` client), and an idempotent `close()`.\\n\\n`raw` is typed `unknown`, because the base cannot promise either backend's handle.\\nNarrow with `instanceof SqliteConnection` or `instanceof SqlConnection`, which\\nrestores the concrete type.\\n\\nFor SQLite there is `asSqlite`, which does that check and returns the `bun:sqlite`\\n`Database`. Pragmas and triggers are what reach for it:\\n\\n```ts\\nimport { asSqlite } from '@dunx/infra/db';\\n\\nasSqlite(connection).exec('pragma foreign_keys = on');\\n```\\n\\nIt throws naming the backend it was handed, where `connection.raw as Database`\\nwould hand back a `Bun.SQL` client under the wrong type. There is no `asSql` twin:\\n`Bun.SQL`'s surface is reachable through drizzle's own `sql` tag.\\n\\n`onShutdown()` is concrete rather than abstract: the hook and the explicit call are\\none operation. `@dunx/core` shuts down in reverse construction order, and every\\nrepository depends on the drizzle handle which depends on the connection, so\\neverything holding it has already drained by the time it closes.\\n\\n## Pagination\\n\\n`@dunx/infra/pagination` does keyset pagination, which stays correct while rows\\nare being written.\\n\\n```ts\\nimport { paginate, PAGINATION, type Page } from '@dunx/infra/pagination';\\n\\nconst pageQuery = z.object({\\n  take: z.coerce.number().int()\\n    .min(PAGINATION.MIN_TAKE).max(PAGINATION.MAX_TAKE)\\n    .default(PAGINATION.DEFAULT_TAKE),\\n  order: z.enum(['asc', 'desc']).default(PAGINATION.DEFAULT_ORDER),\\n  direction: z.enum(['forward', 'backward']).default(PAGINATION.DEFAULT_DIRECTION),\\n  cursor: z.string().max(PAGINATION.MAX_CURSOR).optional(),\\n});\\nconst paged = { query: pageQuery } as const;\\n\\n@Get('/page', paged)\\npage({ query }: Input<typeof paged>): Promise<Page<Entry>> {\\n  return paginate<typeof ledger, Entry>({\\n    db: this.db,\\n    table: ledger,\\n    options: query,\\n  });\\n}\\n```\\n\\n```json\\n{\\n  \\\"data\\\": [{ \\\"id\\\": 9, \\\"memo\\\": \\\"newest\\\" }],\\n  \\\"meta\\\": {\\n    \\\"take\\\": 20,\\n    \\\"hasNextPage\\\": true,\\n    \\\"hasPreviousPage\\\": false,\\n    \\\"nextCursor\\\": \\\"eyJzIjoiOSIsImkiOiI5In0\\\",\\n    \\\"previousCursor\\\": null\\n  }\\n}\\n```\\n\\nPass `meta.nextCursor` back as `?cursor=` to read forwards, and\\n`meta.previousCursor` with `?direction=backward` to go the other way.\\n\\nBoth type arguments are given above, and a generic wrapper needs them. `paginate`\\ninfers the row type from the table, so a base repository that pages a narrower\\nselect type gets the table's type back unless it says otherwise:\\n\\n```ts\\n// Infers the table's select type, not TSelect.\\nreturn paginate<TTable>({ db, table, options, where });\\n\\n// Returns Page<TSelect>.\\nreturn paginate<TTable, TSelect>({ db, table, options, where });\\n```\\n\\n### Why not `OFFSET`\\n\\nAn offset scan re-reads and discards every row before the page, so page 500 costs 500\\npages of work. Worse, it is **wrong under writes**: insert a row while someone is\\npaging and every later page shifts by one, so an item is served twice or skipped. A\\ncursor names the last row seen, the database seeks straight to it, and a concurrent\\ninsert changes nothing about what has already been read.\\n\\nThe cursor carries the sort value **and** the row id, and the query compares both.\\nWithout the id tie-break, rows sharing a timestamp are silently skipped or\\nrepeated, and a bulk insert produces exactly that.\\n\\n### The schema you write it against\\n\\n`paginate` sorts by the first of `updatedAt`, `createdAt`, `id` your table has, or\\nwhatever `orderBy` names. It has to be unique together with the id column, which is\\nwhat makes the seek deterministic.\\n\\nIt takes anything with drizzle's `select()`, so both dialects and a transaction handle\\nfit - it `await`s the query builder rather than calling `.all()`, because drizzle's\\nbuilders are thenable on the synchronous `bun:sqlite` driver as well as the\\nasynchronous `Bun.SQL` one.\\n\\n### What it does not do\\n\\n- **No zod schema is shipped.** `parsePageOptions` is a hand-written validator, since\\n  route validation targets Standard Schema and shipping a schema would pick the\\n  library for you. Declare your own, as above, and the parameters land in the OpenAPI\\n  document.\\n- **No total count.** `hasNextPage` comes from fetching one row more than asked and\\n  dropping it, so there is no second `COUNT(*)`.\\n- **A 400 without a filter.** A bad cursor throws `CursorError`; bad options throw\\n  `PageOptionsError`. Both extend `AppError` and carry `status = 400`, which is an\\n  integer rather than a dependency on the web layer, and `@dunx/http`'s default\\n  mapper turns it into the response. You write no `catch`.\\n\\n`examples/full` serves it at `GET /api/ledger/page`.\\n\\n## No entity decorators\\n\\nThey were tried on TypeScript 7.0.2, both routes, and both fail with `TS2339:\\nProperty 'table' does not exist`:\\n\\n```ts\\n@Entity('users')\\nclass UserA {}\\nUserA.table; // decorator defineProperty'd a static\\n@Entity('users')\\nclass UserB {}\\nUserB.table; // decorator's return type is C & { table }\\n```\\n\\nTC39 decorators are **type-transparent** in TypeScript: the decorator's return\\ntype does not become the declaration's type.\\n\\ndrizzle's whole value is the table object's _type_ carrying column types into\\nevery query, so a decorator could build a working table at runtime while every\\nquery degraded to `unknown`. Recovering the types would mean hand-writing a\\nmapped type mirroring drizzle's `BuildColumns`, a second source of truth that\\ndrifts from the first.\\n\\n## Related\\n\\n- [Configuration](dunx://guide/12-configuration) for `forRootAsync` and `AppConfigService`\\n- [Authentication](dunx://guide/17-authentication), where `drizzleDatabase(connection)`\\n  hands better-auth the connection this module already opened\\n- [Providers](dunx://guide/03-providers) for factory providers and resolution order\\n\"},{\"slug\":\"15-queues\",\"title\":\"Queues\",\"summary\":\"bullmq is the queue.\",\"sections\":[\"Read this before you deploy it\",\"A handler is a method with a decorator\",\"Setup\",\"Publishing and consuming are separate decisions\",\"Serving and consuming in one process\",\"`jobTimeoutMs`\",\"Shutdown\",\"The ioredis boundary\",\"Testing with no Redis running\",\"A dashboard\",\"Waiting for a job to finish\",\"Related\"],\"body\":\"# Queues\\n\\n**bullmq is the queue.** What `@dunx/infra/queue` contributes is the four things\\nbullmq has no opinion about: where a handler lives, how it is found, how it is\\ninjected, and when it stops. dunx adds no retry policy, no backoff, no rate\\nlimiter and no scheduler: those are bullmq's, and a second implementation of\\nthem would be a worse one.\\n\\n```bash\\nbun add bullmq ioredis\\n```\\n\\nBoth are **optional peer dependencies**, so an app using only `@dunx/infra/files`\\ninstalls neither. `ioredis` is there for bullmq's sake rather than dunx's: see\\n[the ioredis boundary](#the-ioredis-boundary) below.\\n\\n## Read this before you deploy it\\n\\nOne known defect.\\n\\n**A process that attempted a queue operation against a Redis it could not reach\\ndoes not exit on `SIGTERM`.** It is **two** upstream leaks, one in Bun and one in\\nbullmq, and neither is reachable from userland. Bisected a layer at a time, with\\n`connectionTimeout: 2000, maxRetries: 0` throughout:\\n\\n| server                      | `Bun.RedisClient` | bullmq's adapter | a bullmq `Queue` |\\n| --------------------------- | ----------------- | ---------------- | ---------------- |\\n| healthy                     | exits 0           | exits 0          | exits 0          |\\n| refused (nothing listening) | exits 0           | **never exits**  | **never exits**  |\\n| black-holed (SYN dropped)   | **never exits**   | **never exits**  | **never exits**  |\\n\\nThe black-holed row is Bun's: a connect that never completes keeps a handle past\\n`close()`, and no client option changes it. The refused row is bullmq's: its\\nadapter runs a `setTimeout` reconnect chain and both `disconnect()` and `quit()`\\nreturn early once the connection has dropped, which is exactly when one is\\npending.\\n\\nAn app that imports `QueueModule` without publishing is unaffected, and so is a\\nhealthy deployment. What hangs is a process that served a queue route while Redis\\nwas unreachable.\\n\\nIt **serves correctly throughout**, answering 503 in single-digit milliseconds,\\nso this is a shutdown defect rather than an availability one, and whatever\\nsupervises the process will `SIGKILL` it.\\n\\nEarlier versions of this guide also told you to **pin ioredis 5**. That advice was\\nwrong and has been withdrawn: ioredis 6 did not remove `ioredis/built/utils`, both of\\nbullmq's builds import it, and Bun runs the CJS one. Any ioredis from 5.0.0 up works.\\nThe measurement is in architecture/queues.md, \\\"Not pinning ioredis 5\\\".\\n\\n## A handler is a method with a decorator\\n\\nThat is the whole registration. No class decorator, no registry, no queue token.\\n\\n```ts\\nimport { Logger } from '@dunx/core';\\nimport { JobHandler } from '@dunx/infra/queue';\\nimport type { Job } from 'bullmq';\\n\\nexport class Emails {\\n  constructor(\\n    private readonly mailer: Mailer,\\n    private readonly logger: Logger,\\n  ) {}\\n\\n  @JobHandler({ queue: 'emails', name: 'welcome' })\\n  async welcome(job: Job<{ to: string }>): Promise<{ sent: string }> {\\n    await this.mailer.send(job.data.to, 'Welcome');\\n    this.logger.info(`welcomed ${job.data.to}`);\\n    return { sent: job.data.to };\\n  }\\n}\\n```\\n\\n`Emails` is declared in `@Module({ providers })` like any other injectable, and it\\ninjects by constructor like any other class. The same service the HTTP routes use\\ndoes the work here, with no second wiring.\\n\\n### How a handler is found\\n\\nThe same **marker-plus-prototype-scan** that routes and websocket gateways use.\\n`@JobHandler` sets a symbol property on the method function it receives and\\nreturns it; nothing is recorded anywhere else. At boot, `WorkerFactory` walks the\\nprototype chains of the classes the modules already declare, and a marked method\\nis a job.\\n\\nWhat follows from that:\\n\\n- **No second registration.** There is no `registerQueue`, no `@Processor` class\\n  decorator, and no queue token to inject.\\n- **A handler may be inherited.** An abstract base's marked method is found on\\n  every subclass, and overriding it _without_ re-decorating still works, because\\n  the marker is on the base's function and dispatch is bound off the instance, so\\n  it lands on the override.\\n- **Two handlers for one `(queue, name)` pair is a boot error** naming both. It\\n  would otherwise silently split the traffic between them.\\n- **A factory- or value-provided instance is not scanned.** There is no class to\\n  read a prototype chain from until it has been built. Put handlers on a class\\n  provider.\\n\\nAn arriving job whose name no handler claims fails with a message saying what that\\nworker _does_ serve. The shape of that bug is usually a worker deployed ahead of\\nthe handler that serves it, and bullmq retries under the job's own `attempts`.\\n\\n## Setup\\n\\nOne module, imported by **every** process that touches a queue:\\n\\n```ts\\nimport { Module } from '@dunx/core';\\nimport { QueueModule } from '@dunx/infra/queue';\\n\\n@Module({\\n  imports: [QueueModule.forRoot({ url: 'valkey://localhost:6379' })],\\n  providers: [Emails, Mailer],\\n})\\nexport class JobsModule {}\\n```\\n\\n`forRootAsync` is the same thing with the options behind a factory that may await\\nand may inject:\\n\\n```ts\\nQueueModule.forRootAsync({\\n  useFactory: (config: AppConfigService) => {\\n    const { url } = config.get('redis');\\n    return { ...(url === undefined ? {} : { url }), prefix: 'dunx-full' };\\n  },\\n  inject: [AppConfigService] as const,\\n});\\n```\\n\\nWith no `url` it follows the same chain `@dunx/infra/redis` does: `$VALKEY_URL`,\\nthen `$REDIS_URL`, then `valkey://localhost:6379`. The URL is validated when the\\nmodule is configured rather than on first connect.\\n\\n### Options\\n\\n| Option              | Default                                                     | Notes                                                     |\\n| ------------------- | ----------------------------------------------------------- | --------------------------------------------------------- |\\n| `url`               | `$VALKEY_URL`, `$REDIS_URL`, then `valkey://localhost:6379` | Validated at configuration time                           |\\n| `prefix`            | `'bull'`                                                    | bullmq's key prefix                                       |\\n| `worker`            | `{}`                                                        | Forwarded verbatim to every `Worker`                      |\\n| `defaultJobOptions` | none                                                        | Forwarded verbatim as every `Queue`'s `defaultJobOptions` |\\n| `connection`        | `{ connectionTimeout: 5000, maxRetries: 0 }`                | Forwarded to every `Bun.RedisClient`                      |\\n| `jobTimeoutMs`      | none                                                        | Not a bullmq feature. See below                           |\\n\\n`worker` and `defaultJobOptions` are **passthroughs**. `concurrency`,\\n`limiter`, `lockDuration`, `stalledInterval`, `attempts`, `backoff`,\\n`removeOnComplete` and the rest are bullmq's own options, documented by bullmq.\\nRestating them here would only produce a staler copy.\\n\\n### Why `connection` is bounded by default\\n\\nBoth halves of `{ connectionTimeout: 5000, maxRetries: 0 }` were measured rather\\nthan guessed.\\n\\nWith Bun's own defaults, a client that cannot reach Redis retries **without\\nbound**, so `publish()` never settles and a route waiting on it hangs instead of\\nanswering. With the bounded default it rejects in single-digit milliseconds and a\\ncontroller can map that to a 503.\\n\\nAnd with **any** `maxRetries > 0`, a client that never connected keeps a retry\\ntimer alive past `close()` and the process never exits. Verified at\\n`maxRetries: 3`, where a full-example boot with no Redis survived `SIGTERM` for\\n12 s. So `0` is the only default that both fails fast and lets the process die.\\n\\nThe trade: **a worker set to `0` will not ride out a Redis blip.** Raise it if that\\nmatters more than a clean exit on a cold start against an absent Redis. They\\ncannot both be had until Bun clears the timer on `close()`.\\n\\nNeither of these is what the bounded default _cannot_ fix - see the two leaks\\nabove, which survive `maxRetries: 0` entirely.\\n\\n### The connection bullmq builds for itself is bounded too\\n\\nbullmq does not keep the client it is handed. A `Worker`'s blocking connection is\\n`connection.duplicate()`, and every reconnect rebuilds one, both with\\n`new (this.raw.constructor)(this.raw.url)`.\\n\\nThat drops the options, so `maxRetries: 0` would have applied to the first socket\\nonly. `Bun.RedisClient` also has **no `url` property** on Bun 1.3.14, so it\\ndropped the url too: the replacement resolved Bun's default (`$VALKEY_URL`,\\n`$REDIS_URL`, `valkey://localhost:6379`), and a worker pointed at a remote Redis\\nwould block-poll localhost and never see a job.\\n\\n`@dunx/infra/queue` hands bullmq a `Bun.RedisClient` **subclass** that carries the\\nurl and reapplies the options, so every one of those reconstructions comes out the\\nsame as the first. Nothing to configure; it is how `QueueConnection` builds a\\nclient.\\n\\n## Publishing and consuming are separate decisions\\n\\n`QueueModule.forRoot()` exports three tokens: `QueueOptions`, `QueueConnection` and\\n`JobPublisher`. That is the **publish** side, which is all a web process needs. It\\nalso binds a fourth provider it does not export, `QueueRunner` - the piece that\\nopens workers when you ask it to.\\n\\n**By default it consumes nothing.** `consume` is `false`, so a web process that\\npublishes never starts a worker by accident. There are three ways to consume, and\\nthey agree on exactly one thing: the module.\\n\\n| How                                          | Where the workers live                           |\\n| -------------------------------------------- | ------------------------------------------------ |\\n| `QueueModule.forRoot({ consume: true })`     | the container that imported the module           |\\n| `QueueModule.forRoot({ consume: 'if-any' })` | the same, and stands down when no handler exists |\\n| `WorkerFactory.create(root)`                 | a process of its own, with its own container     |\\n| `WorkerFactory.attach(app, root)`            | a container somebody else already built          |\\n\\n`consume: true` is the one to reach for first. `QueueRunner` implements `OnInit` and\\n`OnShutdown`, so the workers start with the container and stop with it, before the\\nconnections the handlers use are closed. That ordering is why it lives in a module\\nrather than in an entrypoint: nothing an app writes by hand can guarantee teardown\\nruns in the right order.\\n\\n```ts\\n@Module({\\n  imports: [QueueModule.forRoot({ url, consume: true, processor })],\\n  providers: [ThumbnailJobs],\\n})\\nexport class JobsModule {}\\n```\\n\\nA broker that is down degrades rather than failing boot: the runner logs at `error`\\nthat the process is serving but consuming nothing. A sandbox child sets\\n`DUNX_JOB_WORKER`, and the runner refuses to open workers when it sees it, so a\\nprocessor file may import a `consume: true` module without forking forever.\\n\\n`consume: true` with no `@JobHandler` anywhere in the graph is a boot error: a\\nprocess that consumes nothing is one nobody notices. `consume: 'if-any'` stands\\ndown with a warning instead, for an incremental migration where the queue wiring\\nlands several commits before the first handler. Two handlers claiming one\\n`(queue, name)` stays a boot error under both.\\n\\n### Isolation is per handler, and per queue in effect\\n\\n`@JobHandler({ queue, name, background })` marks one handler. `background: true`\\nmakes bullmq fork the file named by `QueueModule.forRoot({ processor })` instead of\\ncalling a function in this process - the switch that keeps a CPU-bound handler off\\nthe loop serving requests.\\n\\nTwo things about it are easy to get wrong.\\n\\n- **`processor` must be an absolute path.** bullmq resolves it in the child. A\\n  `background` queue with no `processor` configured is a boot error at `start()`.\\n- **`background` is declared per handler but takes effect per queue.** bullmq opens\\n  one `Worker` per queue and takes either a file path or a function, so one marked\\n  handler sandboxes every handler on that queue.\\n\\n`isolation` is **not** a `@JobHandler` option. It is\\n`QueueModule.forRoot({ isolation })`, and it defaults to `'process'`. Keep it there:\\n\\n- A fork is a fresh Bun process. It reads `bunfig.toml`, so the transform preload\\n  runs and constructor injection works in the child.\\n- `'thread'` enters through bullmq's own prebuilt worker entry, where a preload\\n  cannot match a `.ts` file. The first provider with a constructor parameter then\\n  fails at boot.\\n\\n`'thread'` is usable only against a tree whose dependencies were recorded at build\\ntime.\\n\\nThe file itself default-exports the processor's `handle`:\\n\\n```ts\\n// src/jobs.processor.ts - the file bullmq forks\\nimport { JobProcessor } from '@dunx/infra/queue';\\nimport { JobsProcessorModule } from './jobs.processor.module.js';\\n\\nexport default new JobProcessor(JobsProcessorModule).handle;\\n```\\n\\n`handle` is an arrow property rather than a method, because bullmq calls the export\\nbare. The child builds its container on the first job and reuses it.\\n\\n### Publishing\\n\\n```ts\\nimport { JobPublisher } from '@dunx/infra/queue';\\n\\nexport class Signups {\\n  constructor(private readonly jobs: JobPublisher) {}\\n\\n  async register(email: string): Promise<void> {\\n    await this.jobs.publish('emails', 'welcome', { to: email });\\n  }\\n}\\n```\\n\\n`publish(queue, name, data, options?)` returns bullmq's own `Job`, and\\n`publisher.queue(name)` returns bullmq's own `Queue`, with `addBulk`,\\n`upsertJobScheduler`, `getJobCounts`, `drain` and everything else already on it.\\nThere is no wrapper to outgrow.\\n\\nA queue is opened on **first use** rather than declared up front. A queue is a key prefix,\\nnot a resource to reserve, so there is nothing a registration step could validate\\nand nothing gained by holding a socket for a queue nobody publishes to.\\n`publisher.opened` reports the names opened so far, and `onShutdown` closes each\\nof them.\\n\\n### The worker process\\n\\n```ts\\n// src/worker.ts\\nimport { ConfigModule, Logger, Module } from '@dunx/core';\\nimport { LoggerModule } from '@dunx/infra/logger';\\nimport { WorkerFactory } from '@dunx/infra/queue';\\nimport { AppConfigService, validate } from './config.js';\\nimport { JobsModule } from './jobs/jobs.module.js';\\n\\n@Module({\\n  imports: [\\n    ConfigModule.forRoot({ validate, as: AppConfigService }),\\n    LoggerModule.forRootAsync({\\n      useFactory: (config: AppConfigService) => ({\\n        name: `${config.get('appName')}-worker`,\\n        level: config.get('log').level,\\n      }),\\n      inject: [AppConfigService] as const,\\n    }),\\n    JobsModule,\\n  ],\\n})\\nclass WorkerModule {}\\n\\nconst worker = await WorkerFactory.create(WorkerModule);\\nawait worker.start();\\nworker.enableShutdownHooks();\\nawait worker.closed;\\n```\\n\\n```json\\n{ \\\"scripts\\\": { \\\"worker\\\": \\\"bun run src/worker.ts\\\" } }\\n```\\n\\nThe root module it is handed may be the app's own or a narrower one that leaves\\nthe controllers out. It is a normal dunx container either way, so a handler gets\\nthe same constructor injection a controller does.\\n\\n**`create` discovers and validates; `start` is what opens connections.** So a\\nwiring mistake fails before anything consumes, and `worker.jobs` can be inspected\\nin a test with no server running:\\n\\n| Mistake                              | Error at `create`                                                       |\\n| ------------------------------------ | ----------------------------------------------------------------------- |\\n| No `QueueModule` in the graph        | `ERR_QUEUE_INVALID_STATE`                                               |\\n| No marked method anywhere            | `ERR_QUEUE_NO_HANDLERS`                                                 |\\n| A name in `queues` no handler claims | `ERR_QUEUE_NO_HANDLERS`, naming both what is missing and what was found |\\n| Two handlers on one `(queue, name)`  | `ERR_QUEUE_DUPLICATE_HANDLER`                                           |\\n\\nThe `QueueModule` check reads the **module graph** rather than the container:\\n`QueueOptions` is a class whose constructor argument is optional, so an unbound\\ncontainer would self-bind it and hand back defaults. A worker silently pointed at\\n`localhost` is worse than one that will not boot.\\n\\n`WorkerApp` carries `jobs` (every handler after the filter), `queues` (what this\\nprocess will consume), `start()`, `shutdown()`, `enableShutdownHooks()`, `closed`\\nand `get(token)`.\\n\\n### One queue, one process\\n\\n```ts\\nconst worker = await WorkerFactory.create(AppModule, { queues: ['emails'] });\\n```\\n\\nThat is how one queue gets its own process and its own concurrency. A name in that\\nlist that no handler claims is a boot error, rather than a process that quietly\\nserves only the queues that were spelled right.\\n\\n## Serving and consuming in one process\\n\\n`WorkerFactory.attach(app, root, options?)` consumes inside a container that\\n**already exists**, so a single process can serve HTTP and work the queues:\\n\\n```ts\\nimport { HttpFactory } from '@dunx/http';\\nimport { WorkerFactory } from '@dunx/infra/queue';\\nimport { AppModule } from './app.module.js';\\n\\nconst app = await HttpFactory.create(AppModule);\\nconst consumer = await WorkerFactory.attach(app, AppModule);\\n\\nawait app.listen(3000);\\nawait consumer.start();\\n```\\n\\n`root` is the same module ref the app was built from. The handlers are found by\\ninspecting it, and resolved out of the container that is already running.\\n\\nIt returns a **`QueueConsumer`**, the consuming half of\\n`WorkerFactory.create` with no `App` of its own: `jobs`, `queues`, `start()` and\\n`stop()`. `create` now wraps the same class, so the two paths share their\\nbehaviour rather than merely resembling each other.\\n\\n`attach` validates with exactly the same rules as `create`. No handlers, or a\\nnamed queue nothing consumes, are both boot errors. The difference is what happens\\non failure: `attach` leaves the caller's container running, because it does not\\nown it.\\n\\n### Stop the consumer before you shut the app down\\n\\n```ts\\nawait consumer.stop();\\nawait app.shutdown();\\n```\\n\\n`consumer.stop()` closes the workers and **nothing else**. It is idempotent, and\\nit waits for whatever is mid-flight, because `close()` without `force` stops\\nfetching and waits for what is already running.\\n\\n**Nothing can enforce that ordering.** Core's `App` exposes no hook to register\\nagainst, so `attach` cannot arrange to run first, and a worker still running when\\nproviders tear down finds its database connection closed underneath it.\\n\\nA worker **process** gets the ordering for free, because `WorkerApplication` owns\\nthe container and its `shutdown()` runs `consumer.stop()` before\\n`app.shutdown()`. An attached consumer does not, so the caller has to sequence it.\\n\\nWhich to reach for:\\n\\n- **`consume: true`** when one process is the whole deployment, which is most\\n  deployments. The container owns start and stop ordering, and a `background`\\n  handler still gets its own process per burst.\\n- **A separate worker process** when the two halves should scale, fail and deploy\\n  independently.\\n- **`attach`** when a container already exists and you are adding consumption to it\\n  after the fact. It is the only one of the three where you have to sequence\\n  teardown yourself.\\n\\n## `jobTimeoutMs`\\n\\nThe one behaviour here that bullmq does not already own.\\n\\nbullmq has `lockDuration` and stall detection, which answer _did the worker die_,\\nnot _is this handler stuck_. A handler hung on an external call holds its lock,\\nrenews it, and never finishes. `jobTimeoutMs` rejects it with\\n`ERR_QUEUE_TIMED_OUT` so the job fails and retries under its own `attempts`. Off\\nby default.\\n\\n## Shutdown\\n\\n`worker.shutdown()` closes every bullmq `Worker` **before** the container tears\\ndown, so an in-flight job finishes while the database connection it is using is\\nstill open. `close()` without `force` stops fetching and waits for what is\\nalready running.\\n\\nThe container's own reverse-construction-order teardown then closes the\\npublisher's queues, and last of all the sockets. `QueueConnection` is constructed\\nfirst, because everything else needs it, so it goes last.\\n\\n`enableShutdownHooks()` wires `SIGTERM` and `SIGINT` to that sequence.\\n\\n## The ioredis boundary\\n\\ndunx does not use `ioredis` in its own code, because `Bun.RedisClient` exists.\\nbullmq needs _a_ Redis client. The resolution is not a compromise, and it was\\nfound by measuring rather than by assuming.\\n\\n**Every byte of queue traffic goes through `Bun.RedisClient`.** bullmq accepts\\neither a connection description it builds a client from, or an already-built\\nclient implementing its `IRedisClient` interface, and bullmq 6 ships\\n`createBunRedisClient`, an adapter over Bun's client. `QueueConnection` uses it.\\ndunx neither imports nor constructs ioredis, and `dist/` contains no reference to\\nit.\\n\\nVerified on bullmq 6.0.5, Bun 1.3.14 and Redis 8.4.0, over that adapter, in 0.5 s:\\nconcurrency 5 honoured across 20 jobs, `attempts: 2` with fixed backoff retrying a\\nthrowing handler exactly once, a delayed job reporting state `delayed` and\\narriving, and `worker.close()` waiting 244 ms for a 250 ms handler rather than\\ndropping it.\\n\\nThree findings shaped the code:\\n\\n- **ioredis is a load-time requirement of bullmq, in both its builds.**\\n  `utils/index` and `classes/redis-connection` statically import `ioredis` and\\n  `ioredis/built/utils`, so `import { Queue } from 'bullmq'` throws\\n  `Cannot find module` without it, despite bullmq 6 declaring `ioredis` an\\n  _optional_ peer and shipping three other backends. That is the only reason it is\\n  listed as an optional peer of `@dunx/infra`. If bullmq makes that import lazy,\\n  the entry disappears.\\n\\n  It is optional in the same sense `bullmq` is - needed if and only if you use\\n  `/queue`, so `bun add bullmq ioredis` installs the pair. Any version\\n  from 5.0.0 works, because that is the range bullmq itself declares and dunx has\\n  no opinion beyond it.\\n\\n- **bullmq does not close a connection it was handed.** Measured with\\n  `CLIENT LIST`: four connections live, three after `worker.close()` plus\\n  `queue.close()`. It closed only the duplicate it created itself.\\n  `QueueConnection.onShutdown` closes the rest.\\n- **Closing one afterwards emits `error` on an emitter with no listener**, because\\n  bullmq detaches its own handler on close and Node's `EventEmitter` throws for an\\n  unhandled `error`. Shutdown would fail on its last step. The adapter gets a no-op\\n  `error` listener at construction.\\n- **The adapter has to be disconnected before its socket is closed.** bullmq reads\\n  a socket that closed without being told to as a blip and schedules a reconnect,\\n  which would rebuild the connection being torn down. `QueueConnection.onShutdown`\\n  calls `disconnect()` on the adapter and then `close()` on the socket - both, in\\n  that order, because `disconnect()` skips the close for a client that never\\n  finished connecting.\\n\\nOne client is opened **per bullmq object** rather than one shared, because a\\n`Worker` blocks on `BZPOPMIN` and bullmq duplicates whatever it is given to get a\\nconnection it may block on. Sharing would only add a duplicate.\\n\\n`@dunx/infra/redis` is untouched and unshared: a queue's sockets are its own. See\\n`packages/infra/README.md` for the Redis client itself.\\n\\n### The subpath is the only way in\\n\\n`@dunx/infra/queue` is **not re-exported from the package barrel**,\\nunlike every other area. `src/index.ts` re-exporting it would put bullmq's static\\n`ioredis` import behind `import '@dunx/infra'` for every consumer, queue or no\\nqueue.\\n\\n## Testing with no Redis running\\n\\nDiscovery, dispatch, options and module wiring need no server at all. `create`\\nopens no socket, so a container can be built, inspected and torn down against an\\naddress that is never dialled:\\n\\n```ts\\nconst worker = await WorkerFactory.create(WorkerModule);\\nexpect(worker.jobs.map((job) => `${job.queue}/${job.name}`)).toEqual([\\n  'emails/welcome',\\n]);\\nawait worker.shutdown();\\n```\\n\\ndunx's own integration suite probes the server first and skips itself when nothing\\nanswers, so `bun test` passes on a machine with no Redis.\\n\\n## A dashboard\\n\\n`@dunx/dashboard` mounts [bull-board](https://github.com/felixmosh/bull-board) at\\n`{path}/queues`, behind the same `authorize` callback as every other panel:\\n\\n```ts\\napp.use(DashboardMiddleware);\\n```\\n\\ndunx renders no queue UI of its own. `@dunx/queue-dashboard` existed for one\\nrelease and was deleted; bull-board 8.6.0 ships a `Bun.serve` adapter, which\\nremoved the only reason to hand-roll one. `commands: false` maps onto\\nbull-board's `readOnlyMode`.\\n\\nA read-only one is at\\n[demo.dunx.win/api/dashboard/queues](https://demo.dunx.win/api/dashboard/queues).\\n\\nThe board is built on the **first request for the queues page**, never at boot, so\\nan app that never opens it holds no broker socket and exits cleanly against an\\nabsent Redis.\\n\\nFor your own panel, the queue data is four calls on bullmq's own `Queue`, which\\n`JobPublisher.queue(name)` hands you:\\n\\n```ts\\nconst queue = publisher.queue('emails');\\n\\nawait queue.getJobCounts(); // waiting, active, completed, failed, delayed\\nawait queue.getJob(id); // one job: state, result, failedReason, attempts\\nawait (await queue.getJob(id))?.retry();\\nawait queue.drain(); // discard everything waiting\\n```\\n\\nServing that as an admin-only JSON controller takes about sixty lines.\\n\\n`getWorkers()` **works**, and was long believed not to. It reported `[]` on Bun\\neven while workers drained jobs.\\n\\n`QueueConnection` wrapped `duplicate` and called it with no arguments, dropping\\nthe `{ connectionName }` bullmq's Bun adapter names a connection through. One\\nline, fixed; `CLIENT SETNAME` runs and the worker appears.\\n\\n## Waiting for a job to finish\\n\\nThe process that published a job does not run it, so `job.returnvalue` on the\\nhandle `publish` returned stays empty: it is filled when the job is loaded, and\\nthat load happened in the worker.\\n\\n`JobEvents` hands over bullmq's `QueueEvents` for a queue, which is what\\n`waitUntilFinished` waits on:\\n\\n```ts\\nimport { JobEvents, JobPublisher } from '@dunx/infra/queue';\\n\\nexport class Thumbnails {\\n  constructor(\\n    private readonly jobs: JobPublisher,\\n    private readonly events: JobEvents,\\n  ) {}\\n\\n  async render(width: number): Promise<Rendered> {\\n    const job = await this.jobs.publish('thumbnails', 'render', { width });\\n    // Resolves when the worker completes it, rejects on a failure or the ttl.\\n    return await job.waitUntilFinished(this.events.events('thumbnails'), 8_000);\\n  }\\n}\\n```\\n\\nbullmq writes each event to a Redis stream and `QueueEvents` blocks on `XREAD`,\\nso this costs no polling. The\\nalternative is `queue.getJob(id)` on a timer, which is what a status endpoint\\ndoes instead: an HTTP request cannot hold a socket open for eight seconds, so\\n`GET /jobs/:id` reports the state it finds and the caller asks again.\\n\\nTwo things to know about the stream:\\n\\n- **A queue's stream opens on the first `events()` call**, not at boot. bullmq\\n  starts a blocking read in the constructor, so a process that publishes and\\n  never waits holds no extra connection.\\n- **It is closed for you** at shutdown, before the sockets it borrowed. A stream\\n  that will not close within two seconds is logged and abandoned rather than\\n  waited on, because `close()` against an unreachable broker never settles.\\n\\n## Related\\n\\n- [Configuration](dunx://guide/12-configuration) for `forRootAsync` and `AppConfigService`\\n- [Logging](dunx://guide/13-logging), which the worker uses for job completion and failure\\n- `examples/full`, whose `src/jobs/` is the worked example this page is drawn from.\\n  It sets `consume: true` and ships a `jobs.processor.ts`, so it spawns no worker\\n  process of its own\\n\"},{\"slug\":\"16-scheduling\",\"title\":\"Scheduling\",\"summary\":\"`@Cron`, `@Interval` and `@OnceOnBoot` run a method on a schedule.\",\"sections\":[\"Expressions\",\"Timezones\",\"Overlap\",\"The registry\",\"Timing and limits\",\"One node at a time\",\"Options\"],\"body\":\"# Scheduling\\n\\n`@Cron`, `@Interval` and `@OnceOnBoot` run a method on a schedule. They come from\\n`@dunx/infra/schedule` and are built on `Bun.cron` and Bun's timers.\\n\\n```ts\\nimport {\\n  Cron,\\n  CronExpression,\\n  Interval,\\n  OnceOnBoot,\\n  Overlap,\\n  ScheduleModule,\\n} from '@dunx/infra/schedule';\\n\\nexport class ReportsService {\\n  constructor(private readonly reports: ReportsRepository) {}\\n\\n  @Cron('0 3 * * *')\\n  async nightly(): Promise<void> {\\n    await this.reports.rebuild();\\n  }\\n\\n  @Cron(CronExpression.HOURLY)\\n  async rollUp(): Promise<void> {}\\n\\n  @Interval(30_000, { name: 'probe', overlap: Overlap.SKIP })\\n  async probe(): Promise<void> {}\\n\\n  @OnceOnBoot(5_000)\\n  warmCache(): void {}\\n}\\n\\n@Module({\\n  imports: [ScheduleModule.forRoot()],\\n  providers: [ReportsService],\\n})\\nexport class AppModule {}\\n```\\n\\nA schedule is declared in `@Module({ providers })`, or on a controller, like any\\nother injectable. It is found by its marker, so there is no second registration and\\nno class decorator to remember. An abstract base's marked methods are inherited by\\nevery subclass.\\n\\nThe registry name defaults to `ClassName.methodName`. Two schedules under one name is\\na boot error.\\n\\n## Expressions\\n\\n`@Cron` takes five fields at minute resolution. A sixth is rejected: `Bun.cron` has\\nno seconds field, and sub-minute work belongs in `@Interval`.\\n\\nBun's named schedules work too, and an editor offers them:\\n\\n```ts\\n@Cron('@daily')\\n@Cron('@hourly')\\n```\\n\\nAll seven are `@yearly`, `@annually`, `@monthly`, `@weekly`, `@daily`, `@midnight`\\nand `@hourly`. `CronExpression` holds the same seven as values, for a config object\\nthat cannot carry a literal.\\n\\nAn expression `Bun.cron` cannot parse fails the boot.\\n\\n## Timezones\\n\\nA `@Cron` takes `{ tz }`, and a zone id the IANA database does not hold is a boot\\nerror.\\n\\n**Bun 1.4 honours the option; Bun 1.3 ignores it.** A zone a runtime ignores would\\nrun at the UTC hour with no error anywhere, so dunx refuses a named zone on such a\\nruntime rather than accepting one and getting it wrong.\\n\\n```ts\\n// Works on Bun 1.4. Boot error on Bun 1.3, which would run this at 09:00 UTC.\\n@Cron('0 9 * * *', { tz: 'America/New_York' })\\n```\\n\\nDetection asks the parser for two answers and compares them, so a backport or a fork\\nis read correctly. `supportsTz()` is exported if you would rather fail your own boot\\non it.\\n\\nSchedules always run in UTC unless a zone is named, on every Bun version. Bun 1.4\\nchanged `Bun.cron`'s own default from UTC to the container's local zone; dunx passes\\n`tz` on every call, so a schedule does not move when `TZ` does.\\n\\n## Overlap\\n\\n`Overlap.SKIP` is the default. A fire that lands while a run is still going is skipped\\nand logged at `warn` with the name and how long that run has been going.\\n\\n`Overlap.CONCURRENT` starts the new run anyway.\\n\\nAn overrun that must not be dropped is a job, which is `@JobHandler` and\\n[queues](dunx://guide/15-queues). There is no queue mode here.\\n\\nA throwing handler is reported and never rethrown, so one bad run does not disarm the\\nschedule. Its message lands on the entry's `lastError`.\\n\\n## The registry\\n\\n`ScheduleRegistry` is exported, so a schedule can change without a redeploy.\\n\\n```ts\\nconst registry = app.get(ScheduleRegistry);\\n\\nawait registry.trigger('ReportsService.nightly');\\nregistry.list(); // name, kind, at, tz, runs, running, lastError, nextRunAt\\nregistry.remove('probe');\\nregistry.add(\\n  { kind: ScheduleKind.INTERVAL, at: 60_000, name: 'tenant-7' },\\n  run,\\n);\\n```\\n\\n`trigger` runs a schedule off its cadence, honouring `overlap`. It is also how a\\nschedule is tested: `Bun.cron` fires at minute resolution, so waiting for a boundary\\nis not a test.\\n\\n## Timing and limits\\n\\n`@Interval` and `@OnceOnBoot` are measured from `onInit`, the latest lifecycle hook\\nthere is, and it runs **before** `Bun.serve` binds. So `@OnceOnBoot(0)`\\nfires before the socket is open, and the delay counts from container readiness rather\\nthan from the first request.\\n\\nFor the later point, use `ScheduleModule.forRoot({ enabled: false })` and call\\n`registry.add` after `listen()`.\\n\\nA delay above 2,147,483,647 ms is a boot error. Bun clamps a larger timer to 1 ms and\\nfires it at about 17 ms, so it would be a hot loop rather than a long wait. Use\\n`@Cron` past 24 days.\\n\\n## One node at a time\\n\\nSchedules are in-process. Two replicas both run every schedule, because nothing here\\ncoordinates.\\n\\nA schedule that must fire once across a fleet is a job. bullmq's `upsertJobScheduler`\\nthrough [`@dunx/infra/queue`](dunx://guide/15-queues) is that, and dunx does not wrap it.\\n\\n## Options\\n\\n```ts\\nScheduleModule.forRoot({\\n  enabled: true, // arm at boot\\n  tz: 'UTC', // default zone for a @Cron that names none\\n  keepAlive: true, // hold the event loop open while armed\\n  overlap: Overlap.SKIP,\\n});\\n\\nScheduleModule.forRootAsync({\\n  useFactory: (config: AppConfigService) => ({ tz: config.get('tz') }),\\n  inject: [AppConfigService],\\n});\\n```\\n\\n`keepAlive: false` unrefs every handle, so a process with nothing else to do exits\\ninstead of waiting for the next fire.\\n\"},{\"slug\":\"17-authentication\",\"title\":\"Authentication\",\"summary\":\"better-auth is the authentication system.\",\"sections\":[\"Setup\",\"Mounting on `Bun.serve`\",\"`Auth`, the injection token\",\"`SessionGuard`\",\"`AuthContext`\",\"`Bun.password` hashing\",\"The two adapters\",\"Why these restate structurally\",\"No schema\",\"Related\"],\"body\":\"# Authentication\\n\\n**better-auth is the authentication system.** `@dunx/auth` is the wiring around it\\nand nothing else: no sign-in flow, no session table, no password reset, no OAuth\\ndance.\\n\\nThat is not a close call. An auth system is years of edge cases, and a half-built\\none is a liability dressed as a feature. What `@dunx/auth` contributes is the\\nmodule, the mount, a guard that reads `@dunx/http`'s existing metadata, the caller\\nin async context, and two Bun-native adapters.\\n\\n```bash\\nbun add better-auth\\n```\\n\\n`better-auth` is a **required** peer dependency, because `module.ts` imports\\n`betterAuth` as a value and `dist/index.js` cannot load without it. `drizzle-orm`\\nis optional, because only the `@dunx/auth/drizzle` subpath imports it. That is the\\nsame test every optional peer in dunx passes: a peer is optional exactly when the\\nentry point a consumer imports does not need it.\\n\\n## Setup\\n\\n```ts\\nimport { AuthModule, bunPassword } from '@dunx/auth';\\nimport { drizzleDatabase } from '@dunx/auth/drizzle';\\nimport { Module } from '@dunx/core';\\nimport { DbConnection } from '@dunx/infra/db';\\nimport { admin, bearer } from 'better-auth/plugins';\\nimport { AppConfigService } from '../config.js';\\nimport { ProfileController } from './profile.controller.js';\\n\\n@Module({\\n  imports: [\\n    AuthModule.forRootAsync(\\n      {\\n        useFactory: (config: AppConfigService, connection: DbConnection) => ({\\n          secret: config.get('auth').secret,\\n          baseURL: `http://localhost:${config.get('port')}`,\\n          basePath: '/api/auth',\\n          database: drizzleDatabase(connection),\\n          emailAndPassword: {\\n            enabled: true,\\n            minPasswordLength: 8,\\n            password: bunPassword,\\n          },\\n          plugins: [admin(), bearer()],\\n        }),\\n        inject: [AppConfigService, DbConnection] as const,\\n      },\\n      '/auth',\\n    ),\\n  ],\\n  controllers: [ProfileController],\\n})\\nexport class AccountsModule {}\\n```\\n\\nThe synchronous form is the same shape without the factory:\\n\\n```ts\\nAuthModule.forRoot({\\n  secret: process.env.BETTER_AUTH_SECRET,\\n  baseURL: 'http://localhost:3000',\\n  database: drizzleDatabase(connection),\\n  emailAndPassword: { enabled: true },\\n  plugins: [admin(), bearer()],\\n});\\n```\\n\\n`const O` on `forRoot`'s type parameter is load-bearing: it keeps the literal\\n`plugins` tuple that `betterAuth()` infers the plugin endpoints from, and\\ntherefore what `Auth<typeof options>` resolves to at an injection site.\\n\\n### What it binds\\n\\n| Token          | What it is                                                   |\\n| -------------- | ------------------------------------------------------------ |\\n| `AuthOptions`  | What `betterAuth()` was called with, and where it is mounted |\\n| `Auth`         | The better-auth instance itself                              |\\n| `AuthContext`  | The authenticated caller, per request                        |\\n| `SessionGuard` | Registered as a provider, **not** installed for you          |\\n\\nPlus one controller: a prefixed `AuthHandler` serving every better-auth endpoint\\nunder `basePath`.\\n\\n`SessionGuard` is a provider rather than global middleware because whether it\\nguards the whole app or one controller is the app's decision to make.\\n\\n### Reaching the caller from a second module\\n\\n`AuthModule` exports those four tokens **to the module that imported it**, which is\\nthe `AccountsModule` above. A second feature module that injects `AuthContext` gets\\na boot error, and calling `forRootAsync` again there would build a second\\nbetter-auth against a second session store.\\n\\nPass them on instead, the way any module re-exports what it imported:\\n\\n```ts\\n@Module({\\n  imports: [AuthModule.forRootAsync({ ... }, '/auth')],\\n  controllers: [ProfileController],\\n  exports: [Auth, AuthContext, SessionGuard],\\n})\\nexport class AccountsModule {}\\n```\\n\\nNow `imports: [AccountsModule]` reaches them. Add `global: true` to that options\\nobject when enough modules need the caller that naming the import everywhere is the\\nlarger cost.\\n\\nThe boot error names both fixes and the module that has the binding, so getting\\nthis wrong is a one-read fix rather than a hunt:\\n\\n```\\nCannot resolve Auth in module \\\"UsersModule\\\". \\\"AuthModule\\\" declares it, but\\n\\\"UsersModule\\\" does not import it. Add that module to \\\"UsersModule\\\"'s imports,\\nor give it `global: true`.\\n```\\n\\n## Mounting on `Bun.serve`\\n\\nbetter-auth's handler is a plain `(request: Request) => Promise<Response>`, so\\nmounting it is five one-line routes and nothing else:\\n\\n```ts\\n@Public()\\nexport class AuthHandler {\\n  readonly #auth = inject(Auth);\\n\\n  @Get('/*') get({ req }: Input<RouteSchemas>): Promise<Response> {\\n    /* ... */\\n  }\\n  @Post('/*') post({ req }: Input<RouteSchemas>): Promise<Response> {\\n    /* ... */\\n  }\\n  // Put, Patch, Delete too\\n}\\n```\\n\\n`Bun.serve({ routes })` matches `<basePath>/*` **natively**, verified on Bun\\n1.3.14, including that it does not match the bare `<basePath>`, which better-auth\\nhas no endpoint at. So Bun is still the router: there is no JavaScript dispatch\\ntable in front of it, and dunx does not restate, wrap or re-dispatch a single one\\nof better-auth's endpoints.\\n\\nAll five verbs are mounted because a plugin may declare any of them; better-auth's\\nown endpoints are `GET` and `POST`. The `Response` is returned untouched, which is\\nwhat keeps `Set-Cookie` headers and redirects intact.\\n\\n`AuthHandler` is `@Public()` **at class scope**. Without it, a globally installed\\n`SessionGuard` would demand a session from the sign-in endpoint, and no session\\ncould ever be created.\\n\\nThe controller `AuthModule` registers is a **subclass** created in `forRoot`,\\nrather than `@Controller(...)` on `AuthHandler` itself, because the prefix is only\\nknown once the module is configured, and mutating the shared class from a factory\\nwould make two configurations fight over one prefix.\\n\\n### `basePath` and `mountAt`\\n\\nbetter-auth resolves an endpoint by comparing the **whole pathname** to its own\\n`basePath`. Measured: `baseURL: 'http://host/api'` with `basePath: '/auth'` served\\nat `/api/auth/*` answers 404 to everything, so the path in `baseURL` is not\\nconsulted.\\n\\nThat gives you two knobs, each with one meaning:\\n\\n- **`basePath`** in the options is what better-auth matches against.\\n- **`mountAt`**, the second argument to `forRoot`/`forRootAsync`, is the **route**\\n  path in Bun's table.\\n\\nThey are the same string unless the app calls `setGlobalPrefix`. With prefix\\n`api`, the route has to be `/auth` while better-auth has to be told `/api/auth`:\\n\\n```ts\\nAuthModule.forRoot({ basePath: '/api/auth' /* ... */ }, '/auth');\\napp.setGlobalPrefix('api');\\n```\\n\\nThe common case, no prefix, uses neither.\\n\\n`mountAt` is a **synchronous** second argument on `forRootAsync` for the same\\nreason `DbModule.forRootAsync` takes its token positionally: the mount is a route\\nin Bun's table, and that table is built before any factory has run. Omitting it\\nwhile the factory returns a non-default `basePath` is a boot error, because that\\ncombination could only ever have mounted the handler where better-auth is not\\nlooking.\\n\\nA wrong **explicit** `mountAt` cannot be known at boot, since the final path is\\nonly settled once `listen()` has applied the global prefix. So `AuthHandler`\\nchecks the pathname against `basePath` on the **first** request only, and throws\\nan `AuthError` naming both.\\n\\n## `Auth`, the injection token\\n\\n`betterAuth()` returns a plain object, so there is no class to use as a token.\\n`Auth` is an abstract class whose members are **aliases of better-auth's own**,\\nnot restatements, which a real instance satisfies structurally. Same shape as\\n`Logger` and `RequestContext` in `@dunx/core`.\\n\\n```ts\\nexport class Profiles {\\n  constructor(private readonly auth: Auth) {}\\n\\n  async whoIs(headers: Headers) {\\n    return this.auth.api.getSession({ headers });\\n  }\\n}\\n```\\n\\nThe type argument is the `DbModule` trick again: the token is the erased class, so\\n`Auth<typeof authOptions>` at an injection site keeps the plugin-widened `api`\\nwhile still resolving the one binding. Written bare, `Auth` carries better-auth's\\ncore endpoints only.\\n\\nMeasured: assigning `betterAuth(opts)` to `Auth<typeof opts>` typechecks, and\\nwidening `Auth<O>` to `Auth<BetterAuthOptions>` does not, because `$context` is\\ninvariant through `PluginContext<O>`. So the module narrows the token variable\\nrather than widening the value.\\n\\n`Auth`'s constructor throws when `new.target` is `Auth` itself. Every class\\nself-binds in the container, so an unbound abstract token would otherwise resolve\\nto an object whose every member is `undefined`, and the first symptom would be\\n`auth.handler is not a function` deep inside a request.\\n\\n## `SessionGuard`\\n\\n```ts\\nexport class SessionGuard implements Middleware {\\n  async handle(\\n    req: BunRequest,\\n    ctx: RouteContext,\\n    next: Next,\\n  ): Promise<Response> {\\n    if (ctx.get(PUBLIC)) return next();\\n\\n    const principal = await this.auth.api.getSession({ headers: req.headers });\\n    if (!principal)\\n      throw new HttpError(HttpStatusCode.UNAUTHORIZED, 'UNAUTHENTICATED');\\n\\n    const required = ctx.get(ROLES);\\n    if (required?.length) {\\n      const held = rolesOf(principal.user);\\n      if (!required.some((role) => held.includes(role))) {\\n        throw new HttpError(\\n          HttpStatusCode.FORBIDDEN,\\n          `Requires one of: ${required.join(', ')}`,\\n        );\\n      }\\n    }\\n\\n    return this.context.run(principal, next);\\n  }\\n}\\n```\\n\\nTwo ways to install it, and `AuthModule` registers it either way:\\n\\n```ts\\n// Globally: everything is guarded, opt routes out with @Public()\\nHttpFactory.create(AppModule, { middleware: [SessionGuard] });\\n\\n// Scoped: leave the rest of the app open\\n@UseGuards(SessionGuard)\\nexport class ReportsController {}\\n```\\n\\n### `@Public()`\\n\\nA `@Public()` route is **skipped outright**. No session lookup, no rejection, no\\nrole check. Global installation is safe for that reason: better-auth's own\\nendpoints are `@Public()`, and a sign-in route that needed a session could never\\nbe reached.\\n\\nBest-effort session resolution on public routes was considered and dropped,\\nbecause the mounted auth endpoints are all `@Public()` and it would have put a\\nduplicate session lookup on the busiest public path in the app, `get-session`\\nincluded.\\n\\nA public route that wants to **adapt** to an optional caller injects `Auth` and\\ncalls `auth.api.getSession({ headers: req.headers })` itself. One line, and it\\ndoes not put a lookup on every public request.\\n\\n### `@Roles()`\\n\\n```ts\\n@Roles('admin')\\n@Get('/reports')\\nlist() { /* 403 unless the caller holds 'admin' */ }\\n```\\n\\n`rolesOf(user)` reads both shapes better-auth produces. The `admin` plugin stores\\nroles in a single `role` column, comma-separated for more than one; a custom\\nplugin may use an array. A user with no roles reads as `[]` rather than throwing,\\nsince an app may well not use roles at all.\\n\\n`@Public()` and `@Roles()` are `@dunx/http`'s own metadata rather than\\nauth-specific decorators. `SessionGuard` composes with what the routes already carry.\\n\\n## `AuthContext`\\n\\nHow the authenticated caller reaches a handler, and anything the handler calls,\\nhowever deep.\\n\\n```ts\\nexport class Notes {\\n  constructor(private readonly auth: AuthContext) {}\\n\\n  create(body: string): Note {\\n    const { user } = this.auth.require();\\n    return { ownerId: user.id, body };\\n  }\\n}\\n```\\n\\n- `current<O>()` returns the principal, or `undefined` on an anonymous request.\\n- `require<O>()` returns it or throws a 401. For a handler behind `SessionGuard`\\n  that is not `@Public()`.\\n- `run(principal, callback)` runs `callback` with that caller. `SessionGuard`\\n  calls this; a job or a socket handler that resolved a session itself can too.\\n\\nA `Principal` is `{ session, user }`, so the caller is one field down: `require().id`\\nis `undefined` and `require().user.id` is the id.\\n\\nThe type argument surfaces a plugin's extra user fields, on `current` and `require`\\nalike. `admin()` puts `role` on the user, which is the line a role check is built\\nfrom:\\n\\n```ts\\nconst principal = this.auth.current<typeof authOptions>();\\n\\n// Without the type argument, `role` is not on the type: `user` is better-auth's\\n// base user.\\nconst isAdmin = this.auth.require<typeof authOptions>().user.role === 'admin';\\n```\\n\\n### Why a second async store\\n\\n`AuthContext` owns its own `AsyncLocalStorage<Principal>`, separate from\\n`@dunx/core`'s `RequestContext`.\\n\\n`AsyncLocalStorage` at all, for the same reason core's `RequestContext` uses it:\\na Node built-in Bun implements natively, and the only mechanism that gets a value\\nfrom middleware to a service three constructor hops away without passing it.\\n\\nBoth alternatives were worse. Request-scoped DI was measured and rejected, and\\nhanging the principal off `req` reaches a route handler but nothing a route\\nhandler calls.\\n\\nA **second** store rather than a key in `RequestContext`, because that store is\\nthe log record. Every field in it is serialized into every line the request\\nwrites, so a session object there would be noise on each entry and a redaction\\nhazard in the ones that matter.\\n\\nWhat does go there is `userId`, a well-known `RequestFields` key, written by\\n`run()`. So the log lines are correlated without carrying the principal. See\\n[Logging](dunx://guide/13-logging).\\n\\n## `Bun.password` hashing\\n\\nbetter-auth's default hasher is a **pure-JavaScript scrypt**. `AuthModule`\\nsubstitutes native bcrypt through `Bun.password` whenever `emailAndPassword` is\\nenabled and no `password` of your own was supplied:\\n\\n```ts\\nexport const bunPassword = {\\n  hash: (password: string) =>\\n    Bun.password.hash(password, { algorithm: 'bcrypt', cost: 10 }),\\n  verify: async ({ hash, password }) => {\\n    try {\\n      return await Bun.password.verify(password, hash);\\n    } catch {\\n      return false;\\n    }\\n  },\\n};\\n```\\n\\nNaming it explicitly, as the example above does, changes nothing; it just makes\\nthe substitution visible.\\n\\nBun pre-hashes the input, so bcrypt's **72-byte cap is a non-issue** even for a\\nmaximum-length multibyte password.\\n\\n`verify` swallows Bun's `UnsupportedAlgorithm` throw, so a hash produced by a\\ndifferent algorithm - a scrypt hash written before this was in place - is a clean\\nauthentication failure rather than a 500.\\n\\n**The cost, stated plainly:** those users must reset their password to get a\\nbcrypt hash. If you are migrating an existing user table and cannot make them,\\npass your own `password` implementation instead.\\n\\n## The two adapters\\n\\n### `drizzleDatabase(connection)`\\n\\nbetter-auth's `database` option over a connection the app **already opened**:\\n\\n```ts\\nimport { drizzleDatabase } from '@dunx/auth/drizzle';\\n\\nAuthModule.forRootAsync({\\n  useFactory: (connection: DbConnection) => ({\\n    database: drizzleDatabase(connection),\\n  }),\\n  inject: [DbConnection],\\n});\\n```\\n\\nNothing here connects. The point is that the app keeps **one** pool, one SQLite\\nhandle and one shutdown path, instead of better-auth opening a second.\\n\\nThe `provider` comes from the connection's own dialect, so swapping `bun:sqlite`\\nfor `Bun.SQL` needs no edit at the call site. The schema does not have to be\\npassed either: `@dunx/infra/db` builds its handle with `drizzle({ client, schema })`\\nand the adapter reads `db._.fullSchema`, so the better-auth tables being in the\\napp's schema object is the whole requirement.\\n\\nIt lives on **its own subpath** because it imports\\n`better-auth/adapters/drizzle`, which imports `drizzle-orm`. On the main entry\\nthat would make `drizzle-orm` a hard requirement for a Prisma or MongoDB user.\\n\\n### `redisStorage(connection)`\\n\\nbetter-auth's `secondaryStorage` over `Bun.RedisClient`, so sessions, verification\\nvalues and rate-limit counters live in Redis instead of costing a database round\\ntrip on every request:\\n\\n```ts\\nimport { redisStorage } from '@dunx/auth';\\nimport { RedisConnection } from '@dunx/infra/redis';\\n\\nAuthModule.forRootAsync({\\n  useFactory: (redis: RedisConnection) => ({\\n    secondaryStorage: redisStorage(redis),\\n  }),\\n  inject: [RedisConnection],\\n});\\n```\\n\\n**All five methods are implemented, beyond the three that are mandatory.**\\nbetter-auth marks `getAndDelete` and `increment` optional because most clients\\ncannot do them atomically. `Bun.RedisClient` can, through `GETDEL` and `INCR`.\\nWithout them, better-auth falls back to read-then-delete for single-use\\ncredentials, which is a race, and to a non-atomic rate-limit counter.\\n\\n`increment`'s TTL is applied only when `INCR` returns `1`, keeping the window\\nfixed rather than sliding forever. A return of `1` signals that this call created\\nthe key.\\n\\nRedis being unreachable is **not** softened. Bun's client connects\\nlazily and queues, so a command against a down server rejects and better-auth's\\nown error path is what should see it. A swallowed `null` from `get` would read as\\n\\\"no session\\\" and sign every user out.\\n\\n## Why these restate structurally\\n\\n`drizzleDatabase` and `redisStorage` would naturally import `DbConnection` and\\n`RedisConnection` from `@dunx/infra`. Neither does. `DrizzleSource` and\\n`RedisStore` are restated as small structural interfaces:\\n\\n```ts\\nexport interface DrizzleSource {\\n  readonly dialect: 'postgres' | 'mysql' | 'mariadb' | 'sqlite';\\n  readonly db: unknown;\\n}\\n\\nexport interface RedisStore {\\n  get(key: string): Promise<string | null>;\\n  getdel(key: string): Promise<string | null>;\\n  incr(key: string): Promise<number>;\\n  expire(key: string, seconds: number): Promise<boolean>;\\n  set(\\n    key: string,\\n    value: string,\\n    options?: { readonly ex?: number },\\n  ): Promise<string | null>;\\n  del(key: string): Promise<number>;\\n}\\n```\\n\\nAn `@dunx/infra/db` connection satisfies the first with no adapter in between, and\\na `RedisConnection` satisfies the second because its parameters are wider, which\\nis the assignable direction. A bare `drizzle({ client, schema })` handle works\\ntoo, and a test double is six methods instead of a whole surface.\\n\\nTwo reasons, and the second is the concrete one.\\n\\n**The web layer boundary.** `@dunx/auth` is its own package because the guard is\\n`@dunx/http` middleware and reads `@dunx/http`'s `PUBLIC` and `ROLES` metadata\\nkeys.\\n\\n`@dunx/infra` must not depend on the web layer: it is what a CLI script, a seeder\\nor a queue worker imports, and none of those have an HTTP server. A package that\\npulled `@dunx/http` in behind `@dunx/infra/db` would put a route table in every\\none of them. The dependency runs the other way, and `@dunx/auth` depends on\\n`@dunx/infra` **not at all**.\\n\\n**A build-order race.** `@dunx/infra` as a `devDependency` of `@dunx/auth` is not\\nan edge `bun run --filter '*'` orders on, so `tsc --emitDeclarationOnly` in\\n`@dunx/auth` ran against a `packages/infra/dist` that had just been `rm -rf`'d.\\nType-only imports would not have helped, because tsc needs the `.d.ts` either\\nway. Restating **removed the edge** instead of sequencing it.\\n\\n## No schema\\n\\ndunx ships **no** schema for better-auth's tables. They are better-auth's, they\\nchange with its plugins, and its own CLI generates them:\\n\\n```bash\\nbunx @better-auth/cli generate\\n```\\n\\nA copy of them inside a framework is a copy that silently rots against the library\\nthat reads it.\\n\\nTwo things learned while building the test fixture, which apply if you create\\nthose tables by hand:\\n\\n- ``db.run(sql`...`)`` goes through `bun:sqlite`'s `prepare`, which compiles\\n  **one** statement and silently drops what follows the first semicolon. Four\\n  `CREATE TABLE`s in one template gives one table, with no error.\\n- better-auth rejects a cookie-bearing state change with no `Origin` header\\n  (`MISSING_OR_NULL_ORIGIN`), so a server-side client has to send one matching\\n  `trustedOrigins`. A browser does it for free.\\n\\n## Related\\n\\n- [Database](dunx://guide/14-database) for the connection `drizzleDatabase` reuses\\n- [Logging](dunx://guide/13-logging) for the `RequestContext` that carries `userId`\\n- [Configuration](dunx://guide/12-configuration) for `forRootAsync` and `AppConfigService`\\n- `packages/auth/README.md` for the full API surface\\n\"},{\"slug\":\"18-files-and-images\",\"title\":\"Files and images\",\"summary\":\"Two subpaths, both built on Bun primitives.\",\"sections\":[\"Storage\",\"Images\",\"Related\"],\"body\":\"# Files and images\\n\\nTwo subpaths, both built on Bun primitives. `@dunx/infra/files` is one\\nstorage contract over `Bun.file`, `Bun.write`, `Bun.Glob` and `Bun.S3Client`.\\n`@dunx/infra/images` decodes, inspects and transforms images on `Bun.Image`.\\n\\nBoth work with no extra install: no `@aws-sdk/*`, no `sharp`, no `jimp`, no\\n`image-size`, no native module to compile.\\n\\n## Storage\\n\\n```ts\\nimport { Storage } from '@dunx/infra/files';\\n\\nexport class Uploads {\\n  constructor(private readonly storage: Storage) {}\\n\\n  async save(name: string, body: ReadableStream<Uint8Array>): Promise<number> {\\n    return this.storage.write(`uploads/${name}`, body);\\n  }\\n}\\n```\\n\\n`Storage` is an abstract class, so it is both the injectable contract and the\\ntoken. Which backend gets used, disk or bucket, is decided in one `forRoot`\\ncall. The code above stays the same either way.\\n\\n### Setup\\n\\n```ts\\nimport { Module } from '@dunx/core';\\nimport { FilesModule, LocalStorageOptions } from '@dunx/infra/files';\\n\\n@Module({\\n  imports: [FilesModule.forRoot(new LocalStorageOptions('/var/lib/app/data'))],\\n  providers: [Uploads],\\n})\\nexport class StorageModule {}\\n```\\n\\nS3, or R2, or MinIO, or Spaces, is the same call with different options:\\n\\n```ts\\nimport { FilesModule, S3StorageOptions } from '@dunx/infra/files';\\n\\nFilesModule.forRoot(\\n  new S3StorageOptions(\\n    { bucket: 'invoices', region: 'eu-west-1' },\\n    'tenant-a', // optional key prefix\\n  ),\\n);\\n```\\n\\nAnything omitted from the client options falls back to the environment:\\n`S3_BUCKET` or `AWS_BUCKET`, `AWS_ACCESS_KEY_ID`, `AWS_SECRET_ACCESS_KEY`,\\n`AWS_REGION`, `AWS_ENDPOINT`. That is `Bun.S3Client`'s own resolution; this\\npackage adds none of its own.\\n\\nUse `forRootAsync` when the configuration has to be loaded or injected first.\\nCreating the storage root before `LocalStorageOptions` can name it is a real\\ncase, and that setup can be async, so the factory may await it:\\n\\n```ts\\nFilesModule.forRootAsync({\\n  useFactory: async (workspace: Workspace) =>\\n    new LocalStorageOptions(await workspace.create()),\\n  inject: [Workspace],\\n});\\n```\\n\\nBoth bind the same two tokens: `Storage`, and the `StorageOptions` that selected\\nit. The module never branches on the backend: the backend is whichever\\n`StorageOptions` subclass got configured, and `options.create()` builds it.\\nAdding a backend means writing a subclass.\\n\\n### `LocalStorageOptions`\\n\\nThe constructor is `(root: string, createPath = true)`. `root` is resolved to an\\nabsolute path, and every key is resolved against it and may not escape it.\\n`createPath` creates missing parent directories on write.\\n\\n### The contract\\n\\n```ts\\nabstract class Storage {\\n  read(key: string): Promise<string>;\\n  readBytes(key: string): Promise<Uint8Array>;\\n  readStream(key: string): Promise<ReadableStream<Uint8Array>>;\\n  write(key: string, data: WriteData): Promise<number>;\\n  exists(key: string): Promise<boolean>;\\n  delete(key: string): Promise<void>;\\n  list(options?: ListOptions): AsyncIterable<ListEntry>;\\n  stat(key: string): Promise<FileStat>;\\n  presign(key: string, options?: PresignOptions): string;\\n}\\n```\\n\\n`write` takes a `string`, `Uint8Array`, `ArrayBuffer`, `Blob` or `ReadableStream`,\\nand returns the byte count. `delete` is idempotent on both backends: removing a\\nkey that was never there is not an error. A missing key raises\\n`FileNotFoundError` whichever backend you are on.\\n\\nKeys are always relative to the storage root: the configured directory locally,\\nthe configured prefix on S3. What `write` takes is what `list` and `stat` give\\nback. Putting a bucket behind a prefix does not ripple into call sites.\\n\\n### Listing\\n\\n`list` is an `AsyncIterable`, so a bucket with a million objects is paged rather\\nthan accumulated:\\n\\n```ts\\nfor await (const entry of storage.list({ prefix: 'reports', glob: '*.csv' })) {\\n  console.log(entry.key);\\n}\\n```\\n\\nDetails:\\n\\n- **Local listings include dotfiles.** S3 has no notion of a hidden object, so\\n  neither does this.\\n- **Order is whatever the backend gives**: lexicographic on S3, filesystem order\\n  for a glob scan. Sorting would mean buffering the whole listing.\\n- **`size` and `lastModified` on a `ListEntry` are set only when the backend hands\\n  them over with the listing.** S3 does; a glob scan does not, and statting every\\n  hit would turn one listing into N syscalls. Call `stat()` when you need them.\\n- **A prefix that does not exist lists as empty** on both backends rather than\\n  raising.\\n- **`list({ glob })` on S3 costs more than it looks.** S3 has no glob, so it lists\\n  by prefix and applies the pattern to the keys that come back. The page size is\\n  therefore not capped by `limit` when a glob is in play, because capping it would\\n  truncate before the filter ran.\\n\\n### presign\\n\\nS3 signs; a local disk cannot. `LocalStorage.presign()` throws\\n`UnsupportedOperationError`, naming the key and what to do instead:\\n\\n```text\\nLocalStorage does not support presign(). Nothing signs \\\"report.pdf\\\" on a local\\ndisk. Configure S3StorageOptions, or serve the bytes through your own route.\\n```\\n\\nSigning is HMAC over the canonical request. `S3Storage.presign()` is\\n**synchronous and never touches the network**, so it returns a `string` rather\\nthan a promise:\\n\\n```ts\\nconst url = storage.presign('invoices/2026-01.pdf', {\\n  expiresIn: 900,\\n  method: 'PUT',\\n  type: 'application/pdf',\\n});\\n```\\n\\n### Streaming stays streaming\\n\\nNothing here buffers a whole file to satisfy the contract. `readStream` returns\\n`Bun.file().stream()`, or the S3 `GET` body, unread. A `ReadableStream` passed to\\n`write` is pumped chunk by chunk into a sink: a `FileSink` locally, a multipart\\n`NetworkSink` on S3. A file larger than memory transfers either way.\\n\\nThe sink exists because of two `Bun.write` behaviours, both measured on Bun\\n1.3.14:\\n\\n- **`Bun.write(path, stream)` silently writes the wrong bytes.** It matches no\\n  overload, so the stream is stringified and the file contains the 23 bytes\\n  `[object ReadableStream]`. No error, no warning.\\n- **`Bun.write(path, new Response(stream))` never settles** when the response body\\n  is itself a stream. `new Response('string')` settles normally.\\n\\nA third behaviour forces a streaming local write to do an empty `Bun.write` first:\\n**`Bun.file(path).writer()` does not truncate and does not create parent\\ndirectories.** Writing `\\\"bb\\\"` over a 20-byte file leaves\\n`bbAAAAAAAAAAAAAAAAAA`. The empty write handles truncation and directory\\ncreation, then the sink streams in over the top.\\n\\nTwo places where a call costs more than it looks:\\n\\n- **`readStream` does one `exists()` first**, so a missing key rejects the promise\\n  instead of handing back a stream that fails on the consumer's first `read()`.\\n  On S3 that is one extra `HEAD`. The `GET` has not started; the returned stream\\n  is still lazy.\\n- `Bun.file().stream()` is itself lazy, opening on the first read, which the\\n  `exists()` check compensates for.\\n\\n### Errors\\n\\n| Class                       | When                                       |\\n| --------------------------- | ------------------------------------------ |\\n| `FileNotFoundError`         | A backend-neutral ENOENT, mapped from both |\\n| `PathTraversalError`        | A key that escapes the storage root        |\\n| `UnsupportedOperationError` | `presign()` on a local disk                |\\n| `StorageError`              | The base for all three                     |\\n\\n### Path traversal is rejected rather than sanitised\\n\\nEvery key is resolved against the configured root. One that lands outside it\\nraises `PathTraversalError` **before any syscall**:\\n\\n```ts\\nawait storage.read('../../etc/passwd'); // PathTraversalError\\n```\\n\\nThat covers `../`, an absolute key, an empty key, and the root itself. None of\\nthose name a file the caller is entitled to.\\n\\nTwo checks run, and the order matters. A key is accepted or refused\\n**identically on every platform**: `..\\\\..\\\\etc` is one legal filename to POSIX\\n`resolve` but three segments to Windows, so `..` is checked as a segment on\\n**both separators** before the path is resolved at all. The boundary check then\\ncatches what segments cannot: an absolute key, or a root-relative one that\\nresolves out.\\n\\nS3 keys get the same treatment. A key is opaque to S3, so a `..` in one was meant\\nas a path, and under a configured prefix it would escape it. There it is rejected\\noutright rather than collapsed.\\n\\n**One thing this does not do.** `resolve` collapses segments textually, so a\\nsymlink **inside** the root pointing outside it is still followed. Detecting that\\nneeds `realpath`, which cannot answer for a file that does not exist yet. Do not\\nmake the root writable by anything you would not trust with its contents.\\n\\n## Images\\n\\nStorage moves bytes; the images subpath reads and transforms them.\\n\\n```ts\\nimport { Images, ImagesModule, ImageFit } from '@dunx/infra/images';\\nimport { Module } from '@dunx/core';\\n\\n@Module({ imports: [ImagesModule.forRoot({ quality: 85, maxWidth: 2048 })] })\\nexport class PicturesModule {}\\n\\nexport class Thumbnails {\\n  constructor(private readonly images: Images) {}\\n\\n  async card(upload: Blob): Promise<string> {\\n    const source = await this.images.load(upload);\\n    return source\\n      .resize(320, 320, { fit: ImageFit.INSIDE, withoutEnlargement: true })\\n      .to('webp', { quality: 78 })\\n      .toDataUrl();\\n  }\\n}\\n```\\n\\n`forRoot` also takes a function, awaited, so asynchronously loaded options need\\nnothing extra:\\n\\n```ts\\nImagesModule.forRoot(async () => ({ quality: await settings.imageQuality() }));\\n```\\n\\n`forRootAsync` is for the one thing `forRoot` cannot do: **injecting** a\\ndependency into the factory.\\n\\n```ts\\nImagesModule.forRootAsync({\\n  useFactory: (config: AppConfigService) => ({\\n    quality: config.get('images').quality,\\n    maxWidth: 1024,\\n  }),\\n  inject: [AppConfigService],\\n});\\n```\\n\\n`Images` is bound through an explicit factory rather than as a bare class, so this\\narea works with or without the `@dunx/transform` preload. You still need the\\npreload for your **own** classes to inject `Images` by constructor.\\n\\n### Configuration\\n\\n`ImagesOptions` is an `abstract class`, so it is a usable injection token; an\\n`interface` would erase and `@dunx/transform` would record the parameter as\\nunresolved. Inject it to read the effective configuration.\\n\\n| Option           | Default                   | Effect                                           |\\n| ---------------- | ------------------------- | ------------------------------------------------ |\\n| `quality`        | `80`                      | Encoder quality when a call does not override it |\\n| `maxPixels`      | `0x3fff * 0x3fff`         | Reject a source over this, before pixel alloc    |\\n| `autoOrient`     | `true`                    | Apply the JPEG EXIF `Orientation` tag first      |\\n| `allowedFormats` | every container Bun reads | Gates both decoding and encoding                 |\\n| `maxWidth`       | `undefined`               | Clamps every requested resize width              |\\n| `maxHeight`      | `undefined`               | Clamps every requested resize height             |\\n\\n`maxPixels` matches Bun's own default. It is checked after the header is parsed\\nbut **before any pixel buffer is allocated**, so a small file declaring an\\nenormous canvas is rejected cheaply.\\n\\n`maxWidth` and `maxHeight` **clamp** rather than refuse, so a request larger than\\nthe ceiling is served smaller.\\n\\n### Sources\\n\\n`load()` takes a `BunFile`, a `Blob`, an `ArrayBuffer`, a `Uint8Array`, a\\n`Buffer`, a filesystem path, or a `data:` URL, and normalises all of them to\\nbytes. A `data:` URL is resolved through `fetch`, natively, with no network\\ninvolved.\\n\\nA `Response` or a `ReadableStream` is refused with `ERR_IMAGE_UNREADABLE_SOURCE`.\\n`Bun.Image` rejects both with `ERR_INVALID_ARG_TYPE`; call `.blob()` first.\\n\\nAn `http(s)://` string is **not** fetched. `Bun.Image` treats it as a path, which\\nis an `ENOENT`.\\n\\n### Format detection is content-based\\n\\nThe container is decided by **magic bytes, never by a filename**:\\n\\n```ts\\nconst pipeline = await images.load('avatar.png');\\npipeline.format; // 'jpeg', if that is what the bytes are\\n```\\n\\n`sniffFormat(bytes)` is the same check as a free function, `images.detect(bytes)`\\nis it on the service, and `images.supports(bytes)` folds it together with the\\nconfigured `allowedFormats`.\\n\\n`ImageFormat` covers `jpeg`, `png`, `webp`, `heic`, `avif`, `bmp`, `tiff` and\\n`gif`. `EncodableFormat` is the subset Bun has an **encoder** for: `jpeg`, `png`,\\n`webp`, `heic`, `avif`. `bmp`, `tiff` and `gif` decode only.\\n\\nBoth are frozen objects plus an indexed-access union rather than enums, so one\\nname serves as the value and the type.\\n\\n### The pipeline is immutable\\n\\n```ts\\nconst source = await images.load(bytes);\\nconst thumb = source.resize(64, 64); // source is unchanged\\nconst hero = source.resize(1200); // and still 'source'\\n```\\n\\nThis is the single most important difference between `ImagePipeline` and\\n`Bun.Image` underneath it. **`Bun.Image` mutates and returns `this`**, so two\\ncallers holding one instance silently reconfigure each other's transform. An\\n`ImagePipeline` returns a new value from every operation. It can be shared and\\nforked freely, and re-runs the whole recipe from the original bytes on each\\nterminal.\\n\\n**Operations:** `resize`, `rotate`, `flip`, `flop`, `modulate`, `to`.\\n\\n**Terminals:** `encode`, `toBytes`, `toBuffer`, `toBlob`, `toBase64`, `toDataUrl`,\\n`toFile`, `placeholder`, `sourceMetadata`.\\n\\n`encode()` is the one that reports real **output** dimensions:\\n\\n```ts\\nconst { bytes, format, mimeType, width, height } = await pipeline.encode();\\n```\\n\\nTwo read-only properties are free: `pipeline.format` is the container the source\\nbytes actually are, and `pipeline.outputFormat` is what a terminal will emit.\\n\\nNothing decodes until a terminal is awaited. State is recorded as a **record**\\nrather than a list, matching the engine: `Bun.Image` chainables overwrite, so\\ncalling `.resize()` twice keeps only the second.\\n\\n### Execution order is fixed\\n\\nRegardless of the order you called them in, the pipeline runs:\\n\\n```\\nautoOrient -> rotate -> flip/flop -> resize -> modulate\\n```\\n\\nThat ordering is `Bun.Image`'s own, and dunx does not reorder it.\\n\\n### `metadata()` is not a validity check\\n\\nThis is the sharpest edge in the whole API.\\n\\n`Bun.Image.metadata()` answers from the container header and never decodes pixels,\\nso a **truncated file still reports its declared dimensions**:\\n\\n```ts\\nawait images.metadata(halfAFile); // { width: 64, height: 48, format: 'png' } - resolves!\\nawait images.verify(halfAFile); // throws ImageError ERR_IMAGE_DECODE_FAILED\\n```\\n\\nUse `metadata()` when you want the cheap header read, and `verify()` when the\\npixels have to be known-good. `verify()` runs a full decode and then reports the\\nmetadata.\\n\\n`sourceMetadata()` on a pipeline has the same property, and one more: **it ignores\\nthe chain**. `load(x).resize(32, 24).sourceMetadata()` still reports the input's\\ndimensions and the input's format. So does `placeholder()`.\\n\\n### `placeholder()`\\n\\nA ThumbHash low-quality placeholder of the **source**, as a\\n`data:image/png;base64,...` URL. Roughly 1.4 KB for a photo, at most 32px on the\\nlong edge.\\n\\n### What `Bun.Image` does that will surprise you\\n\\n`Bun.Image` is barely documented upstream. Everything here was measured on Bun\\n1.3.14 and is pinned by tests in `@dunx/infra`.\\n\\n**Silent clamping, no throw.** `resize(0)`, `resize(-5)` and `resize(1.5)` all\\nproduce a 1x1 image. `quality: 0` behaves as the minimum and `quality: 101` as\\n`100`. A bogus option **key** is ignored, but a bogus option **value** for\\n`filter` throws.\\n\\n**Decode-only formats fall back to PNG.** Bun decodes `gif` (first frame), `bmp`\\nand `tiff` but has no encoder for them. Bun's docs say a terminal with no format\\nsetter re-encodes in the source format; for those three it actually emits **PNG**,\\nand `blob().type` reports `image/png`. `ImagePipeline.outputFormat` tells you this\\nbefore you run anything.\\n\\n**`width`/`height` on a raw `Bun.Image` are `-1`** until a terminal has been\\nawaited, and then hold whatever that terminal produced. `encode()` exists so you\\nnever have to reason about that.\\n\\n**Lazy and re-runnable.** The pipeline runs on a worker thread when a terminal is\\nawaited, and awaiting a second terminal re-runs it rather than throwing. Parallel\\nterminals via `Promise.all` are safe.\\n\\n**Platform.** `Bun.Image.backend` is `'bun'` on Linux and `'system'` on\\nmacOS/Windows. On Linux, **HEIC and AVIF encoding is unavailable**, `tiff` decode\\nfails with `ERR_IMAGE_FORMAT_UNSUPPORTED`, and setting `backend = 'system'` does\\nnot change either. The clipboard statics are inert there too.\\n\\n`allowedFormats` defaults to every container Bun can identify, including HEIC and\\nAVIF: a machine with the codec can use them, and the runtime's own\\n`ERR_IMAGE_FORMAT_UNSUPPORTED` is the honest answer where it cannot. Narrow it if\\nyou want the refusal to be a policy decision instead.\\n\\n**Undocumented but present.** `Bun.file(path).image()` and `Blob.prototype.image()`\\nboth exist and return a `Bun.Image`. `linear` works as a resize filter, an alias\\nfor `bilinear`, even though it is missing from the error message listing the valid\\nnames.\\n\\n### Errors\\n\\nEverything throws `ImageError extends AppError`, carrying a `code` and the\\noriginal throw as `cause`:\\n\\n```ts\\ntry {\\n  await images.verify(upload);\\n} catch (error) {\\n  if (\\n    error instanceof ImageError &&\\n    error.code === ImageErrorCode.DECODE_FAILED\\n  ) {\\n    // truncated or corrupted payload\\n  }\\n}\\n```\\n\\nBun's own codes pass through unchanged. Two are added here:\\n`ERR_IMAGE_UNREADABLE_SOURCE` for a source that could not be read at all, and\\n`ERR_IMAGE_FORMAT_NOT_ALLOWED` for one excluded by `allowedFormats`.\\n\\n| Condition                                    | Cause         | `code`                         |\\n| -------------------------------------------- | ------------- | ------------------------------ |\\n| No container signature matched               | `Error`       | `ERR_IMAGE_UNKNOWN_FORMAT`     |\\n| Header valid, pixels truncated or corrupt    | `Error`       | `ERR_IMAGE_DECODE_FAILED`      |\\n| HEIC/AVIF/TIFF with no OS codec              | `Error`       | `ERR_IMAGE_FORMAT_UNSUPPORTED` |\\n| Over `maxPixels` (raised even by `metadata`) | `Error`       | `ERR_IMAGE_TOO_MANY_PIXELS`    |\\n| Rotation not a multiple of 90                | `TypeError`   | `ERR_INVALID_ARG_TYPE`         |\\n| Unknown resize `filter`                      | `TypeError`   | `ERR_INVALID_ARG_TYPE`         |\\n| Input is a `Response`/`ReadableStream`       | `TypeError`   | `ERR_INVALID_ARG_TYPE`         |\\n| Missing path or directory                    | syscall error | `ERR_IMAGE_UNREADABLE_SOURCE`  |\\n\\n`ERR_IMAGE_ENCODE_FAILED` and `ERR_INVALID_STATE` are declared in Bun's types but\\nwere not reachable in probing.\\n\\n## Related\\n\\n- [Configuration](dunx://guide/12-configuration) for `forRootAsync` and `AppConfigService`\\n- [Queues](dunx://guide/15-queues), since image work is the archetypal job to move off the\\n  request path\\n- `packages/infra/README.md` for the rest of `@dunx/infra`\\n\"},{\"slug\":\"19-deployment\",\"title\":\"Deployment\",\"summary\":\"A dunx app is a Bun process that calls `Bun.serve`.\",\"sections\":[\"The one thing that must survive to production\",\"Running it\",\"HTTP/2\",\"Shutting down cleanly\",\"Configuration\",\"Container image\",\"Health checks\",\"Logging\",\"Horizontal scaling\",\"Cold start\"],\"body\":\"# Deployment\\n\\nA dunx app is a Bun process that calls `Bun.serve`. There is no adapter to pick\\nand no build step that rewrites your code. Nothing has to run before the process\\nstarts except one preload line.\\n\\n## The one thing that must survive to production\\n\\n```toml\\n# bunfig.toml\\npreload = [\\\"@dunx/transform/preload\\\"]\\n```\\n\\n`@dunx/transform` records each class's constructor parameter types when the file\\nloads. Without it the container has no way to know what a constructor wants, and\\nboot fails with an error naming the class rather than constructing it with\\n`undefined` arguments. A deployment that loses `bunfig.toml` fails immediately\\nand loudly rather than at the first request.\\n\\nThree ways to supply it, all equivalent:\\n\\n| Where           | How                                                |\\n| --------------- | -------------------------------------------------- |\\n| `bun run`       | `preload` in `bunfig.toml`, next to the entrypoint |\\n| A bundled build | `Bun.build({ plugins: [depsPlugin] })`             |\\n| A test          | `Bun.plugin(depsPlugin)` from a preload file       |\\n\\n`node_modules` is skipped by the plugin: a published package was already\\ntransformed by its own build, and re-parsing dependencies on every load is pure\\ncost.\\n\\n## Running it\\n\\n```bash\\nbun src/main.ts\\n```\\n\\nThat is the whole command. `HttpFactory.create` builds the container,\\n`listen()` hands the route table to `Bun.serve`, and the server holds the\\nprocess open. There is no cluster module to configure, see the note on\\nhorizontal scaling below.\\n\\n## HTTP/2\\n\\n`http2: true` serves HTTP/2 on the same port as HTTP/1.1, through the same routes\\nand the same 404 fallback:\\n\\n```ts\\nawait HttpFactory.create(AppModule, { http2: true });\\n```\\n\\nWithout TLS that is h2c: a client opening with the HTTP/2 preface gets HTTP/2, and\\neverything else gets HTTP/1.1. That is what a reverse proxy in front of the app\\nspeaks, which is the deployment this is for. Bun marks the option experimental.\\n\\nWhat it is worth, at 64 requests in flight either way: **2.9x** the requests per\\nsecond on a small JSON body, **2.1x** on a 4 KiB POST, **1.3x** on a 64 KiB one.\\n\\nThe saving is per-request framing, so it shrinks as the body grows. Turn it on\\nfor an API serving small JSON; expect little from it if you mostly serve large\\npayloads. Server CPU per request falls by the same ratios, and the method behind\\nthat is in `docs/bun-apis.md`.\\n\\nGateways keep working, because a websocket upgrade is an HTTP/1.1 request and both\\nprotocols share the socket. There is no websocket over HTTP/2.\\n\\n### http1: false, and gateways\\n\\n`http1: false` is the pair to it and refuses HTTP/1.x with a 505. A websocket\\nupgrade **is** an HTTP/1.1 request, so a port with it set can serve HTTP/2 routes\\nor gateways and never both. Setting it with a gateway declared and no second port\\nis a boot error naming the stranded paths, because the app would otherwise start\\nhealthy and never accept a socket.\\n\\n`gatewayPort` is the way to have both. The routes keep `port` and the upgrades\\nmove to a second `Bun.serve` that takes no protocol overrides:\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule, {\\n  http2: true,\\n  http1: false,\\n  gatewayPort: 3001,\\n});\\n\\nawait app.listen(3000); // HTTP/2 only, the controllers\\napp.gatewayUrl; // http://localhost:3001, HTTP/1.1, the gateways\\n```\\n\\nBoth ports come out of **one container**, which is why this is an option rather\\nthan a second `HttpFactory.create`: a second app would build a second container,\\nand the gateways would inject different singletons than the controllers.\\n\\n`gatewayPort` works without `http1: false` too, for a deployment that wants the\\nsocket port behind a different firewall rule. An HTTP request to it answers 404.\\n\\nBun's own `fetch` cannot call an h2c origin: `protocol: 'http2'` rejects with\\n`HTTP2Unsupported` against any cleartext peer, whatever that peer serves. Leave\\n`protocol` unset for a plain-HTTP upstream.\\n\\n## Shutting down cleanly\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule);\\napp.enableShutdownHooks();\\n\\nawait app.listen(3000);\\nawait app.closed;\\n```\\n\\n`enableShutdownHooks()` installs the signal handlers. On `SIGTERM` or `SIGINT`\\nthe graph is torn down in **reverse construction order**, so a repository is\\ndisposed before the database connection it holds. `app.closed` resolves once\\nthat finishes, and anything implementing `OnShutdown` participates.\\n\\nThis matters more than it looks under an orchestrator. Kubernetes sends\\n`SIGTERM` and then waits `terminationGracePeriodSeconds` before `SIGKILL`; a\\nprocess that ignores the first signal loses whatever was in flight.\\n\\n**It then ends the process.** Draining differs from exiting: one handle that\\noutlives teardown leaves a drained, idle process alive until `SIGKILL`, and that\\nhandle is often not yours.\\n\\nThe real case is a Redis client. A `Bun.RedisClient` whose TCP connect never\\ncompleted keeps a handle past `close()`, and bullmq's Bun adapter cannot cancel\\nits own reconnect once the connection has dropped. An app that touched an\\nunreachable broker used to drain perfectly and then hang.\\n\\nBoth leaks are upstream and neither is reachable from userland. They are recorded\\nin [queue-shutdown-sigterm.md](https://github.com/petarzarkov/dunx/blob/main/internal/notes/roadmap/queue-shutdown-sigterm.md).\\n\\nOnce the drain finishes, dunx gives the process a moment to end on its own and\\nexits it if it has not. The timer is `unref()`d, so it cannot itself hold the\\nruntime open: a process with nothing pending exits immediately, and the pause is\\nonly ever spent on a process that would otherwise have hung. A forced exit always\\nlogs a line, since it means something leaked.\\n\\nYou no longer need a short `terminationGracePeriodSeconds` to work around this.\\n\\nPass `{ exitAfterMs: false }` to opt out. Pass it in **tests that fire a\\nsignal at their own process**, too, or the forced exit lands in the middle of\\nyour test run:\\n\\n```ts\\napp.enableShutdownHooks(['SIGTERM'], { exitAfterMs: false });\\n```\\n\\n## Configuration\\n\\nBun reads `.env` and `.env.local` itself, so there is no loader to configure and\\nno `dotenv` to install. In a container you will normally set real environment\\nvariables instead and ship no `.env` at all.\\n\\nValidation happens once, at boot, through the single function you gave\\n`ConfigModule.forRoot`. A missing or malformed variable fails the process before\\nit serves anything, so a bad config becomes a failed rollout rather than a\\nrunning service returning 500s. See [Configuration](dunx://guide/12-configuration).\\n\\n## Container image\\n\\n```dockerfile\\nFROM oven/bun:1.4.2-alpine\\nWORKDIR /app\\n\\n# Dependencies first, so a source change does not reinstall them.\\nCOPY package.json bun.lock ./\\nRUN bun install --frozen-lockfile --production\\n\\nCOPY . .\\nENV NODE_ENV=production\\nEXPOSE 3000\\nCMD [\\\"bun\\\", \\\"src/main.ts\\\"]\\n```\\n\\nThree details worth getting right:\\n\\n- **Pin the patch, not `1.4-alpine`.** 1.4.2 fixes a crash on musl that\\n  `Array.prototype.splice`, `shift` or a shrinking `length` on an array of objects\\n  could hit while the collector was marking.\\n- **`--frozen-lockfile`**, so a deploy can never silently resolve a different\\n  version than the one that was tested.\\n- **`bunfig.toml` must be in the image.** It is easy to miss because it is not\\n  under `src/`. If your `.dockerignore` is written as an allowlist, add it\\n  explicitly.\\n\\n`@dunx/transform` is needed at runtime under `bun run`, because the transform\\nhappens on load. It is not a devDependency. If you bundle ahead of time with\\n`Bun.build` and the plugin, it becomes build-time only and can be dropped from\\nthe image.\\n\\n## Health checks\\n\\n`HealthModule` from `@dunx/http` serves `/api/health/live` and `/api/health/ready`.\\n\\n```ts\\nHealthModule.forRootAsync({\\n  useFactory: (db: DbConnection, redis: RedisConnection) => ({\\n    readiness: [\\n      new DatabaseIndicator(db),\\n      new RedisIndicator(redis, { critical: false }),\\n    ],\\n    drainDelayMs: 15_000,\\n  }),\\n  inject: [DbConnection, RedisConnection],\\n});\\n```\\n\\nDo not hand-roll a controller for this. The part worth having is the drain, and a\\nplain controller cannot express it. Two settings decide whether a rollout drops\\nrequests; the full mechanics, including how to write your own indicator, are in\\n[Health checks](dunx://guide/20-health-checks).\\n\\n**`critical`** separates readiness from liveness. A `critical: false` indicator\\nreports `degraded` without failing the probe, so an absent Redis degrades a route\\nrather than restarting the process. Be sparing with `critical: true`: it should\\nname only what makes the process useless, which in most services is the database\\nalone. A liveness probe that checks Redis will restart a healthy process on a\\ncache blip.\\n\\n**`drainDelayMs`** holds readiness failing before the port closes.\\n`Readiness` implements `OnBeforeShutdown`, which runs while the server is still\\naccepting, so the probe can answer \\\"not ready\\\" on an open socket for as long as\\nthe load balancer needs to notice. An `onShutdown` hook runs after the server has\\nstopped, so a probe answering from there answers on a closed socket already.\\n\\nLiveness keeps passing throughout: a pod that is shutting down does not need\\nkilling.\\n\\nSet `drainDelayMs` to at least your ingress's deregistration interval. The probes\\nare hidden from the OpenAPI document, so they will not appear in a generated\\nclient.\\n\\n## Logging\\n\\nRequest logging is on by default and writes one structured line per request,\\ncarrying the request and the response together: stdout, one JSON object per line,\\ncollected by whatever runs the container.\\n\\n`ConsoleLogger` batches `info` and below into a single write per event-loop turn.\\n`warn`, `error` and `fatal` are never buffered and flush everything queued ahead\\nof them, so ordering holds and the entries you go looking for after a crash were\\nnever held back.\\n\\nA buffered `info` line can be lost if the process dies without unwinding, under a\\n`SIGKILL` or an OOM kill. If you need every line, construct the logger with\\nbuffering off:\\n\\n```ts\\nprovide(Logger, { useValue: new ConsoleLogger(context, LogLevel.INFO, false) });\\n```\\n\\nFor redaction, rotation and file transports, bind `LoggerModule` from\\n`@dunx/infra/logger`. See [Logging](dunx://guide/13-logging).\\n\\n## Horizontal scaling\\n\\nNothing in dunx holds cross-request state, so running N processes behind a load\\nbalancer works with no changes. Two things need attention when you do:\\n\\n- **WebSocket fan-out is per process.** `socket.subscribe(topic)` joins a topic\\n  in the Bun runtime of that process only, so a publish reaches the clients\\n  connected to that instance. Attach the Redis relay to fan out across nodes,\\n  see [WebSockets](dunx://guide/09-websockets).\\n- **Queue workers are separate processes.** `QueueModule.forRoot` binds the\\n  publish side alone, so a web process that publishes never accidentally starts\\n  consuming. Run workers with their own entrypoint and `WorkerFactory`.\\n\\n## Cold start\\n\\nRoughly twice raw `Bun.serve`, from the `oxc-parser` preload and eager dependency\\nresolution. It beats every Node framework measured here by a wide margin, but if\\nyou are deploying somewhere that pays cold start per request, it is the number to\\nwatch. The current figures are on the\\n[benchmarks page](https://dunx.win/benchmarks), regenerated\\nfrom a real run rather than written down.\\n\\nEager resolution is a trade: every provider is constructed at boot, so a missing\\nbinding or a bad config is a failed start rather than a 500 on the first request\\nthat happens to need it.\\n\"},{\"slug\":\"20-health-checks\",\"title\":\"Health checks\",\"summary\":\"`HealthModule` mounts two routes and gives an orchestrator something to read.\",\"sections\":[\"The report\",\"Three states\",\"Critical and not\",\"Draining\",\"Taking a pod out by hand\",\"Your own indicators\",\"No startup probe\",\"Options\"],\"body\":\"# Health checks\\n\\n`HealthModule` mounts two routes and gives an orchestrator something to read.\\n\\n```ts\\nimport {\\n  DatabaseIndicator,\\n  HealthModule,\\n  MemoryIndicator,\\n  MemoryOptions,\\n  RedisIndicator,\\n} from '@dunx/http';\\n\\n@Module({\\n  imports: [\\n    HealthModule.forRootAsync({\\n      useFactory: (db: DbConnection, redis: RedisConnection) => ({\\n        readiness: [new DatabaseIndicator(db), new RedisIndicator(redis)],\\n        liveness: [\\n          new MemoryIndicator(\\n            new MemoryOptions({ maxRssBytes: 512 * 1024 ** 2 }),\\n          ),\\n        ],\\n        drainDelayMs: 15_000,\\n      }),\\n      inject: [DbConnection, RedisConnection],\\n    }),\\n  ],\\n})\\nexport class AppModule {}\\n```\\n\\n`GET /health/live` answers \\\"is this process working\\\". `GET /health/ready` answers\\n\\\"should it receive traffic\\\". `up` is `200` and anything else is `503`.\\n\\nBoth are `@Public()`: a probe carries no credentials.\\n\\nBoth are documented, under a `Health` tag, with the report shape as\\n`components/schemas/HealthReport` on both the 200 and the 503. `documented: false`\\nmounts a variant carrying `@ApiHidden()`, which serves the same two routes and\\nleaves them out of the OpenAPI document.\\n\\n`HEALTH_REPORT_SCHEMA` is exported, so an app answering on its own paths can\\nreference the same definition.\\n\\n## The report\\n\\n```json\\n{\\n  \\\"status\\\": \\\"up\\\",\\n  \\\"draining\\\": false,\\n  \\\"uptimeMs\\\": 41233,\\n  \\\"checks\\\": [{ \\\"name\\\": \\\"database\\\", \\\"state\\\": \\\"up\\\", \\\"critical\\\": true, \\\"ms\\\": 1 }]\\n}\\n```\\n\\nOne list, so finding the unhappy check is one place to look.\\n\\nChecks run concurrently, each bounded by `timeoutMs` (default 2000), so the report\\ncosts the slowest check rather than their sum.\\n\\n## Three states\\n\\nA check that throws is `down`, carrying its message. A check that outruns its\\nbudget is `unknown`.\\n\\nThe difference matters. A probe that did not answer has told you nothing, which\\nis not the same as telling you it is broken.\\n\\n`unknown` on a critical check fails readiness. On a non-critical one it does not.\\n\\n## Critical and not\\n\\n`critical` defaults to `true`. A failure sheds traffic.\\n\\n`MemoryIndicator` and `DiskIndicator` ship as `critical: false`. A disk at 91\\npercent is worth seeing on the page. Pulling the pod out of rotation does not\\nmake it emptier, since no other pod's disk is either.\\n\\nA memory ceiling belongs on `liveness`, where the orchestrator restarts the\\nprocess rather than routing around it.\\n\\n## Draining\\n\\nReadiness starts failing **before** the port closes.\\n\\n`Readiness` implements [`OnBeforeShutdown`](dunx://guide/07-lifecycle), which runs while\\nthe server is still accepting, so the probe can answer \\\"not ready\\\" while the\\nload balancer can still reach it. Every `onShutdown` hook runs after the server\\nhas stopped, so a probe answering from there answers on a socket that is already\\nclosed.\\n\\n`drainDelayMs` keeps readiness failing for that long before the socket closes. A\\nload balancer notices a failing probe on its own schedule: at a 2-second interval\\nand a 3-failure threshold, traffic can arrive for 6 seconds after the pod has\\ndecided to go. Set it to a few intervals.\\n\\nLiveness keeps passing throughout. A pod that is shutting down does not need\\nrestarting, and `down` there invites a SIGKILL mid-drain.\\n\\n## Taking a pod out by hand\\n\\nA drain does not always start with a signal. A migration needs the same\\n\\\"stop sending me traffic\\\" behaviour on demand, and `Readiness` is injectable so\\na handler can trigger it directly.\\n\\n```ts\\nexport class MaintenanceController {\\n  readonly #readiness = inject(Readiness);\\n\\n  @Post('/pause')\\n  pause(): void {\\n    this.#readiness.hold('migrating');\\n  }\\n\\n  @Post('/resume')\\n  resume(): void {\\n    this.#readiness.release();\\n  }\\n}\\n```\\n\\n`release()` does not undo a shutdown.\\n\\n## Your own indicators\\n\\nSubclass `HealthIndicator`, or hand `HealthOptions` any object with the three\\nmembers.\\n\\n```ts\\nimport { HealthIndicator, type ProbeResult } from '@dunx/http';\\n\\nexport class BrokerIndicator extends HealthIndicator {\\n  readonly name = 'broker';\\n\\n  async check(): Promise<ProbeResult> {\\n    const started = performance.now();\\n    await this.broker.ping();\\n    return {\\n      state: 'up',\\n      detail: `${Math.round(performance.now() - started)} ms`,\\n    };\\n  }\\n}\\n```\\n\\nThrowing is how a check reports `down`. The registry never lets one throw into a\\nresponse.\\n\\n`DatabaseIndicator` needs a connection with `ping()`, which `DbConnection` from\\n`@dunx/infra/db` has. A custom connection must implement `ping()` too: the base\\nthrows a message naming what is missing, rather than reporting a database\\nhealthy without having asked it anything.\\n\\n## No startup probe\\n\\nThe port already answers that question. `create()` finishes every `onInit`\\nbefore `listen()` binds, so a refused connection means \\\"not started yet\\\".\\n\\n## Options\\n\\n```ts\\nHealthModule.forRoot({\\n  liveness: [],\\n  readiness: [],\\n  timeoutMs: 2000,\\n  drainDelayMs: 0,\\n  routes: true,\\n  documented: true,\\n});\\n```\\n\\n`routes: false` binds `HealthRegistry` and `Readiness` and mounts nothing, for an\\napp that answers on its own paths.\\n\\n`documented: false` mounts the routes and hides them from `@dunx/openapi`.\\n\"},{\"slug\":\"21-agent-tooling\",\"title\":\"Agent tooling\",\"summary\":\"An agent working in a dunx application spends most of its budget rediscovering things the framework already knows: which routes exist, what validates a body, which module bound a provider, why boot...\",\"sections\":[\"Wiring it into a client\",\"The tools\",\"Resources\",\"Starting a project with an agent\",\"It reads the app. It never boots it.\",\"What to ask it\"],\"body\":\"# Agent tooling\\n\\nAn agent working in a dunx application spends most of its budget rediscovering\\nthings the framework already knows: which routes exist, what validates a body, which\\nmodule bound a provider, why boot fails. `@dunx/mcp` answers those over the\\n[Model Context Protocol](https://modelcontextprotocol.io) so the agent can ask\\ninstead of grepping.\\n\\nIt answers before the app exists too. Three of its tools carry the written guide,\\nthe smallest working app, and the feature catalogue inside the package, so an agent\\nthat has been asked to adopt dunx has something to read.\\n\\n```bash\\nbunx @dunx/mcp                        # the guide, the starter, the catalogue\\nbunx @dunx/mcp ./src/app.module.ts    # those, plus the readers for your app\\n```\\n\\n## Wiring it into a client\\n\\n```json\\n{\\n  \\\"mcpServers\\\": {\\n    \\\"dunx\\\": {\\n      \\\"command\\\": \\\"bunx\\\",\\n      \\\"args\\\": [\\\"@dunx/mcp\\\", \\\"./src/app.module.ts\\\"]\\n    }\\n  }\\n}\\n```\\n\\nThe entry is optional. Without one the server starts with the three tools that\\nneed no app, which is the state a project has before dunx is installed in it.\\n\\nPoint it at the file that declares your root module once there is one. No naming\\nconvention applies: `@Module` leaves a marker, so a module exported only by name is\\nfound on its own. `bunx @dunx/create-app` scaffolds a module exported exactly this\\nway.\\n\\n`default` and `root` win if present. `--export=<name>` settles a file that\\ndeclares several. The path is resolved with `Bun.resolveSync`, so anything\\n`import` accepts works: a relative path with or without `./`, an absolute one, an\\nextensionless specifier, or a package name.\\n\\n## The tools\\n\\nThree need no app:\\n\\n| Tool            | Answers                                                                             |\\n| --------------- | ----------------------------------------------------------------------------------- |\\n| `dunx_start`    | The runtime, the two ways to get an app, and the rules that are boot errors         |\\n| `dunx_guide`    | The written guide: the index, one chapter in full, or a search across every chapter |\\n| `dunx_scaffold` | Every feature `bunx @dunx/create-app` generates, and the source of the smallest app |\\n\\nSix read the app, and are served once an entry is given:\\n\\n| Tool             | Answers                                                                                                         |\\n| ---------------- | --------------------------------------------------------------------------------------------------------------- |\\n| `dunx_overview`  | Counts, plus every constructor dependency whose type was erased. The cheapest first call                        |\\n| `dunx_routes`    | Every route: controller, handler, module, guards, `@Public()`/`@Roles()`, status, and which inputs it validates |\\n| `dunx_providers` | Every registration - controllers, gateways, `useClass`, `useValue`, `useFactory` - with its dependencies        |\\n| `dunx_gateways`  | Every websocket gateway, its path, and the handler each `@OnMessage` event lands on                             |\\n| `dunx_modules`   | The module graph in traversal order, and what each module contributes                                           |\\n| `dunx_openapi`   | The OpenAPI 3.1 document, with the real request and response JSON Schemas                                       |\\n\\nEvery tool takes optional filters and nothing else, so a caller that knows nothing\\nstill gets a useful first answer:\\n\\n```jsonc\\n{ \\\"name\\\": \\\"dunx_routes\\\", \\\"arguments\\\": { \\\"method\\\": \\\"POST\\\", \\\"path\\\": \\\"/users\\\" } }\\n{ \\\"name\\\": \\\"dunx_providers\\\", \\\"arguments\\\": { \\\"unresolvedOnly\\\": true } }\\n```\\n\\nThe filters exist because a large app's full route table is a lot of tokens to hand a\\nmodel that asked about one path. Omitting them means everything.\\n\\n### Start with dunx_start, then the overview\\n\\n`dunx_start` is the call worth making before writing any dunx. It costs about 4 KB\\nand carries the runtime, the scaffold command, the two install commands and the\\n`bunfig.toml` that add dunx to a project that already exists, an index of the guide,\\nand the rules that fail at boot rather than at review:\\n\\n```json\\n{\\n  \\\"rule\\\": \\\"Constructor injection needs the preload.\\\",\\n  \\\"detail\\\": \\\"Add `preload = [\\\\\\\"@dunx/transform/preload\\\\\\\"]` to bunfig.toml, and again under `[test]`.\\\"\\n}\\n```\\n\\n`dunx_guide` then answers the chapter-level questions. With no arguments it returns\\nthe index; `search` returns matching lines with the chapter and line number of each,\\ncapped at five per chapter so a common word still reaches the chapter that answers\\nit, and reports how many it left out; `topic` returns one chapter in full.\\n\\n`search` matches literal text, so a question written as a sentence matches no line\\nanywhere. Every result also carries `suggested`, the chapters the query's own words\\npoint at, scored highest on a title and lowest on a body mention:\\n\\n```json\\n{\\n  \\\"query\\\": \\\"how do I validate a request body\\\",\\n  \\\"hits\\\": [],\\n  \\\"omitted\\\": 0,\\n  \\\"suggested\\\": [\\\"06-validation\\\", \\\"08-middleware-and-guards\\\", \\\"05-controllers\\\"]\\n}\\n```\\n\\n`dunx_overview` is the call worth making first once there is an app. It says how big the app is and\\nwhether it would boot, without returning the graph:\\n\\n```json\\n{\\n  \\\"modules\\\": 23,\\n  \\\"controllers\\\": 12,\\n  \\\"gateways\\\": 1,\\n  \\\"providers\\\": 53,\\n  \\\"routes\\\": 40,\\n  \\\"publicRoutes\\\": 8,\\n  \\\"guardedRoutes\\\": 7,\\n  \\\"unresolvedDependencies\\\": []\\n}\\n```\\n\\n`unresolvedDependencies` is listed rather than counted: each entry is a boot\\nerror naming a parameter. A constructor parameter whose type was erased - an\\ninterface, a primitive, a union, a type-only import - is recorded by\\n`@dunx/transform` as `unresolved`. That is the same wart `emitDecoratorMetadata`\\nhas; dunx's transform does not carry it. The `typeOnly` case gets its own field\\nbecause it has a one-line fix:\\n\\n```json\\n{\\n  \\\"provider\\\": \\\"ReportsService\\\",\\n  \\\"module\\\": \\\"ReportsModule\\\",\\n  \\\"unresolved\\\": \\\"private readonly config: AppConfig\\\",\\n  \\\"typeOnly\\\": \\\"AppConfig\\\"\\n}\\n```\\n\\nDrop the `type` from that import and it resolves.\\n\\n### Which inputs, or which schemas\\n\\n`dunx_routes` reports **that** a route validates its body, and by which Standard\\nSchema vendor. It does not report the schema:\\n\\n```json\\n{\\n  \\\"method\\\": \\\"POST\\\",\\n  \\\"path\\\": \\\"/api/users\\\",\\n  \\\"controller\\\": \\\"UsersController\\\",\\n  \\\"handler\\\": \\\"create\\\",\\n  \\\"module\\\": \\\"UsersModule\\\",\\n  \\\"public\\\": false,\\n  \\\"roles\\\": [\\\"admin\\\"],\\n  \\\"guards\\\": [\\\"SessionGuard\\\"],\\n  \\\"hidden\\\": false,\\n  \\\"validates\\\": { \\\"body\\\": \\\"zod\\\" },\\n  \\\"status\\\": 201,\\n  \\\"responses\\\": [201, 422]\\n}\\n```\\n\\nTurning a schema into JSON Schema is zod-specific work; `@dunx/openapi` already\\ndoes it properly, so `dunx_openapi` is where it lives. That split keeps the other\\neight tools working in an app with no OpenAPI setup at all. `@dunx/openapi` is an\\noptional peer, loaded only when `dunx_openapi` is called.\\n\\n## Resources\\n\\nThe guide chapters are served as MCP resources as well, at `dunx://guide/<slug>`,\\nfor a client that attaches documents rather than calling tools. A chapter link\\ninside one points at the same scheme; a link to anything else in the repository\\nbecomes absolute.\\n\\n## Starting a project with an agent\\n\\nAn agent with the server wired up already has all of this: `dunx_start` for the\\nrules, `dunx_scaffold` for the features and the starter files, `dunx_guide` for\\neverything written. Two files are served over HTTP for an agent that does not:\\n\\n| URL                         | Holds                                                                   |\\n| --------------------------- | ----------------------------------------------------------------------- |\\n| <https://dunx.win/setup.md> | Install, wire and verify an app, plus the rules dunx fails at boot over |\\n| <https://dunx.win/llms.txt> | Every dunx document, linked as raw markdown                             |\\n\\nHand the first one to an agent as an instruction: \\\"set up my project using\\n<https://dunx.win/setup.md>\\\". It is the same content the\\nrepository's guards check, copied to that URL by each build, so it states the\\nversion being served.\\n\\n`bunx @dunx/create-app my-api --yes` writes an `AGENTS.md` and a `CLAUDE.md` into\\nthe app: its layout, its commands, the features it carries and the services those\\nwant running.\\n\\nAn agent driving a terminal should **pass `--yes`**, since a bare run opens a\\nfeature list and waits for an arrow key. To pick features from a script, call\\n`scaffold({ target, features })` from `@dunx/create-app`. With no terminal at all\\nit writes the minimal template rather than blocking.\\n\\n## It reads the app. It never boots it.\\n\\n`AppFactory.create()` instantiates every declared binding and awaits every async\\nfactory before it returns. Booting an app to answer \\\"what\\nroutes exist\\\" would open database connections, start queue workers, bind sockets\\nand run every `onInit`. An agent asking a question about the code would end up\\nrunning the code against whatever environment happened to be configured.\\n\\nReading costs none of that. `discoverRoutes` and `discoverGateway` each walk a\\nprototype chain, and `Object.create(Controller.prototype)` is that chain with\\nnothing behind it: `instance.constructor` still resolves to the class, every\\nmethod stays reachable, and no constructor has to exist.\\n\\nThe container graph comes from the same functions the container reads it with:\\n`collectModules`, `readControllers`, `readDeps` and `describeToken`.\\n\\n**What that rules out is runtime state.** The value of a config field, or whether the\\ndatabase is reachable, is not answerable here. If one of those is ever genuinely\\nneeded it belongs in a separately named tool whose description says it boots the app,\\nso the cost is visible at the call site rather than hidden inside every answer.\\n\\n## What to ask it\\n\\nThe questions it answers better than a search:\\n\\n- **\\\"What is the unauthenticated surface?\\\"** `dunx_routes` with `publicOnly`, which\\n  is `@Public()` resolved through class-level and method-level metadata rather than\\n  grepped for.\\n- **\\\"Why does boot fail?\\\"** `dunx_providers` with `unresolvedOnly`, giving the\\n  registrations that would throw, with the parameter named.\\n- **\\\"Who binds this token?\\\"** `dunx_providers` with `token`, which reports the module\\n  and the binding kind - a `useFactory` and a bare class look nothing alike in source\\n  and identical here.\\n- **\\\"Which event does this websocket message land on?\\\"** `dunx_gateways`, since\\n  `@OnMessage('say')` is a marker on a method and nothing in the path tells you.\\n\\nAnd the one it cannot answer: **\\\"is Redis up?\\\"** That needs the app running, and\\nthis never runs it.\\n\"},{\"slug\":\"22-metrics\",\"title\":\"Metrics\",\"summary\":\"Counts and timings for requests and database queries, as JSON.\",\"sections\":[\"Turning it on\",\"Reading requests\",\"Reading queries\",\"On the dashboard\",\"What it costs\",\"Feeding Prometheus\",\"Process and event-loop readers\",\"Resetting\"],\"body\":\"# Metrics\\n\\nCounts and timings for requests and database queries, as JSON. There is no\\nPrometheus endpoint and no metrics dependency. dunx supplies the numbers Bun can\\nmeasure; exposition belongs to whatever already scrapes your service.\\n\\n## Turning it on\\n\\nTwo flags, independent of each other:\\n\\n```ts\\nconst app = await HttpFactory.create(AppModule, { metrics: true });\\n```\\n\\n```ts\\nDbModule.forRoot(new SqliteOptions({ schema, filename }), { metrics: true });\\n```\\n\\nBoth default to `false`. With `metrics: false` no driver is wrapped and no\\nhistogram is allocated.\\n\\n## Reading requests\\n\\n`RequestMetrics` is bound app-wide by `HttpFactory`, so any provider can inject it:\\n\\n```ts\\nexport class OpsService {\\n  constructor(private readonly metrics: RequestMetrics) {}\\n\\n  report(): HttpStatsReport {\\n    return this.metrics.snapshot();\\n  }\\n}\\n```\\n\\n```json\\n{\\n  \\\"routes\\\": [\\n    {\\n      \\\"route\\\": \\\"/users/:id\\\",\\n      \\\"method\\\": \\\"GET\\\",\\n      \\\"count\\\": 1841,\\n      \\\"byStatus\\\": { \\\"200\\\": 1802, \\\"404\\\": 39 },\\n      \\\"duration\\\": {\\n        \\\"count\\\": 1841,\\n        \\\"min\\\": 210000,\\n        \\\"max\\\": 48100000,\\n        \\\"p50\\\": 940000,\\n        \\\"p90\\\": 2100000,\\n        \\\"p95\\\": 3400000,\\n        \\\"p99\\\": 12800000,\\n        \\\"p999\\\": 47900000\\n      },\\n      \\\"slowestTraceId\\\": \\\"4bf92f3577b34da6a3ce929d0e0e4736\\\"\\n    }\\n  ],\\n  \\\"inFlight\\\": 3,\\n  \\\"pendingWebSockets\\\": 12,\\n  \\\"since\\\": \\\"2026-09-02T09:14:22.881Z\\\"\\n}\\n```\\n\\nDurations are **nanoseconds**. `inFlight` and `pendingWebSockets` are read off the\\nlive `Bun.serve` server at 14.7 ns rather than counted.\\n\\n### One series per route pattern\\n\\n`/users/1` and `/users/2` land on the one `/users/:id` series. The key is the\\nroute context dunx freezes when it builds the table, so there is no normalisation\\nstep and the series count is bounded by the handler count.\\n\\nEvery path that matched nothing collapses into a single `(unmatched)` series per\\nmethod. A 404's log line still names the concrete path it missed.\\n\\nAn `ignore`d or `ignorePrefix`ed path **is** counted. That option is about log\\nvolume, and a health check polled every second is the clearest case of something\\nworth a metric and not worth an entry.\\n\\n### `slowestTraceId`\\n\\nThe trace of the slowest request seen on that route. Every line that request\\nwrote carries the same `traceId`, so one search finds the logs behind the p99.\\n\\nIt is absent when `requestLogging: { trace: false }` turned tracing off.\\n\\n## Reading queries\\n\\n`QueryMetrics` is exported by `DbModule` when `metrics: true`:\\n\\n```json\\n{\\n  \\\"operations\\\": [\\n    {\\n      \\\"operation\\\": \\\"select\\\",\\n      \\\"count\\\": 4210,\\n      \\\"errors\\\": 0,\\n      \\\"duration\\\": { \\\"count\\\": 4210, \\\"min\\\": 8000, \\\"p99\\\": 1400000 },\\n      \\\"slowest\\\": \\\"select \\\\\\\"id\\\\\\\", \\\\\\\"name\\\\\\\" from \\\\\\\"users\\\\\\\" where \\\\\\\"users\\\\\\\".\\\\\\\"id\\\\\\\" = $1\\\"\\n    }\\n  ],\\n  \\\"total\\\": 4380,\\n  \\\"since\\\": \\\"2026-09-02T09:14:22.881Z\\\"\\n}\\n```\\n\\nQueries are grouped by leading keyword: `select`, `insert`, `update`, `delete`,\\n`other`. A statement starting with `with` is `other`, since a CTE can end in any of\\nthe four.\\n\\nTiming happens at the driver dunx constructs. Drizzle's `logger` option cannot\\nsupply it: `logQuery` fires immediately before a statement runs and has no\\ncompletion callback.\\n\\nFor `bun:sqlite` the prepared statement's execute methods are wrapped, which is\\nexact because they are synchronous. For `Bun.SQL` the lazy `Query`'s `then` is\\nwrapped, so the measurement covers execution without starting it early.\\n\\n`errors` counts statements that threw or whose promise rejected. They stay in\\n`count` as well.\\n\\n### `slowest` is a shape, not a query\\n\\nLiterals are replaced before the text is stored: `where email = 'ada@example.com'`\\nis kept as `where email = '?'`. The snapshot is served over the dashboard's stats\\nendpoint, so anything retained is readable by whoever can reach that page.\\n\\ndrizzle parameterises, so a query it built carries no values anyway. The redaction\\nis for the `sql` template escape hatch and hand-written statements. Redaction runs\\nbefore truncation, so a long literal cannot survive by being cut off mid-string.\\n\\n## On the dashboard\\n\\nPass either source to `DashboardModule` and the Stats panel renders it:\\n\\n```ts\\nDashboardModule.forRootAsync({\\n  imports: [DatabaseModule],\\n  useFactory: (stats: RequestMetrics, dbStats: QueryMetrics) => ({\\n    path: '/api/_dunx',\\n    authorize,\\n    stats,\\n    dbStats,\\n  }),\\n  inject: [RequestMetrics, QueryMetrics] as const,\\n});\\n```\\n\\nThe JSON sibling is `GET {path}/api/stats`, behind the same `authorize` as every\\nother panel. An unauthenticated endpoint listing every route and its error rate is\\nreconnaissance, so there is no public `/metrics`.\\n\\nThe Stats panel is visible at\\n[demo.dunx.win/api/dashboard](https://demo.dunx.win/api/dashboard), a demo that\\nmounts the page with no `authorize` and a read-only board.\\n\\n## What it costs\\n\\n**+35.2 ns per request** in the shipped configuration. `RequestLoggingMiddleware`\\nalready allocates a `.then` and already holds the start mark, so the observation\\nfolds into both. Against the 5.38 µs request logging costs over\\n`requestLogging: false`, that is 0.65%.\\n\\nWith `requestLogging: false`, a `MetricsMiddleware` is installed instead and pays\\nfor its own `.then`: **+175.9 ns**.\\n\\nMemory is about 16 KiB per route series: ~390 KiB at 24 routes, ~3.2 MiB at 200.\\n\\nReading is a poll-time cost, not a request-time one. `snapshot()` over 24 routes\\nand five statuses each is 261.5 µs, of which 182.2 µs is the 96 percentile reads.\\n\\n## Feeding Prometheus\\n\\ndunx writes no Prometheus text. Its histogram is\\n`node:perf_hooks.createHistogram`, compiled into Bun, recording at 11.1 ns.\\n`prom-client`'s observes at 655.9 ns and owns exposition, including bucket\\nordering, `+Inf`, label quoting and content-type negotiation.\\n\\nPump the snapshot into your own registry:\\n\\n```ts\\nimport { Gauge, Registry } from 'prom-client';\\n\\nconst registry = new Registry();\\nconst p99 = new Gauge({\\n  name: 'http_server_request_duration_p99_seconds',\\n  help: 'p99 request duration',\\n  labelNames: ['http_route', 'http_request_method'],\\n  registers: [registry],\\n});\\n\\n@Controller('metrics')\\nexport class MetricsController {\\n  constructor(private readonly metrics: RequestMetrics) {}\\n\\n  @Get('/')\\n  async scrape(): Promise<Response> {\\n    for (const route of this.metrics.snapshot().routes) {\\n      p99.set(\\n        { http_route: route.route, http_request_method: route.method },\\n        (route.duration.p99 ?? 0) / 1e9,\\n      );\\n    }\\n    return new Response(await registry.metrics(), {\\n      headers: { 'content-type': registry.contentType },\\n    });\\n  }\\n}\\n```\\n\\nThe label names above are OpenTelemetry's semantic conventions, which dunx follows\\nfor naming and does not depend on.\\n\\n## Process and event-loop readers\\n\\n`@dunx/core` exports the same primitives the request half is built on, for\\nanything else worth counting.\\n\\n```ts\\nimport {\\n  Counter,\\n  Durations,\\n  EventLoopLag,\\n  Gauge,\\n  RuntimeStats,\\n} from '@dunx/core';\\n```\\n\\n`RuntimeStats.snapshot()` returns pid, uptime, memory, CPU and resource usage in\\none object, at about 14 µs. `uptimeMs` counts from construction rather than from\\n`process.uptime()`, which counts from interpreter start.\\n\\n`Durations` is a recording histogram with the native one's four sharp edges closed:\\nan observation below 1 ns clamps instead of throwing, and an empty histogram\\nreports `{ count: 0 }` instead of a `min` of 9223372036854776000 and a `mean` of\\n`NaN`.\\n\\n`EventLoopLag` wraps `monitorEventLoopDelay` and enables it in `onInit`. A block\\nin the same event-loop turn as `enable()` is not sampled, so a monitor first\\nenabled by a scrape reports 1.6-7.9 ms for a 300 ms stall.\\n\\n```ts\\n@Module({ providers: [EventLoopLag] })\\nexport class OpsModule {}\\n```\\n\\nThere is no garbage-collection metric. `PerformanceObserver.supportedEntryTypes`\\nis `[\\\"mark\\\", \\\"measure\\\", \\\"resource\\\"]` under Bun, and a `gc` observer never fires.\\n\\n## Resetting\\n\\n`reset()` on either class drops every series and moves `since` forward. Nothing\\ncalls it for you. A cumulative histogram is what `rate()` in a scraper wants, and\\nresetting on scrape would break the consumer most likely to be reading.\\n\"},{\"slug\":\"23-upgrading\",\"title\":\"Upgrading\",\"summary\":\"What changed, and the line that replaces each thing.\",\"sections\":[\"An unmatched path answers 404\",\"HTTP settings can come from validated config\",\"A named outbound client can be a class\",\"A named Redis connection can be a class\",\"The websocket relay can be a provider\",\"Config takes a schema directly\",\"An OpenAPI contribution can be a provider\",\"A constraint violation answers 409\",\"Four more `fetch` options\"],\"body\":\"# Upgrading\\n\\nWhat changed, and the line that replaces each thing. Every item here is additive\\nexcept the first, which changes a default.\\n\\n## An unmatched path answers 404\\n\\n`HttpFactory.create` used to report a miss to global middleware with no route\\nmetadata. A global guard refused it, and a prober could not tell a 404 from a 401. That is now opt-in.\\n\\n| Before                            | After                                    |\\n| --------------------------------- | ---------------------------------------- |\\n| a miss behind a global guard: 401 | a miss behind a global guard: 404        |\\n| `notFound: 'public'` to get 404   | `notFound: 'guarded'` to get the old 401 |\\n\\nAn app with no global authentication guard needs no change. It now behaves the\\nway every other framework does. An app that has one, and wants a miss to look\\nlike every other refused request, sets it back:\\n\\n```ts\\nawait HttpFactory.create(AppModule, { notFound: 'guarded' });\\n```\\n\\n## HTTP settings can come from validated config\\n\\n`HttpFactory.create(root, options)` builds the container, so its `options` argument\\nhas to be ready before any provider exists. An app whose request logging follows its\\nown configuration had to validate that configuration twice.\\n\\n`HttpOptionsProvider` is a subclass resolved from the container:\\n\\n```ts\\nexport class AppHttpOptions extends HttpOptionsProvider {\\n  constructor(private readonly config: AppConfigService) {\\n    super();\\n  }\\n\\n  override readonly trustProxy = true;\\n\\n  override get prefix(): string {\\n    return this.config.get('prefix');\\n  }\\n\\n  override get requestLogging(): RequestLoggingOptions {\\n    return { requestBody: this.config.get('log').requestBody };\\n  }\\n}\\n\\n@Module({\\n  providers: [provide(HttpOptionsProvider, { useClass: AppHttpOptions })],\\n  exports: [HttpOptionsProvider],\\n})\\nexport class HttpConfigModule {}\\n```\\n\\n| Before                                           | After                            |\\n| ------------------------------------------------ | -------------------------------- |\\n| `const log = validate(Bun.env).log` in `main.ts` | inject `AppConfigService`        |\\n| `app.setGlobalPrefix('api')`                     | `override get prefix()`, or both |\\n| `app.enableCors({ ... })`                        | `override get cors()`, or both   |\\n| `app.set('trust proxy', true)`                   | `override readonly trustProxy`   |\\n\\n**Nothing is removed.** `setGlobalPrefix`, `enableCors`, `set` and\\n`enableShutdownHooks` all still work. A call to one wins over the provider,\\nbecause it happens after construction. An argument to `create()` wins too, field\\nby field, so a setting can move into the container one at a time.\\n\\nOverride a field with a field and a getter with a getter: TypeScript rejects the\\nother pairing with `TS2611` and `TS2610`. To derive a field from config, declare\\n`override trustProxy: boolean` and assign it in the constructor.\\n\\n## A named outbound client can be a class\\n\\n`httpClient(name)` returns a `Token`, and a token is not a class. A named client\\ncould only be reached with `inject()` in a field initialiser.\\n\\n```ts\\nexport class EmailClient extends HttpService {}\\n\\nHttpModule.forRootAsync({ useFactory, inject }, EmailClient);\\n```\\n\\n| Before                                         | After                                      |\\n| ---------------------------------------------- | ------------------------------------------ |\\n| `readonly email = inject(httpClient('email'))` | `constructor(private email: EmailClient)`  |\\n| `HttpModule.forRoot({ name: 'email', ... })`   | `HttpModule.forRoot({ ... }, EmailClient)` |\\n\\nThe string form still works. A subclass does not claim `HttpService`, so a default\\nclient and any number of named ones coexist.\\n\\n## A named Redis connection can be a class\\n\\nThe same change, in `@dunx/infra/redis`. `redisConnection(name)` returns a\\n`Token`, so a named connection could only be reached with `inject()` in a field.\\n\\n```ts\\nexport class SessionsRedis extends Redis {}\\n\\nRedisModule.forRootAsync({ useFactory, inject }, SessionsRedis);\\n```\\n\\n| Before                                                 | After                                         |\\n| ------------------------------------------------------ | --------------------------------------------- |\\n| `readonly redis = inject(redisConnection('sessions'))` | `constructor(private redis: SessionsRedis)`   |\\n| `RedisModule.forRoot({ name: 'sessions', ... })`       | `RedisModule.forRoot({ ... }, SessionsRedis)` |\\n\\n`Redis` is now exported for this: `RedisConnection` is the abstract contract and\\ntakes no options, so it cannot be the base a subclass extends. The string form\\nstill works. A subclass does not claim `RedisConnection`.\\n\\n## The websocket relay can be a provider\\n\\n`relay: new RedisRelay({...})` was an instance `main.ts` built and threaded into\\n`HttpFactory.create`. That made it the one setting an options provider could not\\nanswer from config.\\n\\n| Before                                     | After                                        |\\n| ------------------------------------------ | -------------------------------------------- |\\n| `new RedisRelay(...)` in `main.ts`         | `WsRelayModule.forRootAsync({ useFactory })` |\\n| `relay:` and `relayChannel:` on `create()` | `override get relay()` on the provider       |\\n\\nThe container closes it at shutdown. `PubSub.close()` does not do that for an app\\nthat never opened a socket. Passing an instance to `create()` still works.\\n\\n## Config takes a schema directly\\n\\n`validate: (env) => envSchema.parse(env)` still works. The wrapper is now optional:\\n\\n| Before                                    | After               |\\n| ----------------------------------------- | ------------------- |\\n| `validate: (env) => envSchema.parse(env)` | `schema: envSchema` |\\n\\nOne or the other, never both. A schema failure becomes a `ConfigError` naming\\nevery issue and its path.\\n\\n## An OpenAPI contribution can be a provider\\n\\n`contribute` took a fragment or a thunk. It now also takes anything with a\\n`contribute()` method, so a contributor that needs an injected instance is a\\nprovider rather than a closure:\\n\\n```ts\\nexport class AuthDocs extends DocumentSource {\\n  constructor(private readonly auth: Auth) {\\n    super();\\n  }\\n\\n  override async contribute(): Promise<DocumentFragment> {\\n    return betterAuthDocument(this.auth, { basePath: '/api/auth' })();\\n  }\\n}\\n\\nOpenApiModule.forRootAsync({\\n  root: AppModule,\\n  imports: [DocsModule],\\n  inject: [AuthDocs],\\n  useFactory: (docs: AuthDocs) => ({ contribute: [docs] }),\\n});\\n```\\n\\n`imports` is what puts `AuthDocs` in reach: the module is its own scope, so\\nimporting its module into the root does not reach this factory.\\n\\n## A constraint violation answers 409\\n\\nA unique violation reaching the HTTP layer used to answer 500.\\n\\n```ts\\ntry {\\n  return this.db.insert(users).values({ name }).returning().get();\\n} catch (error) {\\n  throw toDatabaseError(error);\\n}\\n```\\n\\n`toDatabaseError` returns a `ConstraintError` carrying a status - 409 for a\\nunique or foreign key violation, 400 for not-null and check. Anything it does\\nnot recognise passes through untouched. `@dunx/http` reads the status off it, so\\nno error filter is involved. `transaction`, `transactionSync` and `runSeeds`\\nalready classify on the way out.\\n\\nThe driver's own message stays on `cause` rather than in the response body, which\\nwould otherwise carry the table and column names.\\n\\n## Four more `fetch` options\\n\\n`HttpClientOptionsInit` passes `compress`, `protocol` and `maxRedirects` through.\\n`proxy` widens to `string | URL | { url, headers }`: the object form sends\\n`Proxy-Authorization` to the proxy rather than to the target.\\n\\n`protocol: 'http2'` lets concurrent requests to one origin share a connection.\\nAgainst a cleartext `http://` upstream Bun raises `HTTP2Unsupported` rather than\\nfalling back, so set it only against an HTTPS origin that offers h2.\\n\"},{\"slug\":\"25-resilience\",\"title\":\"Resilience\",\"summary\":\"Timeout, retry, exponential backoff, jitter and fallback around one operation.\",\"sections\":[\"Binding a policy\",\"Two policies, and one that is a constructor parameter\",\"Deciding what is worth retrying\",\"Backoff and jitter\",\"Answering with something when the attempts are spent\",\"The outbound client already uses one\"],\"body\":\"# Resilience\\n\\nTimeout, retry, exponential backoff, jitter and fallback around one operation.\\n`ResiliencePolicy` lives in `@dunx/core`, has no dependency, and wraps anything\\nthat returns a promise: an outbound call, a driver query, a broker publish.\\n\\nThere is no circuit breaker, no bulkhead and no rate limiter here. The last one\\nalready exists in the other direction: `ThrottleModule` in `@dunx/http` is\\ninbound admission control, keyed by caller and backed by a shared store. Retrying\\nwork this process owns is bullmq's, through `@dunx/infra/queue`.\\n\\n## Binding a policy\\n\\n```ts\\nimport { ResilienceModule } from '@dunx/core';\\n\\n@Module({\\n  imports: [\\n    ResilienceModule.forRoot({\\n      timeoutMs: 3_000,\\n      retry: { maxRetries: 3, retryDelayMs: 200 },\\n    }),\\n  ],\\n})\\nexport class PaymentsModule {}\\n```\\n\\nThat binds `ResiliencePolicy` and `ResilienceOptions`. `run` takes the operation\\nand hands it the signal for its attempt:\\n\\n```ts\\nexport class Checkout {\\n  constructor(private readonly policy: ResiliencePolicy) {}\\n\\n  charge(order: Order): Promise<Receipt> {\\n    return this.policy.run((signal) => this.gateway.charge(order, signal));\\n  }\\n}\\n```\\n\\n`maxRetries` counts retries after the first attempt, so `3` is up to four calls.\\n`timeoutMs` is per attempt and `0` leaves each one unbounded. The signal is\\n`AbortSignal.timeout` combined with any signal passed in `signal`, through\\n`AbortSignal.any`; an operation that ignores it still runs to completion, and\\nonly a `fetch` or a `throwIfAborted()` makes the budget real.\\n\\n## Two policies, and one that is a constructor parameter\\n\\nA second `forRoot` binds its own options token, so two budgets do not collide:\\n\\n```ts\\nResilienceModule.forRoot({ name: 'payment', timeoutMs: 3_000 });\\nResilienceModule.forRoot({ name: 'search', timeoutMs: 400 });\\n```\\n\\nA name binds a `Token`, which is reached with `inject()` in a field:\\n\\n```ts\\nexport class Checkout {\\n  readonly payment = inject(resiliencePolicy('payment'));\\n}\\n```\\n\\n`resiliencePolicy(name)` returns the same token for the same name. A subclass is\\nboth a token and a parameter type, so prefer it for new code:\\n\\n```ts\\nexport class PaymentPolicy extends ResiliencePolicy {}\\n\\nResilienceModule.forRoot({ timeoutMs: 3_000 }, PaymentPolicy);\\n\\nexport class Checkout {\\n  constructor(private readonly policy: PaymentPolicy) {}\\n}\\n```\\n\\nEither form leaves `ResiliencePolicy` itself unbound, so a default policy and\\nseveral named ones coexist.\\n\\n`forRootAsync` takes the same `{ useFactory, inject, imports }` every other dunx\\nmodule does, for a budget that comes off `ConfigService`:\\n\\n```ts\\nResilienceModule.forRootAsync({\\n  useFactory: (config: AppConfigService) => ({\\n    timeoutMs: config.get('upstream').timeoutMs,\\n  }),\\n  inject: [AppConfigService] as const,\\n});\\n```\\n\\n## Deciding what is worth retrying\\n\\n`RetryClassifier` answers that, and is an abstract class rather than an\\ninterface, since an interface at an injection site is a boot error. The default\\nis `TransientRetryClassifier`: everything is retried except an abort, which means\\nthe attempt's timeout expired or the caller's signal fired.\\n\\n`@dunx/http/client` ships `HttpRetryClassifier` for HTTP work. It retries 408,\\n429 and 5xx, refuses the rest, and reads `Retry-After` in both spellings RFC 9110\\nallows, seconds and an HTTP date:\\n\\n```ts\\nimport { HttpRetryClassifier } from '@dunx/http/client';\\n\\nResilienceModule.forRoot({\\n  timeoutMs: 3_000,\\n  classifier: new HttpRetryClassifier(),\\n  retry: { maxRetries: 3, retryDelayMs: 200 },\\n});\\n```\\n\\nA 409 or a 422 is the server rejecting the request, and sending it again\\nunchanged gets the same answer, so neither is retried. Pass\\n`shouldRetryOnStatus` to widen or narrow that, and `respectRetryAfter: false` to\\nuse the computed backoff instead of what the upstream asked for.\\n\\nWriting one is a `classify` that returns a verdict:\\n\\n```ts\\nexport class DbRetryClassifier extends RetryClassifier {\\n  classify(error: unknown): RetryVerdict {\\n    return { retry: error instanceof DeadlockError };\\n  }\\n}\\n```\\n\\n`delayMs` on the verdict overrides the computed backoff for that attempt, capped\\nby `backoff.maxMs`, which is what keeps an upstream asking for an hour from\\nparking a request handler for an hour.\\n\\n## Backoff and jitter\\n\\nThe wait before retry `n` is `retryDelayMs * power ** n + jitter`, capped at\\n`maxMs`:\\n\\n```ts\\nResilienceModule.forRoot({\\n  retry: {\\n    maxRetries: 4,\\n    retryDelayMs: 200,\\n    backoff: { power: 2, jitterMs: 250, maxMs: 5_000 },\\n  },\\n});\\n```\\n\\nDefaults are `power: 2`, `jitterMs: 1000` and `maxMs: 30000`. The jitter comes\\nfrom `crypto.getRandomValues`, not `Math.random`: decorrelating a fleet of\\nclients retrying together is the whole job.\\n\\n`onAttempt`, `onError` and `onSuccess` report the loop without wrapping it:\\n\\n```ts\\nResilienceModule.forRoot({\\n  retry: {\\n    onAttempt: (attempt, isRetry) => log.debug({ attempt, isRetry }),\\n    onError: (error, attempt, willRetry) => log.warn({ attempt, willRetry }),\\n  },\\n});\\n```\\n\\n## Answering with something when the attempts are spent\\n\\n`fallback` receives the last error and its value becomes the call's result:\\n\\n```ts\\nResilienceModule.forRoot({\\n  retry: { maxRetries: 2 },\\n  fallback: () => ({ cached: true, items: [] }),\\n});\\n```\\n\\nIt may be async, and it may throw, which replaces the failure rather than\\nsuppressing it. Without a `fallback` the last error is rethrown.\\n\\n## The outbound client already uses one\\n\\n`HttpService` in `@dunx/http/client` builds a policy per call from its own\\n`timeoutMs` and `retry`, with `HttpRetryClassifier`, so an app calling out\\nthrough it gets all of this without binding a module:\\n\\n```ts\\nHttpModule.forRoot({\\n  baseUrl: 'https://api.upstream.test',\\n  timeoutMs: 3_000,\\n  retry: { maxRetries: 3, retryDelayMs: 200, backoff: { maxMs: 2_000 } },\\n});\\n```\\n\\nBind `ResilienceModule` when the work is not a request that client makes. A\\npolicy wrapped around `HttpService` has to hand the attempt's signal to the\\nrequest, or the policy's `timeoutMs` never reaches `fetch`:\\n\\n```ts\\npolicy.run((signal) => this.http.get(url, { signal }));\\n```\\n\"}]") as readonly GuideDoc[];

/** `examples/minimal` plus the base template, which is what an empty selection writes. */
export const MINIMAL = JSON.parse("{\"runtime\":\"bun >=1.4.1\",\"dependencies\":[\"@dunx/core\",\"@dunx/http\",\"@dunx/transform\"],\"devDependencies\":[\"@dunx/testing\",\"@types/bun\",\"typescript\"],\"files\":[{\"path\":\"package.json\",\"body\":\"{\\n  \\\"name\\\": \\\"my-api\\\",\\n  \\\"version\\\": \\\"0.1.0\\\",\\n  \\\"private\\\": true,\\n  \\\"type\\\": \\\"module\\\",\\n  \\\"scripts\\\": {\\n    \\\"dev\\\": \\\"bun --watch src/main.ts\\\",\\n    \\\"start\\\": \\\"bun src/main.ts\\\",\\n    \\\"test\\\": \\\"bun test\\\",\\n    \\\"typecheck\\\": \\\"tsc --noEmit\\\"\\n  },\\n  \\\"dependencies\\\": {\\n    \\\"@dunx/core\\\": \\\"__DUNX_VERSION__\\\",\\n    \\\"@dunx/http\\\": \\\"__DUNX_VERSION__\\\",\\n    \\\"@dunx/transform\\\": \\\"__DUNX_VERSION__\\\"\\n  },\\n  \\\"devDependencies\\\": {\\n    \\\"@dunx/testing\\\": \\\"__DUNX_VERSION__\\\",\\n    \\\"@types/bun\\\": \\\">=1.4.1\\\",\\n    \\\"typescript\\\": \\\"^5.7.0\\\"\\n  },\\n  \\\"engines\\\": {\\n    \\\"bun\\\": \\\">=1.4.1\\\"\\n  }\\n}\\n\"},{\"path\":\"src/app.module.ts\",\"body\":\"import { Module } from '@dunx/core';\\nimport { GreetingsController } from './greetings.controller.js';\\nimport { GreetingsService } from './greetings.service.js';\\n\\n@Module({\\n  controllers: [GreetingsController],\\n  providers: [GreetingsService],\\n})\\nexport class AppModule {}\\n\"},{\"path\":\"src/app.test.ts\",\"body\":\"import { describe, expect, test } from 'bun:test';\\nimport { createTestServer } from '@dunx/testing';\\nimport { AppModule } from './app.module.js';\\n\\ndescribe('minimal', () => {\\n  test('serves the greeting', async () => {\\n    const server = await createTestServer({ modules: [AppModule] });\\n\\n    const { status, body } = await server.json<{ greeting: string }>(\\n      'greetings/ada',\\n    );\\n\\n    expect(status).toBe(200);\\n    expect(body.greeting).toBe('hello, ada');\\n    await server.close();\\n  });\\n});\\n\"},{\"path\":\"src/greetings.controller.ts\",\"body\":\"import { Controller, Get, type Input, type RouteSchemas } from '@dunx/http';\\nimport { GreetingsService } from './greetings.service.js';\\n\\n@Controller('greetings')\\nexport class GreetingsController {\\n  constructor(private readonly greetings: GreetingsService) {}\\n\\n  @Get('/')\\n  index(): { routes: readonly string[] } {\\n    return { routes: ['GET /greetings', 'GET /greetings/:name'] };\\n  }\\n\\n  // With no `params` schema declared, a path param stays a string.\\n  // `examples/full` shows the typed, coerced version.\\n  @Get('/:name')\\n  one(input: Input<RouteSchemas>): { greeting: string; served: number } {\\n    return this.greetings.greet(input.req.params['name'] ?? 'world');\\n  }\\n}\\n\"},{\"path\":\"src/greetings.service.ts\",\"body\":\"import { Logger, type OnInit } from '@dunx/core';\\n\\n/** A provider is a plain class. Listing it in a module's `providers` is what\\n * makes it injectable; the container reads `Logger` off the constructor. */\\nexport class GreetingsService implements OnInit {\\n  #greeted = 0;\\n\\n  constructor(private readonly logger: Logger) {}\\n\\n  onInit(): void {\\n    this.logger.info('greetings ready');\\n  }\\n\\n  greet(name: string): { greeting: string; served: number } {\\n    this.#greeted++;\\n    return { greeting: `hello, ${name}`, served: this.#greeted };\\n  }\\n}\\n\"},{\"path\":\"src/main.ts\",\"body\":\"import { HttpFactory } from '@dunx/http';\\nimport { AppModule } from './app.module.js';\\n\\nconst app = await HttpFactory.create(AppModule);\\napp.enableShutdownHooks();\\n\\nconst url = await app.listen(3000);\\nconsole.log(`listening on ${url}greetings`);\\n\\nawait app.closed;\\n\"},{\"path\":\"bunfig.toml\",\"body\":\"# The one line that makes constructor injection work. The compiler plugin records\\n# each class's constructor parameter types so the container can resolve them.\\n# Without it, providers are built with no arguments and boot fails saying so.\\npreload = [\\\"@dunx/transform/preload\\\"]\\n\\n[test]\\npreload = [\\\"@dunx/transform/preload\\\"]\\n\"},{\"path\":\"tsconfig.json\",\"body\":\"{\\n  \\\"compilerOptions\\\": {\\n    \\\"target\\\": \\\"ESNext\\\",\\n    \\\"lib\\\": [\\\"ESNext\\\"],\\n    \\\"module\\\": \\\"nodenext\\\",\\n    \\\"moduleResolution\\\": \\\"nodenext\\\",\\n    \\\"types\\\": [\\\"bun\\\"],\\n    \\\"strict\\\": true,\\n    \\\"noUncheckedIndexedAccess\\\": true,\\n    \\\"exactOptionalPropertyTypes\\\": true,\\n    \\\"noImplicitOverride\\\": true,\\n    \\\"noPropertyAccessFromIndexSignature\\\": true,\\n    \\\"verbatimModuleSyntax\\\": true,\\n    \\\"skipLibCheck\\\": true,\\n    \\\"noEmit\\\": true\\n  },\\n  \\\"include\\\": [\\\"src\\\"],\\n  \\\"exclude\\\": [\\\"node_modules\\\"]\\n}\\n\"}]}") as Starter;

/** The features `bunx @dunx/create-app` composes an app from. */
export const SCAFFOLD = JSON.parse("[{\"name\":\"notes\",\"summary\":\"CRUD routes with zod validation. The smallest real feature.\",\"requires\":[],\"dependencies\":[\"@dunx/openapi\",\"zod\"]},{\"name\":\"openapi\",\"summary\":\"OpenAPI 3.1 from the routes own schemas, plus the Swagger UI page.\",\"requires\":[],\"dependencies\":[\"@dunx/openapi\",\"zod\"]},{\"name\":\"http\",\"summary\":\"CORS, a middleware of your own on the response, and error mapping.\",\"requires\":[],\"dependencies\":[]},{\"name\":\"guards\",\"summary\":\"Route guards with @Roles and @Public, and a protected controller.\",\"requires\":[],\"dependencies\":[\"zod\"]},{\"name\":\"database\",\"summary\":\"drizzle over bun:sqlite, with a schema, seeds and migrations.\",\"requires\":[],\"dependencies\":[\"@dunx/infra\",\"drizzle-orm\",\"zod\"]},{\"name\":\"users\",\"summary\":\"A repository, a service and validated routes over the database.\",\"requires\":[\"database\"],\"dependencies\":[\"@dunx/infra\",\"drizzle-orm\",\"zod\"]},{\"name\":\"auth\",\"summary\":\"better-auth mounted, with SessionGuard and an audit trail.\",\"requires\":[\"database\"],\"dependencies\":[\"@dunx/auth\",\"better-auth\",\"drizzle-orm\"]},{\"name\":\"cache\",\"summary\":\"Bun.RedisClient behind a session store, degrading when absent.\",\"requires\":[],\"dependencies\":[\"@dunx/infra\",\"zod\"],\"service\":\"Redis or Valkey\"},{\"name\":\"websockets\",\"summary\":\"A @Gateway with @OnMessage events, PubSub and a Redis relay.\",\"requires\":[\"cache\"],\"dependencies\":[\"@dunx/infra\"],\"service\":\"Redis or Valkey, for multi-node fan-out only\"},{\"name\":\"images\",\"summary\":\"Bun.Image resizing and format conversion behind a route.\",\"requires\":[],\"dependencies\":[\"@dunx/infra\",\"zod\"]},{\"name\":\"files\",\"summary\":\"Uploads and downloads on Bun.file, with a workspace root.\",\"requires\":[],\"dependencies\":[\"@dunx/infra\",\"zod\"]},{\"name\":\"jobs\",\"summary\":\"bullmq queues over Bun.RedisClient, background handlers forked.\",\"requires\":[\"images\"],\"dependencies\":[\"@dunx/infra\",\"bullmq\",\"ioredis\",\"zod\"],\"service\":\"Redis or Valkey\"},{\"name\":\"health\",\"summary\":\"`HealthModule`'s liveness and readiness probes, wired to this app's own indicators.\",\"requires\":[\"cache\",\"database\",\"files\"],\"dependencies\":[\"@dunx/infra\"]},{\"name\":\"throttle\",\"summary\":\"A fixed-window rate limit, with the counter in Redis and per-route overrides.\",\"requires\":[\"cache\"],\"dependencies\":[\"@dunx/infra\"],\"service\":\"Redis or Valkey\"},{\"name\":\"schedule\",\"summary\":\"@Cron, @Interval and @OnceOnBoot on Bun.cron, armed at boot and triggerable.\",\"requires\":[],\"dependencies\":[\"@dunx/infra\"]},{\"name\":\"assets\",\"summary\":\"A static directory on Bun.file, with a short max-age and an immutable rule.\",\"requires\":[],\"dependencies\":[]},{\"name\":\"stats\",\"summary\":\"Per-route request timings and per-operation query timings, as JSON.\",\"requires\":[\"database\"],\"dependencies\":[]},{\"name\":\"client\",\"summary\":\"The outbound half of @dunx/http: retry, backoff and a typed FetchError.\",\"requires\":[],\"dependencies\":[]}]") as readonly ScaffoldFeature[];

/** The rules a dunx app breaks by omission. Declared by `@dunx/create-app`. */
export const RULES = JSON.parse("[{\"rule\":\"Constructor injection needs the preload.\",\"detail\":\"Add `preload = [\\\"@dunx/transform/preload\\\"]` to bunfig.toml, and again under `[test]`. It records each class's constructor parameter types at load time. Without it a class with constructor parameters is a boot error naming the preload.\"},{\"rule\":\"No `@Injectable()`, and no `@Inject()`.\",\"detail\":\"Listing a class in a module's `providers` is what makes it injectable. dunx uses TC39 standard decorators, which have no parameter decorators. For a value with no constructor parameter to hang off, use `inject(Token)` in a field initializer.\"},{\"rule\":\"Do not add `reflect-metadata`, `experimentalDecorators` or `emitDecoratorMetadata`.\",\"detail\":\"`@dunx/transform` records the constructor parameter types instead, and it needs none of them. Adding them does not make injection work; removing the preload line breaks it.\"},{\"rule\":\"A constructor parameter whose type is erased fails at boot, naming the parameter.\",\"detail\":\"An interface, a primitive, a union, a class type parameter, or an `import type` at an injection site all record as `unresolved`. Inject a class, and drop `type` from the import.\"},{\"rule\":\"Relative imports carry a .js extension.\",\"detail\":\"`import { UsersService } from './users.service.js'`. The manifest is `\\\"type\\\": \\\"module\\\"` and resolution is nodenext, so an extensionless relative specifier does not resolve.\"},{\"rule\":\"A module's `exports` is its public surface.\",\"detail\":\"The container is scoped per module, so a provider another module injects has to be exported by the module that declares it. Absent `exports` means nothing is exported, and `global: true` publishes them app-wide.\"},{\"rule\":\"`bun` only.\",\"detail\":\"No `npm`, `npx`, `yarn` or `pnpm`. Run tools with `bunx` and scripts with `bun run <script>`.\"}]") as readonly BootRule[];
